#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array to store NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T **nfaApiArray;
int nfaApiSize = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeNfaApiArray(int size) {
    nfaApiSize = size;
    nfaApiArray = (NFAPI_CRC_INDICATION_PDU_T **)malloc(nfaApiSize * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (int i = 0; i < nfaApiSize; i++) {
        nfaApiArray[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

void destroyNfaApiArray() {
    for (int i = 0; i < nfaApiSize; i++) {
        free(nfaApiArray[i]);
    }
    free(nfaApiArray);
    nfaApiArray = NULL;
    nfaApiSize = 0;
}

void* threadSafeAddElement(void* data) {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    element->RX_UE_INFORMATION_TAG = rand();
    element->RNTI = rand();
    element->CRC_INDICATION_REL8_TAG = rand();
    int flag = rand() % 2;
    element->CRCFLAG = flag;
    // Add the element to the array
    for (int i = nfaApiSize - 1; i > 0; i--) {
        nfaApiArray[i] = nfaApiArray[i - 1];
    }
    nfaApiArray[0] = element;
    nfaApiSize++;
    pthread_mutex_unlock(&lock);
    return NULL;
}

void validateNfaApiArray() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < nfaApiSize; i++) {
        if (!nfaApiArray[i]) {
            printf("Invalid or incomplete structure found at index %d\n", i);
        } else {
            printf("Valid structure found at index %d with tag %d, RNTI %d, and CRCFLAG %d\n", 
                   i, nfaApiArray[i]->RX_UE_INFORMATION_TAG, nfaApiArray[i]->RNTI, nfaApiArray[i]->CRCFLAG);
        }
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    initializeNfaApiArray(10);
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, threadSafeAddElement, NULL);
    }
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }
    validateNfaApiArray();
    destroyNfaApiArray();
    return 0;
}

