#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    int value;
} record;

// Function to allocate and initialize records
int* initRecords(int numRecords, pthread_mutex_t* mutex) {
    // Allocate memory for the records array
    record* records = (record*)malloc(numRecords * sizeof(record));

    // Initialize each record with a random value within the range [0, 100]
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % 101;
        records[i].value = rand() % 100;
    }

    return (int*)records;
}

// Function to validate record keys and handle conflicts
void validateKeys(record* records, int numRecords) {
    // Iterate through the records array
    for (int i = 0; i < numRecords; i++) {
        // Check if any duplicate keys exist
        bool keyFound = false;
        for (int j = 0; j < numRecords; j++) {
            if (records[i].key == records[j].key && i != j) {
                keyFound = true;
                break;
            }
        }

        // Handle conflicts by rehashing the record with a unique key
        if (keyFound) {
            for (int j = 0; j < numRecords; j++) {
                if (records[i].key == records[j].key && i != j) {
                    records[i].key += j;
                }
            }
        }
    }
}

// Main function to manage memory allocation and initialization
int* initMemory(int numRecords, int maxKey, pthread_mutex_t* mutex) {
    // Initialize the record array
    record* records = initRecords(numRecords, mutex);

    // Initialize the key array
    int* keys = (int*)malloc(numRecords * sizeof(int));
    for (int i = 0; i < numRecords; i++) {
        keys[i] = i;
    }

    // Initialize the offset values array
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = i * maxKey;
    }

    return records;
}

// Function to handle memory allocation failure
void handleMemoryFailure() {
    printf("Memory allocation failed. Exiting...\n");
    exit(1);
}
