int* process_ints(int** ints_ptr, int* num_ints);
void validate_ints(int* ints, int num_ints);

int main() {
    int* ints = NULL;
    int num_ints = 0;

    while (1) {
        printf("Enter a list of integers (or 'q' to quit): ");
        if (!fgets(buffer, sizeof(buffer), stdin)) break;

        *ints_ptr = realloc(*ints_ptr, (*num_ints + MAX_INTS) * sizeof(int));
        ints = *ints_ptr;

        char* token = strtok(buffer, " ");
        while (token && num_ints < MAX_INTS) {
            if (!strcmp(token, "q")) break;

            int val = strtol(token, NULL, 10);
            if (val < MIN_INT || val > MAX_INT) continue; // invalid integer

            ints[num_ints++] = val;
            token = strtok(NULL, " ");
        }

        validate_ints(ints, num_ints);

        printf("Largest integer: %d\n", *process_ints(&ints, &num_ints));
    }

    free(ints);
    return 0;
}

int* process_ints(int** ints_ptr, int* num_ints) {
    int max_val = *ints_ptr[0];
    for (int i = 1; i < *num_ints; i++) {
        if (*ints_ptr[i] > max_val) max_val = *ints_ptr[i];
    }
    return &max_val;
}

void validate_ints(int* ints, int num_ints) {
    // simulate external data source validation
