import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class PokemonWeaknessRetriever {

    private static final HttpClient client = HttpClient.newHttpClient();
    private static final Map<String, String> pokemonDataCache = new HashMap<>();

    public String getWeaknesses(Pokemon pokemon) {
        String pokemonName = pokemon.getName();
        if (!pokemonDataCache.containsKey(pokemonName)) {
            // Fetch data from API
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create("https://api.pokemon.com/pokemon/" + pokemonName))
                    .GET()
                    .build();
            try {
                HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
                String apiResponse = response.body();
                if (apiResponse != null) {
                    // Process API response
                    List<String> weaknesses = new ArrayList<>();
                    for (String type : pokemon.getTypes()) {
                        String[] typeWeaknesses = getTypeWeaknesses(type);
                        weaknesses.addAll(typeWeaknesses);
                    }
                    // Cache data for future reuse
                    pokemonDataCache.put(pokemonName, String.join(", ", weaknesses));
                } else {
                    // Handle API error
                    return "Error: Unable to retrieve Pokémon data. Try again later.";
                }
            } catch (IOException | InterruptedException e) {
                // Handle network errors
                return "Error: Network issue occurred. Please try again later.";
            }
        }
        return pokemonDataCache.get(pokemonName);
    }

    private String[] getTypeWeaknesses(String type) {
        // Implementation for getting weaknesses of a given Pokémon type
    }
}

class Pokemon {
    private String name;
    private List<String> types;

    public Pokemon(String name, List<String> types) {
        this.name = name;
        this.types = types;
    }

    public String getName() {
        return name;
    }

    public List<String> getTypes() {
        return types;
    }
}
