}

semaphore_t *create_semaphore() {
    if (sema_count >= SEMAPHORE_MAX) return NULL;
    semaphore_t *s = malloc(sizeof(semaphore_t));
    init_semaphore(s);
    sema[s->value] = s;
    used_semaphores++;
    free_semaphores--;
    return s;
}

void delete_semaphore(semaphore_t *s) {
    pthread_mutex_lock(&s->mutex);
    if (pthread_trylock(&s->mutex)) {
        printf("Semaphore already deleted or not accessible\n");
        exit(-1);
    }
    used_semaphores--;
    free_semaphores++;
    pthread_cond_destroy(&s->cond);
    pthread_mutex_unlock(&s->mutex);
}

void print_stats() {
    printf("Total semaphores: %d\n", SEMAPHORE_MAX);
    printf("Used semaphores: %d\n", used_semaphores);
    printf("Free semaphores: %d\n", free_semaphores);
}

int main(int argc, char **argv) {
    pthread_t config_thread;
    pthread_create(&config_thread, NULL, &config_manager, NULL);

    while (1) {
        print_stats();
        sleep(STAT_INTERVAL);
    }
    return 0;
}

void* config_manager(void *arg) {
    while (1) {
        // fetch real-time application load metrics from external service
        int new_load = get_app_load();

        if (new_load > free_semaphores) {
            int to_create = new_load - free_semaphores;
            for (int i = 0; i < to_create; i++) {
                semaphore_t *s = create_semaphore();
                if (!s) printf("Semaphore creation failed\n");
            }
        } else if (new_load < used_semaphores) {
            int to_delete = used_semaphores - new_load;
            for (int i = 0; i < to_delete; i++) {
                semaphore_t *s = sema[i];
                delete_semaphore(s);
                free(s);
            }
        }

        // monitor and log semaphore usage patterns
        printf("Semaphore usage pattern: \n");
        // TO DO: implement logging mechanism

        sleep(1);  // adjust according to your needs
    }
    return NULL;
}

