using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Collections.Generic;

namespace WeatherApp
{
    public class WeatherAPI
    {
        private readonly HttpClient _httpClient;
        private readonly Dictionary<string, CacheItem> _cache = new Dictionary<string, CacheItem>();

        public WeatherAPI(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<WeatherData> GetWeatherAsync(string location, string apiKey)
        {
            if (_cache.TryGetValue(location, out var cachedItem))
            {
                if (cachedItem.ExpiresAfter > DateTime.Now)
                {
                    return JsonConvert.DeserializeObject<WeatherData>(cachedItem.Response);
                }
            }

            try
            {
                HttpResponseMessage response = await _httpClient.GetAsync($"api/weather/{location}?apiKey={apiKey}");
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();

                WeatherData data = JsonConvert.DeserializeObject<WeatherData>(responseBody);

                // Caching mechanism
                CacheItem cacheItem = new CacheItem(responseBody, DateTime.Now.AddMinutes(30)); // Set cache expiration to 30 minutes
                _cache[location] = cacheItem;

                return data;
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine("Error fetching weather: {0}", ex.Message);
                return null; // Handle API errors gracefully
            }
        }

        public async Task SetWeatherAsync(string location, WeatherData data)
        {
            if (_cache.ContainsKey(location))
            {
                _cache[location] = new CacheItem(JsonConvert.SerializeObject(data), DateTime.Now.AddMinutes(30)); // Update cache expiration to 30 minutes
            }
        }
    }

    public class CacheItem
    {
        public string Response { get; set; }
        public DateTime ExpiresAfter { get; set; }

        public CacheItem(string response, DateTime expiresAfter)
        {
            Response = response;
            ExpiresAfter = expiresAfter;
        }
    }

    public class WeatherData
    {
        public double Temperature { get; set; }
        public double Humidity { get; set; }
        public double WindSpeed { get; set; }
        // Add more properties as needed
    }

    public class Program
    {
        public static async Task Main(string[] args)
        {
            HttpClient client = new HttpClient();
            WeatherAPI weatherApi = new WeatherAPI(client);

            while (true)
            {
                Console.WriteLine("Enter location (e.g., 'New York'):");
                string location = Console.ReadLine();

                WeatherData data = await weatherApi.GetWeatherAsync(location, "YOUR_API_KEY");

                if (data != null)
                {
                    // Adjust UI background color based on temperature, humidity, and wind speed
                    double averageValue = (data.Temperature + data.Humidity + data.WindSpeed) / 3;
                    int r = Convert.ToInt32(Math.Min(255, averageValue));
                    int g = Convert.ToInt32(Math.Max(0, averageValue - 128));
                    int b = Convert.ToInt32(Math.Max(0, 255 - averageValue));

                    // Set UI background color
                    Console.BackgroundColor = (ConsoleColor)System.Enum.ToObject(typeof(ConsoleColor), r, g, b);

                    Console.WriteLine("Temperature: {0}°C", data.Temperature);
                    Console.WriteLine("Humidity: {0}%", data.Humidity);
                    Console.WriteLine("Wind Speed: {0} km/h", data.WindSpeed);
                }
                else
                {
                    Console.WriteLine("Failed to fetch weather data. Try again later.");
                }

                // Handle daylight savings time adjustments
                DateTime timeZone = await GetTimeZoneAsync(location);
                if (timeZone != null)
                {
                    Console.WriteLine($"Time zone: {timeZone.ToString("yyyy-MM-dd HH:mm")}");
                }
            }
        }

        public static async Task<DateTime?> GetTimeZoneAsync(string location)
        {
