using System;
using System.IO;
using System.Xml.XPath;

public class XmlEnvironmentProcessor
{
    public void ProcessXmlAndInitializeEnvironment(string xmlFilePath, string directoryName, string environmentVariableName)
    {
        try
        {
            // Parse XML using XPath to find the first element matching a specified name
            var doc = new XmlDocument();
            doc.Load(xmlFilePath);
            XPathNavigator nav = doc.CreateNavigator();
            XPathExpression expression = nav.Compile("//" + directoryName);
            XPathNodeIterator iterator = nav.Select(expression);

            if (!iterator.MoveNext())
            {
                // No elements found, log a warning message
                System.Diagnostics.Logger.Warn("No elements found in XML file");
                return;
            }

            string path = iterator.Current.Value;

            try
            {
                // Create the directory with the specified path
                Directory.CreateDirectory(path);
                LogDirectoryCreationSuccess(path);

                // Initialize environment variable with the created directory path
                Environment.SetEnvironmentVariable(environmentVariableName, path);
                LogEnvironmentVariableInitializationSuccess();
            }
            catch (Exception e)
            {
                // Handle exceptions during directory creation or environment variable setting
                System.Diagnostics.Logger.Warn("Failed to create directory or set environment variable", e);

                try
                {
                    // Attempt to fall back to a default directory path
                    Directory.CreateDirectory(GetDefaultDirectoryPath());
                    LogFallbackToDefaultDirectory();
                }
                catch (Exception fallbackE)
                {
                    // Handle exceptions during fallback to default directory
                    System.Diagnostics.Logger.Warn("Failed to create default directory", fallbackE);
                }
            }
        }
        catch (XmlDocumentException e)
        {
            // Handle XML parsing exceptions
            System.Diagnostics.Logger.Error("Error parsing XML file", e);
        }
    }

    private void LogDirectoryCreationSuccess(string path) => System.Diagnostics.Logger.Info($"Directory created successfully: {path}");
    private void LogEnvironmentVariableInitializationSuccess() => System.Diagnostics.Logger.Info("Environment variable initialized successfully");
    private void LogFallbackToDefaultDirectory() => System.Diagnostics.Logger.Warn("Falling back to default directory");

    private string GetDefaultDirectoryPath() => "C:\\Default\\Directory";
}
