        {
            // Check if the username is available
            if (usernameAlreadyExists(username))
            {
                throw new Exception("Username already exists");
            }

            var account = new UserAccount { Id = id, Username = username, Password = password };
            _accounts.Add(id, account);
        }

        public bool ValidateUserLogin(int id, string username, string password)
        {
            if (!_accounts.ContainsKey(id))
                return false;

            var account = _accounts[id];
            if (account.Username != username || !_passwordValidator.ValidatePassword(password, account.Password))
                return false;

            // Check for MFA requirements
            if (account.MFAMethods.Count > 0)
                return ValidateMFA(account);

            return true;
        }

        public void LockOutUserAccount(int id)
        {
            var account = _accounts[id];
            if (!account.IsLockedOut)
                account.IsLockedOut = true;
        }

        public void UnlockUserAccount(int id, int retryAttempts)
        {
            var account = _accounts[id];
            account.IsLockedOut = false;
            account.LastLoginAttempted = DateTime.Now.AddMinutes(retryAttempts);
        }

        private bool usernameAlreadyExists(string username)
        {
            // Check if the username already exists
            return _accounts.Any(account => account.Value.Username.ToLower() == username.ToLower());
        }

        public void AddMFA(int id, string mfaMethod)
        {
            var account = _accounts[id];
            account.MFAMethods.Add(mfaMethod);
        }
