const { marked } = require('marked');
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

function processDirectory(directoryPath) {
  const htmlFiles = [];
  const maxConcurrentReads = 10;

  async function readAndProcessFile(filePath, retries = 0) {
    if (retries >= 3) {
      console.warn(`Failed to read file: ${filePath}`);
      return;
    }

    try {
      const fileContent = await fs.readFile(filePath, 'utf8');
      const mdConfig = await getMdConfigFromApi(filePath);

      const htmlContent = marked(fileContent);
      htmlFiles.push({ fileName: path.basename(filePath), html: htmlContent });

      // Simulate concurrent reads
      for (let i = 0; i < maxConcurrentReads && i < fs.readdirSync(directoryPath).length; i++) {
        readAndProcessFile(path.join(directoryPath, fs.readdirSync(directoryPath)[i]), retries);
      }
    } catch (error) {
      if (error.code === 'ECONNREFUSED' || error.name === 'TimeoutError') {
        // Network timeout or connection refused, retry after 1 second
        setTimeout(() => readAndProcessFile(filePath, retries + 1), 1000);
      } else {
        console.error(`Error reading file: ${filePath} - ${error.message}`);
        await readAndProcessFile(filePath, retries + 1);
      }
    }
  }

  await readAndProcessFile(directoryPath);

  return htmlFiles;
}

async function getMdConfigFromApi(filePath) {
  try {
    const response = await axios.get(`https://your-external-api.com/config/${path.basename(filePath)}`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching config: ${filePath} - ${error.message}`);
    throw error;
  }
}

module.exports = processDirectory;
