function testModule(moduleName) {
  const blueSlip = require('blueslip');
  const tests = require(`./tests/${moduleName}`);
  const threads = process.cpuUsage().system / process.cpuUsage().user * 5; // adjust thread count based on CPU usage
  const concurrentThreads = Math.min(threads, 10); // limit to a maximum of 10 concurrent threads

  for (const testName in tests) {
    const test = tests[testName];
    blueSlip.reset(); // reset mocking framework before each test

    try {
      const start = process.hrtime();
      test.run();
      const end = process.hrtime();

      console.log(`Test ${testName} completed in ${end[0] - start[0]} seconds`);
    } catch (error) {
      console.error(`Error running test ${testName}: ${error}`);
    }

    setTimeout(() => { // simulate a delay to mimic real-world scenario
      for (let i = 0; i < concurrentThreads; i++) {
        tests[(testName + i).replace('.', '_')].run();
      }
    }, 100);
  }

  blueSlip.reset(); // clean up mocking framework after all tests are completed
}
