async function getBattleFrequency(query) {
  const stopWords = ['and', 'the', 'in'];
  const battlesBefore1000AD = await getBattlesBefore1000AD();
  const queryLowercase = query.toLowerCase();

  // Tokenize the query and remove stop words
  const tokens = queryLowercase.split(' ').filter(token => !stopWords.includes(token));

  // Initialize a map to store battle frequencies
  const battleFrequencies = {};

  // Retrieve battles from the database that match the query
  const results = await getBattlesMatchingQuery(tokens);

  // Process each result and update the frequency map
  for (const battle of results) {
    if (!battlesBefore1000AD.includes(battle.name)) {
      const lowercaseName = battle.name.toLowerCase();
      if (!battleFrequencies[lowercaseName]) {
        battleFrequencies[lowercaseName] = 1;
      } else {
        battleFrequencies[lowercaseName]++;
      }
    }
  }

  // Return the frequency map
  return Object.fromEntries(Object.entries(battleFrequencies).map(([name, count]) => [name, count]));
}

async function getBattlesBefore1000AD() {
  const results = await db.collection('battles').find({ year: { $lt: 1000 } }).toArray();
  return results.map(battle => battle.name);
}

async function getBattlesMatchingQuery(tokens) {
  // Implement database query optimization techniques here
  const results = await db.collection('battles').aggregate([
    { $match: { name: { $regex: new RegExp(`\\b(${tokens.join('|')})\\b`, 'i') } } },
    { $sort: { year: -1 } }
  ]).toArray();
  return results;
}
