function generateFooterScripts(scripts) {
  let footerScripts = '';
  for (let i = 0; i < scripts.length; i++) {
    const script = scripts[i];
    if (!script.id || !script.type) {
      continue;
    }
    let attributes = [];
    if (script.async) {
      attributes.push(`async`);
    }
    if (script.defer) {
      attributes.push(`defer`);
    }
    if (script.crossorigin) {
      attributes.push(`crossorigin="anonymous"`);
    }
    footerScripts += `<script id="${script.id}" type="${script.type}" ${attributes.join(' ')}></script>`;
  }
  return footerScripts;
}
