import scapy.all as scapy
from typing import List, Dict
from collections import deque
from threading import Lock
from functools import lru_cache
from cachecontrol import CacheControl
from requests.exceptions import ReadTimeout

class PacketProcessor:
    def __init__(self):
        self.packet_buffer = []
        self. fragment_queue = deque()
        self.header_cache = {}
        self.lock = Lock()

    @lru_cache(maxsize=10000)
    def get_packet_info(self, packet_id: int) -> Dict[str, str]:
        # Call external data service for header metadata
        try:
            response = requests.get(f"https://packet-service.com/{packet_id}")
            if response.status_code == 200:
                return json.loads(response.content.decode("utf-8"))
            else:
                raise ReadTimeout()
        except (requests.exceptions.RequestException, ValueError):
            return {}

    def process_packet(self, packet: scapy.Packet) -> None:
        with self.lock:
            # Check for fragmentation
            if packet.haslayer(scapy.IP) and packet[TCP].flags & 0x02:  
                self.fragment_queue.append(packet)
                return

            # Extract essential headers
            header_data = {}
            for layer in [packet.arp, packet.ipv6, packet.tcp]:
                if layer:
                    header_data.update(layer.fields_dict)

            # Add to buffer and cache
            self.packet_buffer.append(header_data)
            self.header_cache[packet.id] = header_data

    def process_fragmented_packets(self) -> None:
        with self.lock:
            while self.fragment_queue:
                packet = self.fragment_queue.popleft()
                # Reassemble fragmented packets
                if packet.haslayer(scapy.IP):
                    reassembled_packet = scapy.IP()
                    for layer in [packet.arp, packet.ipv6, packet.tcp]:
                        reassembled_packet.add_payload(layer)
                    self.process_packet(reassembled_packet)

    def start_processing(self) -> None:
        while True:
            try:
                # Process packets from buffer
                if not self.packet_buffer:
                    break

                packet = self.packet_buffer.pop(0)
                if 'frag' in packet['tcp']:
                    self.process_fragmented_packets()
                    continue

                # Perform packet processing logic here...
                print(f"Processed packet {packet['id']}")
            except Exception as e:
                print(f"Error: {e}")

    def run(self) -> None:
        try:
            while True:
                packet = scapy.sniff(timeout=1)
                if packet:
                    self.process_packet(packet)
                else:
                    break
        finally:
            self.start_processing()
