function getElementList(rootNode, selectorFilter, predicate, maxDepth) {
    const result = [];
    (function traverse(node, depth) {
        if (!node || depth > maxDepth) return;
        if (node.nodeType === 3) return; // Skip text nodes
        if (node.nodeType === 8) return; // Skip comments

        let shouldInclude = false;
        if (selectorFilter) {
            const selectorMatches = node.querySelectorAll(selectorFilter);
            if (selectorMatches.length > 0) {
                shouldInclude = true;
            }
        } else {
            shouldInclude = predicate(node);
        }

        if (shouldInclude) result.push(node);

        for (const child of node.childNodes) {
            traverse(child, depth + 1);
        }
    })(rootNode, 1);
    return result;
}
