const { c Library } = require('./cLibrary');

// Function to dynamically load and execute user-specified JavaScript files
async function loadAndExecuteJsFile(filePath) {
  try {
    // Analyze the original filename's character structure
    const extension = path.extname(filePath);
    const fileType = await cLibrary.analyzeExtension(extension);

    // Modify file extension based on analysis result
    const modifiedFilePath = `${path.dirname(filePath)}/${fileType.replace('.', '')}.js`;

    // Load and execute JavaScript file asynchronously
    fs.readFile(modifiedFilePath, 'utf8', (err, data) => {
      if (err) {
        console.error(`Error loading file: ${modifiedFilePath}`);
      } else {
        const script = document.createElement('script');
        script.src = modifiedFilePath;
        document.head.appendChild(script);
      }
    });
  } catch (error) {
    console.error(`Error executing file: ${filePath}`);
  }
}

// Function to handle concurrent file requests efficiently
async function loadJsFilesConcurrently(filePaths, callback) {
  const promises = filePaths.map((filePath) => loadAndExecuteJsFile(filePath));
  await Promise.all(promises);
  callback();
}

// Example usage:
const filePaths = ['file1.js', 'file2.ts', 'file3.js'];
loadJsFilesConcurrently(filePaths, () => console.log('All files loaded and executed'));
