    public Map<String, Long> processLogEntries(List<LogEntry> logEntries) throws Exception {
        Map<String, Long> intervals = new TreeMap<>();
        Instant previousTimestamp = null;
        String currentInterval = "";
        long totalIntervalTime = 0;

        for (LogEntry entry : logEntries) {
            if (!isValidLogEntry(entry)) {
                throw new Exception("Invalid log entry format: " + entry);
            }

            if (previousTimestamp == null || Instant.between(previousTimestamp, entry.timestamp)) {
                previousTimestamp = entry.timestamp;
                currentInterval += entry.eventType;
            } else {
                if (intervals.containsKey(currentInterval)) {
                    totalIntervalTime += intervals.get(currentInterval);
                }
                adjustIntervalBoundary(intervals, currentInterval, previousTimestamp.toEpochMillisecond(), DEFAULT_INTERVAL_THRESHOLD_MILLIS);
                previousTimestamp = entry.timestamp;
                currentInterval = entry.eventType;
            }

            totalIntervalTime += Instant.now().toEpochMillisecond() - entry.timestamp.toEpochMillisecond();
        }

        if (intervals.containsKey(currentInterval)) {
            totalIntervalTime += intervals.get(currentInterval);
        }
        adjustIntervalBoundary(intervals, currentInterval, previousTimestamp.toEpochMillisecond(), DEFAULT_INTERVAL_THRESHOLD_MILLIS);

        return intervals;
    }

