    private void adjustIntervalBoundary(Map<String, Long> intervals, String intervalName, long timestamp, int threshold) {
        if (intervals.containsKey(intervalName)) {
            long previousTimestamp = (long) intervals.getOrDefault(intervalName, 0);
            if (timestamp - previousTimestamp >= threshold) {
                intervals.put(intervalName, timestamp);
            } else {
                // Adjust the boundary based on your custom logic
                // For example, you can adjust it to be every `threshold` milliseconds
                int adjustment = (int) ((timestamp - previousTimestamp) % threshold);
                intervals.put(intervalName, timestamp - adjustment);
            }
        } else {
            intervals.put(intervalName, timestamp);
        }
    }

