            try {
                // Establish connection and handle requests
                sessionSocket = establishConnection(endpoint);
                while (true) {
                    // Handle incoming data and update performance metrics
                    processRequest(sessionSocket.getInputStream());
                    updatePerformanceMetrics();
                    if (isTimeoutReached()) {
                        break;
                    }
                }
