import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;
import java.util.Random;

import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ServiceManager {
    private static final Logger logger = LoggerFactory.getLogger(ServiceManager.class);
    private static final Random random = new Random();
    private Properties properties;

    public ServiceManager(Properties properties) {
        this.properties = properties;
    }

    public void startService() throws IOException, InterruptedException {
        long delay = generateRandomDelay(properties.getProperty("delay.range", "500-1000"));
        Thread.sleep(delay);
        logger.info("Service started");
    }

    public void stopService() throws IOException, InterruptedException {
        sendStopMessage();
        logger.info("Service stopped");
    }

    private void sendStopMessage() throws IOException, InterruptedException {
        int maxRetries = Integer.parseInt(properties.getProperty("max.retries", "3"));
        int backoffFactor = Integer.parseInt(properties.getProperty("backoff.factor", "2"));
        for (int i = 0; i < maxRetries && !sendMessage(); i++) {
            Thread.sleep((long) Math.pow(2, i) * backoffFactor);
        }
    }

    private boolean sendMessage() throws IOException, InterruptedException {
        // Send message to external messaging system
        return true;
    }

    private long generateRandomDelay(String delayRange) {
        String[] parts = delayRange.split("-");
        int minDelay = Integer.parseInt(parts[0]);
        int maxDelay = Integer.parseInt(parts[1]);
        return (long) random.nextInt((maxDelay - minDelay + 1)) + minDelay;
    }

    public void logMetrics() {
        // Log service metrics
    }
}
