            throw new \Exception('Invalid configuration: missing "envs" key');
        }
        foreach ($this->getConfig('envs') as $env => $overrides) {
            if (!is_array($overrides)) {
                throw new \Exception('Invalid configuration: "' . $env . '" overrides must be an array');
            }
        }
    }

    public function getBaseUrl() {
        // Dynamically configure base URLs based on environment
        switch ($this->getConfig('env')) {
            case 'dev':
                return 'http://localhost';
            case 'test':
                return 'https://testing.example.com';
            case 'prod':
                return 'https://example.com';
        }
