        switch ($this->getConfig('env')) {
            case 'dev':
                return \Logger::DEBUG;
            case 'test':
                return \Logger::INFO;
            case 'prod':
                return \Logger::WARNING;
        }
    }

    public function updateDependencies() {
        // Automatically update vendor autoloader upon changes to dependencies
        $dependencies = require_once 'composer.json';
        foreach ($dependencies as $package => $version) {
            if (isset($this->getConfig('dependencies')) && isset($this->getConfig('dependencies')[$package])) {
                $requiredVersion = $this->getConfig('dependencies')[$package];
