use reqwest::get;
use tokio::sync::{mpsc, oneshot};
use log::{info, error};

struct HttpClient {
    max_concurrency: usize,
    request_headers: Vec<(&str, &str)>,
    disable_cert_validation: bool,
    logger: Box<dyn log::Logger + Send>,
}

impl HttpClient {
    async fn new(max_concurrency: usize, request_headers: Vec<(&str, &str)>, disable_cert_validation: bool, logger: Box<dyn log::Logger + Send>) -> Self {
        Self { 
            max_concurrency,
            request_headers,
            disable_cert_validation,
            logger
        }
    }

    async fn send_request(&self, url: &str) -> Result<(), reqwest::Error> {
        let (tx, rx) = oneshot::channel();

        tokio::spawn(async move {
            info!("Sending request to {}", url);

            let client = if self.disable_cert_validation {
                reqwest::get(url)
            } else {
                reqwest::get(url).dangerously_insecure()
            };

            client
                .headers(self.request_headers.clone())
                .send()
                .await?

                .json::<serde_json::Value>().await?;

            info!("Received response from {}", url);
            tx.send(Ok(())).unwrap();
        });

        rx.await.unwrap().unwrap();
        Ok(())
    }
}

async fn main() {
    let mut client = HttpClient::new(
        5, // max concurrency
        vec![("Accept", "text/plain")], // request headers
        false, // disable certificate validation
        Box::new(log4rs::log::LogBuilder::new().add_appender(Box::new(log4rs::log::console())).build()),
    );

    for i in 0..10 {
        client.send_request(&format!("https://example.com/api/endpoint/{}", i)).await.unwrap();
    }
}
