use std::fs;
use std::process::{Command, ExitCode};
use time::{Duration, Instant};
use sys_info::{SysInfo, System};

fn compile_project(path: &str) -> ExitCode {
    let start_time = Instant::now();
    let mut sys_info = SysInfo::new();
    let system = System::current();

    // Set up logging configuration
    let log_verbosity = match std::env::var("LOG_VERBOSITY") {
        Ok(v) => v.parse::<u8>().unwrap_or(1),
        Err(_) => 1,
    };

    // Log start time and initial system information
    match sys_info.log(log_verbosity, "Compilation started") {
        Ok(_) => (),
        Err(e) => eprintln!("Failed to log compilation start: {}", e),
    }

    let command = Command::new("rustc")
        .arg("--out-dir")
        .arg(path)
        .arg("-Z")
        .arg("unstable")
        .output();

    match command {
        Ok(output) => {
            // Log end time and system information
            let end_time = Instant::now();
            let duration = Duration::between(start_time, end_time);
            let memory_usage = sys_info.memory().unwrap_or(0.0);

            match sys_info.log(log_verbosity, "Compilation finished") {
                Ok(_) => {
                    if log_verbosity > 1 {
                        println!("Duration: {} ms", duration.as_milliseconds());
                        println!("Memory usage: {:.2} GB", memory_usage / (1024.0 * 1024.0));
                    }
                }
                Err(e) => eprintln!("Failed to log compilation end: {}", e),
            }

            // Check for compilation errors
            if !output.status().is_success() {
                match sys_info.log(log_verbosity, "Compilation failed") {
                    Ok(_) => (),
                    Err(e) => eprintln!("Failed to log compilation failure: {}", e),
                }
                return output.status().code().unwrap_or(1);
            }

            // Log success and return exit code
            match sys_info.log(log_verbosity, "Compilation successful") {
                Ok(_) => ExitCode::from(output.status().code()),
                Err(e) => eprintln!("Failed to log compilation success: {}", e),
            }
        }
        Err(e) => {
            // Log failure and return error code
            match sys_info.log(log_verbosity, "Compilation failed due to command failure") {
                Ok(_) => ExitCode::from(e.raw_os_error().unwrap_or(1)),
                Err(f) => eprintln!("Failed to log compilation failure: {}", f),
            }
        }
    }

    ExitCode::from(0)
}
