function getUserDetailsAndResolveDomain($username) {
    $oauthClient = new OAuthClient('your_client_id', 'your_client_secret');
    $accessToken = $oauthClient->getAccessToken($username);

    if ($accessToken === false) {
        return ['error' => 'OAuth authentication failed'];
    }

    $_SESSION['access_token'] = $accessToken;

    // DNS resolution logic
    function resolveDomain($domain) {
        try {
            $dnsResponse = dns_get_record($domain);
            if (!empty($dnsResponse)) {
                return array_column($dnsResponse, 'ipAddress');
            }
        } catch (Exception $e) {
            return ['error' => 'DNS resolution failed: ' . $e->getMessage()];
        }

        return [];
    }

    // Dynamic DNS resolution with caching
    function getDomainIP($domain) {
        $cache = new SimpleCache();
        if ($cachedIP = $cache->get($domain)) {
            return $cachedIP;
        }

        try {
            $ipAddress = resolveDomain($domain);
            if (!empty($ipAddress)) {
                $cache->set($domain, $ipAddress);
                return $ipAddress;
            }
        } catch (Exception $e) {
            return ['error' => 'DNS resolution failed: ' . $e->getMessage()];
        }

        return [];
    }

    // OAuth and DNS resolution result
    if ($userDetails = json_decode($oauthClient->getUserDetails($accessToken), true)) {
        $domain = $userDetails['domain'];
        $ipAddress = getDomainIP($domain);

        if (!empty($ipAddress)) {
            return array_merge(['success' => 'User details and domain resolved'], $userDetails, ['domain' => $domain, 'ipAddress' => $ipAddress]);
        }
    }

    return ['error' => 'OAuth authentication or DNS resolution failed'];
}

