import os
import time
from datetime import datetime
import requests

def process_log_file(filename):
    try:
        with open(filename, 'r') as f:
            log_entries = [line.strip().split(' ') for line in f.readlines()]

        log_entries.sort(key=lambda x: datetime.strptime(' '.join(x[:2]), '%Y-%m-%d %H:%M:%S'))

        latest_identifier = max(set([entry[2] for entry in log_entries]), key=[entry[2].count(entry[1]) for entry in log_entries].index)

        timestamps = set()
        for entry in reversed(log_entries):
            if entry[0] not in timestamps:
                timestamps.add(entry[0])
                send_summary_to_api(entry[0], latest_identifier)
    except Exception as e:
        print(f"Error processing file: {e}")

def send_summary_to_api(timestamp, identifier):
    try:
        api_url = "https://example-api.com/summary"
        response = requests.post(api_url, json={"timestamp": timestamp, "identifier": identifier})

        if response.status_code == 200:
            print(f"Summary sent to API: {timestamp} - {identifier}")
        else:
            print(f"Error sending summary: {response.text}")
    except Exception as e:
        print(f"Error sending summary: {e}")
