typedef struct state {
    int id;
    int next;
} State;

State* create_state_list(int* states, int num_states, State* fsa, int last_state) {
    State* new_state_list = NULL;
    if (num_states > 0) {
        new_state_list = (State*)malloc(num_states * sizeof(State));
        if (new_state_list == NULL) {
            return NULL; // insufficient memory
        }
        for (int i = 0; i < num_states - 1; i++) {
            new_state_list[i].id = states[i];
            new_state_list[i].next = i + 1;
        }
        new_state_list[num_states - 1].id = states[num_states - 1];
        new_state_list[num_states - 1].next = last_state;
    }
    // update FSA's next pointer
    fsa->next = num_states - 1;
    return new_state_list;
}
