int lastAttack = -1;
int cooldown[5] = {0, 0, 0, 0, 0};
int currentCooldownIndex = 0;

void logAttack(int attack) {
    std::ofstream file("attack_log.txt", std::ios_base::app);
    if (file.is_open()) {
        file << "Attack selected: " << attack << "\n";
        file.close();
    }
}

int selectAttack() {
    int attack = 0;

    while (true) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1));

        if (lastAttack == -1 || lastAttack != currentCooldownIndex) {
            do {
                attack = rand() % 5;
            } while (attack == currentCooldownIndex);

            if (cooldown[attack] > 0) {
                continue;
            }

            break;
        }

        for (int i = 0; i < 5; i++) {
            if (i != lastAttack && cooldown[i] > 0) {
                do {
                    attack = rand() % 5;
                } while (attack == currentCooldownIndex || cooldown[attack] > 0);

                break;
            }
        }

        if (attack == -1) {
            continue;
        }

        lastAttack = attack;
        cooldown[attack]++;
    }

    std::cout << "Selected attack: " << attack << "\n";

    logAttack(attack);

    return attack;
}
