    {
        ValidateRange(minFloat, maxFloat, minInt, maxInt);
    }

    public void ValidateRange(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        if (minFloat > maxFloat || minInt > maxInt)
            throw new ArgumentException("Invalid range");
    }

    public float GenerateRandomFloat()
    {
        return (float)RandomValue(minFloat, maxFloat);
    }

    public int GenerateRandomInt()
    {
        return RandomValue(minInt, maxInt);
    }

    private int RandomValue(int min, int max)
    {
        Random rand = new Random();
        return rand.Next(min, max + 1);
    }

    public string ToString()
    {
        return $"Current range: [{_minFloat}, {_maxFloat}] for floats and [{_minInt}, {_maxInt}] for integers. Last 10 generated values: Floats - {string.Join(", ", _floatHistory.Take(10))}, Integers - {string.Join(", ", _intHistory.Take(10))}";
    }

    public List<float> GetFloatHistory()
    {
        return _floatHistory;
    }

    public List<int> GetIntHistory()
    {
        return _intHistory;
    }

    public void ResetHistory()
    {
        _floatHistory.Clear();
        _intHistory.Clear();
