class AggregationService extends EventEmitter {
  constructor({ maxRetryCount = 3, timeout = 1000, batchThreshold = 500 }) {
    super();
    this.maxRetryCount = maxRetryCount;
    this.timeout = timeout;
    this.batchThreshold = batchThreshold;
    this.aggregatedData = {};
    this.configured = false;
    this.emitter = new EventEmitter();
  }

  configure({ maxRetryCount, timeout, batchThreshold }) {
    if (this.configured) return;
    this.maxRetryCount = maxRetryCount;
    this.timeout = timeout;
    this.batchThreshold = batchThreshold;
    this.configured = true;
  }

  async processTransactions(transactions) {
    if (!Array.isArray(transactions)) throw new Error('Invalid input: transactions must be an array');

    const promises = [];
    for (const transaction of transactions) {
      if (!transaction.id || !transaction.amount || !transaction.currency || !transaction.timestamp)
        throw new Error('Invalid transaction data');
      if (transaction.amount <= 0) throw new Error('Transaction amount must be positive');

      const promise = promisify(() => this.processTransaction(transaction));
      promises.push(promise);
    }

    await Promise.all(promises);

    // Aggregate results
    for (const [currency, transactions] of Object.entries(this.aggregatedData)) {
      let totalAmount = 0;
      for (const transaction of transactions) {
        totalAmount += transaction.amount;
      }
      this.emitter.emit('aggregated', { currency, amount: totalAmount });
    }

    // Reset data
    this.aggregatedData = {};
  }

  async processTransaction(transaction) {
    try {
      if (!this.configured) throw new Error('Service not configured');

      // Validate transaction
      const isValid = await this.validateTransaction(transaction);
      if (!isValid) return;

      // Process transaction
      await this.processTransactionLogic(transaction);

      // Aggregate result
      const currency = transaction.currency;
      const amount = transaction.amount;
      if (!this.aggregatedData[currency]) this.aggregatedData[currency] = [];
      this.aggregatedData[currency].push({ ...transaction, amount });

    } catch (error) {
      // Handle error
      console.error('Error processing transaction:', error);
      await this.handleError(error, transaction);
    }
  }

