#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <crypto/cryptmd5.h>

typedef struct {
    char* filePath;
    int width;
    int height;
    int bitDepth;
    int numSamples;
    int* extraSampleBitDepths;
    uint8_t* md5Hash;
} tiffMetadata;

tiffMetadata parseTIFFAndHash(const char* filePath) {
    tiffMetadata metadata;

    TIFF *tif = TIFFOpen(filePath, "r");
    if (!tif) {
        // Handle error
        return (tiffMetadata){NULL, 0, 0, 0, 0, NULL, NULL};
    }

    int width = TIFFGetFieldAsShort(tif, TIFF_FIELD_IMAGE_WIDTH);
    int height = TIFFGetFieldAsShort(tif, TIFF_FIELD_IMAGE_LENGTH);

    // Initialize bit depth and number of samples
    int bitDepth = TIFFGetFieldAsLong(tif, TIFF_FIELD_BITSPERSAMPLE);
    int numSamples = TIFFGetFieldAsLong(tif, TIFF_FIELD_SAMPLES_PER_PIXEL);

    // Parse extra sample information
    uint16_t* extras;
    size_t extraCount = TIFFGetField(tif, TIFF_FIELD_EXTRASAMPLES, &extras);

    // Initialize bit depth array for extra samples
    int* extraSampleBitDepths = malloc(extraCount * sizeof(int));
    for (int i = 0; i < extraCount; i++) {
        extraSampleBitDepths[i] = extras[i].extraSamples.bitDepth;
    }

    // Compute MD5 hash
    uint8_t md5Hash[16];
    FILE* file = fopen(filePath, "rb");
    if (file) {
        fseek(file, 0L, SEEK_SET);
        size_t bytesRead = fread(md5Hash, sizeof(uint8_t), 1024, file);
        fclose(file);

        // Calculate MD5 hash
        md5_hash_ctx ctx;
        md5_init(&ctx);
        for (size_t i = 0; i < bytesRead; i++) {
            md5_update(&ctx, &md5Hash[i], 1);
        }
        md5_final(&ctx, md5Hash);
    } else {
        // Handle error
        return (tiffMetadata){NULL, 0, 0, 0, 0, NULL, NULL};
    }

    metadata.filePath = filePath;
    metadata.width = width;
    metadata.height = height;
    metadata.bitDepth = bitDepth;
    metadata.numSamples = numSamples;
    metadata.extraSampleBitDepths = extraSampleBitDepths;
    metadata.md5Hash = md5Hash;

    return metadata;
}
