#include <time.h>

char* generate_unique_filename(const char* original_filename) {
    int sequence_length = 0;
    for (int i = 0; i < strlen(original_filename); i++) {
        if ((original_filename[i] >= 'a' && original_filename[i] <= 'z') ||
            (original_filename[i] >= 'A' && original_filename[i] <= 'Z') ||
            (original_filename[i] >= '0' && original_filename[i] <= '9')) {
            sequence_length++;
        }
    }
    if (sequence_length < 5) {
        sequence_length = 5;
    }

    time_t current_time = time(NULL);
    char timestamp[26];
    strftime(timestamp, 25, "%Y%m%d%H%M%S", localtime(&current_time));

    int checksum = 0;
    for (int i = 0; i < sequence_length; i++) {
        checksum += original_filename[i] - 'a' + 1;
    }

    char* new_filename = malloc(strlen(original_filename) + strlen(timestamp) + sizeof(char) * (sequence_length + 2));
    if (!new_filename) {
        return NULL;
    }
    sprintf(new_filename, "%s_%*x_%*c", original_filename, sequence_length, &checksum, timestamp);
    return new_filename;
}
