AES_CTX *initializeAESCipherWithTheme(const char* password, const char* themeCachePath) {
    // Initialize SHA-1 hash context
    SHA_CTX shaCtx;
    SHA_Init(&shaCtx);

    // Calculate the encryption key from the user-provided password via a SHA-1 hash function
    unsigned char key[32];
    SHA_Update(&shaCtx, password, strlen(password));
    SHA_Final(key, &shaCtx);
    EVP_BytesToKey(NULL, NULL, &shaCtx, key, 20, 32, key, 32);

    // Initialize AES-256-CBC cipher context
    AES_CTX* aesCtx = malloc(sizeof(AES_CTX));
    if (!aesCtx) {
        return NULL;
    }

    // Set IV length to 16 bytes and key length to 32 bytes
    unsigned char iv[16] = {0};
    AES_set_encrypt_key(key, 32, &aesCtx->key);
    aesCtx->iv = iv;

    // Initialize theme cache management
    theme_cache_t* themeCache = malloc(sizeof(theme_cache_t));
    if (!themeCache) {
        free(aesCtx);
        return NULL;
    }

    // Check if the default theme directory is set; if not, initialize it with a specified default value
    if (!themeCache->defaultThemeDir) {
        themeCache->defaultThemeDir = "default_theme_dir";
    }

    // Parse PNG file from cache root directory and store it in the theme cache
    parse_png_file(themeCachePath, &themeCache);

    return aesCtx;
}

void freeAESCipher(AES_CTX* aesCtx) {
    if (aesCtx) {
        free(aesCtx->key);
        free(aesCtx);
    }
}

