using System;
using System.Security.Cryptography;
using System.Text;

public static class Base64DecryptionService
{
    public static string DecryptBase64String(string base64EncodedMessage, string key, string iv)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage))
            throw new ArgumentNullException(nameof(base64EncodedMessage));

        try
        {
            byte[] decodedBytes = Convert.FromBase64String(base64EncodedMessage);
            using MemoryStream ms = new MemoryStream(decodedBytes);
            using ICryptoTransform decryptor = TripleDES.CreateDecryptor(key, iv);

            using CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
            int bytesRead;
            byte[] decryptedBytes = new byte[decodedBytes.Length];
            using (MemoryStream msDecrypted = new MemoryStream())
            {
                using (CryptoStream csDecrypted = new CryptoStream(msDecrypted, decryptor, CryptoStreamMode.Write))
                {
                    while ((bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length)) > 0)
                    {
                        csDecrypted.Write(decryptedBytes, 0, bytesRead);
                    }
                }
            }

            return Encoding.UTF8.GetString(msDecrypted.ToArray());
        }
        catch (FormatException ex)
        {
            throw new ArgumentException("Invalid Base64 encoding", nameof(base64EncodedMessage), ex);
        }
        catch (Exception ex)
        {
            throw new ArgumentException("Failed to decrypt the message", nameof(base64EncodedMessage), ex);
        }
    }
}
