            throw new ArgumentNullException("Input parameters cannot be null");

        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;

        using var decryptor = aes.CreateDecryptor();

        try
        {
            using var memoryStream = new MemoryStream(ciphertext);
            using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);

            byte[] plaintext = new byte[cryptoStream.Length];
            int bytesRead = cryptoStream.Read(plaintext, 0, plaintext.Length);

            return plaintext;
        }
        catch (CryptographicException ex)
        {
            _logger.LogError(ex, "Error during decryption");
            return null; // Return partial decryption or error message
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error during decryption");
            return null; // Return partial decryption or error message
