                compressionAlgorithm = "zlib";

            switch (compressionAlgorithm.ToLower())
            {
                case "zlib":
                    return ZLibLoadAndDeserialize(stream);
                default:
                    throw new ArgumentException("Unsupported compression algorithm");
            }
        }
