import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.Map;

public class CustomDeserializer {
    private static Map<String, Class<?>> cachedClasses = new HashMap<>();

    public Object deserialize(byte[] bytes, String className) throws Exception {
        try {
            ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
            return deserialize(bis, className);
        } catch (IOException | ClassNotFoundException e) {
            // Log a warning message and return null
            System.out.println("Warning: Deserialization failed for class " + className);
            return null;
        }
    }

    private Object deserialize(ByteArrayInputStream bis, String className) throws IOException, ClassNotFoundException {
        Class<?> clazz = cachedClasses.computeIfAbsent(className, this::loadClass);

        // Read the byte array
        ObjectInputStream ois = new ObjectInputStream(bis);
        try {
            return clazz.getConstructor().newInstance(ois.readObject());
        } catch (InstantiationException | IllegalAccessException e) {
            // Log an error message and rethrow exception
            System.out.println("Error: Unable to instantiate object of class " + className);
            throw e;
        }
    }

    private Class<?> loadClass(String className) throws ClassNotFoundException, Exception {
        try {
            return Class.forName(className);
        } catch (ClassNotFoundException e) {
            // Handle legacy data formats or third-party libraries
            // ...
        }

        // If the class is not found, consider raising an exception or providing a default implementation
        // ...
    }
}
