// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
void* manageArray(void* arg) {
    // Get the number of threads and the URL from the argument
    int numThreads = *(int*)arg;
    char* url = (char*)malloc(strlen(arg) + 1);
    strcpy(url, arg);

    // Initialize the dynamic array with a default size
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numThreads * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; i++) {
        // Initialize the structure with random CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T* structInstance = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        structInstance->RX_UE_INFORMATION_TAG = rand();
        structInstance->RNTI = rand();
        structInstance->CRC_INDICATION_REL8_TAG = rand();
        structInstance->CRCFLAG = rand() % 2;

        // Add the structure to the array
        array[i] = structInstance;
    }

    // Create threads and upload files concurrently
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, uploadFile, url);
    }

    // Wait for all threads to finish
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated by the dynamic array and its structures
    for (int i = 0; i < numThreads; i++) {
        free(array[i]);
    }
    free(array);

    return NULL;
}

// Function to upload a file given a URL using libcurl
void* uploadFile(void* arg) {
    // Get the URL from the argument
    char* url = (char*)arg;

    // Initialize and set up libcurl
    CURL* curl;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        // Set the URL to upload
        curl_easy_setopt(curl, CURLOPT_URL, url);

        // Perform the transfer
        CURLcode res = curl_easy_perform(NULL);

        // Check for errors
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        // Clean up
        curl_easy_cleanup();
    }
    else {
        printf("curl_easy_init() failed!\n");
    }

    return NULL;
}

// Function to validate the integrity of the array
void validateArray(NFAPI_CRC_INDICATION_PDU_T** array, int numElements) {
    for (int i = 0; i < numElements; i++) {
        // Check if the structure is not NULL and its fields are initialized correctly
        if(array[i] != NULL && array[i]->RX_UE_INFORMATION_TAG > 0 &&
           array[i]->RNTI > 0 && array[i]->CRC_INDICATION_REL8_TAG > 0 &&
           (array[i]->CRCFLAG == 0 || array[i]->CRCFLAG == 1)) {
            printf("Array element %d is valid.\n", i);
        }
        else {
            printf("Error: Array element %d is not valid.\n", i);
        }
    }

    return;
}

