const { ChildProcess, spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const { EventEmitter } = require('events');

class ShellCommandExecutor {
  constructor(cacheExpirationTime) {
    this.cache = {};
    this.events = new EventEmitter();
    this.cacheExpirationTime = cacheExpirationTime;
  }

  execute(commands, callback) {
    const promises = [];
    for (const command of commands) {
      if (!this.cache[command]) {
        this.cache[command] = { promise: null, timeout: null };
      }
      if (!this.cache[command].promise || Date.now() - this.cache[command].timeout > this.cacheExpirationTime) {
        const promise = new Promise((resolve, reject) => {
          const childProcess = spawn('bash', ['-c', command]);
          let output = '';
          childProcess.stdout.on('data', (data) => {
            output += data.toString();
          });
          childProcess.stderr.on('data', (data) => {
            console.error(`Error: ${data.toString()}`);
          });
          childProcess.on('close', () => {
            if (childProcess.exitCode === 0) {
              resolve(output);
            } else {
              reject(new Error(`Command failed with exit code ${childProcess.exitCode}`));
            }
          });
        });
        promises.push(promise);
        this.cache[command].promise = promise;
      } else {
        promises.push(this.cache[command].promise);
      }
    }
    Promise.all(promises)
      .then((results) => callback(null, results.join('\n')))
      .catch((error) => callback(error));
  }

  on(event, listener) {
    this.events.on(event, listener);
  }

  log(message) {
    console.log(message);
  }

  monitor() {
    setInterval(() => {
      for (const command in this.cache) {
        if (!this.cache[command].promise || Date.now() - this.cache[command].timeout > this.cacheExpirationTime) {
          this.cache[command] = { promise: null, timeout: null };
        }
      }
    }, 10000);
  }
}

module.exports = ShellCommandExecutor;
