    pub fn manage_config_file(&self, file_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
        config_manager::ConfigManager::new().manage_file(file_path)?;
        Ok(())
    }

    // Leverage dependency injection to decouple configuration management from the core application logic
    pub fn get_module_dir(&self, module_name: &str) -> Option<&Path> {
        self.module_dirs.iter().find(|module| module.file_name() == module_name)
    }
}

fn env_var_or_arg(name: &str, default: &str) -> Result<String, Box<dyn std::error::Error>> {
