#include <time.h>

int find_largest_rnti(int **rntis, int size) {
    int max_rnti = rntis[0][0];
    for (int i = 1; i < size; i++) {
        if (rntis[i][0] > max_rnti) {
            max_rnti = rntis[i][0];
        }
    }
    return max_rnti;
}

void read_and_filter(int **rntis, int *size) {
    FILE *fp = stdin;
    srand(time(NULL)); // seed for reproducibility

    *size = 0;

    int current_size = 10; // initialize array size
    *rntis = (int **)malloc(current_size * sizeof(int *));
    for (int i = 0; i < current_size; i++) {
        (*rntis)[i] = (int *)malloc(sizeof(int));
    }

    int valid_count = 0;
    while (1) {
        int input;
        if (fscanf(fp, "%d", &input) != 1) {
            break;
        }
        if (input < 0 || input > 1000000) { // filter out invalid inputs
            continue;
        }
        (*rntis)[valid_count][0] = input;
        valid_count++;
        if (valid_count == current_size) {
            int *temp = (int *)malloc((current_size + 10) * sizeof(int *));
            for (int i = 0; i < current_size; i++) {
                temp[i] = (*rntis)[i];
            }
            free(*rntis);
            *rntis = temp;
            current_size += 10;
        }
    }

    if (valid_count > 0) {
        int *temp = (int *)malloc((valid_count + 1) * sizeof(int *));
        for (int i = 0; i < valid_count; i++) {
            temp[i] = (*rntis)[i][0];
        }
        temp[valid_count] = -1;
        free(*rntis);
        *rntis = temp;
        *size = valid_count;
    } else {
        *size = 0;
        free(*rntis);
        *rntis = NULL;
    }
}

int main() {
    int *rntis = NULL;
    int size = 0;

    read_and_filter(&rntis, &size);

    if (size > 0) {
        printf("Largest RNTI: %d\n", find_largest_rnti(&rntis, size));
    } else {
        printf("No valid RNTIs found.\n");
    }

    for (int i = 0; i < size; i++) {
        free(rntis[i]);
    }
    free(rntis);

    return 0;
}
