    // Dynamically allocate memory for arrays
    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));
    int* keys = (int*)malloc(num_records * sizeof(int));
    long* offsets = (long*)malloc(num_records * sizeof(long));

    if (!records || !keys || !offsets) {
        free(records);
        free(keys);
        free(offsets);
        return -1; // Memory allocation failed
    }

    // Initialize records with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int key = rand() % (max_value - min_value + 1) + min_value;
        long offset = (long)rand() % ((long)~0 >> 31);
        records[i].key = key;
        records[i].offset = offset;
    }

