import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;

public class ConnectionManager {
    // Method to establish a connection to a remote address using a Java Channel
    public void connect(InetSocketAddress remoteAddress) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        Selector selector = Selector.open();

        // Set up the socket channel and selector
        channel.bind(new InetSocketAddress(0));
        channel.connect(remoteAddress);
        channel.register(selector, SelectionKey.OP_CONNECT);

        // Handle connection state changes
        while (true) {
            try {
                selector.select();
                SelectionKey key = selector.selectedKey();
                if (key.isValid() && key.isConnectNowSupported()) {
                    channel.finishConnect();

                    // Handle the connected state
                    System.out.println("Connected to " + remoteAddress);

                    // Close the socket when done
                    channel.close();
                }
            } catch (IOException e) {
                // Handle connection errors
                System.out.println("Error connecting to " + remoteAddress);
                // Reconnect with exponential backoff
                reconnect(selector, channel, remoteAddress);
            }
        }
    }

    // Method to reconnect on failure with exponential backoff
    private void reconnect(Selector selector, SocketChannel channel, InetSocketAddress remoteAddress) {
        long timeout = 1000; // Initial delay in milliseconds

        while (true) {
            try {
                Thread.sleep(timeout);

                // Attempt to reconnect
                connect(remoteAddress);

                return;
            } catch (IOException | InterruptedException e) {
                // Increase the delay for the next attempt
                timeout *= 2;

                if (timeout > 30000) { // Maximum delay in milliseconds
                    System.out.println("Maximum connection attempts reached.");
                    break;
                }
            }
        }
    }
}
