    if (!ptr) {
        fprintf(stderr, "Memory allocation failed!\n");
        return NULL;
    }
    return ptr;
}

int main() {
    int max_events = 1000; // adjust this value based on performance requirements
    int max_timestamps = 10000; // adjust this value based on precision threshold

    double *sensor_readings = malloc_safe(max_events * sizeof(double));
    time_t *timestamps = malloc_safe(max_events * sizeof(time_t));

    event *events = malloc_safe(max_events * sizeof(event));
    event *head = NULL;
    event *tail = NULL;

    for (int i = 0; i < max_events; i++) {
        sensor_readings[i] = rand() / (double)RAND_MAX;
        timestamps[i] = time(NULL);
        events[i].timestamp = timestamps[i];
        events[i].message[0] = 'I'; // initialize with "INFO" message
        strcpy(events[i].message + 1, " - Random sensor reading");

        if (i > 0 && timestamps[i] == timestamps[i - 1]) {
            fprintf(stderr, "Duplicate timestamp detected!\n");
        }

        event *new_event = malloc_safe(sizeof(event));
        new_event->timestamp = events[i].timestamp;
        strcpy(new_event->message, events[i].message);

        if (head == NULL) {
            head = new_event;
            tail = new_event;
        } else {
            tail->next = new_event;
            tail = new_event;
        }
    }

    // validate timestamps for uniqueness within the specified time window
    for (event *curr = head; curr != NULL; curr = curr->next) {
        if (curr->timestamp < time(NULL) - 60) { // adjust this value based on time window
            fprintf(stderr, "Timestamp is outdated!\n");
        }
    }

    free(sensor_readings);
    free(timestamps);

    event *curr_event = head;
    while (curr_event != NULL) {
        if (curr_event->timestamp < time(NULL) - 60) { // adjust this value based on time window
            fprintf(stderr, "Timestamp is outdated!\n");
        }
        curr_event = curr_event->next;
    }

    return 0;
}
