#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    int key;
    int value;
} record;

// Define a hash table structure
typedef struct {
    size_t size;
    record** records;
    pthread_mutex_t lock;
} hashtable;

// Initialize the hash table
hashtable* initialize_hashtable(size_t capacity) {
    hashtable* table = (hashtable*)malloc(sizeof(hashtable));
    table->size = capacity;
    table->records = (record**)calloc(capacity, sizeof(record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Hash function to calculate the index of a record
size_t hash_function(int key) {
    return key % 256; // Simple linear probing for demonstration purposes
}

// Check if a key exists in the hash table
int exists(hashtable* table, int key) {
    size_t index = hash_function(key);
    while (table->records[index] && table->records[index]->key != key) {
        index = (index + 1) % table->size;
    }
    return table->records[index] ? 0 : 1; // Return 1 if not found, 0 otherwise
}

// Insert a record into the hash table
int insert_record(hashtable* table, int key, int value) {
    size_t index = hash_function(key);
    while (table->records[index]) {
        index = (index + 1) % table->size;
    }
    table->records[index] = (record*)malloc(sizeof(record));
    table->records[index]->key = key;
    table->records[index]->value = value;
    return 0; // Success
}

// Validate the uniqueness of keys in the hash table
int validate_keys(hashtable* table) {
    for (size_t i = 0; i < table->size; i++) {
        if (table->records[i] && exists(table, table->records[i]->key)) {
            printf("Duplicate key found: %d\n", table->records[i]->key);
            return -1; // Error
        }
    }
    return 0; // Success
}

// Release all allocated resources on failure
void release_resources(hashtable* table) {
    for (size_t i = 0; i < table->size; i++) {
        if (table->records[i]) {
            free(table->records[i]);
        }
    }
    free(table);
}

int main() {
    // Initialize the hash table with a capacity of 1024
    hashtable* table = initialize_hashtable(1024);

    // Insert records into the hash table
    insert_record(table, 1, 10);
    insert_record(table, 2, 20);
    insert_record(table, 3, 30);

    // Validate the uniqueness of keys
    if (validate_keys(table) < 0) {
        release_resources(table);
        return -1; // Error
    }

    // Clean up
    for (size_t i = 0; i < table->size; i++) {
        if (table->records[i]) {
            free(table->records[i]);
        }
    }
    free(table);

    return 0;
}

