void* generateNfareport(void* arg) {
    int numEntries = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* nfaPDUArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    srand(time(NULL));

    for(int i=0; i<numEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = rand() % 1000000; // Random RNTI
        pdu.crcflag = rand() % 2; // Random CRC flag (0 or 1)
        nfaPDUArray[i] = pdu;
    }

    int startTime = clock();
    pthread_exit(NULL);
}

int calculateDisjointPairs(NFAPI_CRC_INDICATION_PDU_T* array, int numEntries) {
    int disjointPairs = 0;

    // Union-Find data structure
    int* parent = (int*)malloc(numEntries * sizeof(int));
    int* rank = (int*)malloc(numEntries * sizeof(int));

    for(int i=0; i<numEntries; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    for(int i=0; i<numEntries; i++) {
        for(int j=i+1; j<numEntries; j++) {
            if(array[i].rnti != array[j].rnti) {
                int root1 = find(parent, array[i].rnti);
                int root2 = find(parent, array[j].rnti);

                if(root1 != root2) {
                    unionSets(parent, rank, root1, root2);
                    disjointPairs++;
                }
            }
        }
    }

    free(parent);
    free(rank);

    return disjointPairs;
}

int find(int* parent, int value) {
    if(parent[value] != value) {
        parent[value] = find(parent, parent[value]);
    }
    return parent[value];
}

void unionSets(int* parent, int* rank, int x, int y) {
    int rootX = find(parent, x);
