public class SessionIdentifierProcessor
{
    public async Task<List<string>> ProcessSessions(string filePath, string eventType)
    {
        List<string> uniqueSessionIds = new List<string>();

        await using (StreamReader reader = File.OpenText(filePath))
        {
            string line;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                try
                {
                    dynamic jsonData = JsonConvert.DeserializeObject(line);
                    if (!jsonData.eventType.ToString().Equals(eventType, StringComparison.OrdinalIgnoreCase)) continue;

                    string sessionId = jsonData.sessionId;
                    if (string.IsNullOrEmpty(sessionId)) continue;

                    if (!uniqueSessionIds.Contains(sessionId))
                        uniqueSessionIds.Add(sessionId);
                }
                catch { } // Handle potential null or malformed JSON
            }
        }

        return uniqueSessionIds.Distinct().ToList();
    }
}
