import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVParser;
import org.apache.commons.csv.CSVPrinter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

public class CSVFilter {

    private static final Logger logger = LoggerFactory.getLogger(CSVFilter.class);

    public enum ProcessingMode {
        BATCH, STREAM
    }

    public void filterCSV(String inputFile, String outputFile, Predicate<String[]> predicate, ProcessingMode mode) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(inputFile));
             BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile))) {

            CSVParser parser = CSVFormat.DEFAULT.parse(reader);
            CSVPrinter printer = CSVFormat.DEFAULT.printer(writer);

            if (mode == ProcessingMode.BATCH) {
                filterInChunks(parser, printer, predicate);
            } else if (mode == ProcessingMode.STREAM) {
                filterAsStream(parser, printer, predicate);
            }
        }
    }

    private void filterInChunks(CSVParser parser, CSVPrinter printer, Predicate<String[]> predicate) throws IOException {
        List<List<String>> chunks = new ArrayList<>();
        int chunkSize = 10000; // adjust to your needs

        for (CSVFormat.FormatRecord record : parser.getRecords()) {
            if (chunks.size() * chunkSize >= parser.getRecordCount()) {
                processChunk(chunks, printer, predicate);
                chunks.clear();
            }
            chunks.add(record.toLineArray());
        }

        if (!chunks.isEmpty()) {
            processChunk(chunks, printer, predicate);
        }
    }

    private void filterAsStream(CSVParser parser, CSVPrinter printer, Predicate<String[]> predicate) throws IOException {
        parser.forEach((record) -> {
            String[] row = record.toLineArray();
            if (predicate.test(row)) {
                printer.printRecord(record);
            } else {
                logger.info("Filtered out: {}", row);
            }
        });
    }

    private void processChunk(List<List<String>> chunk, CSVPrinter printer, Predicate<String[]> predicate) throws IOException {
        for (List<String> record : chunk) {
            if (predicate.test(record.toArray(new String[0]))) {
                printer.printRecord(CSVFormat.DEFAULT.parseRecord(record));
            } else {
                logger.info("Filtered out: {}", record);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        CSVFilter filter = new CSVFilter();
        filter.filterCSV("input.csv", "output.csv", (row) -> row[0].equals("desired_value"), ProcessingMode.BATCH);
    }
}
