class CombatUnit {
public:
    // Constructor
    CombatUnit() : cooldown_time_(500), log_size_(500) {}

    // Add a new skill with unique identifier and cooldown duration
    void addSkill(const std::string& id, int cooldown_duration) {
        skills_[id] = Cooldown(cooldown_duration);
    }

    // Use a specific skill
    bool useSkill(const std::string& id) {
        if (skills_.find(id) == skills_.end()) return false;  // Skill not found
        auto& cooldown = skills_[id];
        if (!cooldown.ready_) return false;  // Skill is on cooldown

        // Reset cooldown and log usage
        cooldown.reset();
        log_.push({id, std::chrono::high_resolution_clock::now()});
        if (log_.size() > log_size_) {
            auto oldest = log_.front();  // Remove oldest entry
            log_.pop();
            oldest.second = std::chrono::time_point<std::chrono::system_clock>();
        }
        return true;
    }

    // Check if a skill is ready to use
    bool canUseSkill(const std::string& id) {
        if (skills_.find(id) == skills_.end()) return false;  // Skill not found
        auto& cooldown = skills_[id];
        return !cooldown.ready_;
    }

private:
    struct Cooldown {
        int duration_{};
        bool ready_ = true;
        void reset() { std::this_thread::sleep_for(std::chrono::seconds(duration_)); ready_ = false; }
    };

    std::map<std::string, Cooldown> skills_;
    std::queue<std::pair<std::string, std::chrono::time_point<std::chrono::system_clock>>> log_;
    int cooldown_time_, log_size_;
};

