typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct node* next;
} Node;

Node* create_node(int rnti) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->data->RX_UE_INFORMATION_TAG = 1;
    new_node->data->RNTI = rnti;
    srand(time(NULL));
    if (rand() % 2) {
        new_node->data->CRCFLAG = 0;
    } else {
        new_node->data->CRCFLAG = 1;
    }
    return new_node;
}

void free_node(Node* node) {
    free(node->data);
    free(node);
}

Node* insert_node(Node** head, int rnti) {
    Node* new_node = create_node(rnti);
    if (*head == NULL || rnti > (*head)->data->RNTI) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->data->RNTI >= rnti)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
    return *head;
}

void print_largest_RNTI(Node* head) {
    Node* max_rnti_node = head;
    while (max_rnti_node->next) {
        if (max_rnti_node->data->RNTI < max_rnti_node->next->data->RNTI)
            max_rnti_node = max_rnti_node->next;
    }
    printf("Largest RNTI: %d\n", max_rnti_node->data->RNTI);
}

int main() {
    Node* head = NULL;
    int rnti;
    while (scanf("%d", &rnti) == 1) {
        insert_node(&head, rnti);
    }
    print_largest_RNTI(head);
    while (head) {
        free_node(head);
        head = head->next;
    }
    return 0;
}
