    long *offsets = (long *)malloc(max_size * sizeof(long));
    int *keys = (int *)malloc(max_size * sizeof(int));
    record *records = (record *)malloc(max_size * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
