    pthread_mutex_t lock;

    // Initialize the lock
    if (pthread_mutex_init(&lock, NULL) != 0) {
        // Handle initialization failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Define a function to load and execute tests
    void (*f)(void);

    // Load the user-provided module
