    }

    int* keys = (int*) malloc(num_records * sizeof(int));
    if (!keys) return -2; // Error allocating memory

    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (max_range - min_range + 1) + min_range;
    }

    record* records = (record*) malloc(num_records * sizeof(record));
    if (!records) return -3; // Error allocating memory

    for (int i = 0; i < num_records; i++) {
