    if (sem == SEM_FAILED) {
        perror("sem_open");
        return -1;
    }

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structures
    struct NFAPI_CRC_INDICATION_PDU_T *nfa_data_list_head = NULL;
    int nfa_data_count = 0;

    while (1) {
        sem_wait(sem);
        if (nfa_data_count >= 1000) break; // Limit the number of NFAPI_CRC_INDICATION_PDU_T structures for demonstration purposes
        struct NFAPI_CRC_INDICATION_PDU_T *new_nfa_data = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!new_nfa_data) {
            sem_post(sem);
            return -1;
        }

        new_nfa_data->RX_UE_INFORMATION_TAG = rand() % 1000;
        new_nfa_data->RNTI = rand() % 1000;
        new_nfa_data->CRCFLAG = (rand() & 1) ? 1 : 0; // Randomly set CRCFLAG

        if (!nfa_data_list_head) {
            nfa_data_list_head = new_nfa_data;
        } else {
            struct NFAPI_CRC_INDICATION_PDU_T *last_nfa_data = nfa_data_list_head;
            while (last_nfa_data->RX_UE_INFORMATION_TAG > 0) last_nfa_data = last_nfa_data->next;
            last_nfa_data->next = new_nfa_data;
        }
        nfa_data_count++;

        sem_post(sem);
    }

    *nfa_data_list = nfa_data_list_head;

    // Clean up allocated resources and semaphore
    while (nfa_data_list_head) {
        struct NFAPI_CRC_INDICATION_PDU_T *temp = nfa_data_list_head;
        nfa_data_list_head = nfa_data_list_head->next;
        free(temp);
    }
    sem_close(sem);

    return 0;
}
