#define MAX_LIST_SIZE 100
#define THRESHOLD 75

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* list = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0;
int threshold = THRESHOLD;

void manage_list(int new_element) {
    pthread_mutex_lock(&lock);
    if (list == NULL) {
        list = malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*) list;
    for (int i = 0; i < list_size; i++) {
        if (current[i].RX_UE_INFORMATION_TAG == new_element) {
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    if (list_size >= MAX_LIST_SIZE) {
        printf("List is full, cannot add more elements.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    current[list_size].RX_UE_INFORMATION_TAG = new_element;
    current[list_size].RNTI = rand() % 1000 + 1;
    sprintf(current[list_size].CRC_INDICATION_REL8_TAG, "REL%02d", list_size + 1);
    current[list_size].CRCFLAG = rand() % 2;
    list_size++;
    pthread_mutex_unlock(&lock);

    if (list_size >= threshold) {
        printf("List has reached the threshold, notification sent.\n");
    }
}

void print_list() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < list_size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: %d\n",
               ((NFAPI_CRC_INDICATION_PDU_T*)list)[i].RX_UE_INFORMATION_TAG,
               ((NFAPI_CRC_INDICATION_PDU_T*)list)[i].RNTI,
               ((NFAPI_CRC_INDICATION_PDU_T*)list)[i].CRC_INDICATION_REL8_TAG,
               ((NFAPI_CRC_INDICATION_PDU_T*)list)[i].CRCFLAG);
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));
    manage_list(1);
    manage_list(2);
    manage_list(3);
    print_list();
    return 0;
}
