['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure for a node in the dynamic linked list
typedef struct {
    int key;
    struct item *item_list;
    char *desc;
} Node;

// Structure for an item within a node's item list
typedef struct {
    int data;
} Item;

// Function prototypes
Node* create_node(int, char *);
void free_node(Node *);
Item* create_item(int);
void free_item(Item *);
void insert_node(Node **, int, char *, int);
int retrieve_node(Node *, int);
void print_list(Node *);

int total_items = 0;

// Create a new node with the given key, description, and item list
Node* create_node(int key, char *desc) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->key = key;
    node->item_list = NULL;
    node->desc = desc;
    total_items += 1; // Increment the total item count
    return node;
}

// Free a node and all its items
void free_node(Node *node) {
    if (!node) return;
    if (node->item_list) {
        Item *item = node->item_list;
        while (item) {
            Item *next_item = item->next;
            free_item(item);
            item = next_item;
        }
    }
    free(node->desc);
    free(node);
}

// Create a new item with the given data
Item* create_item(int data) {
    Item *item = (Item *)malloc(sizeof(Item));
    if (!item) return NULL;
    item->data = data;
    return item;
}

// Free an item
void free_item(Item *item) {
    if (!item) return;
    free(item);
}

// Insert a new node with the given key, description, and item list into the dynamic linked list
void insert_node(Node **head, int key, char *desc, int num_items) {
    Node *new_node = create_node(key, desc);
    if (*head) {
        // Insert at the end of the list
        Node *current = *head;
        while (current->next) current = current->next;
        current->next = new_node;
    } else {
        *head = new_node;
    }
    for (int i = 0; i < num_items; i++) {
        Item *new_item = create_item(i);
        if (!(*head)->item_list) (*head)->item_list = new_item;
        else {
            Node *current = *head;
            while (current->next) current = current->next;
            current->next->item_list = new_item;
        }
    }
}

// Retrieve the item with the given key from a node
int retrieve_node(Node *node, int key) {
    if (!node) return -1; // Return error code for invalid operation
    Node *current = node;
    while (current) {
        Item *item = current->item_list;
        while (item) {
            if (item->data == key) return item->data;
            item = item->next;
        }
        current = current->next;
    }
    return -1; // Return error code for invalid operation
}

// Print the dynamic linked list with node keys and descriptions
void print_list(Node *head) {
    Node *current = head;
    while (current) {
        printf("Node %d: %s\n", current->key, current->desc);
        Item *item = current->item_list;
        while (item) {
            printf("  Item: %d\n", item->data);
            item = item->next;
        }
        current = current->next;
    }
}
