typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head == NULL || memcmp(&(*head)->data, &new_node->data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) > 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && memcmp(&current->next->data, &new_node->data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) > 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    if (*head == NULL) {
        return;
    }
    if (memcmp(&(*head)->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }
    Node* current = *head;
    while (current->next && memcmp(&current->next->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        current = current->next;
