void add_event(time_t timestamp, const char* category) {
    // check if the timestamp is within the time window
    if (timestamp <= events[num_events - 1].timestamp + TIME_WINDOW) {
        // duplicate entry, handle error
    }
    Event* new_event = create_event(timestamp, category);
    if (!new_event) {
        // handle error
    }
