typedef struct {
    double d;
    char *s;
    int i;
} data_t;

data_t* create_node() {
    data_t *node = (data_t*)malloc(sizeof(data_t));
    if (!node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    node->d = 0.0; // Initialize with default values
    node->s = NULL;
    node->i = 0;
    return node;
}

void free_node(data_t *node) {
    if (node) {
        free(node);
    }
}

data_t* init_linked_list(int n) {
    data_t *head = NULL;
    for (int i = 0; i < n; i++) {
        data_t *node = create_node();
        char str[129]; // Ensure null-termination and extra space
        // Generate random string, double, and int values
        srand(time(NULL) + i); // Vary seed for randomness
        sprintf(str, "%c%c%c", 'a' + rand() % 26, 'a' + rand() % 26, 'a' + rand() % 26);
        node->s = (char*)malloc(strlen(str) + 1);
        strcpy(node->s, str);
        node->d = (double)rand() / RAND_MAX;
        node->i = rand() % 100;
        // Link the new node to the list
        if (!head) {
            head = node;
        } else {
            data_t *current = head;
            while (current->s != NULL) {
                current = current->s;
            }
            current->s = node;
        }
    }
    return head;
}

void free_linked_list(data_t *head) {
    for (data_t *node = head; node != NULL; ) {
        data_t *next = node->s;
        free_node(node);
        node = next;
    }
}
