#include <mysql.h>
#include <string.h>

#define DB_HOST "localhost"
#define DB_USER "username"
#define DB_PASSWORD "password"
#define DB_NAME "database"

MYSQL* connect_to_db() {
    MYSQL *conn;
    conn = mysql_init(NULL);

    if(conn == NULL) {
        printf("Error initializing database connection.\n");
        return NULL;
    }

    if(mysql_real_connect(conn, DB_HOST, DB_USER, DB_PASSWORD, DB_NAME, 0, NULL, 0) < 0) {
        fprintf(stderr, "Error connecting to the database: %s\n", mysql_error(conn));
        return NULL;
    }

    return conn;
}

void execute_query(MYSQL* conn, char* query) {
    MYSQL_RES *result;
    MYSQL_ROW row;

    if(mysql_query(conn, query)) {
        printf("Error executing query: %s\n", mysql_error(conn));
    } else {
        result = mysql_use_result(conn);

        while((row = mysql_fetch_row(result)) != NULL) {
            printf("%s ", row[0]);
            for(int i = 1; i < mysql_num_fields(result); i++) {
                printf("%s ", row[i]);
            }
            printf("\n");
        }
    }

    mysql_free_result(result);
}

int main() {
    MYSQL* conn;

    conn = connect_to_db();

    if(conn != NULL) {
        char query[256];
        sprintf(query, "SELECT name, city, address FROM Employees WHERE supervisor_id = %d", 123);

        execute_query(conn, query);

        mysql_close(conn);
    }
}
