int process_file(char *file_name, char *output_file_name, int max_size, int timeout) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int pdu_count = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        // Dynamically allocate memory for the current NFAPI CRC indication PDU
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current_pdu) {
            // Handle memory allocation failure and log error
            perror("Memory allocation failed");
            return -1;
        }

        // Initialize the CRC flag based on a pseudo-random number generator seeded with the provided integer
        current_pdu->CRCFLAG = (rand() % 2);

        // Add the new pdu to the array, ensuring thread safety using the mutex
        pthread_mutex_lock(&mutex);
        if (pdu_count >= max_size) {
            // If the array exceeds the maximum size, log the current size and retain only the most recent entries
            printf("Array exceeded maximum size of %d. Retaining only the most recent entries.\n", max_size);
            pdu_array = realloc(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (max_size - 1));
            pdu_count = max_size - 1;
        }
        pdu_array = realloc(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (++pdu_count));
        memcpy(&pdu_array[pdu_count - 1], current_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&mutex);

        // Convert the JPEG file to PDF and handle potential failures
        if (jpeg_to_pdf_converter(file_name, output_file_name) != 0) {
            // Handle conversion failure and log error
            perror("JPEG to PDF conversion failed");
            free(current_pdu);
            return -1;
        }

        free(current_pdu);

        // Check for timeout
        if (timeout > 0 && pdu_count >= max_size) {
            pthread_mutex_lock(&mutex);
            // If the array exceeds the maximum size and the timeout is reached, log the current size and retain only the most recent entries
            printf("Array exceeded maximum size of %d after %d iterations. Retaining only the most recent entries.\n", max_size, timeout);
            pdu_array = realloc(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (max_size - 1));
            pdu_count = max_size - 1;
            pthread_mutex_unlock(&mutex);
        }
    }

    return 0;
}
