typedef struct {
    double val;
    char str[128];
    extended_data ed;
} data_node;

data_node* init_list(int n) {
    srand(time(NULL));
    data_node* head = NULL;
    for (int i = 0; i < n; i++) {
        data_node* node = malloc(sizeof(data_node));
        if (!node) {
            fprintf(stderr, "Memory allocation failed!\n");
            return NULL;
        }
        node->val = ((double)rand() / RAND_MAX);
        char str[128];
        int j = 0;
        while (j < 127 && rand() % 2) j++;
        str[j] = '\0';
        strcpy(node->str, str);
        node->ed.d = ((double)rand() / RAND_MAX);
        node->ed.i = rand() % 100;
        if (!validate_str(node->str)) {
            free(node);
            i--;
            continue;
        }
        head = (head ? head : node);
        while (head) {
            data_node* temp = head;
            head = head->next;
            free(temp);
        }
        head = node;
    }
    return head;
}

int validate_str(char* str) {
    if (!str || strlen(str) > 127) return 0;
    int i = 0, valid = 1;
    while (str[i] && i < 127) {
        if (!isalnum((unsigned char)str[i])) valid = 0;
        i++;
    }
    return valid;
}
