    list->max_size = max_size;
    list->list = (GTPv2_Path_Status_Indication*)malloc(max_size * sizeof(GTPv2_Path_Status_Indication));
    return list;
}

void gtpv2_path_status_list_free(GTPv2_Path_Status_List* list) {
