int gtpv2_path_status_list_add(GTPv2_Path_Status_List* list, uint32_t teid, uint16_t pdp_context_id, uint8_t path_status_indication) {
    if (list->size >= list->max_size) {
        // List is full, free the oldest entry
        GTPv2_Path_Status_Indication* oldest = &list->list[0];
        for (int i = 1; i < list->size; i++) {
            oldest = &list->list[i];
        }
        teid = oldest->teid;
        pdp_context_id = oldest->pdp_context_id;
        path_status_indication = oldest->path_status_indication;
    }
    list->list[list->size].teid = teid;
    list->list[list->size].pdp_context_id = pdp_context_id;
    list->list[list->size].path_status_indication = path_status_indication;
    list->size++;
    return 0; // Success
