void resize_array(void** arr, size_t new_size) {
    void* new_arr = realloc(*arr, new_size * sizeof(PHY_CONTEXT));
    if (!new_arr) {
        printf("Memory reallocation failed.\n");
        free(*arr);
        *arr = NULL;
    } else {
        *arr = new_arr;
    }
}

void manage_array(void** arr, size_t* size, size_t max_size) {
    while (*size < max_size && *size > 0) {
        if (*size < MAX_SIZE / 2) {
            resize_array(arr, *size * 2);
        } else {
            resize_array(arr, *size / 2);
        }
    }
}

int validate_array(void* arr, size_t size) {
    PHY_CONTEXT* contexts = (PHY_CONTEXT*)arr;
    for (size_t i = 0; i < size; ++i) {
        if (contexts[i].phy_channel_id == 0) {
            printf("Invalid channel ID.\n");
            return -1;
        }
    }
    // Check for duplicate channel IDs
    bool found_duplicates = false;
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            if (contexts[i].phy_channel_id == contexts[j].phy_channel_id) {
                printf("Duplicate channel ID detected.\n");
                found_duplicates = true;
                break;
            }
        }
        if (found_duplicates) break;
    }
    return found_duplicates ? -1 : 0;
}

void clean_up_array(void** arr, size_t* size) {
    PHY_CONTEXT* contexts = (PHY_CONTEXT*)*arr;
    clock_t age_threshold = clock() - TIME_THRESHOLD * CLOCKS_PER_SEC;
    for (size_t i = 0; i < *size; ++i) {
        if (contexts[i].phy_layer_status == IDLE && contexts[i].frame_number <= age_threshold) {
            // Remove unused structures
            memmove(contexts, contexts + i + 1, (*size - i - 1) * sizeof(PHY_CONTEXT));
            *size -= 1;
            i--;
        }
