record* allocate_records(int num_records) {
    record *records = NULL;
    long *offsets = (long *)malloc(10000 * sizeof(long));
    for (int i = 0; i < 10000; i++) {
        offsets[i] = i;
    }
    int *keys = (int *)malloc(1000 * sizeof(int));
    for (int i = 1; i <= 1000; i++) {
        keys[i - 1] = i;
    }

    srand(time(NULL)); // seed random number generator
    records = (record *)malloc(num_records * sizeof(record));

    for (int i = 0; i < num_records; i++) {
        record temp;
        temp.offset = &offsets[rand() % 10000];
        temp.key = &keys[rand() % 1000] + 1; // ensure key is between 1 and 1000
        while (*temp.key > 1000 || *temp.key < 1) {
            temp.key = &keys[rand() % 1000] + 1;
        }
