typedef struct {
    long* offset;
    int* key;
    char label[50];
} record;

record* generateRecords(int maxRecords) {
    // Initialize random seed with current timestamp
    srand(time(NULL));

    // Initialize arrays for keys and offsets
    int* keys = (int*)malloc((1000) * sizeof(int));
    long* offsets = (long*)malloc((10000) * sizeof(long));

    // Fill in the keys array with unique values between 1 and 1000
    for (int i = 0; i < 1000; i++) {
        keys[i] = i + 1;
    }

    // Fill in the offsets array with unique long values up to 10,000
    for (long i = 0; i < 10000; i++) {
        offsets[i] = i;
    }

    record* records = NULL;

    int numRecords = 0;

    while (numRecords < maxRecords) {
        // Initialize a new record with random offset and key
        record tempRecord;
        tempRecord.offset = &offsets[rand() % 10000];
        tempRecord.key = &keys[rand() % 1000];

        // Check if the generated key is within range (1 to 1000)
        if (*tempRecord.key < 1 || *tempRecord.key > 1000) {
            continue;
        }

        int retryCount = 0;

        while (retryCount < 3) {
            bool foundDuplicate = false;
            for (int i = 0; i < numRecords; i++) {
                if (*tempRecord.key == records[i].key && *tempRecord.offset == records[i].offset) {
                    foundDuplicate = true;
                    break;
                }
            }

            if (!foundDuplicate) {
                // If no duplicate found, add the record to the array
                tempRecord.label[0] = '\0';
                records = (record*)realloc(records, ++numRecords * sizeof(record));
                records[numRecords - 1] = tempRecord;
                break;
            }

            retryCount++;
        }

        if (retryCount >= 3) {
            // If no valid record can be generated after retries, log a warning and terminate
            printf("Warning: Unable to generate unique record. Terminating.\n");
            for (int i = 0; i < numRecords; i++) {
                free(records[i].offset);
                free(records[i].key);
            }
            free(keys);
            free(offsets);
            return NULL;
        }
    }

    // Free allocated memory
    for (int i = 0; i < numRecords; i++) {
        free(records[i].offset);
        free(records[i].key);
    }
    free(records);

    return NULL;
}
