#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define CHUNK_SIZE (10 * 1024 * 1024)

typedef struct {
    int* data;
    size_t len;
} Chunk;

Chunk* chunk_create(size_t initial_len) {
    Chunk* chunk = malloc(sizeof(Chunk));
    chunk->data = malloc(initial_len * sizeof(int));
    chunk->len = 0;
    return chunk;
}

void chunk_free(Chunk* chunk) {
    free(chunk->data);
    free(chunk);
}

void sort_chunk(Chunk* chunk, int (*cmp)(int, int)) {
    qsort(chunk->data, chunk->len, sizeof(int), cmp);
}

bool filter_chunk(Chunk* chunk, int min, int max, bool (*pred)(int)) {
    for (size_t i = 0; i < chunk->len; ++i) {
        if (!pred(chunk->data[i])) continue;
        if (chunk->data[i] < min || chunk->data[i] > max) return false;
    }
    return true;
}

Chunk* deduplicate_chunk(Chunk* chunk, size_t (*hash)(int)) {
    size_t bucket_size = 16; // adjust based on dataset size
    size_t* hash_bucket = malloc(bucket_size * sizeof(size_t));
    size_t bucket_len = 0;

    for (size_t i = 0; i < chunk->len; ++i) {
        size_t key_hash = hash(chunk->data[i]);
        size_t idx = key_hash % bucket_size;
        while (hash_bucket[idx] != 0 && hash_bucket[idx] != key_hash) {
            // collision handling
            idx = (idx + 1) % bucket_size;
        }
        if (!hash_bucket[idx]) {
            hash_bucket[idx] = key_hash;
            ++bucket_len;
        }
    }

    Chunk* deduped_chunk = chunk_create(bucket_len);
    for (size_t i = 0; i < bucket_size; ++i) {
        size_t key_hash = hash_bucket[i];
        while (key_hash != 0 && key_hash != hash_bucket[idx]) {
            // collision handling
            idx = (idx + 1) % bucket_size;
        }
        if (hash_bucket[idx] == key_hash) {
            deduped_chunk->data[deduped_chunk->len++] = chunk->data[i];
        }
    }

    free(hash_bucket);
    return deduped_chunk;
}

int main() {
    // Example usage:
    int data[] = {1, 2, -3, 4, 5, 6, 7, -8};
    size_t len = sizeof(data) / sizeof(data[0]);

    Chunk* chunk = chunk_create(len);
    memcpy(chunk->data, data, len * sizeof(int));
    chunk->len = len;

    // Sort
    sort_chunk(chunk, (int (*)(int, int)) qsort_cmp);

    // Filter values between 2 and 6
    if (!filter_chunk(chunk, 2, 6, (int (*)(int)) is_positive)) {
        printf("Filtered out values outside range [2, 6]\n");
    }

    // Deduplicate
    Chunk* deduped_chunk = deduplicate_chunk(chunk, (size_t (*)(int)) int_hash);
    for (size_t i = 0; i < deduped_chunk->len; ++i) {
        printf("%d ", deduped_chunk->data[i]);
    }
    printf("\n");

    // Clean up
    chunk_free(chunk);
    chunk_free(deduped_chunk);

    return 0;
}

// Custom sorting function for qsort()
int qsort_cmp(int a, int b) {
    if (a < b) return -1;
    else if (a > b) return 1;
    else return 0;
}

bool is_positive(int x) {
    return x > 0;
}

size_t int_hash(int x) {
    return (size_t) x;
}
