    struct pool* p = (struct pool*)malloc(sizeof(struct pool));
    if (!p) return NULL;

    p->size = initial_size;
    p->blocks = (char**)malloc(initial_size * sizeof(char*));

    for (int i = 0; i < initial_size; i++) {
        p->blocks[i] = (char*)malloc(1024); // Default block size
    }

    return p;
}

void free_pool(struct pool* p) {
