void add_event(struct node** head, event* e) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (!new_node) return;

    new_node->data = e;
    new_node->next = *head;
    *head = new_node;
}

// Thread-safe linked list operations
void remove_event(struct node** head, event* e) {
    struct node* current = *head;
    struct node* previous = NULL;

    while (current && current->data != e) {
        previous = current;
        current = current->next;
    }

    if (current) {
        if (previous) {
            previous->next = current->next;
        } else {
            *head = current->next;
        }
        free(current);
    }
}

// Event validation and conflict resolution
