    struct pool* pool = create_pool(1000);
    if (!pool) return 1;

    // Initialize the timestamp reference
    time_t timestamp_reference = time(NULL);

    // Create a linked list to store events
    struct node* head = NULL;

    // Add events to the linked list
    add_event(&head, create_event(time(0), "INFO", 1));
    add_event(&head, create_event(correct_timestamp(time(0) + 10000, timestamp_reference), "ERROR", 2));

    // Validate events within a time window
    validate_events(pool, head, timestamp_reference, timestamp_reference + 60);

    // Free allocated resources
    while (head) {
        event* e = head->data;
        remove_event(&head, e);
        free_event(e);
    }
    free_pool(pool);

