    // Allocate ring buffer for packet IDs
    uint32_t* packet_ids = (uint32_t*)malloc(buffer_size * sizeof(uint32_t));

    if (!packet_ids) {
        fprintf(stderr, "Failed to allocate memory for packet IDs.\n");
        return -1;
    }

    // Initialize packet IDs with default values
    memset(packet_ids, 0, buffer_size * sizeof(uint32_t));

    // Validate and initialize array of packet info structures
    packet_info* packets = (packet_info*)malloc(num_packets * sizeof(packet_info));

    if (!packets) {
        free(packet_ids);
        return -1;
    }

    for (int i = 0; i < num_packets; i++) {
        packets[i].id = i;
        packets[i].timestamp = time(NULL);
        packets[i].payload_size = sizeof(char) * 1024;
    }

    // Initialize hash table for storing and retrieving packet metadata
    uint32_t* hash_table = (uint32_t*)malloc(RING_BUFFER_SIZE * sizeof(uint32_t));

    if (!hash_table) {
        free(packet_ids);
        free(packets);
        return -1;
    }

    memset(hash_table, 0, RING_BUFFER_SIZE * sizeof(uint32_t));

    // Validate and handle edge cases
    for (int i = 0; i < num_packets; i++) {
        if (validate_packet_info(&packets[i])) {
            // Insert packet info into hash table
            uint32_t key = packets[i].id;
            if (!insert_into_hash_table(hash_table, RING_BUFFER_SIZE, &key)) {
                free(packet_ids);
                free(packets);
                return -1;
            }
        } else {
            // Handle invalid or duplicate packet ID
            printf("Invalid or duplicate packet ID: %u\n", packets[i].id);
        }
    }

    // Optimize function for performance and minimize memory fragmentation
    // ...

    // Return status code to application
    return 0;
}

// Function to validate packet info structure
int validate_packet_info(packet_info* packet) {
    if (packet->id == 0) {
        return -1; // Invalid packet ID
    }

    if (packet->timestamp > time(NULL)) {
        return -2; // Duplicate timestamp
    }

    if (packet->payload_size < sizeof(char) * 1024) {
        return -3; // Payload size exceeds limit
    }

    return 0;
}

// Function to insert packet info into hash table
int insert_into_hash_table(uint32_t* hash_table, uint32_t size, uint32_t* key) {
    int index = *key % size;

    if (hash_table[index] == 0) {
        // Insert new packet info into hash table
        hash_table[index] = *key;
        return 1; // Successful insertion
    } else {
        // Duplicate packet ID, handle edge case
        printf("Duplicate packet ID: %u\n", *key);
        return -1;
    }
}
