#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define CLEANUP_INTERVAL 5 // seconds

typedef struct connection {
    int id;
    char* addr;
} Connection;

Connection** connections = NULL;
int num_connections = 0;
int max_connections = 0;
int used_connections = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void init_memory_pool() {
    max_connections = MAX_CONNECTIONS;
    connections = (Connection**)malloc(max_connections * sizeof(Connection*));
}

void* create_connection(int id, char* addr) {
    Connection* conn = NULL;

    pthread_mutex_lock(&mutex);
    if (num_connections < max_connections && !check_duplicate(id)) {
        conn = (Connection*)malloc(sizeof(Connection));
        conn->id = id;
        conn->addr = strdup(addr);
        connections[num_connections] = conn;
        num_connections++;
        used_connections++;
        pthread_cond_signal(&cond);
    }
    pthread_mutex_unlock(&mutex);

    return conn;
}

int check_duplicate(int id) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->id == id) {
            return 1;
        }
    }

    return 0;
}

void release_connection(Connection* conn) {
    pthread_mutex_lock(&mutex);
    used_connections--;
    free(conn->addr);
    free(conn);
    for (int i = num_connections - 1; i > 0; i--) {
        if (!connections[i]) {
            connections[i] = connections[0];
            connections[0] = NULL;
            break;
        }
    }
    num_connections--;
    pthread_mutex_unlock(&mutex);

    cleanup();
}

void cleanup() {
    while (num_connections > 0) {
        for (int i = 0; i < num_connections; i++) {
            if (!connections[i]->addr) {
                free(connections[i]);
                connections[i] = NULL;
                break;
            }
        }

        usleep(CLEANUP_INTERVAL * 1000000);
    }
}

void print_stats() {
    printf("Memory Pool Statistics:\n");
    printf("Available Connections: %d\n", max_connections - num_connections);
    printf("Used Connections: %d\n", used_connections);
    printf("Cleanup Activity: every %d seconds\n", CLEANUP_INTERVAL);
}

int main() {
    init_memory_pool();

    pthread_t tid;
    pthread_create(&tid, NULL, (void*)create_connection, 1);
    pthread_join(tid, NULL);

    // Simulate connections and cleanup
    for (int i = 0; i < 10; i++) {
        create_connection(i + 1, "localhost");
        release_connection(create_connection(2, "localhost"));
        print_stats();
        usleep(CLEANUP_INTERVAL * 1000000);
    }

    return 0;
}
