    int i;
    // Allocate memory for temperature readings array
    temperature_readings = (double *)malloc(5000 * sizeof(double));

    if (temperature_readings == NULL) {
        printf("Memory allocation failed for temperature readings.\n");
        return -1;  // Return error status
    }

    // Initialize each reading with random value within range
    for (i = 0; i < 5000; i++) {
        temperature_readings[i] = (double)(rand() % 170) - 50;
    }

    // Allocate memory for time data array
    *time_data_array = (time_data *)malloc(5000 * sizeof(time_data));

    if (*time_data_array == NULL) {
        printf("Memory allocation failed for time data.\n");
        free(temperature_readings);  // Free allocated temperature readings memory
        return -1;  // Return error status
    }

    // Initialize each time data structure with random timestamp and location
    srand(time(NULL));  // Seed random number generator

    int retry_count = 0;
    for (i = 0; i < 5000; i++) {
        while (1) {
            (*time_data_array)[i].timestamp = rand() % (time(NULL) + 3600 * 24);
            strcpy((*time_data_array)[i].location, "Location");

            if ((rand() % 2) == 0) {  // 50% chance of a duplicate timestamp
                continue;
            }

            retry_count = 0;  // Reset retry count for each successful attempt
            break;
        }

        if (retry_count > 3) {
            printf("Error: Max retries reached. Timestamp generation failed.\n");
            free(temperature_readings);  // Free allocated temperature readings memory
            free(*time_data_array);  // Free allocated time data memory
            return -1;  // Return error status
        }

        retry_count++;
    }

    printf("Memory allocation and initialization successful.\n");

    return 0;
}

int main() {
    double *temperature_readings = NULL;
    time_data *time_data_array = NULL;

    int result = manage_memory(temperature_readings, &time_data_array);

    if (result < 0) {
        printf("Memory management failed. Error code: %d\n", result);
    } else {
        printf("Memory management successful.\n");
    }

    // Free allocated memory
    free(temperature_readings);
    free(time_data_array);

    return 0;
}
