} LoggingConfig;

// Define a function to load configuration from JSON file
int load_config_from_json(const char *json_file, LoggingConfig *config) {
    // Initialize JSON parser and database connection
    json_object *json_obj = NULL;
    sqlite3 *db = NULL;
    sqlite3_open("logging_system.db", &db);

    // Load JSON file into the JSON object
    FILE *fp = fopen(json_file, "r");
    if (fp == NULL) {
        return 1; // Error loading file
    }
    json_object *load_json = json_load_file(fp, 0);
    fclose(fp);

    // Parse JSON and validate configuration settings
    if (json_object_object_get(load_json, "log_level")) {
        config->log_level = json_object_get_int(load_json, "log_level");
    } else {
        return 1; // Error parsing log level
    }
    if (json_object_object_get(load_json, "log_file")) {
        char *log_file = json_object_get_string(load_json, "log_file");
        config->log_file = strdup(log_file);
    } else {
        return 1; // Error parsing log file
    }

    // Save configuration to the database for persistence
    sqlite3_stmt *stmt;
    const char *sql = "INSERT INTO configurations (log_level, log_file) VALUES (?, ?)";
    sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    sqlite3_bind_int(stmt, 1, config->log_level);
    sqlite3_bind_text(stmt, 2, config->log_file, strlen(config->log_file), SQLITE_STATIC);
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);

    // Clean up
    json_object_put(load_json);
    sqlite3_close(db);

    return 0; // Success
}

// Define a function to update configuration in the database
int update_config_in_db(LoggingConfig *config) {
    sqlite3_stmt *stmt;
    const char *sql = "UPDATE configurations SET log_level = ?, log_file = ? WHERE id = 1";
    sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    sqlite3_bind_int(stmt, 1, config->log_level);
    sqlite3_bind_text(stmt, 2, config->log_file, strlen(config->log_file), SQLITE_STATIC);
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);

    return 0; // Success
}

