    if (gtp_dynamic_list_size >= max_list_size) {
        printf("Error: GTP dynamic list is full.\n");
        return;
    }
    gtp_dynamic_list[gtp_dynamic_list_size].teid = teid;
    gtp_dynamic_list[gtp_dynamic_list_size].pdp_context_id = pdp_context_id;
    strcpy(gtp_dynamic_list[gtp_dynamic_list_size].path_status_indication, path_status_indication);
