    gtp_dynamic_list[gtp_dynamic_list_size].nfaapi_crc_indication_pdu.crc_indicator_rel8_tag = (uint16_t)(rand() % 255);
    gtp_dynamic_list_size++;
}

void clean_up_gtp_dynamic_list(int age_threshold) {
    int i;
    for (i = 0; i < gtp_dynamic_list_size; i++) {
        if ((time(NULL) - gtp_dynamic_list[i].teid) > age_threshold) {
            // Free up resources and optimize performance
            free(gtp_dynamic_list);
            init_gtp_dynamic_list();
            return;
        }
    }
}
