typedef struct {
    int value;
} record_t;

int manage_arrays() {
    long *offsets = NULL;
    int *keys = NULL;
    record_t *records = NULL;

    // Initialize random number generator
    srand(time(NULL));

    // Step 1: Allocate memory for array of 'long' offset values
    if ((offsets = (long *)malloc(1024L*1024L*sizeof(long))) == NULL) {
        return -1; // Memory allocation failure
    }

    // Step 2: Populate offsets array with unique random long values within the range [-1000, 1000]
    for (int i = 0; i < 1024*1024; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    // Step 3: Allocate memory for array of 'int' keys
    if ((keys = (int *)malloc(1024L*1024L*sizeof(int))) == NULL) {
        free(offsets);
        return -1; // Memory allocation failure
    }

    // Step 4: Populate keys array with unique random int values within the range [0, 10000]
    for (int i = 0; i < 1024*1024; i++) {
        while (1) {
            int key = rand() % 10001;
            bool is_unique = true;
            for (int j = 0; j < i; j++) {
                if (keys[j] == key) {
                    is_unique = false;
                    break;
                }
            }
            if (is_unique) {
                keys[i] = key;
                break;
            }
        }
    }

    // Step 5: Allocate memory for array of 'record' structures
    if ((records = (record_t *)malloc(1024L*1024L*sizeof(record_t))) == NULL) {
        free(offsets);
        free(keys);
        return -1; // Memory allocation failure
    }

    // Step 6: Populate records array with unique random record values within the range [-1000, 1000]
    for (int i = 0; i < 1024*1024; i++) {
        records[i].value = rand() % 2001 - 1000;
    }

    // Step 7: Return the number of successfully initialized records
    int num_records = 1024*1024;

    free(offsets);
    free(keys);
    free(records);

    return num_records;
}
