```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum number of employees and projects per department
#define MAX_EMPLOYEES 100
#define MAX_PROJECTS 20

// Structure to represent an employee
typedef struct {
    char name[32];
    int ID;
    double salary;
} Employee;

// Structure to represent a project
typedef struct {
    char* name;
    float budget;
} Project;

// Structure to represent a department
typedef struct {
    Employee* employees;
    Project* projects;
    int num_employees;
    int num_projects;
} Department;

// Function to initialize a department structure with default values
Department* create_department() {
    Department* department = (Department*) malloc(sizeof(Department));
    department->num_employees = 0;
    department->num_projects = 0;
    department->employees = (Employee*) malloc(MAX_EMPLOYEES * sizeof(Employee));
    department->projects = (Project*) malloc(MAX_PROJECTS * sizeof(Project));
    return department;
}

// Function to iterate over employees in a department
void iterate_employees(Department* department) {
    for (int i = 0; i < department->num_employees; i++) {
        printf("Employee %d: Name - %s, ID - %d, Salary - %.2lf\n", 
               i + 1, department->employees[i].name, department->employees[i].ID, department->employees[i].salary);
    }
}

// Function to search for an employee by name or ID
void search_employee(Department* department) {
    printf("Enter the name or ID of the employee you want to find: ");
    char input[32];
    scanf("%s", input);

    for (int i = 0; i < department->num_employees; i++) {
        if (strcmp(input, department->employees[i].name) == 0 || department->employees[i].ID == atoi(input)) {
            printf("Employee found: Name - %s, ID - %d, Salary - %.2lf\n", 
                   department->employees[i].name, department->employees[i].ID, department->employees[i].salary);
        }
    }
}

// Function to find projects by name or budget range
void search_projects(Department* department) {
    printf("Enter the project name or enter a budget range (min-max): ");
    char input[32];
    scanf("%s", input);

    if (strcmp(input, "") == 0) { // If the user entered an empty string, print all projects
        for (int i = 0; i < department->num_projects; i++) {
            printf("Project %d: Name - %s, Budget - %.2f\n", 
                   i + 1, department->projects[i].name, department->projects[i].budget);
        }
    } else if (sscanf(input, "%*s-%f-%f", &input[0], &input[1]) == 3) { // If the user entered a budget range
        float min_budget = atof(&input[0]);
        float max_budget = atof(&input[1]);

        for (int i = 0; i < department->num_projects; i++) {
            if ((department->projects[i].budget >= min_budget && department->projects[i].budget <= max_budget)) {
                printf("Project %d: Name - %s, Budget - %.2f\n", 
                       i + 1, department->projects[i].name, department->projects[i].budget);
            }
        }
    } else { // If the user entered a project name
        for (int i = 0; i < department->num_projects; i++) {
            if (strcmp(input, department->projects[i].name) == 0) {
                printf("Project found: Name - %s, Budget - %.2f\n", 
                       department->projects[i].name, department->projects[i].budget);
            }
        }
    }
}

// Example usage:
int main() {
    Department* department = create_department();

    // Add employees and projects to the department...

    iterate_employees(department);
    search_employee(department);
    search_projects(department);

    free(department->employees);
    free(department->projects);
    free(department);

    return 0;
}
```

This code implements a department structure that contains arrays of employees and projects. The `create_department` function initializes the department with default values, while the `iterate_employees`, `search_employee`, and `search_projects` functions provide ways to iterate over employees and projects, search for employees by name or ID, and find projects by name or budget range.

Note that this code does not handle concurrent access or thread-safety issues. Implementing these features would require additional synchronization mechanisms, such as locks or atomic operations.']

