    current_size = new_size;
}

// Function to add a new resource context
void add_resource_context(int resource_id, int base_station_id, int frame_number, int status_code) {
    if (current_size >= MAX_SIZE) {
        printf("Error: Array is full. Consider resizing or deleting resources.\n");
        return;
    }
    RESOURCE_CONTEXT* new_resource = my_calloc(1 * sizeof(RESOURCE_CONTEXT));
    new_resource->resource_id = resource_id;
    new_resource->base_station_id = base_station_id;
    new_resource->frame_number = frame_number;
    new_resource->status_code = status_code;
    resource_array[current_size] = new_resource;
    age_array[current_size] = 0; // Initialize the age of the new resource
    current_size++;
}

// Function to delete a resource context
void delete_resource_context(int resource_id) {
    for (int i = 0; i < current_size; i++) {
        if (resource_array[i]->resource_id == resource_id) {
            my_free(resource_array[i]);
            memmove(&resource_array[i], &resource_array[i + 1], (current_size - i - 1) * sizeof(RESOURCE_CONTEXT*));
            current_size--;
            break;
        }
    }
}

// Function to update the age of each resource
void update_age() {
    for (int i = 0; i < current_size; i++) {
        age_array[i]++;
    }
}

// Function to validate the integrity of the array
void validate_resource_array() {
    for (int i = 0; i < current_size; i++) {
        if (resource_array[i]->resource_id == resource_array[i-1]->resource_id) {
            printf("Warning: Duplicate resource ID detected.\n");
        }
    }
}

// Function to update the local array with the latest resource status information
