    add_resource_context(1, 2, 3, 4);
    add_resource_context(5, 6, 7, 8);
    update_age();
    validate_resource_array();
    sync_resource_array();
    delete_resource_context(1);
    return 0;
}

// Memory allocation and deallocation functions
