void* phy_array_init(int initial_size) {
    void *array = (void *)malloc(initial_size * sizeof(PHY_CONTEXT));
    if (!array) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }
    array[0].PHY_CHANNEL_ID = -1; // dummy value to indicate empty slot
    return array;
}

int phy_array_insert(void *array, int size, PHY_CONTEXT *context) {
    if (size >= MAX_ARRAY_SIZE) {
        printf("Error: Array exceeded maximum size\n");
        return -1;
    }
    for (int i = 0; i < size; i++) {
        if (array[i].PHY_CHANNEL_ID == context->PHY_CHANNEL_ID)
            return -2; // duplicate entry found
    }
    PHY_CONTEXT *new_context = realloc(array, (size + 1) * sizeof(PHY_CONTEXT));
    if (!new_context) {
        printf("Error: Memory reallocation failed\n");
        return -3;
    }
    new_context[size].PHY_CHANNEL_ID = context->PHY_CHANNEL_ID;
    new_context[size].BASE_STATION_ID = context->BASE_STATION_ID;
    new_context[size].FRAME_NUMBER = context->FRAME_NUMBER;
    new_context[size].PHY_LAYER_STATUS = strdup(context->PHY_LAYER_STATUS);
    return size + 1;
}

void phy_array_remove(void *array, int start, int end) {
    for (int i = end; i >= start; i--) {
        free(array[i].PHY_LAYER_STATUS);
        memmove((void *)&array[i], (void *)&array[i+1], sizeof(PHY_CONTEXT) * (end - start));
    }
}

void phy_array_validate(void *array, int size) {
    for (int i = 0; i < size; i++) {
        if (array[i].PHY_CHANNEL_ID == -1) // dummy value indicates empty slot
            continue;
        if (array[i].BASE_STATION_ID < 0 || array[i].FRAME_NUMBER < 0)
            printf("Warning: Invalid data detected at index %d\n", i);
    }
}

