#include <iostream>
#include <vector>
#include <string>
#include <random>

namespace NFAPI {

class NFAPI_CRC_INDICATION_PDU_T {
public:
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    std::string CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;

    // Constructor
    NFAPI_CRC_INDICATION_PDU_T() : CRCFLAG(false) {}

    // Destructor
    ~NFAPI_CRC_INDICATION_PDU_T() {}
};

class NFAPI_CRC_INDICATION_MANAGER {
public:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> dynamicList;

    // Constructor
    NFAPI_CRC_INDICATION_MANAGER() : randomEngine(std::mt19937()) {}

    // Destructor
    ~NFAPI_CRC_INDICATION_MANAGER() {
        for (auto& pdu : dynamicList) {
            delete &pdu;
        }
    }

    void addPDU(const std::string& RX_UE_INFORMATION_TAG, int RNTI) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = new NFAPI_CRC_INDATION_PDU_T();
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        // Set random CRCFLAG using Mersenne Twister algorithm
        std::uniform_int_distribution<> crcDistribution(0, 1);
        pdu->CRCFLAG = (crcDistribution(randomEngine) == 0);

        dynamicList.push_back(*pdu);
    }

    void displayPDUList() {
        for (const auto& pdu : dynamicList) {
            std::cout << "RX_UE_INFORMATION_TAG: " << pdu.RX_UE_INFORMATION_TAG
                      << ", RNTI: " << pdu.RNTI
                      << ", CRC_INDICATION_REL8_TAG: " << pdu.CRC_INDICATION_REL8_TAG
                      << ", CRCFLAG: " << (pdu.CRCFLAG ? "True" : "False") << std::endl;
        }
    }

private:
    std::mt19937 randomEngine;
};

} // namespace NFAPI

int main() {
    NFAPI::NFAPI_CRC_INDICATION_MANAGER manager;

    // Add some example PDUs
    manager.addPDU("RX_UE_INFORMATION_TAG1", 123);
    manager.addPDU("RX_UE_INFORMATION_TAG2", 456);
    manager.addPDU("RX_UE_INFORMATION_TAG3", 789);

    // Display the PDU list
    manager.displayPDUList();

    return 0;
}

