        match level {
            "info" | "warning" | "error" | "debug" => {
                let now = Instant::now();
                self.log_buffer.push(format!("{} [{}] {}", now, level, message));
                if level == "error" {
                    // critical log handling
                }
                Ok(())
            }
            _ => Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid log level")),
        }
    }

    fn flush(&mut self) -> Result<(), io::Error> {
        for message in &self.log_buffer {
            match self.output_target() {
                "file" => fs::write("log.txt", message.as_bytes())?,
                "console" => println!("{}", message),
                "network" => // implementation for network-based logging,
            }
        }
        Ok(())
    }

    fn output_target(&self) -> &str {
        // implementation for selecting the current output target
    }

    fn shutdown(&mut self) {
        drop(self.log_buffer);
    }
}

fn main() {
    let buffer_size = 100;
    let mut logger = Logger::new(buffer_size);

    logger.set_output_target("file"); // configure logging to file

    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        loop {
            match rx.recv() {
                Ok(msg) => println!("{}", msg),
                Err(_) => break,
            }
        }
    });

    logger.log("Hello, world!".to_string(), "info", "metadata").unwrap();

    // simulate log burst
    for _ in 0..100 {
        tx.send("Log message".to_string()).unwrap();
        thread::sleep(chrono::duration::Duration::from_millis(10));
    }

    logger.flush().unwrap();
}
