    private static final int MAX_LIST_SIZE = 50000;
    private static final long AGE_THRESHOLD_MILLIS = 1000; // 1 second

    private ReentrantLock lock = new ReentrantLock();
    private MessageDigest digest;
    private List<byte[]> hashStorage;

    public String processText(String text) {
        if (text == null || text.isEmpty()) {
            return "Error: Empty or null input";
        }

        byte[] inputBytes = text.getBytes();
        int size = inputBytes.length;

        if (size > 1024) { // 1KB limit
            return "Error: Input too large";
        }

        try {
            ByteArrayOutputStream bos = new ByteArrayOutputStream(size);
            bos.write(inputBytes, 0, size);

            byte[] hash = getHash(bos.toByteArray());
            storeHash(hash);

            return "Text processed successfully";
        } catch (IOException e) {
            // Log error and retry
            return "Error: Failed to process text";
        }
    }

    private byte[] getHash(byte[] input) throws IOException, NoSuchAlgorithmException {
        lock.lock();
        try {
            if (digest == null) {
                digest = MessageDigest.getInstance("SHA-256");
                hashStorage = new ArrayList<>();
            }

            return digest.digest(input);
        } finally {
            lock.unlock();
        }
    }

    private void storeHash(byte[] hash) {
        // Periodic cleanup based on age threshold
        if (hashStorage.size() > MAX_LIST_SIZE / 2) {
            long oldestAge = Long.MAX_VALUE;
            for (byte[] storedHash : hashStorage) {
                long age = System.currentTimeMillis() - getTimestamp(storedHash);
                if (age < oldestAge) {
                    oldestAge = age;
                }
            }

            if (oldestAge > AGE_THRESHOLD_MILLIS) {
                // Remove old hashes
                int removalCount = 0;
                for (int i = hashStorage.size() - 1; i >= 0; i--) {
                    byte[] storedHash = hashStorage.get(i);
