                // Resize hash storage array
                int newSize = hashStorage.size();
                byte[][] newStorage = new byte[newSize][];
                for (int i = 0; i < newSize; i++) {
                    newStorage[i] = hashStorage.get(i);
                }
                hashStorage = new ArrayList<>(newSize);

                // Update metadata and timestamps
                updateMetadata(newSize, removalCount);
            }
        }

        hashStorage.add(hash);
