typedef struct {
    int key;
    int value;
} record;

// Function to manage memory allocation and initialization
int* allocateOffsetArray(int size) {
    // Allocate memory for the offset array
    long* offsets = (long*)malloc(size * sizeof(long));

    // Initialize the offsets with random values within a specified range
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 10000;
    }

    return (int*)offsets;
}

// Function to manage key allocation and initialization
int* allocateKeyArray(int maxUniqueKeys) {
    // Allocate memory for the key array
    int* keys = (int*)malloc(maxUniqueKeys * sizeof(int));

    // Initialize the keys with random values within a specified range
    for (int i = 0; i < maxUniqueKeys; i++) {
        keys[i] = rand() % 10000;
    }

    return keys;
}

// Function to manage record allocation and initialization
record* allocateRecordArray(int size) {
    // Allocate memory for the record array
    record* records = (record*)malloc(size * sizeof(record));

    // Initialize the records with random values within a specified range
    for (int i = 0; i < size; i++) {
        records[i].key = rand() % 10000;
        records[i].value = rand() % 10000;
    }

    return records;
}

// Function to validate record uniqueness and adjust if necessary
void validateRecords(record* records, int size) {
    for (int i = 0; i < size; i++) {
        // Check for duplicate keys
        for (int j = 0; j < i; j++) {
            if (records[i].key == records[j].key) {
                // Adjust the value to ensure uniqueness
                while (1) {
                    records[i].value = rand() % 10000;
                    bool unique = true;
                    for (int k = 0; k < i; k++) {
                        if (records[k].key == records[i].key && records[k].value == records[i].value) {
                            unique = false;
                            break;
                        }
                    }
                    if (unique) break;
                }
            }
        }
    }
}

// Function to handle memory allocation and deallocation
void* allocateMemory(int size, int type) {
    void* ptr = NULL;

    if (type == 1) { // Allocate memory for offset array
        ptr = malloc(size * sizeof(long));
    } else if (type == 2) { // Allocate memory for key array
        ptr = malloc(size * sizeof(int));
    } else if (type == 3) { // Allocate memory for record array
        ptr = malloc(size * sizeof(record));
    }

    if (!ptr) {
        // Log error information and return an error code
        printf("Memory allocation failed.\n");
        return NULL;
    } else {
        return ptr;
    }
}

