#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/mman.h>

// Define the record structure
typedef struct {
    int key;
    int value;
} record;

// Define the memory pool structure
typedef struct {
    void* mem;
    size_t capacity;
    size_t used;
} memory_pool;

memory_pool* create_memory_pool(size_t capacity) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    pool->mem = malloc(capacity);
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

void* allocate_from_pool(memory_pool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        // Reallocate the memory pool if needed
        pool->mem = realloc(pool->mem, pool->capacity * 2);
        pool->capacity *= 2;
    }
    void* ptr = pool->mem + pool->used;
    pool->used += size;
    return ptr;
}

void deallocate_from_pool(memory_pool* pool, void* ptr) {
    pool->used -= (char*)ptr - (char*)pool->mem;
}

// Define the function to manage memory allocation and initialization
int manage_memory_allocation() {
    // Allocate and initialize an array of long offset values
    memory_pool* offset_pool = create_memory_pool(1024 * 1024); // 1MB capacity
    void* offsets = allocate_from_pool(offset_pool, sizeof(long) * 10000);
    for (size_t i = 0; i < 10000; i++) {
        *(long*)offsets += i;
        offsets += sizeof(long);
    }

    // Allocate and initialize an array of int keys
    memory_pool* key_pool = create_memory_pool(1024 * 1024); // 1MB capacity
    void* keys = allocate_from_pool(key_pool, sizeof(int) * 10000);
    for (size_t i = 0; i < 10000; i++) {
        *(int*)keys += i;
        keys += sizeof(int);
    }

    // Allocate and initialize an array of record structures
    memory_pool* record_pool = create_memory_pool(1024 * 1024); // 1MB capacity
    void* records = allocate_from_pool(record_pool, sizeof(record) * 10000);
    for (size_t i = 0; i < 10000; i++) {
        record* rec = (record*)records + i;
        rec->key = rand() % 100;
        rec->value = rand() % 100;
    }

    // Validate that no two records have the same key and no two records have the same combination of key and value
    for (size_t i = 0; i < 10000; i++) {
        record* rec1 = (record*)records + i;
        for (size_t j = i + 1; j < 10000; j++) {
            record* rec2 = (record*)records + j;
            if (rec1->key == rec2->key || (rec1->key == rec2->key && rec1->value == rec2->value)) {
                // Conflict detected, adjust values to ensure uniqueness
                rec1->value++;
                rec2->value++;
            }
        }
    }

    // Deallocate memory resources
    deallocate_from_pool(offset_pool, offsets);
    deallocate_from_pool(key_pool, keys);
    deallocate_from_pool(record_pool, records);
    free(offset_pool);
    free(key_pool);
    free(record_pool);

    return 0;
}

int main() {
    manage_memory_allocation();
    return 0;
}
