// Priority queue structure to manage data items based on timestamps
typedef struct {
    dataItem* head;
    pthread_mutex_t lock;
} processDataAndTestPipeline;

processDataAndTestPipeline* pDataPipe = NULL;

// Function to create a new priority queue instance
void initProcessDataAndTestPipeline(processDataAndTestPipeline** pipe) {
    *pipe = (processDataAndTestPipeline*)malloc(sizeof(processDataAndTestPipeline));
    (*pipe)->head = NULL;
    pthread_mutex_init(&((*pipe)->lock), NULL);
}

// Function to add a new data item to the priority queue
void processDataAndAddItem(dataItem* item, processDataAndTestPipeline* pipe) {
    pthread_mutex_lock(&pipe->lock);

    // Add new item to the end of the list and reorder if necessary
    dataItem* newNode = (dataItem*)malloc(sizeof(dataItem));
    *newNode = *item;
    newNode->timestamp = time(NULL);  // Update timestamp

    // Reorder the list based on timestamps
    if (!pipe->head || newNode->timestamp <= pipe->head->timestamp) {
        newNode->next = pipe->head;
        pipe->head = newNode;
    } else {
        dataItem* current = pipe->head;
        while (current->next && current->next->timestamp < newNode->timestamp)
            current = current->next;
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&pipe->lock);
}

// Function to process the oldest item from the priority queue
void processDataAndPopItem(processDataAndTestPipeline* pipe) {
    pthread_mutex_lock(&pipe->lock);

    if (!pipe->head) {
        pthread_mutex_unlock(&pipe->lock);
        return;
    }

    // Remove and return the head of the list (oldest item)
    dataItem* popped = pipe->head;
    pipe->head = popped->next;

    free(popped);  // Free the removed item

    pthread_mutex_unlock(&pipe->lock);
}

