record* create_records(int num_records, int min_key, int max_key) {
    record *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;

    // Allocate memory for offsets
    if (!(offsets = (long*)malloc(num_records * sizeof(long)))) {
        printf("Error allocating memory for offsets.\n");
        return NULL;
    }

    // Initialize offsets to 0
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
    }

    // Allocate memory for keys
    if (!(keys = (int*)malloc(num_records * sizeof(int)))) {
        printf("Error allocating memory for keys.\n");
        free(offsets);
        return NULL;
    }

    // Initialize keys to random numbers within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % ((max_key - min_key) + 1) + min_key;
    }

    // Allocate memory for records
    if (!(records = (record*)malloc(num_records * sizeof(record)))) {
        printf("Error allocating memory for records.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].value = keys[i];
    }

    // Validate that no two records have the same key
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (keys[i] == keys[j]) {
                printf("Error: duplicate key found.\n");
                free(offsets);
                free(keys);
                free(records);
                return NULL;
            }
        }
    }

    // Return the allocated memory
    return records;
}

void destroy_records(record *records, int num_records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    record *records = create_records(10, 1, 100);
    destroy_records(records, 10);

    return 0;
}
