    XmlConfig config = xml_config_parse(filename);
    if (!config) {
        // Handle error
        return;
    }

    int key_size = xml_config_get_int(config, "key_size");
    int value_range_min = xml_config_get_int(config, "value_range_min");
    int value_range_max = xml_config_get_int(config, "value_range_max");

    if (*size > 0 && *size <= key_size) {
        // Allocate memory for the records
        *records = (Record *)malloc(*size * sizeof(Record));

        if (!*records) {
            // Handle memory allocation error
            return;
        }

        // Initialize and generate random values for each record
        srand(time(NULL));
        for (int i = 0; i < *size; i++) {
            (*records)[i].key = rand() % key_size;
            (*records)[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        }
    } else {
        // Handle invalid input
    }

    xml_config_free(config);
}
