record* manage_memory(long max_allowed_memory) {
    long total_allocated = 0;
    record* records = NULL;
    size_t offset_size, key_size, record_size;

    // Calculate optimal sizes for each array type
    offset_size = (max_allowed_memory / sizeof(long)) * sizeof(long);
    key_size = (offset_size / sizeof(int)) * sizeof(int);
    record_size = (key_size / sizeof(record)) * sizeof(record);

    if (!record_size) {
        printf("Insufficient memory to allocate even a single record.\n");
        return NULL;
    }

    // Allocate and initialize arrays
    long* offsets = (long*)malloc(offset_size);
    int* keys = (int*)malloc(key_size);
    records = (record*)malloc(record_size);

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < offset_size / sizeof(long); i++) {
        offsets[i] = rand() % 10000000 + 1; // Random offset values
    }

    for (size_t i = 0; i < key_size / sizeof(int); i++) {
        int offset = offsets[i];
        keys[i] = (int)(offset) * 2; // Transformation function (handles overflows)
    }

    for (size_t i = 0; i < record_size / sizeof(record); i++) {
        records[i].value = rand() % 10000 + 1; // Random record values
    }

    printf("Calculated sizes: Offset array - %ld, Key array - %ld, Record array - %ld.\n", offset_size, key_size, record_size);
    printf("Final memory allocation status: Success.\n");

    return records;
}
