typedef struct {
    int USER_ID;
    char EMAIL_ADDRESS[256];
    long LAST_LOGIN_TIME;
    int STATUS_CODE;
} USER_PROFILE;

// Primary linked list structure
typedef struct Node {
    USER_PROFILE data;
    struct Node* next;
} Node;

Node* initList() {
    return NULL;
}

void addElement(Node** head, USER_PROFILE newData) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        return;
    }
    newNode->data = newData;
    newNode->next = *head;
    *head = newNode;
}

void freeList(Node** head) {
    Node* curr = *head;
    Node* next;
    while (curr) {
        next = curr->next;
        free(curr);
        curr = next;
    }
    *head = NULL;
}

// Secondary linked list structure for tracking activity level
typedef struct ActivityNode {
    long ACTIVITY_TIMESTAMP;
    int ACTIVITY_LEVEL;
    struct ActivityNode* next;
} ActivityNode;

ActivityNode* initActivityList() {
    return NULL;
}

void updateActivity(Node** head, long timestamp, int activityLevel) {
    Node* curr = *head;
    while (curr) {
        if (curr->data.LAST_LOGIN_TIME == timestamp) {
            // Update activity level for existing user
            curr->data.STATUS_CODE = activityLevel;
            return;
        }
        curr = curr->next;
    }
}

void cleanUpInactivity(Node** head, long inactivityThreshold) {
    Node* curr = *head;
    ActivityNode* actCurr = initActivityList();
    while (curr) {
        if (curr->data.LAST_LOGIN_TIME < inactivityThreshold) {
            // Remove user with inactivity
            Node* temp = curr;
            curr = curr->next;
            free(temp);
            *head = curr;
        } else {
            updateActivity(&actCurr, curr->data.LAST_LOGIN_TIME, curr->data.STATUS_CODE);
            curr = curr->next;
        }
    }
}

// Web API functions
void updateUserProfile(Node** head, int userId, USER_PROFILE updatedData) {
    Node* curr = *head;
    while (curr) {
        if (curr->data.USER_ID == userId) {
            // Update user profile
            curr->data = updatedData;
            return;
        }
        curr = curr->next;
    }
}

USER_PROFILE deleteUserProfile(Node** head, int userId) {
    Node* curr = *head;
    USER_PROFILE defaultData;
    while (curr) {
        if (curr->data.USER_ID == userId) {
            // Delete user and return default profile
            Node* temp = curr;
            curr = curr->next;
            free(temp);
            return defaultData;
        }
        curr = curr->next;
    }
}

int main() {
    // Initialize primary list
    Node* head = initList();

    // Add elements to the list
    USER_PROFILE newData1 = {123, "user1@example.com", 1643723400, 1};
    addElement(&head, newData1);

    USER_PROFILE newData2 = {456, "user2@example.com", 1643750000, 0};
    addElement(&head, newData2);

    // Update activity levels
    updateActivity(&head, 1643751000, 1);
    updateActivity(&head, 1643723500, 0);

    // Clean up inactivity
    cleanUpInactivity(&head, 1643750000);

    // Update user profile using HTTP PUT
    updateUserProfile(&head, 123, newData2);

    // Delete user profile using HTTP DELETE
    USER_PROFILE deletedData = deleteUserProfile(&head, 456);

    return 0;
}

