    record** records = (record**)malloc(threshold * sizeof(record));
    if (!records) return NULL; // Handle malloc failure

    for (int i = 0; i < threshold; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            free(records);
            return NULL; // Handle malloc failure
        }
        records[i]->value = rand() % 100; // Initialize record value
    }

    return records;
}

// Function to validate unique keys
int validate_unique_keys(int* keys, int num_keys) {
    for (int i = 0; i < num_keys - 1; i++) {
        for (int j = i + 1; j < num_keys; j++) {
            if (keys[i] == keys[j]) return 0; // Duplicate key found
        }
    }
    return 1; // No duplicate keys found
}

