void serialize_records(record** records, int num_records) {
    FILE* file = fopen("records.txt", "w");
    if (!file) return; // Handle file opening failure

    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d\n", records[i]->value);
    }

    fclose(file);
}

