        if (!loaded_record) {
            fclose(file);
            free(loaded_record);
            return NULL; // Handle malloc failure
        }
        loaded_record->value = atoi(buffer);
        num_loaded_records++;
    }

    fclose(file);

    return (record**)malloc(num_loaded_records * sizeof(record*));
}

