// Function to validate that no two records share the same key
int validate_keys(int* keys, int num_keys) {
    // Use a hash table to store the keys and check for duplicates
    int* hash_table = (int*)malloc(num_keys * sizeof(int));
    int i;

    for (i = 0; i < num_keys; i++) {
        hash_table[keys[i]] = 1;
    }

    for (i = 0; i < num_keys; i++) {
        if (hash_table[keys[i]] == 0) return 1;  // Found a duplicate
    }

    free(hash_table);
    return 0;  // No duplicates found
}

