    int idx;
    NFAPI_CRC_INDICATION_PDU_T *new_element;
    pthread_error_code err;

    // Initialize the list with a default size
    if (*size == 0) {
        *size = 10; // Default initial capacity
        *list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        for (idx = 0; idx < *size; idx++) {
            (*list)[idx] = NULL;
        }
    }

    // Insert a new element
    if ((err = pthread_mutex_lock(mutex)) != 0) {
        perror("Failed to acquire the mutex");
        return;
    }
    try {
        if (idx >= *size) { // If the list is full, reallocate it with double the size
            int new_size = *size * 2;
            NFAPI_CRC_INDICATION_PDU_T **new_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(*list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
            if (!new_list) {
                printf("Memory allocation failed\n");
                return;
            }
            for (int i = *size; i < new_size; i++) {
                new_list[i] = NULL;
            }
            *list = new_list;
            *size = new_size;
        }
        (*list)[idx] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!(*list)[idx]) {
            printf("Memory allocation failed\n");
            return;
        }
    } catch (pthread_error_code err) {
        pthread_mutex_unlock(mutex);
    }

    // Delete an element
    try {
        pthread_mutex_lock(mutex);
        if (idx < *size) {
            free((*list)[idx]);
            for (int i = idx; i < *size - 1; i++) {
                (*list)[i] = (*list)[i + 1];
            }
            idx--;
        } else if (idx == *size) {
            // If the list is empty, just unlock and exit
            pthread_mutex_unlock(mutex);
            return;
        }
    } catch (pthread_error_code err) {
        pthread_mutex_unlock(mutex);
    }

    // Retrieve an element
    try {
        pthread_mutex_lock(mutex);
        if (idx < *size) {
            return (*list)[idx];
        }
    } catch (pthread_error_code err) {
        pthread_mutex_unlock(mutex);
    }
}

