#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    char* description;
    int priority;
    int status;
    time_t due_date;
} Task;

// Lock-free data structure to manage tasks
Task** task_list = NULL;
int task_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_task(int id, char* desc, int pri, int stat, time_t duedate) {
    pthread_mutex_lock(&lock);

    Task* new_task = (Task*)malloc(sizeof(Task));
    new_task->id = id;
    new_task->description = desc;
    new_task->priority = pri;
    new_task->status = stat;
    new_task->due_date = duedate;

    task_list = (Task**)realloc(task_list, sizeof(Task*) * (task_count + 1));
    task_list[task_count] = new_task;
    task_count++;

    pthread_mutex_unlock(&lock);
}

void update_task(int id, char* desc, int pri, int stat) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->id == id) {
            task_list[i]->description = desc;
            task_list[i]->priority = pri;
            task_list[i]->status = stat;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void delete_task(int id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->id == id) {
            free(task_list[i]);
            memcpy(&task_list[i], &task_list[i + 1], sizeof(Task*) * (task_count - i - 1));
            task_count--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

Task* get_task(int id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->id == id) {
            Task* result = task_list[i];
            pthread_mutex_unlock(&lock);
            return result;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void free_tasks() {
    for (int i = 0; i < task_count; i++) {
        free(task_list[i]);
    }
    free(task_list);
}
