// Secondary array to track the age of each PHY_CONTEXT structure
int* age_array = NULL;
int age_array_size = 0;

// Function to initialize the arrays and logging framework
void init_arrays() {
    phy_array = (PHY_CONTEXT**)malloc(sizeof(PHY_CONTEXT*) * MAX_ARRAY_SIZE);
    age_array = (int*)malloc(sizeof(int) * MAX_ARRAY_SIZE);

    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        phy_array[i] = NULL;
        age_array[i] = -1; // Indicates the age of each structure
    }
}

// Function to allocate memory for a new PHY_CONTEXT structure and update the arrays
void add_phy_context(int phy_channel_id, int base_station_id, int frame_number, int phy_layer_status) {
    if (phy_array_size >= MAX_ARRAY_SIZE) {
        printf("Error: Array is full. Cannot add more elements.\n");
        return;
    }

    PHY_CONTEXT* new_entry = (PHY_CONTEXT*)malloc(sizeof(PHY_CONTEXT));
    new_entry->phy_channel_id = phy_channel_id;
    new_entry->base_station_id = base_station_id;
    new_entry->frame_number = frame_number;
    new_entry->phy_layer_status = phy_layer_status;

    phy_array[phy_array_size] = new_entry;
    age_array[phy_array_size++] = 0; // Initialize the age of the structure
}

// Function to deallocate memory for a PHY_CONTEXT structure and update the arrays
void remove_phy_context(int index) {
    if (index >= phy_array_size || index < 0) {
        printf("Error: Index out of bounds.\n");
        return;
    }

    free(phy_array[index]);
    phy_array[index] = NULL;

    // Update the age array to prevent deletion of structures that are not yet cleaned up
    age_array[index] = -1; // Indicates the structure has been removed

    for (int i = index + 1; i < phy_array_size; i++) {
        phy_array[i-1] = phy_array[i];
        age_array[i-1] = age_array[i];
    }

    phy_array_size--;
}

// Function to validate the integrity of the array upon termination
void cleanup_arrays() {
    for (int i = 0; i < phy_array_size; i++) {
        if (age_array[i] > TIME_THRESHOLD) {
            remove_phy_context(i);
        }
    }
}

// Function to synchronize the primary array with an external data source
void sync_arrays() {
    // Fetch updated channel status information from the external data source
    // Update the local array accordingly, handling potential discrepancies gracefully
    // ...
}

int main() {
