#include <pthread.h>

typedef struct {
    int value;
} Record;

Record* record_collection = NULL;
size_t record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* random_int(int min, int max) {
    int num;
    pthread_mutex_lock(&lock);
    srand(time(NULL));
    num = rand() % ((max + 1) - (min)) + min;
    pthread_mutex_unlock(&lock);
    return &num;
}

int initialize_records(size_t count, int min, int max) {
    if (record_collection != NULL) {
        free(record_collection);
        record_collection = NULL;
        record_count = 0;
    }

    record_collection = (Record*)malloc(count * sizeof(Record));
    if (record_collection == NULL) {
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < count; i++) {
        int* r = random_int(min, max);
        record_collection[i].value = *r;
    }

    record_count = count;

    return 0;
}

int update_records(size_t start, size_t end, int min, int max) {
    for (size_t i = start; i < end; i++) {
        int* r = random_int(min, max);
        record_collection[i].value = *r;
    }

    return 0;
}

void cleanup() {
    if (record_collection != NULL) {
        free(record_collection);
        record_collection = NULL;
        record_count = 0;
    }
}

int main(int argc, char* argv[]) {
    // Initialize the record collection
    int count = 10000;
    int min = 1;
    int max = 100;

    initialize_records(count, min, max);

    // Perform batch update operation
    size_t start = 0;
    size_t end = count / 2;
    update_records(start, end, min, max);

    // Log the number of records processed
    printf("Records initialized: %zu\n", record_count);
    printf("Records updated: %zu\n", (end - start));

    // Cleanup
    cleanup();

    return 0;
}
