#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the 'item' structure
typedef struct {
    char* str;
    int priority;
} item_t;

// Define the dynamically resizable list of items
typedef struct {
    item_t* data;
    size_t capacity, size;
    pthread_mutex_t lock; // Thread safety mechanism
} item_list_t;

// Function to initialize an empty list
item_list_t* init_item_list() {
    item_list_t* list = malloc(sizeof(item_list_t));
    if (!list) return NULL;

    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to free the memory allocated for an item list
void destroy_item_list(item_list_t* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        free(list->data[i].str);
    }
    free(list->data);
    pthread_mutex_unlock(&list->lock);

    free(list);
}

// Function to insert a new item into the list
void insert_item(item_list_t* list, const char* str, int priority) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    // Dynamically allocate memory for the new item
    item_t* new_item = malloc(sizeof(item_t));
    if (!new_item) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_item->str = strdup(str);
    new_item->priority = priority;

    // If the list is empty, initialize it with the new item
    if (list->size == 0) {
        list->data = malloc(sizeof(item_t));
        list->data[0] = *new_item;
        list->capacity = 1;
        list->size = 1;
    } else { // Otherwise, insert the new item into the sorted list
        size_t i;
        for (i = 0; i < list->size; ++i) {
            if (priority >= list->data[i].priority || !i) break;
        }

        // Reallocate memory if necessary
        if (list->capacity <= i + 1) {
            list->data = realloc(list->data, sizeof(item_t) * (list->capacity *= 2));
        }

        // Shift existing items to make room for the new item
        memmove(&list->data[i + 1], &list->data[i], sizeof(item_t) * (list->size - i));

        list->data[i] = *new_item;
        list->size++;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to delete an item from the list
void delete_item(item_list_t* list, const char* str) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    // Find and remove the item with the matching string
    size_t i;
    for (i = 0; i < list->size; ++i) {
        if (strcmp(list->data[i].str, str) == 0) break;
    }

    if (i >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Shift remaining items to fill the gap
    memmove(&list->data[i], &list->data[i + 1], sizeof(item_t) * (list->size - i));

    free(list->data[--i].str);

    // Reallocate memory if necessary
    if ((list->capacity >> 1) >= list->size) {
        list->data = realloc(list->data, sizeof(item_t) * (list->capacity /= 2));
    }

    list->size--;
}

// Function to retrieve the item with the highest priority
item_t* get_highest_priority_item(item_list_t* list) {
    if (!list || !list->size) return NULL;

    pthread_mutex_lock(&list->lock);

    // Return a copy of the item with the highest priority
    item_t* item = malloc(sizeof(item_t));
    *item = list->data[0];
    free(list->data[0].str);
    free(list->data[0]);

    pthread_mutex_unlock(&list->lock);

    return item;
}

// Function to sort the list in ascending order of priorities
void sort_item_list(item_list_t* list) {
    if (!list || !list->size) return;

    pthread_mutex_lock(&list->lock);

    // Use a stable sorting algorithm (e.g., insertion sort)
    for (size_t i = 1; i < list->size; ++i) {
        item_t temp = list->data[i];
        size_t j;
        for (j = i; j > 0 && temp.priority <= list->data[j - 1].priority; --j) {
            list->data[j] = list->data[j - 1];
        }
        list->data[j] = temp;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    item_list_t* list = init_item_list();

    insert_item(list, "Item 1", 3);
    insert_item(list, "Item 2", 2);
    insert_item(list, "Item 3", 1);

    sort_item_list(list);

    item_t* highest_priority_item = get_highest_priority_item(list);
    printf("Highest priority item: %s (%d)\n", highest_priority_item->str, highest_priority_item->priority);

    destroy_item_list(list);

    return 0;
}
