RecordSet* createRecordSet(int numOffsets, int numKeys, int minValue, int maxValue) {
    // Validate input parameters
    if (numOffsets <= 0 || numKeys <= 0) {
        return NULL; // Handle invalid input
    }

    // Create arrays for offsets and keys
    int* offsetsArray = malloc(numOffsets * sizeof(int));
    int* keysArray = malloc(numKeys * sizeof(int));

    // Initialize random number generator
    srand(time(NULL));

    // Populate offsets and keys arrays with unique values
    for (int i = 0; i < numOffsets; i++) {
        offsetsArray[i] = i;
    }
    for (int i = 0; i < numKeys; i++) {
        keysArray[i] = i;
    }

    // Create the RecordSet structure and its components
    RecordSet* recordSet = malloc(sizeof(RecordSet));
    recordSet->offsets = offsetsArray;
    recordSet->keys = keysArray;

    int numRecords = numOffsets * numKeys;
    recordSet->records = malloc(numRecords * sizeof(record));

    // Initialize records with random values and pointers to offsets and keys
    for (int i = 0; i < numRecords; i++) {
        recordSet->records[i] = malloc(sizeof(record));
        recordSet->records[i]->offset = &offsetsArray[(i % numOffsets)];
        recordSet->records[i]->key = &keysArray[(i / numOffsets) % numKeys];
        recordSet->records[i]->value = rand() % (maxValue - minValue + 1) + minValue;
    }

    return recordSet;
}

void freeRecordSet(RecordSet* recordSet) {
    // Deallocate memory for RecordSet components
    if (recordSet->offsets != NULL) free(recordSet->offsets);
    if (recordSet->keys != NULL) free(recordSet->keys);
    for (int i = 0; i < recordSet->numRecords; i++) {
        free(recordSet->records[i]);
    }
    free(recordSet->records);

    // Set the RecordSet to NULL
    recordSet = NULL;
}

// Example usage:
int main() {
    int numOffsets = 10, numKeys = 5, minValue = 1, maxValue = 100;

    RecordSet* recordSet = createRecordSet(numOffsets, numKeys, minValue, maxValue);

    // Use the record set...

    freeRecordSet(recordSet);

    return 0;
}
