        }
    } else {
        // handle error when max_entries exceeded
        printf("Error: Maximum entries reached.\n");
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* shuffle_list(void* arg) {
    if (list != NULL && list_size > 0) {
        srand(time(NULL)); // randomize seed for shuffling
        int i, j, temp;
        for (i = 0; i < list_size; i++) {
            j = rand() % (list_size - i);
            temp = list[i].RX_UE_INFORMATION_TAG;
            list[i].RX_UE_INFORMATION_TAG = list[j].RX_UE_INFORMATION_TAG;
            list[i].RNTI = list[j].RNTI;
            list[i].CRCFLAG = list[j].CRCFLAG;
            temp = list[i].CRCFLAG;
        }
    }
    return NULL;
}

void free_list() {
    if (list != NULL) {
        free(list);
        list = NULL;
    }
