typedef struct {
    char* str;
    int value;
} Node;

Node** nodes = NULL;
int node_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_node_array(int size) {
    if (size <= 0) return;

    // Reallocate memory for the array of nodes
    nodes = realloc(nodes, sizeof(Node*) * size);
    for (int i = 0; i < size; i++) {
        Node* node = malloc(sizeof(Node));
        node->str = strdup("Initialized");
        node->value = 0;
        nodes[i] = node;
    }
    node_count = size;
}

void free_node_array() {
    for (int i = 0; i < node_count; i++) {
        Node* node = nodes[i];
        free(node->str);
        free(node);
    }
    free(nodes);
    nodes = NULL;
    node_count = 0;
}

Node* get_node(int index) {
    if (index >= 0 && index < node_count) {
        return nodes[index];
    } else {
        return NULL;
    }
}

void set_node_value(int index, int value) {
    pthread_mutex_lock(&mutex);
    Node* node = get_node(index);
    if (node != NULL) {
        node->value = value;
    }
    pthread_mutex_unlock(&mutex);
}
