    for (int i = 0; i < numKeys; i++) {
        keys[i] = i;
    }

    // Allocate and initialize records array
    record_t* records = (record_t*)malloc((numKeys) * sizeof(record_t));

    for (int i = 0; i < numKeys; i++) {
        records[i].offset = &offsets[i % numOffsets];
        records[i].key = &keys[i];
