#include <time.h>

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createPdu(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    pdu->RNTI = rnti;
    srand(time(NULL));
    pdu->CRCFLAG = rand() % 2;
    return pdu;
}

int findMax(int* arr, int size) {
    if (!arr || size == 0) {
        printf("Invalid array!\n");
        exit(1);
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void validateAndProcess(int* arr, int size) {
    // Validate array
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            if (arr[i] == arr[j]) {
                printf("Duplicate RNTI found: %d\n", arr[i]);
                exit(1);
            }
        }
    }

    // Process array
    NFAPI_CRC_INDICATION_PDU_T** pduArr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < size; i++) {
        pduArr[i] = createPdu(arr[i]);
    }

    int maxRnti = findMax(arr, size);
    printf("Largest RNTI: %d\n", maxRnti);

    // Reset system state
    for (int i = 0; i < size; i++) {
        free(pduArr[i]);
    }
    free(pduArr);
}

int main() {
    int n;
    scanf("%d", &n);
    int* arr = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    validateAndProcess(arr, n);

    // Reset system state
    free(arr);

    return 0;
}
