typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[12];
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe queue to manage NFAPI_CRC_INDATION_PDU_T structures
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} QueueNode;

QueueNode* front = NULL, *rear = NULL;

void insert(QueueNode** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    QueueNode* new_node = (QueueNode*) malloc(sizeof(QueueNode));
    if (new_node == NULL)
        return;
    new_node->data = new_data;
    new_node->next = (*head_ref);
    if ((*head_ref) != NULL)
        ((QueueNode*) *head_ref)->next = new_node;
    else
        rear = new_node;
    (*head_ref) = new_node;
}

void delete(QueueNode** head_ref) {
    if ((*head_ref) == NULL)
        return;
    QueueNode* temp = (*head_ref);
    (*head_ref) = temp->next;
    free(temp);
}

int is_empty(QueueNode* front) {
    return (front == NULL);
}

NFAPI_CRC_INDICATION_PDU_T get(QueueNode** head_ref) {
    NFAPI_CRC_INDICATION_PDU_T data;
    if (is_empty(*head_ref))
        return data; // or throw an exception
    QueueNode* temp = *head_ref;
    *head_ref = (*head_ref)->next;
    data = temp->data;
    free(temp);
    return data;
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < 50000; i++) {
        NFAPI_CRC_INDICATION_PDU_T new_data;
        new_data.RX_UE_INFORMATION_TAG[16] = 'R';
