        new_data.CRCFLAG = (rand() % 2 == 0);
        insert(&front, new_data);
    }
    for (int i = 0; i < 50000; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data = get(&front);
    }
    return 0;
}
