import csv
from dataclasses import dataclass
from typing import List

@dataclass
class NfapiCrcIndicationPduT:
    rnti: str
    crc_flag: int

def processRntiList(max_entries: int) -> List[NfapiCrcIndicationPduT]:
    rnti_list = []
    with open('rnti_input.txt', 'r') as file:
        reader = csv.reader(file)
        for row in reader:
            try:
                rnti = row[0].strip()
                crc_flag = int(row[1])
                rnti_list.append(NfapiCrcIndicationPduT(rnti, crc_flag))
                if len(rnti_list) >= max_entries:
                    break
            except (FileNotFoundError, IndexError):
                print(f"Error reading file: {file.name}")
                exit(1)
    return rnti_list

def validateRntiList(rnti_list: List[NfapiCrcIndicationPduT]) -> None:
    crc_flags = [pdu.crc_flag for pdu in rnti_list]
    if len(set(crc_flags)) > 1:
        print("Error: Inconsistent CRC flags detected")
        exit(1)

def findAndPrintLargest(rnti_list: List[NfapiCrcIndicationPduT]) -> None:
    max_rnti = max(rnti_list, key=lambda x: len(x.rnti))
    print(f"Largest RNTI: {max_rnti.rnti}")

if __name__ == "__main__":
    try:
        rnti_list = processRntiList(1000)
        validateRntiList(rnti_list)
        findAndPrintLargest(rnti_list)
    except MemoryError as e:
        print(f"Memory error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

