```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

void nfapi_crc_list_init(NFAPI_CRC_LIST* list) {
    list->size = 0;
    list->elements = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void nfapi_crc_list_insert(NFAPI_CRC_LIST* list, int index, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->lock);

    if (index > list->size) {
        // Resize the array
        void** new_elements = realloc(list->elements, sizeof(void*) * (index + 1));
        if (!new_elements) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->elements = new_elements;

        // Reinitialize the mutex lock after resizing
        pthread_mutex_init(&list->lock, NULL);
    }

    list->elements[index] = element;
    list->size = index + 1;

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_delete(NFAPI_CRC_LIST* list, int index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size) {
        // Handle out-of-bounds access
        pthread_mutex_unlock(&list->lock);
        return;
    }

    for (int i = index; i < list->size - 1; ++i) {
        list->elements[i] = list->elements[i + 1];
    }
    free(list->elements[list->size - 1]);
    list->size--;

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_insert_batch(NFAPI_CRC_LIST* list, int start_index, int count, NFAPI_CRC_INDICATION_PDU_T** elements) {
    pthread_mutex_lock(&list->lock);

    if (start_index > list->size) {
        // Resize the array
        void** new_elements = realloc(list->elements, sizeof(void*) * (start_index + count));
        if (!new_elements) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->elements = new_elements;

        // Reinitialize the mutex lock after resizing
        pthread_mutex_init(&list->lock, NULL);
    }

    for (int i = 0; i < count; ++i) {
        list->elements[start_index + i] = elements[i];
    }
    list->size = start_index + count;

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_delete_batch(NFAPI_CRC_LIST* list, int start_index, int count) {
    pthread_mutex_lock(&list->lock);

    if (start_index >= list->size || start_index + count > list->size) {
        // Handle out-of-bounds access
        pthread_mutex_unlock(&list->lock);
        return;
    }

    for (int i = 0; i < count; ++i) {
        free(list->elements[start_index + i]);
    }
    for (int i = start_index; i < list->size - count; ++i) {
        list->elements[i] = list->elements[i + count];
    }
    list->size -= count;

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_print(NFAPI_CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; ++i) {
        printf("Element %d: %p\n", i, list->elements[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_fini(NFAPI_CRC_LIST* list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}
