#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    int value;
} record;

record* create_records(int size) {
    return (record*)malloc(size * sizeof(record));
}

void set_record_values(record* records, int size, int min_value, int max_value) {
    srand(time(NULL)); // seed for random number generation
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void sort_records(record* records, int size) {
    qsort(records, size, sizeof(record), record_compare);
}

int record_compare(const void* a, const void* b) {
    const record* ra = (const record*)a;
    const record* rb = (const record*)b;
    return (ra->key - rb->key);
}

void ensure_unique_keys(record* records, int size) {
    for (int i = 1; i < size; i++) {
        while (records[i].key == records[i-1].key) {
            records[i].key++;
        }
    }
}

void free_records(record* records) {
    free(records);
}

// Example usage:
int main() {
    int offset_size, key_size, record_count;
    printf("Enter the sizes: ");
    scanf("%d %d %d", &offset_size, &key_size, &record_count);

    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    record* records = create_records(record_count);
    set_record_values(records, record_count, 0, 100); // random values between 0 and 100

    qsort(records, record_count, sizeof(record), record_compare);

    ensure_unique_keys(records, record_count);

    free_offsets(offsets);
    free_keys(keys);
    free_records(records);

    return 0;
}
