struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
};

// Thread-safe dynamic array management
typedef struct {
    struct NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* arr) {
    pthread_mutex_init(&arr->mutex, NULL);
    arr->data = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    arr->size = 0;
    arr->capacity = 1;
}

void resizeDynamicArray(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);
    size_t newCapacity = arr->capacity * 2;
    struct NFAPI_CRC_INDICATION_PDU_T* newData = (struct NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->data, sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
    if (!newData) {
        pthread_mutex_unlock(&arr->mutex);
        return;
    }
    arr->capacity = newCapacity;
    arr->data = newData;
    pthread_mutex_unlock(&arr->mutex);
}

void appendDynamicArray(DynamicArray* arr, struct NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        resizeDynamicArray(arr);
    }
    arr->data[arr->size] = *element;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

void freeDynamicArray(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->data);
    pthread_mutex_unlock(&arr->mutex);
}

// Memory pool for efficient reuse
typedef struct {
    void** blocks;
    size_t size;
    size_t capacity;
} MemoryPool;

void initMemoryPool(MemoryPool* pool, size_t initialCapacity) {
    pool->blocks = (void**)malloc(initialCapacity * sizeof(void*));
    pool->size = 0;
    pool->capacity = initialCapacity;
}

void addBlockToMemoryPool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size >= pool->capacity) {
        // Reallocate and resize
        size_t newCapacity = pool->capacity * 2;
        void** newData = (void**)realloc(pool->blocks, sizeof(void*) * newCapacity);
        if (!newData) {
            pthread_mutex_unlock(&pool->mutex);
            return;
        }
        pool->capacity = newCapacity;
        pool->blocks = newData;
    }
    pool->blocks[pool->size] = block;
    pool->size++;
    pthread_mutex_unlock(&pool->mutex);
}

void freeMemoryPool(MemoryPool* pool) {
    for (int i = 0; i < pool->size; i++) {
        free((void*)pool->blocks[i]);
    }
    free(pool->blocks);
}

// Graph traversal and persistence
typedef struct {
    DynamicArray nodes;
    MemoryPool edges;
} Graph;

void initGraph(Graph* graph) {
    initDynamicArray(&graph->nodes);
    initMemoryPool(&graph->edges, 1000);
}

void addNodeToGraph(Graph* graph, struct NFAPI_CRC_INDICATION_PDU_T* node) {
    appendDynamicArray(&graph->nodes, node);
}

void persistGraph(Graph* graph) {
    // Implementation details omitted
