        node.RX_UE_INFORMATION_TAG = rand();
        node.RNTI = rand();
        node.CRC_INDICATION_REL8_TAG = rand();
        node.CRCFLAG = rand() % 2;
        appendDynamicArray(&arr, &node);
    }

    freeDynamicArray(&arr);

    return 0;
}
