    while (!readingQueue.empty() && readingQueue.top().timestamp < (reading.timestamp - flushIntervalSec_ * 60)) {
        Reading oldReading = readingQueue.top();
        readingQueue.pop();
        // Handle old readings as necessary
    }
    if (readingQueue.size() >= maxBufferReadings_) {
        Reading oldestReading = readingQueue.top();
        readingQueue.pop();
        // Handle oldest reading as necessary
    }
    readingQueue.push(reading);
