NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indications = NULL;
int nfapi_crc_indications_len = 0;

pthread_mutex_t nfapi_crc_indications_lock = PTHREAD_MUTEX_INITIALIZER;

void nfapi_crc_indication_manager(int max_entries, int rnti_start, int rnti_end) {
    NFAPI_CRC_INDICATION_PDU_T *new_crc_indications;
    int new_crc_indications_len = 0;

    pthread_mutex_lock(&nfapi_crc_indications_lock);

    while (1) {
        if (new_crc_indications_len >= max_entries) break;

        if ((new_crc_indications = realloc(nfapi_crc_indications, 
                                            (nfapi_crc_indications_len + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            pthread_mutex_unlock(&nfapi_crc_indications_lock);
            return;
        }

        nfapi_crc_indications = new_crc_indications;
    }

    for (int i = 0; i < nfapi_crc_indications_len; i++) {
        if ((nfapi_crc_indications[i].RNTI >= rnti_start) && (nfapi_crc_indications[i].RNTI <= rnti_end)) {
            new_crc_indications[new_crc_indications_len] = nfapi_crc_indications[i];
            new_crc_indications_len++;
        }
    }

    pthread_mutex_unlock(&nfapi_crc_indications_lock);
}

int main() {
