    NFAPI_CRC_INDICATION_PDU_T* entries;
    pthread_mutex_t lock;
} NFAPICRC_INDICATION_LIST_T;

void nfapi_crc_indication_list_init(NFAPICRC_INDICATION_LIST_T* list, int max_entries) {
    list->max_entries = max_entries;
    list->current_size = 0;
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
}

void nfapi_crc_indication_list_add_entry(NFAPICRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    // Validate integrity of the new entry
    if (entry.rx_ue_info.tag == 0 || !validate_crc_flag(entry.crc_indication_rel8_tag.CRCFLAG)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->current_size < list->max_entries) {
        list->entries[list->current_size] = entry;
        list->current_size++;

        // Implement rate limiting feature
        if (list->current_size > 10) { // Adjust the value based on your requirements
            usleep(100000); // 0.1 seconds
        }
    } else {
        printf("List is full! Cannot add more entries.\n");
    }

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_indication_list_cleanup_expired_entries(NFAPICRC_INDICATION_LIST_T* list, int timeout_duration) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->current_size; i++) {
        // Check if an entry has expired based on the configured timeout duration
        if (is_entry_expired(list->entries[i], timeout_duration)) {
            // Remove the expired entry and shift the remaining entries down
            memmove(&list->entries[i], &list->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->current_size - i));
            list->current_size--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_indication_list_resize(NFAPICRC_INDICATION_LIST_T* list, int new_max_entries) {
    if (new_max_entries > list->max_entries) {
        NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        for (int i = 0; i < list->current_size; i++) {
            temp[i] = list->entries[i];
        }

        free(list->entries);
        list->entries = temp;
        list->max_entries = new_max_entries;
    } else if (new_max_entries < list->max_entries) {
        NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        int remaining_size = new_max_entries;
        for (int i = 0; i < list->current_size; i++) {
            if (remaining_size > 0) {
                temp[i] = list->entries[list->current_size - i - 1];
                remaining_size--;
            } else {
                break;
            }
        }

        free(list->entries);
        list->entries = temp;
        list->max_entries = new_max_entries;
        list->current_size = remaining_size;
    }
}

void nfapi_crc_indication_list_priority_insertion(NFAPICRC_INDICATION_LIST_T* list) {
    for (int i = 0; i < list->current_size; i++) {
        // Find the entry with the highest CRCFLAG value
        int max_crcflag_index = i;
        for (int j = i + 1; j < list->current_size; j++) {
            if (list->entries[j].crc_indication_rel8_tag.CRCFLAG > list->entries[max_crcflag_index].crc_indication_rel8_tag.CRCFLAG) {
                max_crcflag_index = j;
            }
        }

        // Swap the entry with the highest CRCFLAG value to the front of the list
        NFAPI_CRC_INDICATION_PDU_T temp = list->entries[i];
        list->entries[i] = list->entries[max_crcflag_index];
        list->entries[max_crcflag_index] = temp;
    }
}

void nfapi_crc_indication_list_thread_safe_insertion(NFAPICRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    // Add the entry to the list using priority insertion
    nfapi_crc_indication_list_priority_insertion(list);

    pthread_mutex_unlock(&list->lock);
}
