        var elementId = request.Form["elementId"];
        var htmlContent = request.Form["htmlContent"];

        if (!ValidateInputData(request))
        {
            return new PageUpdateResponse { ShouldRefresh = false, Success = false };
        }

        try
        {
            await _reliableService.UpdateHtmlContent(pageSectionId, elementId, htmlContent);
        }
        catch (Exception ex)
        {
            await RetryFailedUpdate(ex);
        }

        return new PageUpdateResponse { ShouldRefresh = true, Success = true };
    }

    private bool ValidateInputData(HttpRequestMessage request)
    {
        // Validation logic here
    }

    private async Task RetryFailedUpdate(Exception ex)
    {
        int retryCount = 0;
        while (retryCount < 3)
        {
            try
            {
                await _reliableService.UpdateHtmlContent(ex);
                return;
            }
            catch (Exception innerEx)
            {
                if (++retryCount >= 3 || !await ShouldRetry(innerEx))
                {
                    throw;
                }

                await Task.Delay((int)(Math.Pow(2, retryCount) * 1000));
            }
        }

        // Log and return error
    }

