#include <random>

class RandomNumberGenerator {
private:
    std::mt19937 engine;
    int seed;

public:
    RandomNumberGenerator(int seed = 0) : seed(seed) {
        if (seed == 0) {
            // use current timestamp as default seed
            seed = static_cast<int>(std::chrono::high_resolution_clock::now().time_since_epoch().count());
        }
        engine.seed(seed);
    }

    template<typename Distribution>
    double sample(const Distribution& dist) {
        return dist(engine);
    }

    void setSeed(int newSeed) {
        seed = newSeed;
        engine.seed(seed);
    }
};

class UniformDistribution {
public:
    UniformDistribution(double a, double b) : a(a), b(b) {}

    template<typename Engine>
    double operator()(Engine& e) const {
        std::uniform_real_distribution<double> dist(a, b);
        return dist(e);
    }

private:
    double a;
    double b;
};

class NormalDistribution {
public:
    NormalDistribution(double mean, double stddev) : mean(mean), stddev(stddev) {}

    template<typename Engine>
    double operator()(Engine& e) const {
        std::normal_distribution<double> dist(mean, stddev);
        return dist(e);
    }

private:
    double mean;
    double stddev;
};

class ExponentialDistribution {
public:
    ExponentialDistribution(double rate) : rate(rate) {}

    template<typename Engine>
    double operator()(Engine& e) const {
        std::exponential_distribution<double> dist(rate);
        return dist(e);
    }

private:
    double rate;
};

class BetaDistribution {
public:
    BetaDistribution(double alpha, double beta) : alpha(alpha), beta(beta) {}

    template<typename Engine>
    double operator()(Engine& e) const {
        std::beta_distribution<double> dist(alpha, beta);
        return dist(e);
    }

private:
    double alpha;
    double beta;
};

int main() {
    RandomNumberGenerator rng;

    UniformDistribution uniform(0.0, 1.0);
    NormalDistribution normal(0.0, 1.0);

    for (int i = 0; i < 10; ++i) {
        std::cout << "Uniform: " << rng.sample(uniform) << std::endl;
        std::cout << "Normal: " << rng.sample(normal) << std::endl;
    }

    return 0;
}
