void* allocArray(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int initArrays(long** offsets, int** keys, Record** records, long offsetCount, int keyCount, int recordSize, int minValue, int maxValue) {
    *offsets = allocArray(offsetCount * sizeof(long));
    if (!*offsets) return -1;

    *keys = allocArray(keyCount * sizeof(int));
    if (!*keys) {
        free(*offsets);
        *offsets = NULL;
        return -1;
    }

    *records = allocArray(recordSize * sizeof(Record));
    if (!*records) {
        free(*offsets);
        free(*keys);
        *offsets = NULL;
        *keys = NULL;
        return -1;
    }

    // Initialize record values
    srand(time(NULL));
    for (int i = 0; i < recordSize; i++) {
        (*records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    return 0;
}

void cleanupArrays(long** offsets, int** keys, Record** records) {
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*records) free(*records);
}
