    int attempts = 0;
    uint64_t start_time = pthread_clock_gettime();

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        int rnti = -1;
        while (rnti == -1 && retries <= MAX_RETRIES) {
            rnti = rand() % INT_MAX;
            pthread_mutex_lock(&lock);
            for (int j = 0; j < i; j++) {
                if (list[j].rnti == rnti) {
                    rnti = -1;
                    pthread_mutex_unlock(&lock);
                    break;
                }
            }
            pthread_mutex_unlock(&lock);
            if (rnti != -1) {
                pdu->rnti = rnti;
            } else {
                retries++;
                usleep(pow(2, retries));
            }
