const { performance } = require('perf_hooks');
const logger = require('./logger');
const rateLimiter = require('./rateLimiter');

class StreamProcessor {
  constructor() {
    this.dataPoints = [];
    this.paused = false;
    this.state = 'STOPPED';
    this.instances = [];
    this.rateLimit = 10000; // points per second
  }

  start() {
    if (this.state === 'STARTED') return;
    this.state = 'STARTED';
    this.paused = false;

    for (let i = 0; i < 10; i++) {
      this.instances.push(new Instance());
    }
  }

  pause() {
    if (this.paused) return;
    this.paused = true;
    this.state = 'PAUSED';
  }

  resume() {
    if (!this.paused) return;
    this.paused = false;
    this.state = 'STARTED';
  }

  stop() {
    if (this.state === 'STOPPED') return;
    this.state = 'STOPPED';
    this.instances.forEach(instance => instance.destroy());
  }

  process(dataPoint) {
    const instance = getInstance();
    instance.addDataPoint(dataPoint);
    rateLimiter.consume();

    if (instance.dataPoints.length >= this.rateLimit) {
      logger.log('Rate limit reached. Pausing stream processing.');
      this.pause();
    }
  }

  getHealthStatus() {
    return {
      instances: this.instances.map(instance => instance.getHealthStatus()),
      rateLimit: rateLimiter.getRemainingCapacity(),
    };
  }
}

class Instance {
  constructor() {
    this.dataPoints = [];
  }

  addDataPoint(dataPoint) {
    this.dataPoints.push(dataPoint);
  }

  getHealthStatus() {
    return {
      dataPoints: this.dataPoints.length,
      memoryUsage: process.memoryUsage().rss,
    };
  }

  destroy() {
    this.dataPoints = [];
  }
}

function getInstance() {
  const instanceIndex = Math.floor(Math.random() * this.instances.length);
  return this.instances[instanceIndex];
}
