typedef struct record {
    float value;
    time_t timestamp;
    char* stringRep;
} Record;

Record* insertAtHead(Record** head, float newFloat) {
    Record* newNode = (Record*) malloc(sizeof(Record));
    if (*head != NULL) {
        newNode->timestamp = time(NULL);
        newNode->value = newFloat;
        newNode->stringRep = (char*) malloc(32 * sizeof(char));
        sprintf(newNode->stringRep, "%.2f", newFloat);
        newNode->next = *head;
        *head = newNode;
    } else {
        (*head) = newNode;
    }
    return *head;
}

Record* deleteAtTail(Record** head) {
    if (*head == NULL) {
        return *head;
    }
    Record* current = *head;
    Record* previous = NULL;
    while (current->next != NULL) {
        previous = current;
        current = current->next;
    }
    free(current);
    if (previous == NULL) {
        *head = NULL;
    } else {
        previous->next = NULL;
    }
    return *head;
}

Record* modifyAtHead(Record** head, float newFloat) {
    if (*head != NULL) {
        (*head)->value = newFloat;
        (*head)->timestamp = time(NULL);
        sprintf((*head)->stringRep, "%.2f", newFloat);
    }
    return *head;
}

void cleanup(Record* head) {
    Record* current = head;
    Record* temp = NULL;
    while (current != NULL) {
        temp = current->next;
        free(current->stringRep);
        free(current);
        current = temp;
    }
}
