    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return NULL;
    }

    Config *config = malloc(sizeof(Config));
    config->name = NULL;
    config->section = NULL;

    Section *currentSection = NULL;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *keyValue = strtok(line, "=[\n\r\t]");
        if (keyValue == NULL) continue;
        if (strchr(keyValue, '[') != NULL) {
            // new section
            Section *newSection = malloc(sizeof(Section));
            newSection->name = strdup(strtok(keyValue, "[") + 1);
            newSection->count = 0;
            newSection->sections = NULL;
            if (currentSection == NULL) config->section = newSection;
            else currentSection->sections[currentSection->count++] = newSection;
            currentSection = newSection;
        } else {
            // key-value pair
            char *key = strtok(keyValue, "=");
            char *value = strtok(NULL, " \n\r\t");
            if (currentSection != NULL) {
                currentSection->sections[currentSection->count++] = malloc(sizeof(Section));
                ((Section *)currentSection->sections[currentSection->count - 1])->name = key;
                ((Section *)currentSection->sections[currentSection->count - 1])->value = value;
            }
        }
    }

    fclose(file);
    return config;
}

int getConfigSections(Config *config) {
    int count = 0;
    Section *section = config->section;
    while (section != NULL) {
        count++;
        section = section->sections[section->count - 1];
    }
    return count;
