import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.Map;

public class TransactionProcessor {
    private static final int MAX_OUTLIER_THRESHOLD = 5; // adjust as needed

    public Map<ZonedDateTime, Map<Long, Double>> processTransactions(java.io.InputStream inputStream) {
        Map<ZonedDateTime, Map<Long, Double>> hourlyTransactions = new HashMap<>();

        try (java.util.Scanner scanner = new java.util.Scanner(inputStream).useDelimiter("\\A").next()) {
            String[] records = scanner.split("\n");

            for (String record : records) {
                if (record.isEmpty()) {
                    continue; // skip empty lines
                }

                String[] fields = record.split(",");
                long customerId = Long.parseLong(fields[0]);
                double transactionAmount = Double.parseDouble(fields[1]);
                ZonedDateTime timestamp = ZonedDateTime.parse(fields[2], DateTimeFormatter.ISO_DATE_TIME);

                hourlyTransactions.computeIfAbsent(timestamp, k -> new HashMap<>()).put(customerId, transactionAmount);
            }
        } catch (Exception e) {
            // handle exceptions as needed
        }

        processHourlyTransactions(hourlyTransactions);

        return hourlyTransactions;
    }

    private void processHourlyTransactions(Map<ZonedDateTime, Map<Long, Double>> hourlyTransactions) {
        for (Map.Entry<ZonedDateTime, Map<Long, Double>> entry : hourlyTransactions.entrySet()) {
            ZonedDateTime timestamp = entry.getKey();
            Map<Long, Double> customerTransactions = entry.getValue();

            // compute total transaction volume and average transaction amount per customer
            double totalVolume = 0;
            double averageAmount = 0;
            int customerCount = 0;

            for (Map.Entry<Long, Double> customerEntry : customerTransactions.entrySet()) {
                long customerId = customerEntry.getKey();
                double transactionAmount = customerEntry.getValue();

                totalVolume += transactionAmount;
                averageAmount += transactionAmount;
                customerCount++;
            }

            averageAmount /= customerCount;

            // detect outliers in transaction amounts
            Map<Long, Double> outlierCustomers = new HashMap<>();
            for (Map.Entry<Long, Double> customerEntry : customerTransactions.entrySet()) {
                long customerId = customerEntry.getKey();
                double transactionAmount = customerEntry.getValue();

                if (Math.abs(transactionAmount - averageAmount) > MAX_OUTLIER_THRESHOLD * averageAmount) {
                    outlierCustomers.put(customerId, transactionAmount);
                }
            }

            // analyze outliers for unusual spikes in transaction volumes
            // ...
        }
    }
}
