typedef struct DataItem {
    float value;
    bool flag;
} DataItem;

typedef struct Node {
    DataItem* item;
    struct Node* next;
} Node;

void init_data_structure(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading: %s\n");
        return;
    }

    Node* head = NULL;
    Node* current = NULL;
    DataItem* item = NULL;

    while (fscanf(file, "%f %d", &item->value, &item->flag) == 2) {
        if (!head) {
            head = malloc(sizeof(Node));
            current = head;
        } else {
            current->next = malloc(sizeof(Node));
            current = current->next;
        }
        item->item = item;

        if (current->next) {
            current = current->next;
        }
    }

    fclose(file);
}

