public class UpdatePageElement
{
    private readonly ILoggingService _loggingService;
    private readonly IUpdateService _updateService;

    public UpdatePageElement(ILoggingService loggingService, IUpdateService updateService)
    {
        _loggingService = loggingService;
        _updateService = updateService;
    }

    [HttpPost]
    public async Task<string> HandleRequest([FromBody] UpdateRequest request)
    {
        try
        {
            await _updateService.UpdateElement(request.PageSectionId, request.ElementId, request.HtmlContent);

            // Log the successful update
            _loggingService.LogInformation($"Updated page element {request.ElementId} successfully.");

            return "Refresh the page to see the updated content.";
        }
        catch (UnauthorizedAccessException ex)
        {
            // Log the error and provide a custom error message
            _loggingService.LogError("Unauthorized access attempt.", ex);
            return "Insufficient permissions to update the page element. Please contact an administrator for assistance.";
        }
        catch (Exception ex)
        {
            // Log the error and provide a generic error message
            _loggingService.LogError("An unexpected error occurred while updating the page element.", ex);
            return "Error updating the page element. Please try again later or contact an administrator for assistance.";
        }
    }
}

public class UpdateRequest
{
    public int PageSectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
