```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for NICBs
typedef struct {
    // MAC Header
    char mac[6];
    // IP Header
    uint16_t src_ip;
    uint16_t dst_ip;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    // TCP Header
    uint16_t src_port;
    uint16_t dst_port;
} NICB;

// Function to initialize dynamic array of NICBs
int init_nicbs(int max_nicbs) {
    NICB* nicbs = (NICB*)malloc(max_nicbs * sizeof(NICB));
    if (!nicbs) return -1; // memory allocation failed

    for (int i = 0; i < max_nicbs; i++) {
        // Generate random MAC address
        srand(time(NULL) + i);
        for (int j = 0; j < 6; j++) {
            nicbs[i].mac[j] = (char)(rand() % 256);
        }

        // Generate random IP headers
        nicbs[i].src_ip = rand() % 65536;
        nicbs[i].dst_ip = rand() % 65536;
        nicbs[i].ttl = rand() % 255 + 1;
        nicbs[i].protocol = rand() % 256;

        // Calculate IP checksum
        uint16_t ip_checksum = 0;
        for (int j = 0; j < 10; j++) {
            ip_checksum += (nicbs[i].src_ip >> (j * 8)) + (nicbs[i].dst_ip >> (j * 8));
        }
        nicbs[i].checksum = ~ip_checksum;

        // Validate IP checksum
        if (nicbs[i].checksum != 0) {
            // Re-calculate IP checksum if invalid
            ip_checksum = 0;
            for (int j = 0; j < 10; j++) {
                ip_checksum += (nicbs[i].src_ip >> (j * 8)) + (nicbs[i].dst_ip >> (j * 8));
            }
            nicbs[i].checksum = ~ip_checksum;
        }

        // Initialize TCP headers
        nicbs[i].src_port = rand() % 65535;
        nicbs[i].dst_port = rand() % 65535;
    }

    return max_nicbs;
}

// Function to load resource bundle from file and count items
int load_resource_bundle(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) return -1; // file not found or error opening

    int num_items = 0;
    while (fscanf(file, "%d", &num_items) == 1);
    fclose(file);

    return num_items;
}

int main() {
    int max_nicbs = 1024;
    int nicb_count = init_nicbs(max_nicbs);
    if (nicb_count < 0) printf("Error initializing NICBs!\n");

    const char* resource_path = "resource.bundle";
    int num_items = load_resource_bundle(resource_path);
    if (num_items < 0) printf("Error loading resource bundle!\n");

    return 0;
}
