#include <iostream>
#include <chrono>
#include <string>
#include <memory>
#include <vector>
#include <thread>
#include <mutex>
#include <queue>
#include <unordered_map>

class MetricRecord {
public:
    double value;
    std::string name;
    std::chrono::milliseconds timestamp;

    MetricRecord(double val, const std::string& nm, const std::chrono::milliseconds& ts)
        : value(val), name(nm), timestamp(ts) {}
};

class MetricStore {
private:
    struct Node {
        MetricRecord* record;
        Node* left;
        Node* right;
    };

    Node* root;
    std::mutex mtx;
    std::priority_queue<std::chrono::milliseconds> timestamps;

public:
    MetricStore() : root(nullptr) {}

    void addMetric(const MetricRecord& record) {
        timestamps.push(record.timestamp);

        if (root == nullptr) {
            root = new Node();
            root->record = &record;
            return;
        }

        Node* current = root;
        while (true) {
            if (record.timestamp < *timestamps.top()) {
                if (current->left == nullptr) {
                    current->left = new Node();
                    current->left->record = &record;
                    break;
                }
                current = current->left;
            } else {
                if (current->right == nullptr) {
                    current->right = new Node();
                    current->right->record = &record;
                    break;
                }
                current = current->right;
            }
        }
    }

    MetricRecord* getMetric(std::chrono::milliseconds timestamp) const {
        Node* current = root;

        while (current != nullptr) {
            if (*timestamps.top() < timestamp) {
                current = current->left;
            } else if (*timestamps.top() > timestamp) {
                current = current->right;
            } else {
                return current->record;
            }
        }

        return nullptr;
    }
};
