        nfaPiArray[i]->RX_UE_INFORMATION_TAG = i;
        nfaPiArray[i]->RNTI = i;
        nfaPiArray[i]->CRC_INDICATION_REL8_TAG = i;
    }
}

// Function to validate the integrity of the array upon termination
void validateNFAPiArray() {
    for (int i = 0; i < nfaPiArraySize; i++) {
        if (nfaPiArray[i] == NULL) {
            printf("Error: Array element %d is null.\n", i);
        }
    }
}

// Function to resize the array
void resizeNFAPiArray(int newSize) {
    NFAPI_CRC_INDICATION_PDU_T **tempArray = (NFAPI_CRC_INDICATION_PDU_T **)malloc(newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (tempArray == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Copy elements from old array to new array
    for (int i = 0; i < nfaPiArraySize && i < newSize; i++) {
        tempArray[i] = nfaPiArray[i];
    }

    // Free old array and update the size
    for (int i = nfaPiArraySize; i > newSize; i--) {
        free(nfaPiArray[i - 1]);
    }
    free(nfaPiArray);
    nfaPiArray = tempArray;
    nfaPiArraySize = newSize;
}

int main() {
    // Initialize the array
    initNFAPiArray();

    // Use the array...

    // Validate the integrity of the array upon termination
    validateNFAPiArray();

    return 0;
