    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_memory(int num_packets) {
    void* memory = NULL;
    size_t required_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_packets;

    if (required_size > MAX_MEMORY_USAGE) {
        printf("Memory allocation failed due to excessive request.\n");
        return NULL;
    }

    memory = malloc(required_size);
    if (!memory) {
        printf("Memory allocation failed. Out of memory.\n");
    } else {
        printf("Memory allocated successfully for %d packets.\n", num_packets);
    }

    // Simulate high-frequency packet arrivals and evaluate performance
    int packet_arrivals = 1000;
    clock_t start_time = clock();
    for (int i = 0; i < packet_arrivals; i++) {
        NFAPI_CRC_INDICATION_PDU_T* packet = memory + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        // Set CRCFLAG randomly
        packet->CRCFLAG = rand() % 2;
    }
    clock_t end_time = clock();
    printf("Processing completed in %f seconds.\n", (double)(end_time - start_time) / CLOCKS_PER_SEC);

    return memory;
}

int main() {
    int num_packets = 1000; // Initial packet count
    void* memory = allocate_memory(num_packets);

    if (!memory) {
        printf("Memory allocation failed. Aborting.\n");
        return 1;
    }

    free(memory); // Deallocate memory when not needed

    return 0;
}

