void read_and_process_data(int **data, int *n, int min_range, int max_range) {
    FILE *file = stdin;
    if (fseek(file, 0, SEEK_END) == 0) {
        rewind(file);
    } else {
        printf("Failed to read from standard input.\n");
        return;
    }

    char line[1024];
    int cnt = 0;
    while (fgets(line, sizeof(line), file)) {
        if (line[strlen(line) - 1] == '\n')
            line[strlen(line) - 1] = '\0';

        int num;
        if (sscanf(line, "%d", &num) == 1) {
            if (num >= min_range && num <= max_range) {
                if (*data != NULL)
                    *data = realloc(*data, (*n + 1) * sizeof(int));
                else
                    *data = malloc(sizeof(int));
                ((int *)*data)[*n] = num;
                (*n)++;
            }
        }
    }

    // Convert the array of integers to NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDATION_PDU_T *pdu_array = NULL;
    if (*n > 0) {
        pdu_array = (NFAPI_CRC_INDATION_PDU_T *)malloc(*n * sizeof(NFAPI_CRC_INDATION_PDU_T));

        for (int i = 0; i < *n; i++) {
