typedef struct {
    char mac[6];
    int rnti;
} MAC_HEADER;

typedef struct {
    char ip[14];
    int checksum;
} IP_HEADER;

typedef struct {
    MAC_HEADER mac;
    IP_HEADER ip;
    int tcp;
} NICB;

NICB* nicb_array = NULL;
int nicb_count = 0;
int nicb_size = 1024;

void init_nicb_array() {
    if (nicb_array != NULL) return;
    nicb_array = (NICB*)malloc(nicb_size * sizeof(NICB));
    memset(nicb_array, 0, nicb_size * sizeof(NICB));
}

void add_nicb(int rnti) {
    init_nicb_array();
    if (nicb_count >= nicb_size) {
        printf("Error: NICB array is full.\n");
        return;
    }
    nicb_array[nicb_count].mac.rnti = rnti;
    nicb_count++;
}

void generate_mac_header(NICB* nicb, char* mac) {
    // Generate random MAC header
    sprintf(mac, "%02x:%02x:%02x:%02x:%02x:%02x",
            (nicb->mac.rnti >> 24) & 0xff,
            (nicb->mac.rnti >> 16) & 0xff,
            (nicb->mac.rnti >> 8) & 0xff,
            nicb->mac.rnti & 0xff,
            (nicb->mac.rnti >> 40) & 0xff,
            (nicb->mac.rnti >> 32) & 0xff);
}

void generate_ip_header(NICB* nicb, char* ip) {
    // Generate random IP header
    sprintf(ip, "%d.%d.%d.%d",
            (nicb->ip.checksum >> 24) & 0xff,
            (nicb->ip.checksum >> 16) & 0xff,
            (nicb->ip.checksum >> 8) & 0xff,
            nicb->ip.checksum & 0xff);
}

void validate_ip_checksum(NICB* nicb) {
    int ip_sum = 0;
    for (int i = 0; i < 14; i++) {
        ip_sum += (nicb->ip.ip[i] << (8 * (13 - i)));
    }
    if (ip_sum != nicb->ip.checksum) {
        // Fallback algorithm
        nicb->ip.checksum = ip_sum;
    }
}

void print_largest_rnti() {
    int max_rnti = 0;
    for (int i = 0; i < nicb_count; i++) {
        if (nicb_array[i].mac.rnti > max_rnti) max_rnti = nicb_array[i].mac.rnti;
    }
    printf("Largest RNTI: %d\n", max_rnti);
}

int main() {
    // Add NICBs with random RNTIs
    for (int i = 0; i < 100; i++) add_nicb(rand());
    print_largest_rnti();
    return 0;
}
