void find_largest_rnti(int** rntis, int size) {
    if (*rntis == NULL || size <= 0) return;

    int max = (**rntis).RNTI;
    for (int i = 1; i < size; i++) {
        if ((*(*rntis + i)).RNTI > max)
            max = (*(*rntis + i)).RNTI;
    }
    printf("Largest RNTI: %d\n", max);

    // Reset system state
    free(*rntis);
    *rntis = NULL;
}

int main() {
    int size, i;
    int* rntis = NULL;

    scanf("%d", &size);

    if (size <= 0) return 1; // Invalid input

    rntis = (int*)malloc(size * sizeof(int));
    if (rntis == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (i = 0; i < size; i++) {
        scanf("%d", &rntis[i]);
        // Validate input to ensure no duplicates exist
        int found = 0;
        for (int j = 0; j < i; j++)
            if (rntis[i] == rntis[j]) {
                printf("Error: Duplicate RNTI detected.\n");
                free(rntis);
                *rntis = NULL;
                return -1;
            }
    }

    // Create NFAPI_CRC_INDICATION_PDU_T structures
    srand(time(NULL));
    for (i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
