        pdu->RX_UE_INFORMATION_TAG = rand() % INT_MAX;
        pdu->CRC_INDICATION_REL8_TAG = rand() % INT_MAX;

        // Populate CRCFLAG randomly
        int flag = rand() % 2;
        if (flag)
            pdu->RX_UE_INFORMATION_TAG |= 0x1;
        else
            pdu->CRC_INDICATION_REL8_TAG |= 0x1;

        printf("RNTI: %d, RX_UE_INFORMATION_TAG: %d, CRC_INDICATION_REL8_TAG: %d\n", pdu->RNTI, pdu->RX_UE_INFORMATION_TAG, pdu->CRC_INDICATION_REL8_TAG);

        free(pdu);
    }

    find_largest_rnti(&rntis, size);

    return 0;
