#include <time.h>

#define MAX_SIZE 10000
#define TIMER_INTERVAL 10 // in seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize and manage dynamic array of structures
void* nfa_pi_crc_indication_pdu_array(int** size) {
    // Initialize the array with a fixed size
    *size = (int*)malloc(sizeof(int));
    if (*size == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    **size = 0;

    return (void**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

// Function to add a new structure to the array
int nfa_pi_crc_indication_pdu_array_add(void** arr, int size) {
    (*arr) = (void*)realloc((*arr), (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if ((*arr) == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }
    ((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[size].RX_UE_INFORMATION_TAG = rand();
    ((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[size].RNTI = rand();
    ((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[size].CRC_INDICATION_REL8_TAG = rand();
    ((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[size].CRCFLAG = rand() % 2;
    size++;

    return size;
}

// Function to validate the integrity of the array
int nfa_pi_crc_indication_pdu_array_validate(void** arr, int size) {
    for (int i = 0; i < size - 1; i++) {
        if (((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[i].RX_UE_INFORMATION_TAG == ((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[size-1].RX_UE_INFORMATION_TAG) {
            printf("Duplicate RX_UE_INFORMATION_TAG found\n");
            return -1;
        }
    }

    return 0;
}

// Function to serialize the array
void nfa_pi_crc_indication_pdu_array_serialize(void** arr, int size, FILE* file) {
    for (int i = 0; i < size; i++) {
        fwrite(&((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

// Function to deserialize the array
void nfa_pi_crc_indication_pdu_array_deserialize(void** arr, int size, FILE* file) {
    for (int i = 0; i < size; i++) {
        fread(&((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

// Function to periodically clean up unused structures
void nfa_pi_crc_indication_pdu_array_cleanup(void** arr, int size) {
    for (int i = size - 1; i >= 0; i--) {
        if (((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[i].RX_UE_INFORMATION_TAG % 2 == 0 && clock() - ((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[i].RX_UE_INFORMATION_TAG > TIMER_INTERVAL) {
            free((void*)&((NFAPI_CRC_INDICATION_PDU_T*)(*arr))[i]);
        }
    }
}

// Function to add a random number of vertices
int nfa_pi_crc_indication_pdu_array_add_vertices(void** arr, int size) {
    for (int i = 0; i < rand() % 10 + 1; i++) {
        *size = nfa_pi_crc_indication_pdu_array_add(arr, *size);
    }

    return *size;
}

int main() {
    // Initialize the array
    int* size = NULL;
    void* arr = nfa_pi_crc_indication_pdu_array(&size);

    // Add structures to the array
    *size = nfa_pi_crc_indication_pdu_array_add(&arr, *size);
    *size = nfa_pi_crc_indication_pdu_array_add(&arr, *size);

    // Validate the integrity of the array
    int result = nfa_pi_crc_indication_pdu_array_validate(&arr, *size);
    if (result != 0) {
        printf("Array validation failed\n");
    }

    // Serialize and deserialize the array
    FILE* file = fopen("array.txt", "wb");
    if (file == NULL) {
        printf("File opening failed\n");
    } else {
        nfa_pi_crc_indication_pdu_array_serialize(&arr, *size, file);
        fclose(file);

        file = fopen("array.txt", "rb");
        if (file == NULL) {
            printf("File opening failed during deserialization\n");
        } else {
            nfa_pi_crc_indication_pdu_array_deserialize(&arr, *size, file);
            fclose(file);
        }
    }

    // Periodically clean up unused structures
    while (1) {
        nfa_pi_crc_indication_pdu_array_cleanup(&arr, *size);
        sleep(10);
    }

    return 0;
}
