use std::sync::{Arc,Mutex};
use std::collections::{VecDeque};

struct PhyContext {
    phy_channel_id: u32,
    base_station_id: u64,
    frame_number: u16,
    phy_layer_status: String,
}

impl PhyContext {
    fn new(phy_channel_id: u32, base_station_id: u64, frame_number: u16) -> Self {
        PhyContext {
            phy_channel_id,
            base_station_id,
            frame_number,
            phy_layer_status: "".to_string(),
        }
    }
}

struct LoggingSystem {
    log_targets: Vec<Mutex<VecDeque<(String, String)>>>,
    phy_contexts: Arc<Mutex<Vec<PhyContext>>>,
}

impl LoggingSystem {
    fn new() -> Self {
        LoggingSystem {
            log_targets: Vec::new(),
            phy_contexts: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn add_log_target(&mut self, target: String) {
        self.log_targets.push(Mutex::new(VecDeque::new()));
    }

    fn remove_log_target(&mut self, index: usize) {
        if index < self.log_targets.len() {
            self.log_targets.remove(index);
        }
    }

    fn log(&self, phy_channel_id: u32, base_station_id: u64, frame_number: u16, status: String) -> Result<(), String> {
        let mut phy_contexts = self.phy_contexts.lock().unwrap();
        if phy_contexts.len() < 1000000 { // dynamic resizing
            let new_phy_context = PhyContext::new(phy_channel_id, base_station_id, frame_number);
            phy_contexts.push(new_phy_context);
        } else {
            return Err("Array size limit reached.".to_string());
        }

        for target in &self.log_targets {
            if let Ok(mut log_target) = target.lock() {
                log_target.push_back((format!("PhyContext: Channel ID - {}, Base Station ID - {}, Frame Number - {}, Status - {}", phy_channel_id, base_station_id, frame_number, status), "Timestamp".to_string()));
            }
        }

        Ok(())
    }
}

fn main() {
    let mut logging_system = LoggingSystem::new();

    // adding log targets
    logging_system.add_log_target("File Log Target".to_string());
    logging_system.add_log_target("Console Log Target".to_string());

    // remove a log target
    logging_system.remove_log_target(0);

    // logging
    logging_system.log(1, 2, 3, "Good Status".to_string()).unwrap();
}
