#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TB_SIZE 1000
#define CRC_FLAG 1
#define ERROR_INDICATOR 0

// Define the LTE DL-SCH transmission block (TB) structure
typedef struct {
    int id;
    int tb_size;
    int crc_flag;
    int error_indicator;
} TB_t;

// Function to initialize a new TB structure and assign it a unique ID
TB_t* init_TB(int tb_size) {
    TB_t* tb = (TB_t*)malloc(sizeof(TB_t));
    if (!tb) return NULL; // Handle memory allocation failure
    tb->id = rand(); // Assign a unique ID to each TB
    tb->tb_size = tb_size;
    tb->crc_flag = CRC_FLAG;
    tb->error_indicator = ERROR_INDICATOR;
    return tb;
}

// Function to add a new TB to the dynamic list, handling concurrent access and memory allocation failures
int add_TB(TB_t** tb_list, int* size, pthread_mutex_t* mutex) {
    TB_t* new_tb = init_TB(TB_SIZE);
    if (!new_tb) return -1; // Handle memory allocation failure
    pthread_mutex_lock(mutex); // Lock for concurrent access
    (*size)++;
    (*tb_list) = (TB_t**)realloc((*tb_list), sizeof(TB_t*) * (*size));
    (*tb_list)[*size-1] = new_tb;
    pthread_mutex_unlock(mutex); // Unlock after adding TB to the list
    return 0; // Successful addition
}

// Function to update an existing TB structure, handling concurrent access and memory allocation failures
int update_TB(TB_t** tb_list, int size, int index, int new_tb_size) {
    if (index >= size || !tb_list[index]) return -1; // Handle invalid index or null TB
    pthread_mutex_lock(tb_list[index]); // Lock for concurrent access
    (*tb_list)[index]->tb_size = new_tb_size;
    pthread_mutex_unlock(tb_list[index]); // Unlock after updating TB
    return 0; // Successful update
}

// Function to remove a TB from the dynamic list, handling concurrent access and memory allocation failures
int remove_TB(TB_t** tb_list, int* size) {
    pthread_mutex_lock(NULL); // No locking required for removing TB
    (*size]--;
    if (*size > 0) {
        free(tb_list[*size]);
        tb_list = (TB_t**)realloc(tb_list, sizeof(TB_t*) * (*size));
    } else {
        free(tb_list);
        tb_list = NULL;
    }
    return 0; // Successful removal
}

int main() {
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t)); // Initialize the mutex for concurrency control
    TB_t** tb_list = NULL;
    int size = 0;

    // Periodically update the dynamic list from an external data source
    while (...) {
        // Read data from the external source and add/update TBs as necessary
        if (add_TB(&tb_list, &size, mutex) < 0) printf("Error adding TB\n");
        else printf("Added new TB\n");

        // Periodically remove stale or outdated TBs from the list
        if (remove_TB(&tb_list, &size) < 0) printf("Error removing TB\n");
        else printf("Removed outdated TB\n");
    }

    free(mutex); // Release the mutex
    return 0;
}
