    if (!root) {
        printf("Error parsing JSON file\n");
        fclose(file);
        return;
    }

    // Validate and initialize configuration
    // ...

    fclose(file);
}

void serialize_complex_data_structure(complex_data_structure_t *cds, const char *output_file) {
    json_object *output = json_object_new_object();

    for (size_t i = 0; i < cds->record_size; i++) {
        json_object *record_obj = json_object_new_object();
        record_obj->int_value = cds->records[i]->key;
        record_obj->long_offset = &cds->offsets[cds->records[i]->offset];

        // ...

        json_object_object_add(output, "record", record_obj);
    }

    FILE *file = fopen(output_file, "w");
    if (!file) {
        printf("Error opening file: %s\n", output_file);
        return;
    }

    json_write_file(output, file, 0);
    fclose(file);
}

void free_complex_data_structure(complex_data_structure_t *cds) {
    free(cds->offsets);
    free(cds->keys);
    for (size_t i = 0; i < cds->record_size; i++) {
        free(cds->records[i]);
    }
