NFAPI_CRC_INDIFICATION_LIST* nfaapi_crc_indication_list_create(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_LIST* list = (NFAPI_CRC_INDICATION_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void nfaapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST* list) {
    free(list->data);
    free(list);
}

int nfaapi_crc_indication_list_append(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        void* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1; // Out of memory
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = pdu;
    return 0;
}

int nfaapi_crc_indication_list_deserialize(NFAPI_CRC_INDICATION_LIST* list, FILE* file) {
    size_t total_size = 0;
    fread(&total_size, sizeof(size_t), 1, file);
    if (ftell(file) != sizeof(size_t)) return -1; // Error
    list->size = total_size;
    for (size_t i = 0; i < total_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (ftell(file) != sizeof(NFAPI_CRC_INDICATION_PDU_T)) return -1; // Error
        list->data[i] = pdu;
    }
    return 0;
}

int nfaapi_crc_indication_list_serialize(NFAPI_CRC_INDICATION_LIST* list, FILE* file) {
    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = list->data[i];
        fwrite(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
