    // Validate input parameters
    if (numUes <= 0 || !ueContextList) return;

    // Allocate memory for the UE context list
    *ueContextList = (LteUeContext**) malloc(numUes * sizeof(LteUeContext*));

    // Initialize each UE context with valid PDU session ID, S-TMSI, and AMBR values
    for (int i = 0; i < numUes; i++) {
        LteUeContext* ueContext = (*ueContextList + i) = (LteUeContext*) malloc(sizeof(LteUeContext));

        // Validate downlink and uplink AMBR values
        while (1) {
            int dlAmbr, ulAmbr;
            printf("Enter downlink AMBR: ");
            scanf("%d", &dlAmbr);
            printf("Enter uplink AMBR: ");
            scanf("%d", &ulAmbr);

            if (dlAmbr >= 0 && dlAmbr <= 10240 && ulAmbr >= 0 && ulAmbr <= 51200) {
                ueContext->downlinkAmbr = dlAmbr;
                ueContext->uplinkAmbr = ulAmbr;
                break;
            } else printf("Invalid AMBR values. Try again.\n");
        }

        // Get valid S-TMSI and PDU session ID
        printf("Enter STMSI: ");
        scanf("%d", &ueContext->stmsi);
        printf("Enter PDU session ID: ");
        scanf("%d", &ueContext->pduSessionId);

        // Check for duplicate entries based on S-TMSI
        int found = 0;
        for (int j = 0; j < i; j++) {
            if ((*ueContextList + j)->stmsi == ueContext->stmsi) {
                printf("Duplicate STMSI detected. Please try again.\n");
                free(ueContext);
                (*ueContextList + i) = NULL;
                found = 1;
                break;
            }
        }

        if (!found) free(ueContext);
    }
}

