    int numUes = 5; // Set the number of UE contexts
    LteUeContext* ueContextList = NULL;

    initLteUeContexts(numUes, &ueContextList);

    // Free allocated memory and print the list of LTE UE contexts
    for (int i = 0; i < numUes; i++) {
        free(ueContextList + i);
    }
    free(ueContextList);

    return 0;
}

