void manageDynamicList(int seed, int numNodes) {
    // Initialize random number generator
    srand(seed);

    // Allocate memory for each node's data field
    Node* nodes = (Node*)malloc(numNodes * sizeof(Node));
    for (int i = 0; i < numNodes; i++) {
        // Generate a unique string based on the node's index and seed
        char buffer[256];
