        // Allocate memory for the node's data field
        nodes[i].data = (char*)malloc(strlen(buffer) + 1);
        strcpy(nodes[i].data, buffer);

        // Initialize node key to the node's index
        nodes[i].key = i;
    }

    // Free allocated memory when no longer needed
    for (int i = 0; i < numNodes; i++) {
        free(nodes[i].data);
    }
    free(nodes);

    return;
}

// Function to generate a random string of length 'length'
char* randomString(int length) {
    char* buffer = (char*)malloc((length + 1) * sizeof(char));
    for (int i = 0; i < length; i++) {
        // Generate a random character
        int randomChar = rand() % 128;
        sprintf(buffer + i, "%c", randomChar);
    }
    buffer[length] = '\0';
    return buffer;
}
