pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int current_size = 0;
record* list = NULL;
size_t memory_limit = 5000000; // 5 MB

void init_list() {
    pthread_mutex_lock(&lock);
    if (list != NULL) {
        free(list);
    }
    list = (record*)malloc(memory_limit);
    current_size = 0;
    pthread_mutex_unlock(&lock);
}

int add_record(record* new_record) {
    pthread_mutex_lock(&lock);
    if (current_size >= memory_limit / sizeof(record)) {
        return -1; // List is full
    }
    list[current_size] = *new_record;
    current_size++;
    pthread_mutex_unlock(&lock);
    return 0;
}

int serialize_list(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // Error opening file
    }
    pthread_mutex_lock(&lock);
    for (int i = 0; i < current_size; i++) {
        fwrite(&list[i], sizeof(record), 1, file);
    }
    fclose(file);
    pthread_mutex_unlock(&lock);
    return 0;
}

int deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Error opening file
    }
    pthread_mutex_lock(&lock);
    current_size = 0;
    record temp;
    while (fread(&temp, sizeof(record), 1, file) == 1) {
        list[current_size] = temp;
        current_size++;
    }
    fclose(file);
    pthread_mutex_unlock(&lock);
    return 0;
}

