// Lock for concurrent access
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list management functions
void add_to_list(Node** head, Node* new_node) {
    pthread_mutex_lock(&list_lock);
    if (*head == NULL || (*head)->data.timestamp > new_node->data.timestamp) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->data.timestamp <= new_node->data.timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);
}

void remove_from_list(Node** head, Node* node_to_remove) {
    pthread_mutex_lock(&list_lock);
    if (*head == node_to_remove) {
        *head = node_to_remove->next;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next != node_to_remove) {
            current = current->next;
        }
        if (current->next != NULL) {
            current->next = node_to_remove->next;
        } else {
            *head = NULL; // Remove the last element
        }
    }
    pthread_mutex_unlock(&list_lock);
}

// Batch processing functions
void add_batch(Node** head, Node* new_nodes[], int num_new_nodes) {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < num_new_nodes; i++) {
        if (*head == NULL || ((*head)->data.timestamp > new_nodes[i]->data.timestamp)) {
            new_nodes[i]->next = *head;
            *head = new_nodes[i];
        } else {
            Node* current = *head;
            while (current->next != NULL && current->next->data.timestamp <= new_nodes[i]->data.timestamp) {
                current = current->next;
            }
            new_nodes[i]->next = current->next;
            current->next = new_nodes[i];
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void remove_batch(Node** head, Node* nodes_to_remove[], int num_nodes_to_remove) {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < num_nodes_to_remove; i++) {
        if (*head == nodes_to_remove[i]) {
            *head = nodes_to_remove[i]->next;
        } else {
            Node* current = *head;
            while (current->next != NULL && current->next != nodes_to_remove[i]) {
                current = current->next;
            }
            if (current->next != NULL) {
                current->next = nodes_to_remove[i]->next;
            } else {
                *head = NULL; // Remove the last element
            }
        }
    }
    pthread_mutex_unlock(&list_lock);
}

// Logging and statistics functions
