typedef struct node {
    char* data;
    int key;
} Node;

Node* create_node(int index, int seed) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL; // Handle out-of-memory condition

    srand(seed + index); // Generate unique string for each node
    char buffer[256];
    sprintf(buffer, "Node %d: %s", index, (char*)randstr(10)); // Use randstr() to generate a random 10-character string

    node->data = strdup(buffer);
    node->key = index;

    return node;
}

void free_node(Node* node) {
    if (!node) return; // Handle null pointer
    free(node->data);
    free(node);
}

void list_init(Node** head, int seed) {
    *head = NULL;
}

Node* list_add(Node* head, Node* node) {
    if (!head) return node; // Handle edge case: empty list

    Node* current = head;
    while (current->next) current = current->next;

    current->next = node;
    return head;
}

void list_remove(Node** head, Node* node) {
    if (!head || !node) return; // Handle edge cases: null pointer or no nodes in the list

    if (*head == node) {
        *head = (*head)->next;
    } else {
        Node* current = *head;
        while (current->next && current->next != node) current = current->next;

        if (current->next) current->next = node->next;
    }

    free_node(node);
}

void list_free(Node** head) {
    Node* current = *head;
    Node* next = NULL;
    while (current) {
        next = current->next;
        free_node(current);
        current = next;
    }
    *head = NULL;
}

char* randstr(int length) {
    static char buffer[256];
    for (int i = 0; i < length; i++) {
        int val = rand() % 26 + 'a';
        buffer[i] = (char)val;
    }
    buffer[length] = '\0';
    return buffer;
}
