    long* offsets = NULL;
    int* keys = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    for (size_t i = 0; i < size; i++) {
        record* new_data = (record*) realloc(data, (i + 1) * sizeof(record));
        if (!new_data) {
            // Handle memory allocation failure
            free(data);
            data = NULL;
            break;
        }
        data = new_data;

        long offset = rand() % RND_RANGE;
        int key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        while (key < MIN_KEY || key > MAX_KEY) {
            key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        }

        for (int j = 0; j < i; j++) {
            if (data[j].value == key) {
                // Handle duplicate key
                offset = rand() % RND_RANGE;
                key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
                while (key < MIN_KEY || key > MAX_KEY) {
                    key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
                }
            }
        }

        data[i].value = key;

        long* new_offsets = (long*) realloc(offsets, (i + 1) * sizeof(long));
