            // Handle memory allocation failure
            free(offsets);
            offsets = NULL;
            break;
        }
        offsets = new_offsets;

        int* new_keys = (int*) realloc(keys, (i + 1) * sizeof(int));
        if (!new_keys) {
            // Handle memory allocation failure
            free(keys);
            keys = NULL;
            break;
        }
        keys = new_keys;
    }

    pthread_mutex_destroy(&lock);

    return data;
}

