} record_t;

record_t* create_record_array(int size) {
    record_t* records = (record_t*)malloc(size * sizeof(record_t));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        records[i].value = 0;
    }
    return records;
}

void manage_memory(int* offset_values_size, int* key_values_size) {
    if (*offset_values_size <= 0 || *key_values_size <= 0) {
        printf("Invalid input. Sizes must be positive integers.\n");
        return;
    }

    int total_records = *offset_values_size + *key_values_size;
    if (total_records > MAX_RECORDS) {
        printf("Total number of records exceeds the maximum limit.\n");
        return;
    }

    record_t* records = create_record_array(total_records);
    if (!records) {
        return;
    }

    // Set random values for each record
    int min_value = 0, max_value = 100;
    srand(time(NULL));
    for (int i = 0; i < total_records; i++) {
        records[i].value = rand_range(min_value, max_value);
    }

    free(records); // Free allocated memory at the end of the function
}

// Provided rand_range function to generate random numbers
int rand_range(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}
