void manageMemory(long*** offsets, int*** keys, Data** datas) {
    *offsets = (long**)malloc(1000 * sizeof(long*));
    for (int i = 0; i < 1000; i++) {
        (*offsets)[i] = (long*)malloc(sizeof(long));
    }

    *keys = (int**)malloc(1000 * sizeof(int*));
    for (int i = 0; i < 1000; i++) {
        (*keys)[i] = (int*)malloc(sizeof(int));
    }

    *datas = (Data*)malloc(1000 * sizeof(Data));
}

void checkpoint(long*** offsets, int*** keys, Data** datas) {
    FILE* file = fopen("checkpoint.bin", "wb");
    if (!file) {
        printf("Error opening file for writing\n");
        return;
    }

    for (int i = 0; i < 1000; i++) {
        fwrite(&((*offsets)[i]), sizeof(long), 1, file);
        fwrite(&((*keys)[i]), sizeof(int), 1, file);
        fwrite(datas, sizeof(Data), 1, file);
    }

    fclose(file);
}

void restore(long*** offsets, int*** keys, Data** datas) {
    FILE* file = fopen("checkpoint.bin", "rb");
    if (!file) {
        printf("Error opening file for reading\n");
        return;
    }

    for (int i = 0; i < 1000; i++) {
        fseek(file, sizeof(long), SEEK_SET);
        fread(&((*offsets)[i]), sizeof(long), 1, file);
        fseek(file, sizeof(int), SEEK_SET);
        fread(&((*keys)[i]), sizeof(int), 1, file);
        fseek(file, sizeof(Data), SEEK_SET);
        fread(datas, sizeof(Data), 1, file);
    }

    fclose(file);
}
