);

try {
    // Fetch user data from API, handling rate limits and caching
    $response = $client->get('/users', array_merge($headers, $params));
    $user_data = json_decode($response->getBody(), true);

    if ($response->getStatusCode() == 200) {
        // Cache retrieved user data for a set amount of time (e.g., 1 hour)
        Cache::remember('user_data_' . $_GET['user_id'], 3600, function () use ($user_data) {
            return $user_data;
        });

        // Display fetched user data
        echo json_encode($user_data);
    } else {
        // Handle API errors and display error message
        echo 'Error: ' . $response->getStatusCode() . ': ' . $response->getReasonPhrase();
    }
} catch (GuzzleHttp\Exception\ConnectException $e) {
