void flush_data_to_disk(Offset* offsets, Key* keys, Data* data, Metadata* metadata, int record_count) {
    if (record_count % 100 == 0) {
        FILE* file = fopen("data.log", "wb");
        if (!file) {
            printf("Error opening file for writing!\n");
            exit(EXIT_FAILURE);
        }

        // Write offsets to disk
        fwrite(offsets, sizeof(Offset), record_count, file);

        // Write keys to disk
        fwrite(keys, sizeof(Key), record_count, file);

        // Write data to disk
        fwrite(data, sizeof(Data), record_count, file);

        // Write metadata to disk
        fwrite(metadata, sizeof(Metadata), 1, file);

        fclose(file);
    }
}

void log_metadata_update(Metadata* metadata) {
    FILE* file = fopen("metadata.log", "ab");
    if (!file) {
        printf("Error opening file for appending!\n");
        exit(EXIT_FAILURE);
    }

    fwrite(metadata, sizeof(Metadata), 1, file);

    fclose(file);
}

void free_memory(void** ptrs[], int size) {
    for (int i = 0; i < size; i++) {
        if (*ptrs[i]) {
            free(*ptrs[i]);
            *ptrs[i] = NULL;
        }
    }
}
