void* allocateArray(size_t n) {
    return calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void freeArray(void** array, size_t n) {
    for (size_t i = 0; i < n; i++) {
        free(array[i]);
    }
    free(array);
}

void initializeCrcFlag(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t n) {
    for (size_t i = 0; i < n; i++) {
        pdu[i].CRCFLAG = rand() % 256;
    }
}

bool validateCrcFlag(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t n) {
    for (size_t i = 0; i < n; i++) {
        if (pdu[i].CRCFLAG > 255) {
            return false;
        }
    }
    return true;
}

void manageArray(NFAPI_CRC_INDICATION_PDU_T** array, size_t* n) {
    pthread_mutex_lock(__pthread_mutex_array);

    // Allocate memory dynamically
    *array = allocateArray(*n + 1);
    for (size_t i = *n; i > 0; i--) {
        memcpy(array[i - 1], &((*array)[i-2]), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Initialize CRC flag
    initializeCrcFlag(&(*array)[*n - 1], *n);

    // Validate integrity of CRCFLAG
    if (!validateCrcFlag(&(*array)[0], *n)) {
        printf("Error: Invalid CRC flag\n");
    }

    pthread_mutex_unlock(__pthread_mutex_array);
}

void printArray(NFAPI_CRC_INDICATION_PDU_T** array, size_t n) {
