        printf("RX_UE_INFORMATION_TAG: %hu, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %u\n",
               (*array)[i].RX_UE_INFORMATION_TAG,
               (*array)[i].RNTI,
               (*array)[i].CRC_INDICATION_REL8_TAG,
               (*array)[i].CRCFLAG);
    }
}

int main() {
    // Example usage:
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    size_t n = 0;

    manageArray(&array, &n);

    printArray(&array, n);

    freeArray(&array, n);

    return 0;
}
