    record *records = (record *)malloc(offset_count * sizeof(record));

    if (!records) return NULL;

    // Initialize each record's key and file offset with values read from a provided file stream.
    for (int i = 0; i < offset_count; i++) {
        records[i].key = rand() % 100;
        records[i].file_offset = i;

        // Populate the character buffer of each record with a unique substring extracted from the file starting at the corresponding file offset and spanning a variable number of characters.
        char *buffer = (char *)malloc(substring_length + 1);
        if (!buffer) {
            free(records);
            return NULL;
        }
        records[i].buffer = buffer;

        // Set the int value of each record to a random integer within a specified range.
        records[i].key = rand() % 100;
    }

    return records;
}

void free_records(record *records, int offset_count) {
    for (int i = 0; i < offset_count; i++) {
        if (records[i].buffer) free(records[i].buffer);
    }
    free(records);
}
