public:
    struct NFAPI_CRC_INDICATION_PDU_T {
        int RX_UE_INFORMATION_TAG;
        int RNTI;
        int CRC_INDICATION_REL8_TAG;
        bool CRCFLAG;
    };

    void populateList(int numStructures) {
        std::vector<int> integers;
        for (int i = 0; i < numStructures; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = getRandomInt();
            pdu.RNTI = getRandomInt();
            pdu.CRC_INDICATION_REL8_TAG = getRandomInt();
            pdu.CRCFLAG = getRandomBool();
            integers.push_back(pdu.RX_UE_INFORMATION_TAG);
        }
    }

    int getLargestInteger() {
        return *std::max_element(integers.begin(), integers.end());
    }

private:
    int getRandomInt() {
        std::uniform_int_distribution<int> dist(1, 1000); // adjust the range as needed
        return dist(getRandGenerator());
    }

    bool getRandomBool() {
        return static_cast<bool>(getRandGenerator().bool());
    }
};

