#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000 // Adjustable limit from config file

typedef struct Record {
    int key;
    double value;
} Record;

Record* records = NULL;
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_records() {
    if ((records = (Record*)malloc(MAX_RECORDS * sizeof(Record))) == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void add_record(int key, double value) {
    pthread_mutex_lock(&lock);

    // Check for memory exhaustion
    if (record_count >= MAX_RECORDS) {
        printf("Error: Maximum number of records reached.\n");
    } else {
        records[record_count].key = key;
        records[record_count].value = value;
        record_count++;
    }

    pthread_mutex_unlock(&lock);
}

double get_value(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&lock);
            return records[i].value;
        }
    }

    pthread_mutex_unlock(&lock);
    printf("Error: Key not found.\n");
    return -1.0;
}

void print_records() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; i++) {
        printf("Key: %d, Value: %.2f\n", records[i].key, records[i].value);
    }

    pthread_mutex_unlock(&lock);
}
