    // Create arrays for offsets and keys
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize offsets with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 10000 + 1; // Random offset between 1 and 10,000
    }

    // Initialize keys with random values
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100 + 1; // Random key between 1 and 100
    }

    if (log_flag) {
        printf("Initialized %d records.\n", num_records);
    }

    // Create array for records, dynamically allocating memory for each record
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));

    if (!records) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize each record with random values and pointers to offset and key
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    if (log_flag) {
        printf("Records initialized with random values and pointers.\n");
    }

    // Clean up
    free(offsets);
    free(keys);

    return records;
}

