typedef struct {
    int value;
} record;

void manage_memory() {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    int key_count = 0, record_count = 0;

    // Allocate memory for and initialize arrays
    if ((offsets = (long *)malloc(1024*1024*1000*sizeof(long))) == NULL) {
        printf("Error allocating memory for offsets.\n");
        return;
    }
    if ((keys = (int *)malloc((get_nearest_prime(10)) * sizeof(int))) == NULL) {
        printf("Error allocating memory for keys.\n");
        free(offsets);
        return;
    }

    // Allocate memory for and initialize record array
    if ((records = (record *)malloc(16777216*sizeof(record))) == NULL) {
        printf("Error allocating memory for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Populate each record's int field with a random value within a specified range, ensuring no two adjacent records have the same value
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        do {
            records[i].value = rand() % 100;
        } while (i > 0 && records[i-1].value == records[i].value);
    }

    // Cleanup routine
    free(offsets);
    free(keys);
    free(records);
}

int get_nearest_prime(int n) {
    if (n <= 1)
        return 2;

    for (int i = 3; i < n; i += 2)
        if (!(i % 2))
            i += 2;
        else
            for (int j = 3; j * j <= i; j += 2)
                if (!(i % j))
                    i++;
    return i;
}

