#define MAX_RECORDS 1000
#define KEY_SOURCE_SIZE 256

typedef struct {
    long offset;
    int key;
    char* description;
} record;

record* records = NULL;
int num_records = 0;
int capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
FILE* key_source = NULL;

int add_record(record** array, int* count) {
    pthread_mutex_lock(&mutex);

    if (*count >= capacity) {
        capacity *= 2;
        *array = realloc(*array, sizeof(record*) * capacity);
        if (!*array) {
            printf("Error allocating memory.\n");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        printf("Error allocating memory for new record.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    int key;
    do {
        // Generate a new key from the data source
        fseek(key_source, 0, SEEK_SET);
        fgets((char*)&key, KEY_SOURCE_SIZE, key_source);
        key = atoi((char*)&key);

        // Check if the generated key is unique
        for (int i = 0; i < *count; i++) {
            if (records[i].key == key) {
                break;
            }
        }

        if (i >= *count) {
            break;
        }

        printf("Failed to add record due to duplicate key. Retrying...\n");
    } while (1);

    new_record->offset = 0; // Initialize offset for new record
    new_record->key = key;
    new_record->description = NULL;

    records[(*count)++] = *new_record;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int delete_record(record** array, int* count, int index) {
    pthread_mutex_lock(&mutex);

    if (index >= *count || index < 0) {
        printf("Error: Index out of bounds.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    record* temp = (record*)malloc(sizeof(record));
    *temp = records[index];
    free(records[index].description);

    for (int i = index; i < *count - 1; i++) {
        records[i] = records[i + 1];
    }
    free(temp);
    (*count)--;

    pthread_mutex_unlock(&mutex);
    return 0;
}

void free_memory(record** array, int* count) {
    for (int i = 0; i < *count; i++) {
        free(array[i]->description);
        free(array[i]);
    }
    free(*array);
    *array = NULL;
    *count = 0;
    capacity = 0;
}

record** create_array() {
    return malloc(sizeof(record*));
}

int get_total_records(int* count) {
    return *count;
}
