#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct config_entry {
    char* key;
    double value;
} config_entry_t;

typedef struct config_manager {
    int entry_count;
    int cache_size;
    config_entry_t** entries;
    config_entry_t** cache_entries;
} config_manager_t;

config_manager_t* config_manager_create(int cache_size) {
    config_manager_t* manager = (config_manager_t*)malloc(sizeof(config_manager_t));
    if (!manager) return NULL;

    manager->entry_count = 0;
    manager->cache_size = cache_size;
    manager->entries = (config_entry_t**)calloc(cache_size, sizeof(config_entry_t*));
    manager->cache_entries = NULL;

    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    return manager;
}

int config_manager_add_entry(config_manager_t* manager, char* key, double value) {
    config_entry_t* entry = (config_entry_t*)malloc(sizeof(config_entry_t));
    if (!entry) return -1;

    entry->key = strdup(key);
    entry->value = value;

    if (manager->entry_count >= manager->cache_size) {
        // cache full, resize
        config_entry_t** new_entries = (config_entry_t**)realloc(manager->entries, (manager->cache_size * 2 + 1) * sizeof(config_entry_t*));
        if (!new_entries) {
            free(entry);
            return -1;
        }
        manager->cache_entries = new_entries + manager->cache_size;
        manager->cache_size *= 2;
    }

    // add to cache
    manager->entries[manager->entry_count] = entry;

    manager->entry_count++;

    return 0;
}

int config_manager_update_entry(config_manager_t* manager, char* key, double value) {
    for (int i = 0; i < manager->entry_count; i++) {
        if (strcmp(manager->entries[i]->key, key) == 0) {
            free(manager->entries[i]->key);
            manager->entries[i]->key = strdup(key);
            manager->entries[i]->value = value;
            return 0;
        }
    }

    return -1; // not found
}

config_entry_t* config_manager_get_entry(config_manager_t* manager, char* key) {
    for (int i = 0; i < manager->entry_count; i++) {
        if (strcmp(manager->entries[i]->key, key) == 0) {
            return manager->entries[i];
        }
    }

    // not found in cache, check cache_entries
    for (int i = 0; i < manager->cache_size; i++) {
        if (manager->cache_entries[i]) {
            if (strcmp(manager->cache_entries[i]->key, key) == 0) {
                return manager->cache_entries[i];
            }
        }
    }

    // not found
    return NULL;
}

void config_manager_free(config_manager_t* manager) {
    for (int i = 0; i < manager->entry_count; i++) {
        free(manager->entries[i]->key);
        free(manager->entries[i]);
    }

    if (manager->cache_entries) {
        for (int i = 0; i < manager->cache_size; i++) {
            if (manager->cache_entries[i]) {
                free(manager->cache_entries[i]->key);
                free(manager->cache_entries[i]);
            }
        }
    }

    free(manager->entries);
    free(manager);

}

void config_manager_iterate(config_manager_t* manager, void (*callback)(config_entry_t*)) {
    for (int i = 0; i < manager->entry_count; i++) {
        callback(manager->entries[i]);
    }

    if (manager->cache_entries) {
        for (int i = 0; i < manager->cache_size; i++) {
            if (manager->cache_entries[i]) {
                callback(manager->cache_entries[i]);
            }
        }
    }
}
