['Here is the code block for the `handleDynamicDataProcessing` function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE 10000
#define MAX_THREADS 10
#define MEMORY_POOL_SIZE 1024*1024*10 // 10MB

typedef struct record {
    int value;
} record;

record *records = NULL;
int *keys = NULL;
long *offsets = NULL;
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* handleDynamicDataProcessing(void* arg) {
    int tid = (int)arg;

    pthread_setcanceltype(PTHREAD_CANCEL_ASYNCHRONOUS, NULL);

    for(int i = 0; i < MAX_SIZE; i++) {
        record newRecord;
        newRecord.value = rand() % 100;

        pthread_mutex_lock(&lock);
        if(record_count >= MAX_SIZE) {
            pthread_mutex_unlock(&lock);
            break;
        }

        records[record_count] = newRecord;
        keys[record_count] = tid;
        offsets[record_count] = i;

        record_count++;

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int threadCount = 0;

    srand(time(NULL));

    records = (record*)malloc(MAX_SIZE * sizeof(record));
    keys = (int*)malloc(MAX_SIZE * sizeof(int));
    offsets = (long*)malloc(MAX_SIZE * sizeof(long));

    for(int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, handleDynamicDataProcessing, (void*)i);
        threadCount++;

        if(threadCount >= MAX_THREADS) {
            break;
        }
    }

    for(int i = 0; i < threadCount; i++) {
        pthread_join(threads[i], NULL);
    }

    free(records);
    free(keys);
    free(offsets);

    return 0;
}
