            TPACKET_V3_PACKET_INFO(uint32_t id, uint64_t ts, uint8_t *header) {
                packet_id = id;
                timestamp = ts;
                memcpy(this->header, header, TPACKET_V3_PACKET_HEADER_SIZE);
            }
    };

    class PacketList {
        public:
            std::vector<TPACKET_V3_PACKET_INFO> packets;

            // Method for adding new packets to the list
            void addPacket(TPACKET_V3_PACKET_INFO packet) {
                packets.push_back(packet);
            }

            // Method for retrieving a specific packet by ID
            TPACKET_V3_PACKET_INFO getPacket(uint32_t id) {
                for (auto& packet : packets) {
                    if (packet.packet_id == id) {
                        return packet;
                    }
                }
                throw std::runtime_error("Packet not found");
            }

            // Method for removing a specific packet from the list
            void removePacket(uint32_t id) {
                packets.erase(std::remove_if(packets.begin(), packets.end(),
                                             [&id](const TPACKET_V3_PACKET_INFO& p) {
                                                 return p.packet_id == id;
                                             }), packets.end());
            }
    };

    class PacketMetadataHashTable {
        public:
            std::unordered_map<uint32_t, TPACKET_V3_PACKET_INFO> metadata;

            // Method for adding new packet metadata to the hash table
            void addPacketMetadata(uint32_t packet_id, TPACKET_V3_PACKET_INFO packet_info) {
                metadata[packet_id] = packet_info;
            }

            // Method for retrieving packet metadata by ID
            TPACKET_V3_PACKET_INFO getPacketMetadata(uint32_t packet_id) {
                if (metadata.find(packet_id) != metadata.end()) {
                    return metadata.at(packet_id);
                }
                throw std::runtime_error("Packet not found");
            }
    };

    class RingBuffer {
        public:
            uint32_t *buffer;
            size_t size;

            // Constructor for initializing the ring buffer
            RingBuffer(size_t capacity) {
                size = capacity;
                buffer = new uint32_t[size];
            }

            // Method for inserting a new packet ID into the ring buffer
            void insert(uint32_t packet_id) {
                // Handle edge cases and optimize insertion operations
            }

            // Method for retrieving a specific packet ID from the ring buffer
            uint32_t getPacketID(size_t index) {
                return buffer[index];
            }

            // Destructor for releasing dynamically allocated memory
            ~RingBuffer() {
                delete[] buffer;
            }
    };

    class PacketManager {
        public:
            PacketList packet_list;
            PacketMetadataHashTable metadata_hash_table;
            RingBuffer ring_buffer;

            // Method for adding a new packet to the system
