                packet_list.addPacket(packet);
                metadata_hash_table.addPacketMetadata(packet.packet_id, packet);
                ring_buffer.insert(packet.packet_id);
            }

            // Method for retrieving packet metadata by ID
            TPACKET_V3_PACKET_INFO getPacketMetadata(uint32_t packet_id) {
                return metadata_hash_table.getPacketMetadata(packet_id);
            }
    };

}  // namespace PacketManager']

