#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_AUDIO_FRAME 1024
#define MAX_LOG_ENTRIES 2048
#define TIMESTAMP_WINDOW 1000 // in milliseconds

typedef enum { INFO, WARN, ERROR } EventLogType;

struct AudioFrame {
    float* samples;
};

struct EventLog {
    long timestamp;
    int id;
    char description[64];
    EventLogType type;
};

void processAudioStreamWithFifoBuffering(int maxFrames, int maxLogEntries) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    struct AudioFrame* audioFrames = (struct AudioFrame*)malloc(sizeof(struct AudioFrame));
    audioFrames->samples = (float*)calloc(MAX_AUDIO_FRAME, sizeof(float));

    struct EventLog** logEntries = (struct EventLog**)malloc(sizeof(struct EventLog*) * MAX_LOG_ENTRIES);
    for(int i = 0; i < maxLogEntries; i++) {
        logEntries[i] = (struct EventLog*)malloc(sizeof(struct EventLog));
    }

    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int head = 0, tail = 0;
    long lastTimestamp = -1;

    void* threadFunc(void* arg) {
        struct EventLog* logEntry = (struct EventLog*)arg;
        pthread_mutex_lock(&lock);
        while(1) {
            if(pthread_cond_timedwait(&cond, &lock, ((lastTimestamp + TIMESTAMP_WINDOW) * 1000)) != ETIMEDOUT) {
                break;
            }
        }
        pthread_mutex_unlock(&lock);

        // add log entry to the circular buffer
        logEntries[tail]->timestamp = logEntry->timestamp;
        logEntries[tail]->id = logEntry->id;
        strcpy(logEntries[tail]->description, logEntry->description);
        logEntries[tail]->type = logEntry->type;

        tail = (tail + 1) % MAX_LOG_ENTRIES;
        if(tail == head) {
            head = (head + 1) % MAX_LOG_ENTRIES;
        }

        lastTimestamp = logEntry->timestamp;

        pthread_mutex_lock(&lock);
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }

    // start the threads
    pthread_t thread[MAX_LOG_ENTRIES];
    for(int i = 0; i < maxLogEntries; i++) {
        int* arg = (int*)malloc(sizeof(int));
        *arg = i;
        if(pthread_create(&thread[i], NULL, threadFunc, arg) != 0) {
            printf("Error creating thread\n");
        }
    }

    // wait for all threads to finish
    for(int i = 0; i < maxLogEntries; i++) {
        pthread_join(thread[i], NULL);
    }

    // clean up memory
    for(int i = 0; i < maxLogEntries; i++) {
        free(logEntries[i]);
    }
    free(logEntries);
    free(audioFrames->samples);
    free(audioFrames);

    return;
}
