#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define structure for image frame
typedef struct {
    int* pixelData;
    int width;
    int height;
    long long timestamp;
} imageFrame;

// Define priority queue node structure
typedef struct {
    imageFrame* frame;
    long long timestamp;
    struct PQNode* next;
} PQNode;

// Define priority queue
typedef struct {
    PQNode* head;
    pthread_mutex_t lock;
} PriorityQueue;

// Function to create a new priority queue node
PQNode* pqCreateNode(imageFrame* frame) {
    PQNode* node = (PQNode*)malloc(sizeof(PQNode));
    node->frame = frame;
    node->timestamp = frame->timestamp;
    node->next = NULL;
    return node;
}

// Function to add a new image frame to the priority queue
void pqAddImageFrame(PriorityQueue* pq, imageFrame* frame) {
    PQNode* newNode = pqCreateNode(frame);
    pthread_mutex_lock(&pq->lock);
    if (pq->head == NULL || newNode->timestamp < pq->head->timestamp) {
        newNode->next = pq->head;
        pq->head = newNode;
    } else {
        PQNode* current = pq->head;
        while (current->next != NULL && current->next->timestamp >= newNode->timestamp)
            current = current->next;
        newNode->next = current->next;
        current->next = newNode;
    }
    pthread_mutex_unlock(&pq->lock);
}

// Function to process the oldest unprocessed image frame from the priority queue
imageFrame* pqPopImageFrame(PriorityQueue* pq) {
    PQNode* node = pq->head;
    if (node == NULL)
        return NULL;

    pthread_mutex_lock(&pq->lock);
    pq->head = node->next;
    pthread_mutex_unlock(&pq->lock);

    imageFrame* frame = node->frame;
    free(node);
    return frame;
}

// Function to process the given image stream
void processImageStream(int maxFrames, imageFrame** frames) {
    PriorityQueue pq;
    pq.head = NULL;
    pthread_mutex_init(&pq.lock, NULL);

    for (int i = 0; i < maxFrames; i++) {
        // Verify pixel data integrity and handle memory allocation failures
        if (frames[i]->width * frames[i]->height > 0) {
            pqAddImageFrame(&pq, frames[i]);
        } else {
            printf("Error: Invalid image frame detected.\n");
        }
    }

    while (1) {
        imageFrame* frame = pqPopImageFrame(&pq);
        if (frame == NULL)
            break;

        // Process the image frame
        printf("Processing frame with timestamp %lld\n", frame->timestamp);

        // Release memory resources for the processed frame
        free(frame->pixelData);
        free(frame);
    }

    pthread_mutex_destroy(&pq.lock);
}

// Example usage of the function
int main() {
    int maxFrames = 100;
    imageFrame** frames = (imageFrame**)malloc(maxFrames * sizeof(imageFrame*));

    // Initialize and populate the image frame array
    for (int i = 0; i < maxFrames; i++) {
        frames[i] = (imageFrame*)malloc(sizeof(imageFrame));
        frames[i]->width = 1024;
        frames[i]->height = 768;
        frames[i]->pixelData = (int*)malloc(frames[i]->width * frames[i]->height * sizeof(int));
        // Initialize pixel data...
    }

    processImageStream(maxFrames, frames);

    // Release memory resources for the image frames
    for (int i = 0; i < maxFrames; i++) {
        free(frames[i]->pixelData);
        free(frames[i]);
    }
    free(frames);

    return 0;
}
