    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T** arr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!arr) {
        return NULL;  // Handle allocation failure
    }

    // Initialize each structure with unique values and random CRCFLAG
    for (int i = 0; i < N; i++) {
        arr[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!arr[i]) {
            free(arr);
            return NULL;  // Handle allocation failure
        }

        // Set RX_UE_INFORMATION_TAG and RNTI values
        strcpy(arr[i]->RX_UE_INFORMATION_TAG, "UniqueValue");
        arr[i]->RNTI = i;

        // Randomly set CRCFLAG for the current structure
        srand(time(NULL));
        arr[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Ensure no two adjacent elements have the same CRCFLAG value
        if (i > 0) {
            while (arr[i-1]->CRC_INDICATION_REL8_TAG.CRCFLAG == arr[i]->CRC_INDICATION_REL8_TAG.CRCFLAG) {
                arr[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
            }
        }
    }

    return arr;
}

