    unsigned short rnti;
    unsigned short crc_indication_rel8_tag;
} Node;

typedef struct node_list {
    Node* nodes;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NodeList;

NodeList* init_node_list() {
    NodeList* list = (NodeList*)malloc(sizeof(NodeList));
    list->size = 0;
    list->capacity = MAX_NODES;
    list->nodes = (Node*)calloc(list->capacity, sizeof(Node));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node_list(NodeList* list) {
    for (int i = 0; i < list->size; i++) {
        if (list->nodes[i].data) free(list->nodes[i].data);
    }
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* add_node(NodeList* list, char* data, int key) {
    Node* node = &list->nodes[list->size];
    node->data = (char*)malloc(MAX_NODE_CAPACITY + 1);
    strcpy(node->data, data);
    node->key = key;
    // Initialize RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    // ...
    list->size++;
    return node;
}

void remove_node(NodeList* list, int index) {
    if (index >= list->size) return;
    free(list->nodes[index].data);
    memmove(&list->nodes[index], &list->nodes[index + 1], (list->size - index - 1) * sizeof(Node));
    list->size--;
}

void update_node(NodeList* list, int index, char* data, int key) {
    if (index >= list->size) return;
    free(list->nodes[index].data);
    list->nodes[index].data = (char*)malloc(MAX_NODE_CAPACITY + 1);
    strcpy(list->nodes[index].data, data);
    list->nodes[index].key = key;
}

void print_node_list(NodeList* list) {
    for (int i = 0; i < list->size; i++) {
        printf("Node %d: Key=%d Data='%s'\n", i, list->nodes[i].key, list->nodes[i].data);
    }
}
