typedef struct {
    int key;
    long offset;
} record;

record* createRecordArray(int numRecords) {
    if (numRecords <= 0) return NULL;

    // Allocate memory for the record array
    record* records = (record*)malloc(numRecords * sizeof(record));

    if (!records) return NULL; // Handle memory allocation failure

    int* keys = (int*)malloc(numRecords * sizeof(int)); // Initialize array of keys
    long* offsets = (long*)malloc(numRecords * sizeof(long)); // Initialize array of offsets

    if (!keys || !offsets) {
        free(records); // Deallocate records in case of failure
        return NULL;
    }

    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < numRecords; ++i) {
        long offset = rand() % ((numRecords * sizeof(record)) - 1);
        while (offset < 0) offset = rand() % ((numRecords * sizeof(record)) - 1);

        // Ensure all keys are unique
        int key = i;
        for (int j = 0; j < i; ++j) {
            if (key == records[j].key) {
                --i; // Decrement and retry
                break;
            }
        }

        records[i].key = key;
        records[i].offset = offset;

        keys[i] = records[i].key;
    }

    free(keys);
    free(offsets);

    return records;
}

void destroyRecordArray(record* array) {
    if (!array) return; // Handle null pointer

    free(array);
}
