time_t max_temp_timestamp = 0;
double avg_temp = 0.0;
double total_records_per_second = 0.0;
time_t last_minute_timestamp = 0;

void update_performance_metrics() {
    time_t current_time = time(NULL);
    if (current_time - last_minute_timestamp >= 60) {
        last_minute_timestamp = current_time;
        total_records_per_second = (double)record_count / ((double)(current_time - last_minute_timestamp));
        avg_temp = avg_temp * (int(record_count / 5.0)) + record_array[record_count - 1].temp;
        avg_temp /= record_count;
    }
}

void handle_new_record(Record* new_record) {
    if (record_count >= record_capacity) {
        // Handle overflow scenario
        Record* old_records = record_array;
        record_array = realloc(record_array, sizeof(Record) * (record_capacity *= 2));
        memcpy(record_array + record_capacity / 2, old_records, sizeof(Record) * record_capacity);
        free(old_records);
    }
    record_array[record_count++] = *new_record;
}

int main() {
    srand(time(NULL));

    // Initialize random number generator
    for (int i = 0; i < 10000; i++) {
        Record new_record;
        if ((new_record.temp = rand() / (double)RAND_MAX * 50.0 + 20.0) > max_temp) {
            max_temp = new_record.temp;
            max_temp_timestamp = time(NULL);
        }
        if (new_record.temp >= 0 && new_record.temp <= 50.0) {
            handle_new_record(&new_record);
        } else {
            printf("Invalid temperature reading: %f\n", new_record.temp);
        }
    }

    // Update performance metrics
    update_performance_metrics();

    printf("Maximum temperature recorded: %f at timestamp %ld.\n", max_temp, max_temp_timestamp);
    printf("Total number of valid records processed: %d.\n", record_count);

    return 0;
}

