        if(task_list[i].id == id) {
            free(new_task);
            pthread_mutex_unlock(&task_lock);
            return;
        }
    }

    task_list = (task_t*)realloc(task_list, (task_count+1)*sizeof(task_t));
    task_list[task_count] = *new_task;
    task_count++;
    pthread_mutex_unlock(&task_lock);
