NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu(int n) {
    int i, retry_count = 0;
    struct tm *start_date_tm = NULL;
    time_t start_date_time;
    char buffer[100];

    // Initialize the timestamp generation mechanism
    if (clock_gettime(NULL, &start_date_time) != 0) {
        printf("Failed to get current time.\n");
        return NULL;
    }
    localtime_r(&start_date_time, &start_date_tm);

    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (i = 0; i < n; i++) {
        time_t timestamp;
        while (retry_count <= TIMESTAMP_MAX_RETRIES) {
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", start_date_tm);
            buffer[strcspn(buffer, "\n")] = '\0';
            if (i > 0) {
                struct tm *new_start_date_tm;
                localtime_r(&start_date_time, &new_start_date_tm);
                new_start_date_tm->tm_sec += i;
                start_date_tm = new_start_date_tm;
            }
            if ((timestamp = mktime(start_date_tm)) != -1) {
                break;
            }
            retry_count++;
            printf("Failed to generate timestamp (retry attempt %d).\n", retry_count);
        }

        arr[i].rx_ue_info = ...; // initialize RX_UE_INFORMATION_TAG
        arr[i].rnti = ...; // initialize RNTI
        arr[i].crc_indication_rel8 = ...; // initialize CRC_INDICATION_REL8_TAG
        arr[i].temperature = ...; // initialize temperature within range -50°C to 120°C
        arr[i].timestamp = timestamp;
        strcpy(arr[i].location, "Location"); // initialize location identifier

        retry_count = 0; // reset retry count for next iteration
    }

    return arr;
}

void free_nfa_pi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* arr) {
    free(arr);
}
