#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

record* createRecords(int numRecords, int maxKey, long maxValue) {
    record* records = NULL;
    int* keys = NULL;
    long* offsets = NULL;
    int i, errCode;

    // Allocate memory for all arrays in a single block
    int blockSize = (numRecords * sizeof(record)) + (numRecords * sizeof(int)) + (numRecords * sizeof(long));
    void* block = malloc(blockSize);
    if (!block) {
        return NULL;
    }

    records = block;
    keys = (int*) (block + (numRecords * sizeof(record)));
    offsets = (long*) ((char*) block + (2 * numRecords * sizeof(record)));

    // Initialize each record's value to a random number
    srand(time(NULL));
    for (i = 0; i < numRecords; ++i) {
        records[i].key = rand() % maxKey;
        records[i].offset = (long)rand() % maxValue;
    }

    return records;
}

void freeRecords(record* records, int numRecords) {
    // Free the memory in reverse order to prevent dangling pointers
    free((void*) ((char*) &records[numRecords - 1] + sizeof(record)));
    free((void*) keys);
    free((void*) offsets);
    free(records);
}

// Serialize the data structure to a file
int serializeRecords(const record* records, int numRecords, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return -1; // Error opening file
    }

    fwrite(&numRecords, sizeof(int), 1, file);
    fwrite(records, sizeof(record), numRecords, file);

    fclose(file);
    return 0;
}

// Deserialize the data structure from a file
record* deserializeRecords(const char* filename) {
    record* records = NULL;
    int numRecords;
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return NULL; // Error opening file
    }

    // Read the number of records
    fread(&numRecords, sizeof(int), 1, file);
    records = malloc(numRecords * sizeof(record));
    fread(records, sizeof(record), numRecords, file);

    fclose(file);
    return records;
}
