    // Initialize dynamic array and its size
    void** arr = (void*)malloc(max_size * sizeof(void*));
    int arr_size = 0;

    // Function to check for duplicate RX_UE_INFORMATION_TAG values
    int is_duplicate(char* tag) {
        for (int i = 0; i < arr_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arr[i];
            if (!strcmp(pdu->RX_UE_INFORMATION_TAG, tag)) {
                return 1;
            }
        }
        return 0;
    }

    // Function to allocate and initialize a new NFAPI_CRC_INDICATION_PDU_T structure
    void* alloc_pdu() {
        void* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Initialize CRCFLAG to a random value
        ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->CRCFLAG = rand() % 2;

        return pdu;
    }

    // Function to deallocate and free a NFAPI_CRC_INDICATION_PDU_T structure
    void free_pdu(void* pdu) {
        if (pdu) {
            free(pdu);
        }
    }

    // Function to periodically clean up unused structures based on age threshold
    void clean_up(int age_threshold) {
        int i = 0;
        for (; i < arr_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arr[i];
            if ((time(NULL) - pdu->timestamp) > age_threshold) {
                free_pdu(arr[i]);
                memmove(&arr[i], &arr[i + 1], sizeof(void*) * (arr_size - i));
                arr_size--;
                i--;
            }
        }
    }

    // Main function to manage dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
    void* process_pdu(int n) {
        for (int i = 0; i < n; i++) {
            if (arr_size >= max_size) {
                printf("Array is full. Cannot add more.\n");
                break;
            }

            // Allocate and initialize a new NFAPI_CRC_INDICATION_PDU_T structure
            void* pdu = alloc_pdu();
            if (!pdu) {
                return NULL;
            }

            // Check for duplicate RX_UE_INFORMATION_TAG values
            char tag[17];
            sprintf(tag, "RX_UE_INFORMATION_TAG_%d", i);
            if (is_duplicate(tag)) {
                printf("Duplicate RX_UE_INFORMATION_TAG detected.\n");
                free_pdu(pdu);
                return NULL;
            }

            // Add the new pdu to the array
            arr[arr_size++] = pdu;
        }

        return NULL;
    }

    // Function to handle memory deallocation and record events
    void log_memory_event(int action, int size) {
        printf("Memory %s event of size %d bytes.\n", action == 0 ? "allocation" : "deallocation", size);
    }

    return process_pdu(n);
}

int main() {
    // Test the function with a sample input
