#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    long *ptr;
    int key;
    int *value;
} record;

record* allocateRecords(int n, int m, int k, int low, int high, size_t maxMemoryUsage) {
    // Allocate memory for integer keys
    int *keys = (int*)malloc(m * sizeof(int));
    if (!keys) return NULL;

    // Validate input parameters
    if (m * sizeof(int) + n * sizeof(long) + k * sizeof(record) > maxMemoryUsage) {
        free(keys);
        return NULL;
    }

    // Allocate memory for records
    record *records = (record*)malloc(k * sizeof(record));
    if (!records) {
        free(keys);
        return NULL;
    }

    // Initialize each record's integer value with a random number between low and high, inclusive
    srand(time(NULL));  // Seed the random number generator
    for (int i = 0; i < k; i++) {
        records[i].key = keys[rand() % m];
        records[i].ptr = malloc(sizeof(long));
        if (!records[i].ptr) {
            free(keys);
            free(records);
            return NULL;
        }
        *records[i].ptr = rand() % (high - low + 1) + low;
        records[i].value = &(*records[i].ptr);
    }

    // Free allocated memory
    free(keys);

    return records;
}

void deallocateRecords(record* records, int k) {
    for (int i = 0; i < k; i++) {
        if (records[i].ptr) free(records[i].ptr);
    }
    free(records);
}
