void init_linked_list(NFAPI_CRC_INDICATION_PDU_T **list, int max_elements) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < max_elements; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = rand() % 200;
        strcpy((*list)[i].CRC_INDICATION_REL8_TAG, "CRC_FLAG");
        (*list)[i].CRCFLAG = 1;
    }
}

// Find the largest RNTI in the array
int find_largest_rnti(NFAPI_CRC_INDICATION_PDU_T *list, int length) {
    int max_rnti = list[0].RNTI;
    for (int i = 1; i < length; i++) {
        if (list[i].RNTI > max_rnti)
            max_rnti = list[i].RNTI;
    }
    return max_rnti;
}

// Serialize the linked list to a binary file
void serialize_linked_list(NFAPI_CRC_INDICATION_PDU_T *list, int length, char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp)
        return;

    for (int i = 0; i < length; i++) {
        fwrite(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
    fclose(fp);
}

// Deserialize the linked list from a binary file
NFAPI_CRC_INDICATION_PDU_T *deserialize_linked_list(char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list;
    int length = (int)fseek(fp, 0, SEEK_END);
    rewind(fp);

    list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < length; i++) {
        fread(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
    fclose(fp);

    return list;
}

// Helper function to print the linked list
void print_linked_list(NFAPI_CRC_INDICATION_PDU_T *list, int length) {
    for (int i = 0; i < length; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRCFLAG);
