    // ...

    // Iterate through supported file types and compress files accordingly
    for (int i = 0; i < strlen(supported_types); i++) {
        const char* file_type = supported_types[i];

        // Find files of the current type in the input directory
        DIR* dir = opendir(input_file);
        struct dirent* entry;
        while ((entry = readdir(dir))) {
            if (strcmp(entry->d_name, file_type)) continue;

            // Compress the file using zlib and write to output archive...
            z_stream strm;
            strm.zalloc = Z_NULL;
            strm.zfree = Z_NULL;
            strm.opaque = Z_NULL;

            int reti;
            unsigned char in[1], out[1024];
            char buffer[1024];
            size_t len, total_out;
            total_out = 0;

            FILE* file = fopen(entry->d_name, "rb");
            if (!file) return 3; // Error opening file

            while ((len = fread(in, 1, sizeof in)) > 0) {
                strm.total_in = len;
                strm.next_in = (Bytef*)in;
                do {
                    strm.avail_out = sizeof out;
                    strm.next_out = (Bytef*)out;
                    reti = deflate(&strm, Z_DEFAULT_COMPRESSION);
                    if (reti < 0) return 4; // Error compressing
                    total_out += strlen((char*)out);
                } while (strm.avail_out == 0);
            }

            fclose(file);

            // Write compressed data to output archive...
            // ...
        }

        closedir(dir);
    }

    // Log any compression errors and handle exceptions...
    // ...

    return 0;
}
