['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    int key;
    struct item *head;
    char *description;
} node;

typedef struct item {
    int value;
    struct item *next;
    struct item *prev;
} item;

node *create_node(int key, int max_items);
void add_item(node *n, int value);
void free_node(node *n);

int total_items = 0;

// Function to dynamically manage nodes and items
void init_nodes(int num_nodes, int range_start, int range_end) {
    node **nodes = (node **)malloc(num_nodes * sizeof(node *));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = create_node(i, range_end - range_start);
        for (int j = 0; j < range_end - range_start && j < nodes[i]->head->max_items; j++) {
            add_item(nodes[i], range_start + j);
        }
    }

    // Clean up
    for (int i = 0; i < num_nodes; i++) {
        free_node(nodes[i]);
    }
    free(nodes);
}

// Function to create a new node with a linked list of items
node *create_node(int key, int max_items) {
    node *n = (node *)malloc(sizeof(node));
    n->key = key;
    n->head = (item *)malloc(sizeof(item));
    n->head->value = 0;
    n->head->next = NULL;
    n->head->prev = NULL;
    n->description = (char *)malloc(64 * sizeof(char));
    sprintf(n->description, "Node %d", key);
    return n;
}

// Function to add an item to a node's linked list
void add_item(node *n, int value) {
    item *new_item = (item *)malloc(sizeof(item));
    new_item->value = value;
    new_item->next = NULL;
    new_item->prev = n->head;
    n->head->next = new_item;
    n->head = new_item;
    total_items++;
}

// Function to free a node and its items
void free_node(node *n) {
    item *current = n->head;
    while (current != NULL) {
        item *temp = current->next;
        free(current);
        current = temp;
    }
    free(n->description);
    free(n);
}
