#include <string.h>
#include <time.h>
#include <rand.h>

typedef struct {
    float temperature;
    time_t timestamp;
    int reliable;
    char id[32];
} SensorReading;

SensorReading* read_and_validate_file(const char* filename, int range_min, int range_max) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return NULL;

    int count = 0;
    float* temperatures = (float*)malloc(sizeof(float));
    SensorReading** readings = (SensorReading**)calloc(1, sizeof(SensorReading*));

    while (fscanf(file, "%f\n", &temperatures[count]) == 1 && temperatures[count] >= range_min && temperatures[count] <= range_max) {
        SensorReading* reading = (SensorReading*)malloc(sizeof(SensorReading));
        reading->temperature = temperatures[count];
        reading->timestamp = time(NULL);
        reading->reliable = rand() % 2;
        sprintf(reading->id, "%p", reading);
        readings = realloc(readings, ++count * sizeof(SensorReading*));
        readings[count - 1] = reading;
    }

    fclose(file);

    SensorReading** temp_readings = readings;
    for (int i = 0; i < count; i++) {
        readings[i] = temp_readings[i];
    }
    free(temp_readings);

    return readings;
}

void print_average_temperature(SensorReading* readings, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += readings[i]->temperature;
    }
    printf("Average temperature: %.2f°C\n", sum / count);
}

void log_execution_stats(const char* filename, int count) {
    FILE* log_file = fopen(filename, "a");
    fprintf(log_file, "Read %d sensor readings from file.\n", count);
    fclose(log_file);
}
