#include <iostream>
#include <vector>
#include <random>
#include <string>

namespace NFAPI {
    class NFAPI_CRC_INDICATION_PDU_T {
    public:
        std::string RX_UE_INFORMATION_TAG;
        int RNTI;
        bool CRCFLAG;

        NFAPI_CRC_INDICATION_PDU_T(const std::string& tag, int rnti) : 
            RX_UE_INFORMATION_TAG(tag), RNTI(rnti) {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_real_distribution<> dis(0.0, 1.0);
            CRCFLAG = (dis(gen) > 0.5);
        }
    };

    class NFAPI_CRC_INDICATION_PDU_T_Handler {
    public:
        NFAPI_CRC_INDICATION_PDU_T_Handler() : mt_(std::random_device{}()) {}

        std::vector<NFAPI_CRC_INDICATION_PDU_T> generatePDU(const std::string& networkStream) {
            std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
            std::istringstream iss(networkStream);
            std::string tag;
            int rnti;
            while (std::getline(iss, tag, ',')) {
                rnti = std::stoi(tag.substr(tag.find_last_of(" ") + 1));
                pduList.emplace_back(tag.substr(0, tag.find_last_of(" ")), rnti);
            }
            for (auto& pdu : pduList) {
                if (!pdu.RX_UE_INFORMATION_TAG.empty()) {
                    pdu.CRCFLAG = (std::bernoulli_distribution()(mt_));
                }
            }
            return pduList;
        }

    private:
        std::mt19937 mt_;
    };

    int main() {
        NFAPI_CRC_INDICATION_PDU_T_Handler handler;
        std::string networkStream = "Tag1, 1, Tag2, 2, Tag3, 3";
        auto pduList = handler.generatePDU(networkStream);
        for (const auto& pdu : pduList) {
            std::cout << pdu.RX_UE_INFORMATION_TAG << " RNTI: " << pdu.RNTI << " CRCFLAG: " << (pdu.CRCFLAG ? "Set" : "Not Set") << std::endl;
        }
        return 0;
    }
}
