public class MessageEventManager {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Gson gson = new GsonBuilder().setPrettyPrinting().create();
    private final Network<MessageEvent> graph = GraphBuilder.undirected().build();

    public void addMessageEvent(MessageEvent event) {
        // Add event to the graph and log its addition
        graph.put(event.getMessageID(), event);
        logEventAdded(event);

        // Start a thread to simulate message delivery with configurable success/failure notifications
        executor.submit(() -> {
            try {
                if (simulateMessageDelivery(event)) {
                    logEventDelivered(event, "success");
                } else {
                    logEventDelivered(event, "failure");
                }
            } catch (IOException e) {
                logException(e);
            }
        });
    }

