class UserSessionFactory {
private:
    std::vector<UserSession*> sessions;
    std::mutex sessionMutex;
    int maxSessions = 5000; // configurable maximum size
    int inactivityThreshold = 30000; // configurable inactivity threshold (in milliseconds)
    bool isCleanedUp = false;

public:
    UserSessionFactory() {
        // Initialize logging framework here
    }

    ~UserSessionFactory() {
        validateIntegrity();
    }

    void addSession(std::string sid, std::string username, long timestamp) {
        std::lock_guard<stdlock> lock(sessionMutex);
        if (sessions.size() >= maxSessions) {
            throw std::runtime_error("Maximum session limit reached");
        }
        sessions.push_back(new UserSession(sid, username, timestamp));
    }

    void removeSession(std::string sid) {
        // Implement this function to remove the session with matching SID
    }

    void validateIntegrity() {
        for (auto session : sessions) {
            if (!session) continue;
            if (std::find_if(sessions.begin(), sessions.end(),
                [this, session](UserSession* s) { return s->sid == session->sid; }) != sessions.end()) {
                // Duplicate SID found
                std::cerr << "Warning: Duplicate SID '" << session->sid << "' found" << std::endl;
            }
        }
    }

    void cleanUpSessions() {
        if (isCleanedUp) return;
        for (auto it = sessions.begin(); it != sessions.end();) {
            auto& session = *it;
            if ((std::chrono::milliseconds(std::chrono::system_clock::now().time_since_epoch()) - 
                 std::chrono::milliseconds(session->timestamp)) > inactivityThreshold) {
                delete session;
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
        isCleanedUp = true;
    }

    void configure(int maxSessions, int inactivityThreshold) {
        this->maxSessions = maxSessions;
        this->inactivityThreshold = inactivityThreshold;
    }
};
