// Structure definition for record
typedef struct {
    int key;
    long offset;
} record;

// Function to initialize and fill records with random values
void init_records(int* num_keys, int* num_offsets, int* num_records, record** records) {
    // Allocate memory for arrays
    int* keys = (int*)malloc(*num_keys * sizeof(int));
    long* offsets = (long*)malloc(*num_offsets * sizeof(long));

    // Initialize key and offset arrays
    srand(time(NULL));  // Ensure consistent randomness
    for (int i = 0; i < *num_keys; i++) {
        keys[i] = rand() % (1 << 31);  // Random int value
    }
    for (int i = 0; i < *num_offsets; i++) {
        offsets[i] = (long)i * (1 << 32) + rand() % (1 << 32);  // Random long value
    }

    // Allocate memory for records
    record* new_records = (record*)malloc(*num_records * sizeof(record));
    for (int i = 0; i < *num_records; i++) {
        new_records[i].key = keys[rand() % *num_keys];  // Randomly select a key
        new_records[i].offset = offsets[rand() % *num_offsets];  // Randomly select an offset
    }

    // Update the original record pointer with the newly allocated records
    *records = new_records;
}

// Function to serialize the initialized data structure
void serialize_data(int* num_keys, int* num_offsets, int* num_records, record** records) {
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Failed to open file for serialization.\n");
        return;
    }

    // Write the number of keys and offsets
    fwrite(num_keys, sizeof(int), 1, file);
    fwrite(num_offsets, sizeof(long), 1, file);

    // Write each record's key and offset
    for (int i = 0; i < *num_records; i++) {
        fwrite(&records[i]->key, sizeof(int), 1, file);
        fwrite(&records[i]->offset, sizeof(long), 1, file);
    }

    fclose(file);
}

// Function to deserialize the data structure
void deserialize_data(int* num_keys, int* num_offsets, int* num_records, record** records) {
    FILE* file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Failed to open file for deserialization.\n");
        return;
    }

    // Read the number of keys and offsets
    fread(num_keys, sizeof(int), 1, file);
    fread(num_offsets, sizeof(long), 1, file);

    // Allocate memory for records and initialize them with deserialized values
    record* new_records = (record*)malloc(*num_records * sizeof(record));
    for (int i = 0; i < *num_records; i++) {
        fread(&new_records[i].key, sizeof(int), 1, file);
        fread(&new_records[i].offset, sizeof(long), 1, file);
    }

    // Update the original record pointer with the newly allocated records
    *records = new_records;

    fclose(file);
}

int main() {
    int num_keys = 10;
    int num_offsets = 20;
    int num_records = 30;
    record* records;

    init_records(&num_keys, &num_offsets, &num_records, &records);

    // Use the initialized data structure as needed

    serialize_data(&num_keys, &num_offsets, &num_records, &records);

    // Later, when needed
    record* new_records;
    deserialize_data(&num_keys, &num_offsets, &num_records, &new_records);

    return 0;
}
