#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 1000
#define GROWTH_THRESHOLD 0.8
#define MIN_VALUE 1
#define MAX_VALUE 1000000

typedef struct {
    char* key;
    long value;
} entry_t;

void init_collection(entry_t** collection, int size) {
    *collection = (entry_t*)malloc(size * sizeof(entry_t));
    for (int i = 0; i < size; i++) {
        (*collection)[i].key = NULL;
    }
}

void resize_collection(entry_t** collection, int old_size, int new_size) {
    entry_t* temp = (entry_t*)realloc(*collection, new_size * sizeof(entry_t));
    if (!temp) {
        printf("Error: Could not resize collection.\n");
        return;
    }
    *collection = temp;
    for (int i = old_size; i < new_size; i++) {
        (*collection)[i].key = NULL;
    }
}

void populate_collection(entry_t** collection, int size, char* (*transform)(char*), FILE* file) {
    srand(time(NULL));
    int current_size = 0;
    while (current_size < size && current_size < MAX_SIZE) {
        entry_t* new_entry = &((*collection)[current_size]);
        new_entry->key = transform("Input string");
        new_entry->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        printf("Entry %d: key '%s' value %ld\n", current_size, new_entry->key, new_entry->value);
        if (++current_size >= size * GROWTH_THRESHOLD && current_size < MAX_SIZE) {
            int new_max_size = (int)(current_size * 1.5);
            printf("Resizing collection from %d to %d entries.\n", old_size, new_max_size);
            resize_collection(collection, old_size, new_max_size);
        }
    }
}

void serialize_collection(entry_t* collection, FILE* file) {
    int size = sizeof(entry_t);
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < MAX_SIZE; i++) {
        if (collection[i].key) {
            size = strlen(collection[i].key) + 1;
            fwrite(&size, sizeof(int), 1, file);
            fwrite(collection[i].key, size, 1, file);
            size = sizeof(long);
            fwrite(&size, sizeof(int), 1, file);
            fwrite(&collection[i].value, size, 1, file);
        }
    }
}

void deserialize_collection(entry_t** collection, FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    *collection = (entry_t*)malloc(size * sizeof(entry_t));
    for (int i = 0; i < size; i++) {
        fread(&((*collection)[i].key), sizeof(int), 1, file);
        (*collection)[i].key = (char*)malloc((*collection)[i].key + 1);
        fread((*collection)[i].key, (*collection)[i].key, 1, file);
        fread(&((*collection)[i].value), sizeof(long), 1, file);
    }
}

int main() {
    entry_t* collection;
    init_collection(&collection, MAX_SIZE);
    populate_collection(&collection, 1000, (char* (*)(char*))strtok, stdout);
    FILE* file = fopen("collection.txt", "wb");
    serialize_collection(collection, file);
    fclose(file);
    return 0;
}
