// Custom memory pool to manage allocations efficiently
typedef struct {
    void* base;
    size_t size;
    int free_blocks;
} MemoryPool;

MemoryPool memory_pool = {
    .base = NULL,
    .size = 0,
    .free_blocks = 0
};

// Thread-safe memory allocation function
void* nfaapi_crc_indication_pdu_alloc(size_t size) {
    void* ptr = NULL;

    pthread_mutex_lock(&memory_pool);

    // Reuse existing blocks from the memory pool to minimize allocations
    if (memory_pool.free_blocks > 0) {
        ptr = memory_pool.base;
        memory_pool.base += size;
        memory_pool.free_blocks--;
    } else {
        // Allocate a new block of memory
        void* temp = malloc(size);
        if (!temp) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        memory_pool.base = temp;
        memory_pool.size = size;
        memory_pool.free_blocks++;
    }

    pthread_mutex_unlock(&memory_pool);

    return ptr;
}

// Thread-safe memory deallocation function
void nfaapi_crc_indication_pdu_free(void* ptr, size_t size) {
    pthread_mutex_lock(&memory_pool);

    // Reuse the allocated block by updating the memory pool
    if (ptr == memory_pool.base) {
        memory_pool.base += size;
        memory_pool.free_blocks++;
    }

    free(ptr);
    pthread_mutex_unlock(&memory_pool);
}

