pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T **array = NULL;
size_t array_size = 0;
size_t allocated_size = 0;
void *memory_pool_head = NULL;

void* my_malloc(size_t size) {
    void *ptr = memory_pool_head;
    if (ptr == NULL || size > (allocated_size - ((char *)memory_pool_head - (char *)0))) {
        ptr = malloc(size);
        if (memory_pool_head != NULL)
            memory_pool_head = realloc(memory_pool_head, allocated_size + size);
        else
            memory_pool_head = ptr;
        allocated_size += size;
    }
    return ptr;
}

void my_free(void *ptr, size_t size) {
    if (ptr == memory_pool_head) {
        memory_pool_head = ((char *)memory_pool_head) + size;
        allocated_size -= size;
    } else
        free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T** create_array(size_t new_size) {
    NFAPI_CRC_INDICATION_PDU_T **new_array = (NFAPI_CRC_INDICATION_PDU_T **)my_malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (array != NULL)
        for (size_t i = 0; i < array_size && i < new_size; i++)
            new_array[i] = array[i];
    else
        for (size_t i = 0; i < new_size; i++)
            new_array[i] = my_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array != NULL)
        for (size_t i = array_size; i > 0; i--)
            my_free(array[i - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(array);
    array = new_array;
