    int used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(int initial_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->blocks = malloc(initial_size * sizeof(void*));
    pool->size = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < pool->used; i++) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfapi(struct MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->size) {
        // Resize the pool if necessary
        pool->blocks = realloc(pool->blocks, (pool->size + 16) * sizeof(void*));
        pool->size += 16;
    }
    void* block = pool->blocks[pool->used++];
