    memcpy(nfa_pi, block, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(block);
    pthread_mutex_unlock(&pool->lock);
    return nfa_pi;
}

void deallocate_nfapi(struct MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* nfa_pi) {
    pthread_mutex_lock(&pool->lock);
    pool->blocks[pool->used - 1] = nfa_pi;
    pthread_mutex_unlock(&pool->lock);
}

// Cache structure
