Cache* create_cache(int initial_size) {
    Cache* cache = malloc(sizeof(Cache));
    cache->cache = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    cache->size = initial_size;
    cache->used = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache* cache) {
    for (int i = 0; i < cache->used; i++) {
        deallocate_nfapi(pool, cache->cache[i]);
    }
    free(cache->cache);
    free(cache);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_cache(Cache* cache, uint8_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->used; i++) {
        if (cache->cache[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            NFAPI_CRC_INDICATION_PDU_T* nfa_pi = cache->cache[i];
            cache->cache[i] = NULL;
            for (int j = i + 1; j < cache->used; j++) {
                if (cache->cache[j] == NULL) {
                    cache->cache[j] = nfa_pi;
                    break;
                }
            }
            deallocate_nfapi(pool, nfa_pi);
            pthread_mutex_unlock(&cache->lock);
            return nfa_pi;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return allocate_nfapi(pool);
}

void put_in_cache(Cache* cache, NFAPI_CRC_INDICATION_PDU_T* nfa_pi) {
    pthread_mutex_lock(&cache->lock);
    if (cache->used < cache->size / 2) {
        // If the cache is less than half full, just insert
        for (int i = 0; i < cache->used; i++) {
