async fn configure_http_client(urls: Vec<String>, timeout: Option<u64>, max_concurrency: Option<u32>) -> Result<(), Error> {
    let client = Client::new();
    let mut timestamps: Vec<i64> = vec![];
    let cache: HashMap<String, String> = HashMap::new();
    let store: Arc<Mutex<DataStore>> = Arc::new(Mutex::new(DataStore { records: vec![] }));

