    for url in urls {
        let client_clone = client.clone();
        let timeout_clone = timeout.clone();
        let max_concurrency_clone = max_concurrency.clone();
        let handle = tokio::spawn(async move {
            if let Some(timeout) = timeout_clone {
                // Configure HTTP request with timeout
                match client_clone.get(&url).timeout(std::time::Duration::from_millis(timeout as u64)).await {
                    Ok(response) => {
                        // Process response and cache it
                        let response_body = response.text().await.unwrap();
                        cache.insert(url.clone(), response_body);
                    }
                    Err(err) => {
                        // Handle request failure with exponential backoff
                        if let Some(max_concurrency) = max_concurrency_clone {
                            // Implement retry mechanism with exponential backoff
                            for _ in 0..5 {
