                                    Ok(response) => {
                                        // Process response and cache it
                                        let response_body = response.text().await.unwrap();
                                        cache.insert(url.clone(), response_body);
                                        break;
                                    }
                                    Err(err) => {
                                        // Wait for a random duration before retrying
                                        tokio::time::sleep(std::time::Duration::from_millis(rand::thread_rng().gen_range(100..5000))).await;
                                    }
                                }
                            }
                        } else {
                            println!("Failed to retrieve {} after 5 attempts: {}", url, err);
                        }
                    }
                }
            } else {
                match client_clone.get(&url).await {
                    Ok(response) => {
                        // Process response and cache it
                        let response_body = response.text().await.unwrap();
                        cache.insert(url.clone(), response_body);
                    }
                    Err(err) => {
                        println!("Failed to retrieve {}: {}", url, err);
                    }
                }
            }
        });
        handles.push(handle);
    }

    // Wait for all requests to complete
    for handle in handles {
        handle.await?;
    }

    Ok(())
}

