#define KEY_RANGE 1000
#define OFFSET_RANGE 1000000
#define MEMORY_THRESHOLD (1024 * 1024) // 1MB

typedef struct {
    int key;
    long offset;
} Record;

Record* records = NULL;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int memory_usage = 0;
int allocation_failures = 0;

void* allocate_record() {
    pthread_mutex_lock(&lock);
    if (num_records >= MAX_RECORDS) {
        allocation_failures++;
        printf("Memory allocation failed: reached maximum capacity.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Record* new_record = realloc(NULL, sizeof(Record));
    if (!new_record) {
        allocation_failures++;
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        free(new_record);
        return NULL;
    }

    num_records++;
    memory_usage += sizeof(Record);

    int key = rand() % KEY_RANGE;
    long offset = (long)rand() * OFFSET_RANGE / RAND_MAX;

    while (records != NULL && find_record(key)) {
        key = (key + 1) % KEY_RANGE;
        offset = (long)rand() * OFFSET_RANGE / RAND_MAX;
    }

    new_record->key = key;
    new_record->offset = offset;

    records = realloc(records, sizeof(Record) * num_records);
    if (!records) {
        allocation_failures++;
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        free(new_record);
        return NULL;
    }

    records[num_records - 1] = new_record;
    pthread_mutex_unlock(&lock);
    return NULL;
}

int find_record(int key) {
