        printf("Error: unable to open 'offsets.txt'\n");
        return;
    }
    char line[20];
    long offsets[num_offsets];
    for (int i = 0; i < num_offsets; i++) {
        fgets(line, sizeof(line), offsets_file);
        if (ferror(offsets_file)) {
            printf("Error: unable to read 'offsets.txt'\n");
            fclose(offsets_file);
            return;
        }
        char *endptr;
        long val = strtol(line, &endptr, 10);
        if (*endptr != '\0' || val < 0) {
            printf("Invalid offset in 'offsets.txt'\n");
            fclose(offsets_file);
            return;
        }
        offsets[i] = val;
    }
    fclose(offsets_file);

    // Read and validate keys.txt
    FILE *keys_file = fopen("keys.txt", "r");
    if (!keys_file) {
        printf("Error: unable to open 'keys.txt'\n");
        return;
    }
    int keys[num_keys];
    for (int i = 0; i < num_keys; i++) {
        fgets(line, sizeof(line), keys_file);
        if (ferror(keys_file)) {
            printf("Error: unable to read 'keys.txt'\n");
            fclose(keys_file);
            return;
        }
        int val = atoi(line);
        if (val < 0) {
            printf("Invalid key in 'keys.txt'\n");
            fclose(keys_file);
            return;
        }
        keys[i] = val;
    }
    fclose(keys_file);

    // Initialize records
    srand(time(NULL));
    record *records = malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % ((max_value - min_value) + 1) + min_value;
    }

    // Initialize memory for offsets and keys
    long *offsets_ptr = malloc(num_offsets * sizeof(long));
    int *keys_ptr = malloc(num_keys * sizeof(int));

    // Copy data to pointers
    memcpy(offsets_ptr, offsets, num_offsets * sizeof(long));
    memcpy(keys_ptr, keys, num_keys * sizeof(int));

    // Monitor memory usage and adjust records if necessary
    size_t total_allocated = (num_offsets + num_keys) * sizeof(long) + num_records * sizeof(record);
    printf("Total allocated: %zu bytes\n", total_allocated);
    if (total_allocated > 1024 * 1024 * 10) { // 10MB threshold
        int new_num_records = num_records - (int)((total_allocated / (num_records * sizeof(record))) + .5);
        record *new_records = realloc(records, new_num_records * sizeof(record));
        if (!new_records) {
            printf("Error: unable to reallocate memory for records\n");
            return;
        }
        num_records = new_num_records;
        records = new_records;
    }

    // Free all allocated memory
    free(offsets_ptr);
    free(keys_ptr);
    free(records);
}
