// Structure to represent a record
typedef struct {
    long offset;
    int key;
    char* state;
} Record;

// Function to initialize records
void initialize_records(long* offsets, int* keys, Record** records, int size, int min_key, int max_key) {
    *records = (Record*) malloc(size * sizeof(Record));

    if (*records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        (*records)[i].offset = offsets[i] = i;
        (*records)[i].key = keys[i] = i + min_key;

        char* state = (char*) malloc(100 * sizeof(char));
        if (state == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        sprintf(state, "initialized (%d-%d)", min_key, max_key);
        (*records)[i].state = state;
    }
}

// Function to update the state of a record
void update_record_state(char* old_state, char* new_state) {
    if (old_state != NULL) {
        free(old_state);
    }

    new_state = (char*) malloc(strlen(new_state) + 1 * sizeof(char));
    strcpy(new_state, new_state);
}

// Function to free memory
void free_memory(long* offsets, int* keys, Record** records, int size) {
    for (int i = 0; i < size; i++) {
        if ((*records)[i].state != NULL) {
            free((*records)[i].state);
        }
    }

    free(*records);
}
