#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
} record;

int readOffsets(int num_offsets, long **offsets) {
    FILE *fp = fopen("offsets.txt", "r");
    if (fp == NULL)
        return -1; // File not found

    *offsets = (long *)malloc(num_offsets * sizeof(long));
    int i;
    for (i = 0; i < num_offsets; i++) {
        fscanf(fp, "%ld\n", &((*offsets)[i]));
    }

    long checksum = 0;
    for (i = 0; i < num_offsets; i++) {
        checksum += (*offsets)[i];
    }
    if (checksum != 0)
        return -1; // Checksum mismatch

    fclose(fp);
    return 0;
}

int readKeys(int num_keys, int **keys) {
    FILE *fp = fopen("keys.txt", "r");
    if (fp == NULL)
        return -1; // File not found

    *keys = (int *)malloc(num_keys * sizeof(int));
    int i;
    for (i = 0; i < num_keys; i++) {
        fscanf(fp, "%d\n", &((*keys)[i]));
    }

    int j;
    for (i = 0; i < num_keys; i++) {
        for (j = 0; j < i; j++) {
            if ((*keys)[j] == (*keys)[i])
                return -1; // Duplicate key found
        }
    }

    fclose(fp);
    return 0;
}

int initRecords(int num_records, int min_value, int max_value, record **records) {
    *records = (record *)malloc(num_records * sizeof(record));
    int i;
    srand(time(NULL)); // Initialize random number generator
    for (i = 0; i < num_records; i++) {
        (*records)[i].key = rand() % ((max_value + 1) - min_value) + min_value;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int num_offsets = atoi(argv[1]);
    int num_keys = atoi(argv[2]);
    int num_records = atoi(argv[3]);
    int min_value = atoi(argv[4]);
    int max_value = atoi(argv[5]);

    long *offsets;
    if (readOffsets(num_offsets, &offsets) < 0)
        return -1; // I/O error

    int *keys;
    if (readKeys(num_keys, &keys) < 0)
        return -1; // I/O error

    record *records;
    if (initRecords(num_records, min_value, max_value, &records) < 0)
        return -1; // Error initializing records

    free(offsets);
    free(keys);

    printf("Initialization successful.\n");
    return 0;
}

