void* phy_context_array_manager(int* size, void** array_ptr) {
    // Define the logging framework
    #include "logging_framework.h"

    // Define the database connection
    #include "database_connection.h"

    // Initialize the array and its size
    *array_ptr = malloc(1 * sizeof(PHY_CONTEXT));
    *size = 0;

    // Function to dynamically resize the array
    void* resize_array(int new_size) {
        PHY_CONTEXT* temp = (PHY_CONTEXT*) realloc(*array_ptr, new_size * sizeof(PHY_CONTEXT));
        if (temp == NULL) {
            log_error("Memory allocation failed");
            return *array_ptr;
        }
        *array_ptr = temp;
        *size = new_size;
        return *array_ptr;
    }

    // Function to add a new PHY_CONTEXT structure to the array
    void add_phy_context(int phy_channel_id, int base_station_id, int frame_number, int phy_layer_status) {
        if (*size >= 50000) {
            log_error("Array exceeded maximum size of 50,000 elements");
            return;
        }
        *array_ptr = resize_array(*size + 1);
        PHY_CONTEXT* new_element = (PHY_CONTEXT*)((*array_ptr) + (*size - 1));
        new_element->phy_channel_id = phy_channel_id;
        new_element->base_station_id = base_station_id;
        new_element->frame_number = frame_number;
        new_element->phy_layer_status = phy_layer_status;
    }

    // Function to remove a PHY_CONTEXT structure from the array
    void remove_phy_context(int phy_channel_id) {
        for (int i = 0; i < *size; i++) {
            if (((*array_ptr)[i]).phy_channel_id == phy_channel_id) {
                *array_ptr = realloc(*array_ptr, (*size - 1) * sizeof(PHY_CONTEXT));
                *size -= 1;
                return;
            }
        }
    }

    // Function to validate the array for duplicate PHY_CHANNEL_ID values
    void validate_phy_context_array() {
        for (int i = 0; i < *size; i++) {
            if (duplicate_found) {
                log_warning("Duplicate PHY_CHANNEL_ID found");
                break;
            }
        }
    }

    // Function to periodically clean up unused structures based on age
    void cleanup_unused_structures(int time_threshold) {
        for (int i = 0; i < *size; i++) {
            if (age > time_threshold) {
                remove_phy_context(phy_channel_id);
            }
        }
    }

    // Function to record memory allocation and deallocation events
    void log_memory_events() {
        timestamp = time(NULL);
        log_info("Memory allocation/deallocation event recorded at %d", timestamp);
    }

    // Function to check for duplicate PHY_CHANNEL_ID values within the array
    int duplicate_found(int phy_channel_id) {
        for (int i = 0; i < *size; i++) {
            if (((*array_ptr)[i]).phy_channel_id == phy_channel_id) {
                return 1;
            }
