#include <time.h>

typedef struct {
    int* value;
    long offset;
} record;

record* initRecords(int n, int m) {
    if (n < 0 || m < 0) {
        return NULL; // error: negative input
    }

    if (m > n) {
        printf("Error: key size exceeds offsets array size\n");
        return NULL;
    }

    record* records = (record*)malloc((n+1)*sizeof(record));
    if (!records) {
        printf("Error: failed to allocate memory for records\n");
        return NULL;
    }

    long* offsets = (long*)malloc((n+1)*sizeof(long));
    if (!offsets) {
        free(records);
        printf("Error: failed to allocate memory for offsets array\n");
        return NULL;
    }

    int* keys = (int*)malloc(m*sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        printf("Error: failed to allocate memory for keys array\n");
        return NULL;
    }

    // initialize records, offsets and keys
    srand(time(NULL)); // seed random number generator

    for (int i = 0; i < n; i++) {
        record* r = &records[i];
        long offset = rand() % (n+1);
        r->offset = offset;
        r->value = (int*)malloc(sizeof(int));
        *r->value = rand() % ((i > m ? i : m)+1); // value within [0, min(i,m)]
    }

    for (int i = 0; i < m; i++) {
        keys[i] = rand() % (n+1);
    }

    free(keys);

    return records;
}

void freeRecords(record* records) {
    if (!records) return;

    record* r = &records[0];
    for (int i = 0; i < records[0].offset; i++) {
        free(r->value);
        r++;
    }

    free(records);
}
