        for ($i = 0; $i < 10000; $i++) {
            $pduStruct = new NFAPI_CRC_INDICATION_PDU_T();
            $pduStruct->RX_UE_INFORMATION_TAG = rand(1, 100);
            $pduStruct->RNTI = rand(1, 1000);
            $pduStruct->CRC_INDICATION_REL8_TAG = rand(1, 100);
            $pduStruct->CRCFLAG = (rand(1, 2) === 1 ? true : false);
