    while (1) {
        if (current_size * sizeof(long) + current_size * sizeof(int) + current_size * sizeof(record) > memory_pool_size) {
            memory_pool_size *= 2; // Double the size of the memory pool
            memory_pool = (char*)realloc(memory_pool, memory_pool_size);
        } else {
            break;
        }
    }

    // Implement performance monitoring and logging
    clock_t start_time = clock();
