int insert_node(node** root, int key);
int search_node(node* root, int target_key);
void free_tree(node* root);
void add_packet_udp(char* ip_address, int port_number, char* payload);
void recalculate_checksum(char* packet_data);
int verify_checksum(char* packet_data);
void update_secondary_tree(node* node_to_update);

// Global variables
node* g_root = NULL;
int total_items = 0;
pthread_mutex_t lock;

// Function implementations

void init_tree(node** root) {
    *root = (node*)malloc(sizeof(node));
    (*root)->key = -1;
    (*root)->item_list = NULL;
    (*root)->left = NULL;
    (*root)->right = NULL;
    (*root)->secondary_list = NULL;
    pthread_mutex_init(&((*root)->lock), NULL);
}

int insert_node(node** root, int key) {
    if (!*root) {
        *root = (node*)malloc(sizeof(node));
        (*root)->key = key;
        return 0;
    }

    node* temp = *root;

    while (temp->right && temp->right->key > key) {
        temp = temp->left;
    }

    if (temp->right && temp->right->key == key) {
        return -1; // Key already exists
    }

    if (!temp->right || !temp->right->key > key) {
        temp->right = insert_node(&temp->right, key);
    } else {
        node* new_node = (node*)malloc(sizeof(node));
        new_node->key = key;
        new_node->item_list = NULL;
        new_node->secondary_list = NULL;

        if (temp->right->key > key) {
            temp->left = new_node;
        } else {
            temp->right = new_node;
        }
    }

    return 0;
}

int search_node(node* root, int target_key) {
    while (root) {
        if (root->key == target_key) {
            return 0; // Key found
        }
        if (root->key > target_key) {
            root = root->left;
        } else {
            root = root->right;
        }
    }
    return -1; // Key not found
}

void free_tree(node* root) {
    if (!root) {
        return;
    }

    free_tree(root->left);
    free_tree(root->right);

    free(root);
}

