    if (long_offsets == NULL) {
        return -1;  // Memory allocation failed.
    }
    for (size_t i = 0; i < long_array_size; i++) {
        long_offsets[i] = rand() % (INT_MAX + 1);
    }

    // Allocate memory for 'int' keys.
    int* int_keys = (int*) OPENSSL_malloc(int_array_size * sizeof(int));
    if (int_keys == NULL) {
        return -1;  // Memory allocation failed.
    }
    for (size_t i = 0; i < int_array_size; i++) {
        int_keys[i] = rand() % (INT_MAX + 1);
    }

    // Allocate memory for 'record' structures containing a single 'int' value.
    struct record* records = (struct record*) OPENSSL_malloc(record_array_size * sizeof(struct record));
    if (records == NULL) {
        return -1;  // Memory allocation failed.
    }
    for (size_t i = 0; i < record_array_size; i++) {
        records[i].value = rand() % (INT_MAX + 1);
    }

    // Free allocated memory when no longer needed.
    OPENSSL_free(long_offsets);
    OPENSSL_free(int_keys);
    OPENSSL_free(records);

