#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t size;
    time_t lastModified;
    char **files;
    int fileCount;
} DirInfo;

DirInfo* processDirectory(char* path) {
    DIR* dir = opendir(path);
    if (dir == NULL)
        return NULL;

    DirInfo* info = malloc(sizeof(DirInfo));
    info->size = 0;
    info->lastModified = time(NULL);
    info->fileCount = 0;

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char filePath[1024];
        sprintf(filePath, "%s/%s", path, ent->d_name);

        struct stat fileStat;
        if (stat(filePath, &fileStat) == -1) {
            closedir(dir);
            free(info);
            return NULL;
        }

        if (S_ISDIR(fileStat.st_mode)) {
            DirInfo* subDir = processDirectory(filePath);
            if (subDir == NULL) {
                closedir(dir);
                free(info);
                return NULL;
            }
            info->size += fileStat.st_size + sizeof(DirInfo) + sizeof(char*);
            info->fileCount++;
        } else if (S_ISREG(fileStat.st_mode)) {
            info->size += fileStat.st_size;
            info->fileCount++;
        }

        free(ent->d_name);
    }
    closedir(dir);

    return info;
}

void printLargestDirSize(DirInfo* root) {
    size_t largest = 0;
    char **largestFiles;

    if (root == NULL)
        return;

    DirInfo* queue[100];
    int queueSize = 0;
    queue[queueSize++] = root;

    while (queueSize > 0) {
        DirInfo* dir = queue[--queueSize];

        if (dir->size > largest) {
            largest = dir->size;
            largestFiles = malloc(sizeof(char*) * dir->fileCount);
            for (int i = 0; i < dir->fileCount; i++)
                largestFiles[i] = malloc(strlen(dir->files[i]) + 1);
        }

        for (int i = 0; i < dir->fileCount; i++) {
            DirInfo* subDir;
            if (dir->files[i][strlen(dir->files[i]) - 1] == '/') {
                subDir = processDirectory(dir->files[i]);
                if (subDir != NULL) {
                    queue[queueSize++] = subDir;
                    free(subDir);
                }
            }
        }

        for (int i = 0; i < dir->fileCount; i++) {
            free(dir->files[i]);
        }
        free(dir->files);
        free(dir);
    }
    printf("Largest directory size: %zu\n", largest);

    // Reset the system state
    system("reset");
}

int main() {
    char buffer[1024];

    while (fgets(buffer, sizeof(buffer), stdin) != NULL) {
        DirInfo* info = processDirectory(buffer);
        if (info == NULL)
            break;

        printf("%s size: %zu, last modified: %lu\n", buffer, info->size, info->lastModified);

        printLargestDirSize(info);

        free(info);
    }

    return 0;
}
