    int size;
    KeyValuePair** buckets;
} HashTable;

HashTable* allocate_hash_table(int initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->buckets = (KeyValuePair**)malloc(initial_size * sizeof(KeyValuePair*));
    return table;
}

void resize_hash_table(HashTable* table, int new_size) {
    KeyValuePair** new_buckets = (KeyValuePair**)realloc(table->buckets, new_size * sizeof(KeyValuePair*));
    if (new_buckets == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    table->buckets = new_buckets;
    table->size = new_size;
}

// Circular buffer for complex numbers
typedef struct {
    double real;
    double imag;
} Complex;

typedef struct {
    int size;
    Complex* data;
} CircularBuffer;

CircularBuffer* allocate_circular_buffer(int initial_size) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    buffer->size = initial_size;
    buffer->data = (Complex*)malloc(initial_size * sizeof(Complex));
    return buffer;
}

void resize_circular_buffer(CircularBuffer* buffer, int new_size) {
    Complex* new_data = (Complex*)realloc(buffer->data, new_size * sizeof(Complex));
    if (new_data == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    buffer->data = new_data;
    buffer->size = new_size;
}

// Validate data integrity in the circular buffer
void validate_circular_buffer(CircularBuffer* buffer, double tolerance) {
    for (int i = 0; i < buffer->size; i++) {
        Complex current = buffer->data[i];
        for (int j = 0; j < buffer->size; j++) {
            if (i != j && fabs(current.real - buffer->data[j].real) <= tolerance &&
                fabs(current.imag - buffer->data[j].imag) <= tolerance) {
                printf("Data integrity violation detected!\n");
                exit(1);
            }
        }
    }
}

int main() {
    // Initialize data structures
    IntArray* int_array = allocate_int_array(10);
    HashTable* hash_table = allocate_hash_table(100);
    CircularBuffer* circular_buffer = allocate_circular_buffer(20);

    // Resize and manage memory allocation
    resize_int_array(int_array, 50);
    resize_hash_table(hash_table, 500);
    resize_circular_buffer(circular_buffer, 50);

    // Validate data integrity in the circular buffer
    validate_circular_buffer(circular_buffer, 1e-6);

    return 0;
}

