typedef struct {
    int x;
    int y;
} point;

typedef struct {
    double* data;
    size_t size;
    size_t capacity;
} vector;

void init_point(point* p, int x, int y) {
    p->x = x;
    p->y = y;
}

point* create_points(int n) {
    point* points = (point*)malloc(n * sizeof(point));
    for (int i = 0; i < n; i++) {
        init_point(&points[i], rand() % 100, rand() % 100);
    }
    return points;
}

void free_points(point* points) {
    free(points);
}

vector* create_vector(int capacity) {
    vector* v = (vector*)malloc(sizeof(vector));
    v->data = (double*)malloc(capacity * sizeof(double));
    v->size = 0;
    v->capacity = capacity;
    return v;
}

void push_vector(vector* v, double val) {
    if (v->size == v->capacity) {
        v->capacity *= 2;
        v->data = (double*)realloc(v->data, v->capacity * sizeof(double));
    }
    v->data[v->size] = val;
    v->size++;
}

void free_vector(vector* v) {
    free(v->data);
    free(v);
}

