    for (int i = 0; i < size; i++) {
        if (nicbs[i].tcp_header.rnti > max)
            max = nicbs[i].tcp_header.rnti;
    }
    printf("Largest RNTI: %d\n", max);
}

// Function to manage dynamic arrays for 'record' and NICB structures
void* dynamic_array_manager(int num_nicbs) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for NICB array
    NICB* nicbs = (NICB*)malloc(num_nicbs * sizeof(NICB));
    if (!nicbs) {
        printf("Memory allocation failure for NICBs.\n");
        return NULL;
