    size_t capacity;
    size_t size;
} Vector;

Vector* createVector(size_t capacity) {
    Vector* vec = (Vector*)malloc(sizeof(Vector));
    vec->values = (double*)malloc(capacity * sizeof(double));
    vec->capacity = capacity;
    vec->size = 0;
    return vec;
}

void freeVector(Vector* vec) {
    if (vec != NULL) {
        free(vec->values);
        free(vec);
    }
}

// Function to dynamically allocate memory and initialize data structures
int main() {
    // Define variables for data structure sizes
    size_t numPoints = 1000000;
    size_t numVectors = 10000;
    size_t vectorCapacity = 100;

    // Allocate arrays of double, char, and struct point objects
    double* doubles = (double*)malloc(numPoints * sizeof(double));
    char* chars = (char*)malloc(numPoints * sizeof(char));
    point* points = (point*)malloc(numPoints * sizeof(point));

    for (size_t i = 0; i < numPoints; i++) {
        // Initialize struct point objects
        points[i].x = rand() % 100;
        points[i].y = rand() % 100;

        // Populate arrays of double and char values
        doubles[i] = rand() / (double)RAND_MAX;
        chars[i] = 'a' + rand() % 26;
    }

    // Create vectors with initial capacity
    Vector* vectors = (Vector*)malloc(numVectors * sizeof(Vector));
    for (size_t i = 0; i < numVectors; i++) {
        vectors[i] = createVector(vectorCapacity);
    }

    // Log memory allocation failures and handle them gracefully
    if (doubles == NULL || chars == NULL || points == NULL) {
        printf("Memory allocation failed. Aborting...\n");
        exit(1);
    }

    for (size_t i = 0; i < numVectors; i++) {
        // Initialize vector values
        for (size_t j = 0; j < vectorCapacity; j++) {
            vectors[i]->values[j] = rand() / (double)RAND_MAX;
        }
    }

    // Free dynamically allocated memory
    free(doubles);
    free(chars);
    free(points);

    for (size_t i = 0; i < numVectors; i++) {
        freeVector(&vectors[i]);
    }
    free(vectors);

    return 0;
}
