        for (int i = 0; i < (record_size + 1); i++) {
            r->array[i] = rand() % 100;
        }

        // Sort the records based on their integer keys
        int compare(const void* a, const void* b) {
            record* ra = (record*)a;
            record* rb = (record*)b;

            if (ra->array[0] > rb->array[0]) return 1;
            else if (ra->array[0] < rb->array[0]) return -1;
            else return 0;
        }

        qsort(records, record_size + 1, sizeof(record), compare);

        // Increase the array sizes
        nfaapi_size++;
        record_size++;
    }
