#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a custom network protocol header
typedef struct {
    char src_ip[16];  // Source IP address
    char dst_ip[16];  // Destination IP address
    int src_port;      // Source port number
    int dst_port;      // Destination port number
    uint8_t flags;     // Randomly generated TCP flags field
} net_header_t;

// Define the dynamic array structure for managing network protocol headers
typedef struct {
    size_t size;
    size_t capacity;
    net_header_t* data;
    pthread_mutex_t mutex;
} net_headers_t;

// Create a new dynamic array to manage network protocol headers
net_headers_t* net_headers_create() {
    net_headers_t* headers = malloc(sizeof(net_headers_t));
    if (!headers) return NULL;

    headers->size = 0;
    headers->capacity = 16; // Initial capacity
    headers->data = calloc(headers->capacity, sizeof(net_header_t));
    if (!headers->data) {
        free(headers);
        return NULL;
    }

    pthread_mutex_init(&headers->mutex, NULL);

    return headers;
}

// Add a new network protocol header to the dynamic array
int net_headers_add(net_headers_t* headers, net_header_t* header) {
    if (pthread_mutex_lock(&headers->mutex)) return -1; // Lock failed

    if (headers->size >= headers->capacity) {
        size_t new_capacity = headers->capacity * 2;
        net_header_t* new_data = realloc(headers->data, new_capacity * sizeof(net_header_t));
        if (!new_data) {
            pthread_mutex_unlock(&headers->mutex);
            return -1; // Memory allocation failed
        }
        headers->data = new_data;
        headers->capacity = new_capacity;
    }

    memcpy(headers->data + headers->size, header, sizeof(net_header_t));
    headers->size++;

    pthread_mutex_unlock(&headers->mutex);

    return 0; // Success
}

// Remove a network protocol header from the dynamic array by index
int net_headers_remove_at_index(net_headers_t* headers, int index) {
    if (pthread_mutex_lock(&headers->mutex)) return -1; // Lock failed

    if (index < 0 || index >= headers->size) {
        pthread_mutex_unlock(&headers->mutex);
        return -1; // Invalid index
    }

    memmove(headers->data + index, headers->data + index + 1, sizeof(net_header_t) * (headers->size - index - 1));
    headers->size--;

    if (headers->size < headers->capacity / 2) {
        size_t new_capacity = headers->capacity / 2;
        net_header_t* new_data = realloc(headers->data, new_capacity * sizeof(net_header_t));
        if (!new_data) {
            pthread_mutex_unlock(&headers->mutex);
            return -1; // Memory allocation failed
        }
        headers->data = new_data;
        headers->capacity = new_capacity;
    }

    pthread_mutex_unlock(&headers->mutex);

    return 0; // Success
}

// Retrieve a network protocol header from the dynamic array by index
net_header_t* net_headers_get_at_index(net_headers_t* headers, int index) {
    if (pthread_mutex_lock(&headers->mutex)) return NULL; // Lock failed

    if (index < 0 || index >= headers->size) {
        pthread_mutex_unlock(&headers->mutex);
        return NULL; // Invalid index
    }

    net_header_t* header = &headers->data[index];

    pthread_mutex_unlock(&headers->mutex);

    return header;
}

// Destroy the dynamic array and its contents
void net_headers_destroy(net_headers_t* headers) {
    if (headers) {
        free(headers->data);
        free(headers);
    }
}
