#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HASH_TABLE_SIZE 1024
#define MAX_KEY_LENGTH 256
#define MAX_VALUE_LENGTH 128

typedef struct {
    char key[MAX_KEY_LENGTH];
    int value;
} KeyValuePair;

typedef struct {
    KeyValuePair* table;
    int size;
    int capacity;
    pthread_mutex_t lock;
} DynamicHashTable;

void* hash_table_init(int initial_size) {
    DynamicHashTable* hash_table = (DynamicHashTable*)malloc(sizeof(DynamicHashTable));

    if (!hash_table)
        return NULL;

    hash_table->table = (KeyValuePair*)malloc(initial_size * sizeof(KeyValuePair));

    if (!hash_table->table) {
        free(hash_table);
        return NULL;
    }

    hash_table->size = 0;
    hash_table->capacity = initial_size;

    pthread_mutex_init(&hash_table->lock, NULL);

    return (void*)hash_table;
}

int hash_function(const char* key, int capacity) {
    unsigned long hash = 5381;
    const unsigned char* p = (const unsigned char*)key;

    while (*p) {
        hash = ((hash << 5) + *p) ^ (hash >> 27);
        p++;
    }

    return hash % capacity;
}

int insert_key_value_pair(void* hash_table, const char* key, int value) {
    DynamicHashTable* table = (DynamicHashTable*)hash_table;
    pthread_mutex_lock(&table->lock);

    if (!key || strlen(key) > MAX_KEY_LENGTH)
        goto error;

    int index = hash_function(key, table->capacity);

    for (int i = 0; i < table->capacity; i++) {
        if (!table->table[index].key[0]) {
            strcpy(table->table[index].key, key);
            table->table[index].value = value;
            table->size++;
            pthread_mutex_unlock(&table->lock);
            return 1;
        }

        index = (index + 1) % table->capacity;
    }

error:
    pthread_mutex_unlock(&table->lock);
    return -1;
}

int delete_key_value_pair(void* hash_table, const char* key) {
    DynamicHashTable* table = (DynamicHashTable*)hash_table;
    pthread_mutex_lock(&table->lock);

    if (!key || strlen(key) > MAX_KEY_LENGTH)
        goto error;

    int index = hash_function(key, table->capacity);

    for (int i = 0; i < table->capacity; i++) {
        if (!strcmp(table->table[index].key, key)) {
            strcpy(table->table[index].key, "");
            table->table[index].value = 0;
            table->size--;
            pthread_mutex_unlock(&table->lock);
            return 1;
        }

        index = (index + 1) % table->capacity;
    }

error:
    pthread_mutex_unlock(&table->lock);
    return -1;
}

int iterate_over_key_value_pairs(void* hash_table, void (*callback)(const char*, int)) {
    DynamicHashTable* table = (DynamicHashTable*)hash_table;
    pthread_mutex_lock(&table->lock);

    for (int i = 0; i < table->capacity; i++) {
        if (!table->table[i].key[0])
            continue;

        callback(table->table[i].key, table->table[i].value);
    }

    pthread_mutex_unlock(&table->lock);
}

void hash_table_free(void* hash_table) {
    DynamicHashTable* table = (DynamicHashTable*)hash_table;
    pthread_mutex_lock(&table->lock);

    free(table->table);
    pthread_mutex_unlock(&table->lock);
}
