#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct for log_entry
typedef struct {
    int id;
    double timestamp;
    char message[256];
} LogEntry;

// Define a struct for log_entry buffer
typedef struct {
    size_t capacity;
    size_t size;
    LogEntry* entries;
} LogBuffer;

// Function to initialize and manage the logging system
void initLoggingSystem(int growthThreshold, int numThreads) {
    // Initialize integer buffer sizes
    size_t intBufSize = 1024;
    size_t* intBuf = (size_t*)malloc(intBufSize * sizeof(size_t));

    // Initialize double precision timestamps
    size_t timestampBufSize = 1024;
    double* timestamps = (double*)malloc(timestampBufSize * sizeof(double));

    // Initialize log_entry structures
    size_t logEntryBufSize = 1024;
    LogEntry* logEntries = (LogEntry*)malloc(logEntryBufSize * sizeof(LogEntry));

    // Initialize log_buffer
    LogBuffer* logBuffer = (LogBuffer*)malloc(sizeof(LogBuffer));
    logBuffer->capacity = intBufSize;
    logBuffer->size = 0;
    logBuffer->entries = logEntries;

    // Resize buffers dynamically based on user-defined growth threshold
    for(int i = 0; i < numThreads; i++) {
        while(logBuffer->size >= (logBuffer->capacity - growthThreshold)) {
            logBuffer->capacity *= 2;
            logEntryBufSize *= 2;
            intBufSize *= 2;
            timestamps = realloc(timestamps, timestampBufSize * sizeof(double));
            intBuf = realloc(intBuf, intBufSize * sizeof(size_t));
