typedef struct {
    int offset;
    int key;
    char* state_description;
} Record;

Record* create_records(int num_records, int max_offset) {
    if (num_records <= 0) return NULL;

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = i;
        records[i].key = rand() % 1000; // Random integer between 0 and 999
        char buffer[20];
        sprintf(buffer, "Initialization process for record %d", i);
        records[i].state_description = (char*)malloc(strlen(buffer) + 1);
        strcpy(records[i].state_description, buffer);

        if (!records[i].state_description) {
            free(records[i].state_description);
            for (int j = 0; j < i; ++j) {
                free(records[j].state_description);
            }
            free(records);
            return NULL;
        }
    }

    // Validate that no two records have the same key
    for (int i = 0; i < num_records - 1; ++i) {
        for (int j = i + 1; j < num_records; ++j) {
            if (records[i].key == records[j].key) {
                free(records[i].state_description);
                for (int k = 0; k <= i; ++k) {
                    free(records[k].state_description);
                }
                free(records);
                return NULL;
            }
        }
    }

    return records;
}

void destroy_records(Record* records, int num_records) {
    if (!records) return;

    for (int i = 0; i < num_records; ++i) {
        free(records[i].state_description);
    }

    free(records);
}
