// Function to initialize and manage a dynamic collection of records
record **initialize_collection(int capacity) {
    // Initialize pointers for the start and end indices
    record **start = (record **)malloc(capacity * sizeof(record *));
    record **end = start + capacity - 1;

    int total_records = 0;
    int current_capacity = capacity;

    // Function to dynamically resize the collection if necessary
    void *resize(int new_capacity) {
        record **new_start = (record **)realloc(start, new_capacity * sizeof(record *));
        for (int i = 0; i < new_capacity; i++) {
            start[i] = new_start + i;
        }
        end = new_start + new_capacity - 1;
        current_capacity = new_capacity;
    }

    // Function to handle memory allocation and deallocation
    int allocate_record() {
        if (total_records == current_capacity) {
            resize(current_capacity * 2);
        }
        return total_records++;
    }

    // Initialize the collection with a predefined capacity
    for (int i = 0; i < capacity; i++) {
        start[i] = NULL;
    }

    return start;
}

// Function to iterate over records and print their contents
void print_collection(record **start, record **end) {
    int i;
    for (record **p = start; p <= end; p++) {
        if (*p != NULL) {
            printf("Offset: %ld\nKey: %d\nString: %s\n", (*p)->offset, (*p)->key, (*p)->str);
        }
    }
}

