    srand(time(NULL));
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int retries = 0;
    clock_t start_time = clock();
    for(int i=0; i<M && i<N; i++) {
        NFAPI_CRC_INDICATION_PDU_T new_pdu;
        do {
            new_pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
            new_pdu.RNTI = rand() % 100000;
            new_pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
            new_pdu.CRCFLAG = rand() % 2;
        } while(existsInList(*list, i, &new_pdu));
        usleep(50000);
        retries++;
    }
    printf("Total time taken: %.3f seconds\n", (double)(clock()-start_time)/CLOCKS_PER_SEC);
    printf("Number of retries: %d\n", retries);
}

int existsInList(NFAPI_CRC_INDICATION_PDU_T *list, int index, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
