    srand(time(NULL));

    // Allocate arrays
    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) return; // Handle allocation failure

    // Initialize arrays
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % 100;
        offsets[i] = (long)i;

        records[i].value = rand() % 100;

        if (records[i].value > threshold) {
            // Store record in sorted array
            int j = i - 1;
            while (j >= 0 && records[j].value < records[i].value) {
                records[j + 1] = records[j];
                j--;
            }
            records[j + 1] = records[i];
        }
    }

    // Free allocated memory
    free(records);
}
