#include <iostream>
#include <list>
#include <string>
#include <map>
#include <mutex>

class TransactionRecord {
public:
    int transactionID;
    std::string timestamp;
    std::string accountDetails;
    double transactionAmount;

    TransactionRecord(int id, const std::string& ts, const std::string& ad, double amount) 
        : transactionID(id), timestamp(ts), accountDetails(ad), transactionAmount(amount) {}
};

class TransactionManager {
public:
    // Data structure to manage transactions
    std::list<TransactionRecord> transactions;

    // Map to store account information (load from external data source)
    std::map<int, std::string> accounts;

    // Mutex for synchronization
    std::mutex mtx;

    void addTransaction(int transactionID, const std::string& timestamp, 
                          const std::string& accountDetails, double transactionAmount) {
        // Validate transaction data
        if (transactionID < 0 || !timestamp.empty() && !accountDetails.empty() || transactionAmount <= 0.0) return;

        // Lock for thread safety
        std::lock_guard<std::mutex> lock(mtx);

        // Create and add new transaction record
        TransactionRecord transaction(transactionID, timestamp, accountDetails, transactionAmount);
        transactions.push_back(transaction);
    }

    void removeTransaction(int transactionID) {
        // Lock for thread safety
        std::lock_guard<std::mutex> lock(mtx);

        auto it = transactions.begin();
        while (it != transactions.end()) {
            if (it->transactionID == transactionID) {
                transactions.erase(it);
                return;
            }
            it++;
        }
    }

    TransactionRecord* getTransaction(int transactionID) {
        // Lock for thread safety
        std::lock_guard<std::mutex> lock(mtx);

        auto it = transactions.begin();
        while (it != transactions.end()) {
            if (it->transactionID == transactionID) return &(*it);
            it++;
        }
        return nullptr;
    }
};

