// Define a structure for media file descriptors
typedef struct {
    char* mime_type;
    int duration;
    char* encoding_format;
    char* checksum;
} MediaFileDescriptor;

// Define a structure for the dynamic list of media file descriptors
typedef struct {
    MediaFileDescriptor* descriptors;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

// Function to create a new dynamic list
DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->descriptors = (MediaFileDescriptor*)calloc(initial_capacity, sizeof(MediaFileDescriptor));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to free a dynamic list
void dynamic_list_free(DynamicList* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->descriptors[i].mime_type);
        free(list->descriptors[i].encoding_format);
        free(list->descriptors[i].checksum);
    }
    free(list->descriptors);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Function to add a new media file descriptor to the dynamic list
void dynamic_list_add(DynamicList* list, MediaFileDescriptor* descriptor) {
    if (list->size == list->capacity) {
        // Reallocate memory for descriptors and increase capacity
        list->descriptors = (MediaFileDescriptor*)realloc(list->descriptors, sizeof(MediaFileDescriptor) * (list->capacity * 2));
        list->capacity *= 2;
    }
    pthread_mutex_lock(&list->mutex);
    list->descriptors[list->size] = *descriptor;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a media file descriptor from the dynamic list by index
void dynamic_list_remove(DynamicList* list, int index) {
    if (index >= 0 && index < list->size) {
        pthread_mutex_lock(&list->mutex);
        // Shift descriptors after the removed one to fill the gap
        memmove(&list->descriptors[index], &list->descriptors[index + 1], sizeof(MediaFileDescriptor) * (list->size - index - 1));
        list->size--;
        pthread_mutex_unlock(&list->mutex);
    }
}

// Function to retrieve a media file descriptor from the dynamic list by index
MediaFileDescriptor* dynamic_list_get(DynamicList* list, int index) {
    if (index >= 0 && index < list->size) {
        return &list->descriptors[index];
    } else {
        return NULL;
    }
}

