void manage_memory(int *offsets, int *keys, int num_records, float probability_threshold) {
    // Calculate the actual number of records based on the smaller size of the two arrays
    int actual_num_records = (num_records > 500 ? 500 : (num_records > 1000 ? 1000 : num_records));

    // Allocate memory for the record structures within a single block
    struct record *records = malloc(actual_num_records * sizeof(struct record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed. Cleaning up previous allocations.\n");
        return;
    }

    // Initialize records with valid data
    for (int i = 0; i < actual_num_records; i++) {
        records[i].key = i % 500;
        records[i].offset = (long) rand() * (1000000 - 1 + 1);
    }

    // Select a random subset of records based on the provided probability threshold
    srand(time(NULL));
    int selected_records = 0;
    for (int i = 0; i < actual_num_records; i++) {
        if ((float) rand() / RAND_MAX <= probability_threshold) {
            selected_records++;
        }
    }

    // Handle dynamic updates to the input arrays
    while (1) {
        int update_offset = rand() % 100;
        int update_key = rand() % 500;

        // Update the records array if the update is valid
        if (update_offset < actual_num_records && update_key < 500) {
            records[update_offset].key = update_key;
        }

        // Clean up any deallocated memory blocks
        free(records);
        records = malloc(actual_num_records * sizeof(struct record));
        if (!records) {
            fprintf(stderr, "Memory allocation failed. Cleaning up previous allocations.\n");
            return;
        }
    }

    // Deallocate the records array to prevent memory leaks
    free(records);

    printf("Selected %d records with probability threshold %.2f\n", selected_records, probability_threshold);
}

int main() {
    int offsets[1000], keys[500];
    manage_memory(offsets, keys, 1000, 0.5f);
    return 0;
