class DynamicValueGenerator {
public:
    DynamicValueGenerator(double min, double max) : min_(min), max_(max) {}

    double generateFloat() {
        return (rand() / static_cast<double>(RAND_MAX)) * (max_ - min_) + min_;
    }

    int generateInt() {
        return rand() % (int)(max_ - min_) + (int)min_;
    }

private:
    double min_, max_;
};

class DynamicConfigurationManager {
public:
    void configure(const std::string& filename) {
        json j = json::parse(filename);
        if (!j.is_object()) {
            throw std::runtime_error("Invalid JSON file");
        }
        for (const auto& [key, value] : j.items()) {
            config_.insert({ key, value });
        }
    }

    void validate() {
        // Implement validation logic here
    }

    void persist(const std::string& filename) {
        json j;
        for (const auto& [key, value] : config_) {
            j[key] = value;
        }
        std::ofstream os(filename);
        if (!os.is_open()) {
            throw std::runtime_error("Failed to open file");
        }
        os << j.dump();
    }

private:
    std::map<std::string, json> config_;
};

int main() {
    DynamicConfigurationManager cfgMgr;
    try {
        cfgMgr.configure("config.json");
        cfgMgr.validate();
        cfgMgr.persist("persisted_config.json");
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
