typedef struct {
    double value;
    uint64_t id;
    time_t timestamp;
    int quality;
} SensorReading;

SensorReading* handleDynamicSensorDataAndTestModule() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    size_t allocated_size = MIN_SIZE;
    SensorReading** data = (SensorReading**)malloc(allocated_size * sizeof(SensorReading*));

    for(size_t i = 0; i < allocated_size; i++) {
        data[i] = (SensorReading*)malloc(sizeof(SensorReading));
        data[i]->value = (double)rand() / RAND_MAX;
        data[i]->id = (uint64_t)rand();
        data[i]->timestamp = time(NULL);
        data[i]->quality = rand() % 2;
    }

    size_t current_size = allocated_size;

    while(1) {
        pthread_mutex_lock(&lock);

        if(current_size * sizeof(SensorReading*) > ((size_t)malloc_usable_space())) {
            allocated_size *= 2;
            SensorReading** newData = (SensorReading**)realloc(data, allocated_size * sizeof(SensorReading*));
            data = newData;

            for(size_t i = current_size; i < allocated_size; i++) {
                data[i] = (SensorReading*)malloc(sizeof(SensorReading));
                data[i]->value = (double)rand() / RAND_MAX;
                data[i]->id = (uint64_t)rand();
                data[i]->timestamp = time(NULL);
                data[i]->quality = rand() % 2;
            }
        }

        pthread_mutex_unlock(&lock);

        if(current_size > THRESHOLD * allocated_size) {
            pthread_cond_signal(&cond);
            current_size = 0;
        } else {
            current_size++;
        }
    }
}
