// Timestamp management system
typedef struct {
    uint64_t timestamp;
    char* message;
} Event;

// Thread-safe linked list of events
typedef struct {
    Event* event;
    struct Node* next;
} Node;

void event_list_init(Node** head) {
    *head = NULL;
}

int event_list_add(Event* new_event, Node** head) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failed

    new_node->event = new_event;
    new_node->next = *head;
    *head = &new_node;

    return 0;
}

// Validate event timestamps
int validate_timestamps(Event* events, size_t count, uint64_t window_size) {
    uint64_t prev_timestamp = events[0].timestamp;
    for (size_t i = 1; i < count; i++) {
        if (events[i].timestamp - prev_timestamp <= window_size)
            return -1; // Duplicate timestamp found
        prev_timestamp = events[i].timestamp;
    }

    return 0; // No duplicate timestamps found
}

int main() {
