typedef struct {
    int packet_id;
    char source_ip[16];
    char destination_ip[16];
    uint16_t port_number;
    char protocol_type[8];
} DATA_PACKET;

typedef struct {
    int queue_id;
    int sequence_number;
    unsigned char* payload;
} TRANSMISSION_QUEUE;

DATA_PACKET* data_packets = NULL;
size_t data_packets_capacity = 0;
size_t data_packets_size = 0;

TRANSMISSION_QUEUE* transmission_queue = NULL;
size_t transmission_queue_capacity = 0;
size_t transmission_queue_size = 0;

pthread_mutex_t packet_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

void init_data_packet_array() {
    data_packets = (DATA_PACKET*)malloc(MAX_PACKETS * sizeof(DATA_PACKET));
    if (!data_packets) {
        LOG_ERROR("Failed to allocate memory for DATA_PACKET array");
        exit(EXIT_FAILURE);
    }
    data_packets_capacity = MAX_PACKETS;
    data_packets_size = 0;
}

void init_transmission_queue() {
    transmission_queue = (TRANSMISSION_QUEUE*)malloc(MAX_PACKETS * sizeof(TRANSMISSION_QUEUE));
    if (!transmission_queue) {
        LOG_ERROR("Failed to allocate memory for TRANSMISSION_QUEUE array");
        exit(EXIT_FAILURE);
    }
    transmission_queue_capacity = MAX_PACKETS;
    transmission_queue_size = 0;
}

void packet_array_resize(size_t new_size) {
    DATA_PACKET* new_packets = (DATA_PACKET*)realloc(data_packets, new_size * sizeof(DATA_PACKET));
    if (!new_packets) {
        LOG_ERROR("Failed to resize memory for DATA_PACKET array");
        exit(EXIT_FAILURE);
    }
    data_packets = new_packets;
    data_packets_capacity = new_size;
}

void transmission_queue_resize(size_t new_size) {
    TRANSMISSION_QUEUE* new_queue = (TRANSMISSION_QUEUE*)realloc(transmission_queue, new_size * sizeof(TRANSMISSION_QUEUE));
    if (!new_queue) {
        LOG_ERROR("Failed to resize memory for TRANSMISSION_QUEUE array");
        exit(EXIT_FAILURE);
    }
    transmission_queue = new_queue;
    transmission_queue_capacity = new_size;
}

int add_packet(int packet_id, char* source_ip, char* destination_ip, uint16_t port_number, char* protocol_type) {
    pthread_mutex_lock(&packet_lock);

    if (data_packets_size == data_packets_capacity) {
        packet_array_resize(data_packets_capacity * 2);
    }

    DATA_PACKET* new_packet = &data_packets[data_packets_size];
    new_packet->packet_id = packet_id;
    strcpy(new_packet->source_ip, source_ip);
    strcpy(new_packet->destination_ip, destination_ip);
    new_packet->port_number = port_number;
    strcpy(new_packet->protocol_type, protocol_type);

    data_packets_size++;
    pthread_mutex_unlock(&packet_lock);

    return 0;
}

int add_to_transmission_queue(int queue_id, int sequence_number) {
    pthread_mutex_lock(&queue_lock);

    if (transmission_queue_size == transmission_queue_capacity) {
        transmission_queue_resize(transmission_queue_capacity * 2);
    }

    TRANSMISSION_QUEUE* new_entry = &transmission_queue[transmission_queue_size];
    new_entry->queue_id = queue_id;
    new_entry->sequence_number = sequence_number;

    // Dynamically allocate payload data
    new_entry->payload = (unsigned char*)malloc(PAYLOAD_DEFAULT_SIZE);
    if (!new_entry->payload) {
        LOG_ERROR("Failed to allocate memory for payload");
        exit(EXIT_FAILURE);
    }

    transmission_queue_size++;
    pthread_mutex_unlock(&queue_lock);

    return 0;
}

int validate_packet_array() {
    int duplicate_found = 0;

    pthread_mutex_lock(&packet_lock);

    for (size_t i = 0; i < data_packets_size; i++) {
        for (size_t j = i + 1; j < data_packets_size; j++) {
            if (data_packets[i].packet_id == data_packets[j].packet_id) {
                duplicate_found = 1;
                break;
            }
        }

        if (duplicate_found)
            break;
    }

    pthread_mutex_unlock(&packet_lock);

    return duplicate_found;
}

void cleanup_unused_structures() {
    // Implement logic to periodically clean up unused structures based on age
}

int main() {
    init_data_packet_array();
    init_transmission_queue();

    // Fetch updated network status information from an external API
    // ...

    while (1) {
        // Perform data operations and memory management

        if (validate_packet_array()) {
            LOG_ERROR("Duplicate packet ID found");
            exit(EXIT_FAILURE);
        }

        cleanup_unused_structures();
    }

    return 0;
}
