} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage memory allocation and initialization
void* manage_memory(int N) {
    // Initialize timestamp array with N elements
    double* sensor_readings = (double*)malloc(N * sizeof(double));

    // Initialize linked list of event structures
    struct event_node* head = NULL;
    for (int i = 0; i < N; i++) {
        struct event* event = (struct event*)malloc(sizeof(struct event));
        event->timestamp = time(NULL);
        // Set CRCFLAG to random value
        event->CRCFLAG = rand();
        // Initialize CRC_INDICATION_REL8_TAG with a valid value
        event->CRC_INDICATION_REL8_TAG = i;
        // Add event node to the linked list
        add_event(&head, event);
    }

    // Initialize array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = i;
        crc_indications[i].RNTI = i;
        crc_indications[i].CRC_INDICATION_REL8_TAG = i;
        // Set CRCFLAG to random value
        crc_indications[i].CRCFLAG = rand();
    }

    return (void*)sensor_readings;
}

// Helper function to add an event node to the linked list
void add_event(struct event_node** head, struct event* event) {
    if (*head == NULL) {
        *head = event;
    } else {
        struct event_node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = event;
    }
}
