    // Allocate memory for the offset array
    long* offsets = (long*)malloc(n_offsets * sizeof(long));

    // Check if allocation was successful
    if (offsets == NULL) {
        printf("Error allocating memory for offsets\n");
        return;
    }

    // Initialize the offset values randomly between 0 and max_value
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < n_offsets; i++) {
        offsets[i] = rand() % (max_value + 1);
    }

    // Calculate the total size of memory allocations so far
    size_t total_size = sizeof(long) * n_offsets;

    // Allocate memory for the key array
    int* keys = (int*)malloc(n_keys * sizeof(int));

    // Check if allocation was successful
    if (keys == NULL) {
        printf("Error allocating memory for keys\n");
        free(offsets); // Free previously allocated memory to prevent leaks
        return;
    }

    // Initialize the key values randomly between 0 and max_value
    for (int i = 0; i < n_keys; i++) {
        keys[i] = rand() % (max_value + 1);
    }

    // Update total size of memory allocations
    total_size += sizeof(int) * n_keys;

    // Calculate the number of records based on offset and key array lengths
    int n_records = n_offsets + n_keys;

    // Allocate memory for the record array
    record* records = (record*)malloc(n_records * sizeof(record));

    // Check if allocation was successful
    if (records == NULL) {
        printf("Error allocating memory for records\n");
        free(offsets); // Free previously allocated memory to prevent leaks
        free(keys); // Free previously allocated memory to prevent leaks
        return;
    }

    // Initialize the record values randomly between 0 and max_value
    for (int i = 0; i < n_records; i++) {
        records[i].value = rand() % (max_value + 1);
    }

    // Validate that total size of memory allocations does not exceed system limit
    const size_t SYSTEM_LIMIT = 1024 * 1024 * 64; // 64 MB for example
    if (total_size > SYSTEM_LIMIT) {
        printf("Total size of memory allocations exceeds the system limit\n");
        free(offsets); // Free previously allocated memory to prevent leaks
        free(keys); // Free previously allocated memory to prevent leaks
        free(records);
        return;
    }

    // Perform additional validation checks here if needed

    // Release all allocated memory when no longer needed
    free(offsets);
    free(keys);
    free(records);
}
