        array = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

        if (!array) {
            printf("Second memory allocation attempt also failed. Returning NULL.\n");
