        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = i * 2;
        array[i].CRC_INDICATION_REL8_TAG = i * 3;

        // Randomly set CRCFLAG. If random number generation fails, default to a specific value.
        int crcFlag = rand() % 2;
        if (crcFlag < 0 || crcFlag > 1) {
            printf("Random number generator failed. Defaulting CRCFLAG to 0.\n");
