void *logger = NULL;

// Function to initialize the list and memory pool
int init_nfapis() {
    int i;
    for (i = 0; i < MAX_NFAPIS; i++) {
        nfap_list[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfap_list[i]) return -1;
    }
    sem_init(&semaphore, 0, 1);
    pthread_mutex_init(&mutex, NULL);
    return 0;
}

// Function to add a new NFAPI structure
int add_nfapi(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&mutex);
    if (nfapi_count >= MAX_NFAPIS) {
        // Log error and reuse first available slot for duplicate RNTI
        logger("Error: Duplicate RNTI detected. Reusing first available slot.");
        for (int i = 0; i < nfapi_count; i++) {
            if (!nfap_list[i]->RNTI) {
                nfap_list[i]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
                nfap_list[i]->RNTI = RNTI;
                nfap_list[i]->CRC_INDICATION_REL8_TAG = rand();
                nfap_list[i]->CRCFLAG = (rand() % 2);
                break;
            }
        }
    } else {
        if (nfapi_count == 0) {
            // Initialize first NFAPI structure
            nfap_list[nfapi_count]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            nfap_list[nfapi_count]->RNTI = RNTI;
            nfap_list[nfapi_count]->CRC_INDICATION_REL8_TAG = rand();
            nfap_list[nfapi_count]->CRCFLAG = (rand() % 2);
        } else {
            // Check for duplicate RNTI
            bool found = false;
            for (int i = 0; i < nfapi_count; i++) {
                if (nfap_list[i]->RNTI == RNTI) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                // Add new NFAPI structure
                nfap_list[nfapi_count]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
                nfap_list[nfapi_count]->RNTI = RNTI;
                nfap_list[nfapi_count]->CRC_INDICATION_REL8_TAG = rand();
                nfap_list[nfapi_count]->CRCFLAG = (rand() % 2);
            }
        }
    }
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to cleanup unused NFAPI structures
void cleanup_nfapis() {
    int i, j;
    pthread_mutex_lock(&mutex);
    for (i = 0; i < nfapi_count; i++) {
        if (!nfap_list[i]->RNTI) {
            // Reuse first available slot
            for (j = i + 1; j < nfapi_count; j++) {
                if (!nfap_list[j]->RNTI) {
                    int temp = nfap_list[i]->RX_UE_INFORMATION_TAG;
                    nfap_list[i]->RX_UE_INFORMATION_TAG = nfap_list[j]->RX_UE_INFORMATION_TAG;
                    nfap_list[j]->RX_UE_INFORMATION_TAG = temp;
                    break;
                }
            }
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to monitor list health and trigger fallback
void monitor_nfapis() {
    int i, count_invalid = 0;
    pthread_mutex_lock(&mutex);
    for (i = 0; i < nfapi_count; i++) {
        if (!nfap_list[i]->RNTI) count_invalid++;
    }
    pthread_mutex_unlock(&mutex);
    if (count_invalid > INVALID_RNTI_THRESHOLD) {
        // Trigger fallback procedure
    }
}

// Function to handle cleanup failures and trigger timeout
