// Custom hash function to generate unique IDs and keys
unsigned int custom_hash(unsigned long seed, const char* input) {
    unsigned int result = 0;
    while (*input != '\0') {
        result = (result * 31 + *input) % 100000;
        input++;
    }
    return (seed + result) % 1000000;
}

// Record structure
typedef struct {
    long timestamp_id;
    int record_key;
    double metric_value;
} record_t;

// Memory allocation and initialization function
int manage_records(int num_records, unsigned long seed) {
    // Allocate memory for IDs, keys, and records
    long* ids = (long*)malloc(num_records * sizeof(long));
    if (!ids) return -1;  // Memory allocation failed

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(ids);
        return -2;  // Memory allocation failed
    }

    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        free(ids);
        free(keys);
        return -3;  // Memory allocation failed
    }

    // Initialize IDs and keys using custom hash function
    for (int i = 0; i < num_records; i++) {
        ids[i] = custom_hash(seed, "record_id");
        int key;
        do {
            key = custom_hash(seed, "record_key");
        } while (keys[key % num_records] != 0);  // Ensure uniqueness
        keys[keys[key % num_records]++] = i;
    }

    // Initialize records with random metric values
    srand(time(NULL));  // Seed for thread-safe random number generation
    for (int i = 0; i < num_records; i++) {
        records[i].timestamp_id = ids[i];
        records[i].record_key = keys[i];
        records[i].metric_value = (double)rand() / RAND_MAX;
    }

    // Validate and clean up any failed allocations
    if (!validate_keys(keys, num_records)) return -4;  // Key validation failed

    free(ids);
    free(keys);

    return 0;  // Successful memory allocation and initialization
}

// Validate that all keys are within the valid range and unique
int validate_keys(int* keys, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (keys[i] >= 100 || keys[i] < 0) return -1;  // Key out of range
        for (int j = 0; j < i; j++) {
            if (keys[j] == keys[i]) return -2;  // Duplicate key found
        }
    }
    return 0;  // All keys are within the valid range and unique
}
