    void* mem_pool = malloc(1024 * 1024);
    char* ptr = (char*)mem_pool;

    srand(time(NULL)); // Seed random number generator

    struct record {
        int key;
        long offset[1000];
        int values[1000];
    };

    int num_records = rand() % 100 + 1; // Randomly generate number of records
    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));

    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 10000; // Randomly generate key value

        // Initialize arrays for each record
        for (int j = 0; j < 1000; j++) {
            records[i].offset[j] = (long)(rand() % 100000); // Randomly generate offset value
            records[i].values[j] = rand() % 256; // Randomly generate value
        }
    }

    // Sort records by key
    qsort(records, num_records, sizeof(struct record), compare);

    // Release memory pool
    free(mem_pool);
}

int compare(const void* a, const void* b) {
    struct record* rec_a = (struct record*)a;
    struct record* rec_b = (struct record*)b;

    if (rec_a->key < rec_b->key)
        return -1;
    else if (rec_a->key > rec_b->key)
        return 1;
    else
        return 0;
}

