#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    int RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* nfa_list = NULL;
int list_size = 0;

void init_crc_indication_list() {
    pthread_mutex_init(&list_lock, NULL);
}

int add_crc_indication_to_list(NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&list_lock);

    if (new_entry == NULL || new_entry->RNTI <= 0) {
        pthread_mutex_unlock(&list_lock);
        return -1; // invalid entry
    }

    for (int i = 0; i < list_size; i++) {
        if (nfa_list[i].RNTI == new_entry->RNTI) {
            // RNTI already exists in the list, reuse the first available slot
            int reused_slot = -1;
            for (int j = 0; j < list_size; j++) {
                if (nfa_list[j].RNTI <= 0) {
                    reused_slot = j;
                    break;
                }
            }
            if (reused_slot >= 0) {
                new_entry->RNTI = nfa_list[reused_slot].RNTI;
                memmove(&nfa_list[reused_slot], &nfa_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                i--;
            }
        }
    }

    if (list_size >= (int)sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1000) {
        // list is full, consider cleaning up unused entries
        int count = 0;
        for (int i = 0; i < list_size; i++) {
            if (nfa_list[i].RNTI <= 0) {
                count++;
            } else {
                memmove(&nfa_list[i], &nfa_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_size - i - 1));
                list_size--;
                i--;
            }
        }
    }

    if (list_size < (int)sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // allocate new space
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(nfa_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 2);
        if (temp == NULL) {
            pthread_mutex_unlock(&list_lock);
            return -1; // memory allocation failed
        }
        nfa_list = temp;
    }

    nfa_list[list_size++] = *new_entry;

    pthread_mutex_unlock(&list_lock);
    return 0;
}

int main() {
    init_crc_indication_list();

    // add some sample entries
    NFAPI_CRC_INDICATION_PDU_T entry1 = {(uint8_t)0x01, 10, (uint16_t)0x1234, (uint8_t)0x02};
    NFAPI_CRC_INDICATION_PDU_T entry2 = {(uint8_t)0x02, 20, (uint16_t)0x5678, (uint8_t)0x03};
    int result1 = add_crc_indication_to_list(&entry1);
    int result2 = add_crc_indication_to_list(&entry2);

    return 0;
}
