typedef struct {
    int value;
    long offset;
} record;

record* init_dataset(int size) {
    record* dataset = (record*)malloc(size * sizeof(record));
    for (int i = 0; i < size; i++) {
        dataset[i].value = rand() % 100;
        dataset[i].offset = -1; // Initialize with invalid offset
    }
    return dataset;
}

void setup_hash_table(record* dataset, int size) {
    long* hash_keys = (long*)malloc(size * sizeof(long));
    for (int i = 0; i < size; i++) {
        // Simple custom hashing algorithm
        long key = (dataset[i].value + i) % size;
        if (hash_keys[key] != -1) {
            // Collision resolution: double hash the value
            key = (key * 1103515245 + dataset[i].value) % size;
        }
        hash_keys[key] = dataset[i].offset;
    }
}

void* resize_dataset(record** dataset, int old_size, int new_size) {
    if (new_size < old_size) {
        // Free excess memory
        for (int i = 0; i < old_size - (new_size - old_size); i++) {
            free(&((*dataset)[i]));
        }
    } else if (old_size > new_size) {
        // Reallocate and copy data to new array
        *dataset = realloc(*dataset, new_size * sizeof(record));
        for (int i = 0; i < old_size - (new_size - old_size); i++) {
            (*dataset)[i].offset = -1;
        }
    } else {
        // No need to reallocate or copy data
        return NULL;
    }
}

int main() {
    int dataset_size = 10000;
    record* dataset = init_dataset(dataset_size);
    setup_hash_table(dataset, dataset_size);

    // Resize dataset for larger size
    dataset_size *= 2;
    void* result = resize_dataset(&dataset, dataset_size / 2, dataset_size);
