typedef struct {
    char* key;
    long value;
    double readings[10];
} Entry;

typedef struct {
    int size;
    Entry** entries;
    pthread_mutex_t lock;
} HashTable;

void init_table(HashTable* table, int initial_size) {
    table->size = initial_size;
    table->entries = (Entry**)malloc(initial_size * sizeof(Entry*));
    for (int i = 0; i < initial_size; i++) {
        table->entries[i] = NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
}

void add_entry(HashTable* table, char* key, long value) {
    int index = hash(key) % table->size;
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;
    for (int i = 0; i < 10; i++) {
        entry->readings[i] = (double)(rand() / (RAND_MAX + 1.0));
    }
    table->entries[index] = entry;
}

void* sensor_allocator(void* ptr) {
    return malloc(1024);
}

void free_sensor_data(void* data, void* ptr) {
    free(data);
}

int main() {
    HashTable table;
    init_table(&table, 10);

    pthread_t thread;
    pthread_create(&thread, NULL, sensor_allocator, NULL);

    for (int i = 0; i < 100; i++) {
        char key[20];
        sprintf(key, "entry_%d", i);
        add_entry(&table, key, i * 10);
    }

    pthread_join(thread, NULL);

    return 0;
}
