typedef struct {
    char name[20];
    int id;
    double salary;
    int skills;
    struct NFAPI_CRC_INDICATION_PDU_T* crc_list;
} Employee;

typedef struct {
    char name[20];
    int id;
    double budget;
    int employee_limit;
    int project_limit;
    Employee** employees;
    struct Project*** projects;
} Department;

typedef struct {
    int rnti;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

Department* create_department(char* name, int id, double budget, int employee_limit, int project_limit) {
    Department* department = (Department*)malloc(sizeof(Department));
    strcpy(department->name, name);
    department->id = id;
    department->budget = budget;
    department->employee_limit = employee_limit;
    department->project_limit = project_limit;
    department->employees = (Employee**)malloc(employee_limit * sizeof(Employee*));
    department->projects = (struct Project***)malloc(project_limit * sizeof(struct Project**));
    return department;
}

void add_employee(Department* department, Employee* employee) {
    // check if the department has reached its employee limit
    if (department->employee_limit <= 0) {
        printf("Department full.\n");
        return;
    }

    for (int i = 0; i < department->employee_limit; i++) {
        if (!department->employees[i]) {
            department->employees[i] = employee;
            break;
        }
    }
}

void add_project(Department* department, struct Project* project) {
    // check if the department has reached its project limit
    if (department->project_limit <= 0) {
        printf("Department full.\n");
        return;
    }

    for (int i = 0; i < department->project_limit; i++) {
        if (!department->projects[i]) {
            department->projects[i] = &project;
            break;
        }
    }
}

void free_department(Department* department) {
    for (int i = 0; i < department->employee_limit; i++) {
