// Define the function to manage and process environmental sensor data
void *process_sensor_data(void *arg) {
    // Initialize variables
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    SensorData *data = (SensorData *) arg;
    int buffer_size = 1000; // Maximum buffer size for data storage
    int retention_policy = 300; // Data retention policy in seconds
    int max_concurrent_requests = 5; // Resource limits for concurrent requests

    while (1) {
        // Process incoming data
        if (data->timestamp % buffer_size == 0 && data->temperature > 25.0f) {
            printf("Temperature anomaly detected at timestamp: %d\n", data->timestamp);
        }

        // Manage memory and resources
        pthread_mutex_lock(&lock);
        if (pthread_get_affinity_np(pthread_self(), NULL, &max_concurrent_requests) != 0) {
            printf("Error setting affinity for thread: %s\n", strerror(errno));
        }
        pthread_mutex_unlock(&lock);

        // Validate data integrity and consistency
        int anomalies = 0;
        float avg_temp = 0.0f;
        float avg_humidity = 0.0f;

        // Calculate average temperature and humidity
        for (int i = 0; i < buffer_size; i++) {
            avg_temp += data[i].temperature / buffer_size;
            avg_humidity += data[i].humidity / buffer_size;
        }

        // Determine anomalies based on threshold values
        if (avg_temp > 25.5f || avg_humidity > 60.0f) {
            anomalies++;
        }

        // Return key metrics and summary reports
        printf("Anomalies: %d\n", anomalies);
        printf("Average Temperature: %.2f°C\n", avg_temp);
        printf("Average Humidity: %.2f%%\n", avg_humidity);

        // Export summary report in JSON format
        FILE *fp = fopen("report.json", "w");
        fprintf(fp, "{ \"Anomalies\": %d, \"AverageTemperature\": %.2f, \"AverageHumidity\": %.2f }", anomalies, avg_temp, avg_humidity);
        fclose(fp);

        // Export summary report in CSV format
        fp = fopen("report.csv", "w");
        fprintf(fp, "Anomalies,Average Temperature,Average Humidity\n%d,%.2f,%.2f", anomalies, avg_temp, avg_humidity);
        fclose(fp);
    }

    return NULL;
}

int main() {
    // Initialize the data buffer
    SensorData *data = (SensorData *) malloc(buffer_size * sizeof(SensorData));
    pthread_t thread;

    // Create and start a new thread to process sensor data
