#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Custom record structure
typedef struct {
    int* ptr;
    char id[20];
} Record;

// Custom allocator function to manage memory efficiently
void* custom_allocator(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    return ptr;
}

// Function to initialize and populate data structures
int* init_and_populate(int** offset_values, int*** keys, Record*** records, size_t initial_size) {
    // Initialize arrays with default values if memory allocation fails
    *offset_values = (*keys = *records = NULL);

    for (size_t i = 0; i < initial_size; i++) {
        // Allocate memory for each data structure and initialize arrays
        Record* record = (Record*)custom_allocator(sizeof(Record));
        if (!record) break;
        int* offset_value = (int*)custom_allocator(sizeof(int));
        int* key = (int*)custom_allocator(sizeof(int));

        // Initialize and populate array elements
        *offset_value = rand() % 100; // Random integer within a specified range
        sprintf(record->id, "Record-%zu", time(NULL)); // Unique timestamp-based identifier

        // Update pointers to record structures
        if (*records) {
            Record** records_array = (Record**)realloc(*records, (i + 1) * sizeof(Record*));
            if (!records_array) break;
            *records = records_array;
        } else {
            *records = malloc(initial_size * sizeof(Record*));
        }
        (*records)[i] = record;

        // Update pointers to keys
        if (*keys) {
            int** keys_array = (int**)realloc(*keys, (i + 1) * sizeof(int*));
            if (!keys_array) break;
            *keys = keys_array;
        } else {
            *keys = malloc(initial_size * sizeof(int*));
        }
        (*keys)[i] = key;

        // Update pointers to offset values
        if (*offset_values) {
            int** offset_values_array = (int**)realloc(*offset_values, (i + 1) * sizeof(int*));
            if (!offset_values_array) break;
            *offset_values = offset_values_array;
        } else {
            *offset_values = malloc(initial_size * sizeof(int*));
        }
        (*offset_values)[i] = offset_value;

        // Periodic cleanup mechanism to optimize memory usage
        static size_t last_cleanup_time = time(NULL);
        if (time(NULL) - last_cleanup_time > 60) { // Example: every minute
            for (size_t j = 0; j < i; j++) {
                free((*records)[j]->ptr); free((*keys)[j]);
                free((*offset_values)[j]);
            }
            *records = realloc(*records, initial_size * sizeof(Record*));
            *keys = realloc(*keys, initial_size * sizeof(int*));
            *offset_values = realloc(*offset_values, initial_size * sizeof(int*));
            last_cleanup_time = time(NULL);
        }

        // Handle potential memory allocation failures gracefully
        if (!record || !key || !offset_value) {
            for (size_t j = 0; j < i; j++) {
                free((*records)[j]->ptr); free((*keys)[j]);
                free((*offset_values)[j]);
            }
            free(record); free(key); free(offset_value);
            return NULL;
        }

        // Update pointers to record structures
        if (i > 0) {
            Record** records_array = (Record**)realloc(*records, (i + 1) * sizeof(Record*));
            if (!records_array) break;
