#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define a struct for record
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define a linked list node
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Function to dynamically allocate memory and initialize arrays
Record **initArrays(size_t numRecords, long minOffset, long maxOffset, int minKey, int maxKey, double minValue, double maxValue) {
    // Allocate memory for the arrays
    Record **offsets = (Record **)malloc(sizeof(Record *) * 3);
    offsets[0] = (Record *)malloc(sizeof(Record) * numRecords);
    offsets[1] = (Record *)malloc(sizeof(Record) * numRecords);
    offsets[2] = (Record *)malloc(sizeof(Record) * numRecords);

    // Initialize arrays
    long offsetRange = maxOffset - minOffset + 1;
    int keyRange = maxKey - minKey + 1;

    for (size_t i = 0; i < numRecords; i++) {
        Record *record = &offsets[2][i];
        record->offset = minOffset + rand() % offsetRange;
        record->key = minKey + rand() % keyRange;
        record->value = minValue + (rand() / (double)RAND_MAX) * (maxValue - minValue);
    }

    // Create a linked list of records
    Node *head = NULL, *current = NULL;

    for (size_t i = 0; i < numRecords; i++) {
        Record *record = &offsets[2][i];
        Node *newNode = (Node *)malloc(sizeof(Node));
        newNode->record = record;
        newNode->next = NULL;

        if (!head) {
            head = current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    // Return the arrays and linked list
    return offsets;
}

// Function to free allocated memory
void freeArrays(Record **arrays, size_t numRecords) {
    for (size_t i = 0; i < 3; i++) {
        if (arrays[i]) {
            free(arrays[i]);
            arrays[i] = NULL;
        }
    }

    Node *current = head, *next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    head = NULL;
}

int main() {
    size_t numRecords = 1000;
    long minOffset = 1, maxOffset = 100000;
    int minKey = 0, maxKey = 10000;
    double minValue = -100.0, maxValue = 100.0;

    Record **arrays = initArrays(numRecords, minOffset, maxOffset, minKey, maxKey, minValue, maxValue);

    // Use the arrays and linked list here

    freeArrays(arrays, numRecords);
    return 0;
}
