    char *id = (char *)malloc(32);
    for (int i = 0; i < strlen(user_id); i++) {
        id[i] = user_id[i] ^ 'X';
    }
    return id;
}

// Function to create and store a new session
void create_session(char *user_id) {
    if (num_sessions >= MAX_SESSIONS) {
        printf("Session limit reached!\n");
        return;
    }

    char *session_id = generate_session_id(user_id);
    Session *new_session = (Session *)malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->user_id = atoi(user_id);
    strcpy(new_session->username, "User");
    time(&new_session->last_accessed);

    sessions[num_sessions] = new_session;
    num_sessions++;

    printf("New session created: %s\n", session_id);
}

// Function to retrieve a session by ID
Session *get_session(char *session_id) {
    for (int i = 0; i < num_sessions; i++) {
        if (strcmp(sessions[i]->session_id, session_id) == 0) {
            return sessions[i];
        }
    }
    return NULL;
}

// Function to update a session's last accessed time
void update_session_last_accessed(Session *session) {
    time(&session->last_accessed);
}

// Function to check if a session has timed out
int is_session_timeout(Session *session) {
    time_t current_time = time(NULL);
    return (current_time - session->last_accessed > SESSION_TIMEOUT);
}

// Function to expire and clean up timed-out sessions
void cleanup_sessions() {
    for (int i = 0; i < num_sessions; i++) {
        if (is_session_timeout(sessions[i])) {
            printf("Expire session: %s\n", sessions[i]->session_id);
            free(sessions[i]);
            sessions[i] = NULL;
            num_sessions--;
            i--; // Re-check the next session
        }
    }
}

// Function to update and delete session information via HTTP methods
void handle_session_api_request(char *method, char *session_id) {
    Session *session = get_session(session_id);
    if (method == "PUT") { // Update session info
        // Implement your own implementation of updating session information
        printf("Session updated: %s\n", session_id);
    } else if (method == "DELETE") { // Delete session
        printf("Delete session: %s\n", session_id);
        free(session->session_id);
        free(session);
        sessions[num_sessions - 1] = NULL;
        num_sessions--;
    }
}

// Main function to manage concurrent session access and timeouts
int main() {
    // Initialize session hash table
    sessions = (Session **)malloc(MAX_SESSIONS * sizeof(Session *));
    for (int i = 0; i < MAX_SESSIONS; i++) {
        sessions[i] = NULL;
    }

    // Start the session management loop
    while (1) {
        int choice;
        printf("Choose an option:\n");
        printf("1. Create a new session\n");
        printf("2. Update a session\n");
        printf("3. Delete a session\n");
        printf("4. Cleanup timed-out sessions\n");
        printf("5. Exit\n");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                char *user_id = (char *)malloc(10);
                printf("Enter user ID: ");
                scanf("%s", user_id);
                create_session(user_id);
                break;
            case 2:
                // Implement your own implementation of updating session information
                break;
            case 3:
                // Implement your own implementation of deleting a session
                break;
            case 4:
                cleanup_sessions();
                break;
            case 5:
                printf("Exiting...\n");
                return 0;
            default:
                printf("Invalid choice. Try again.\n");
        }
    }

    return 0;
}
