} Record;

Record* initializeMemoryBlock(size_t initialSize, size_t seed) {
    Record* records = (Record*)malloc(initialSize * sizeof(Record));
    for (size_t i = 0; i < initialSize; i++) {
        records[i].key = rand_r(&seed);
        records[i].value = rand_r(&seed);
        records[i].offset = i;
    }
    return records;
}

void resizeMemoryBlock(Record** records, size_t currentCapacity, size_t newSize) {
    Record* newRecords = (Record*)realloc(*records, newSize * sizeof(Record));
    if (!newRecords) {
        printf("Error: Memory allocation failed.\n");
        exit(-1);
    }
    *records = newRecords;
}

void shuffleRecords(Record** records, size_t size, size_t seed) {
    for (size_t i = 0; i < size; i++) {
        int idx = rand_r(&seed) % size;
        Record temp = (*records)[i];
        (*records)[i] = (*records)[idx];
        (*records)[idx] = temp;
    }
}

void freeMemoryBlock(Record** records) {
    if (*records) {
        free(*records);
        *records = NULL;
    }
}
