} record;

typedef struct {
    int key;
    record* data;
} hash_entry;

typedef struct {
    int size;
    float load_factor;
    hash_entry** table;
    int num_entries;
} hash_table;

hash_table* init_hash_table(int initial_size) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->size = initial_size;
    ht->load_factor = 0.75f;
    ht->table = (hash_entry**)malloc(sizeof(hash_entry*) * initial_size);
    for (int i = 0; i < initial_size; i++) {
        ht->table[i] = NULL;
    }
    ht->num_entries = 0;
    return ht;
}

void resize_hash_table(hash_table* ht, int new_size) {
    hash_table* temp_ht = init_hash_table(new_size);
    for (int i = 0; i < ht->size; i++) {
        if (ht->table[i] != NULL) {
            temp_ht->num_entries++;
            hash_entry* entry = (hash_entry*)malloc(sizeof(hash_entry));
            entry->key = ht->table[i]->key;
            entry->data = (record*)malloc(sizeof(record));
            strcpy(entry->data->label, ht->table[i]->data->label);
            entry->data->timestamp = ht->table[i]->data->timestamp;
            entry->data->status_code = ht->table[i]->data->status_code;
            temp_ht->table[temp_ht->num_entries % new_size] = entry;
        }
    }
    for (int i = 0; i < ht->size; i++) {
        if (ht->table[i] != NULL) {
            free(ht->table[i]);
        }
    }
    free(ht);
    *ht = *temp_ht;
}

void insert_hash_table(hash_table* ht, int key, record* data) {
    float load_factor = ((float)ht->num_entries / ht->size);
    if (load_factor > ht->load_factor) {
        resize_hash_table(ht, ht->size * 2 + 1);
    }
    hash_entry* entry = (hash_entry*)malloc(sizeof(hash_entry));
    entry->key = key;
    entry->data = data;
    int index = key % ht->size;
    if (ht->table[index] == NULL) {
        ht->table[index] = entry;
    } else {
        while (1) {
            int j = (index + 1) % ht->size;
            if (j == index) {
                break;
            }
            if (ht->table[j] == NULL) {
                ht->table[j] = entry;
                break;
            }
            index = j;
        }
    }
}

void* iterate_hash_table(hash_table* ht, int(*cmp)(const void*, const void*)) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->table[i] != NULL) {
            hash_entry* entry = ht->table[i];
            while (entry->data != NULL) {
                // Perform comparison operation
                int result = cmp(entry->key, entry->data);
                if (result > 0) {
                    break;
                }
                entry = entry->next;
            }
        }
    }
}

record* find_hash_table(hash_table* ht, int key) {
    int index = key % ht->size;
    hash_entry* entry = ht->table[index];
    while (entry != NULL) {
        if (entry->key == key) {
            return entry->data;
        }
        entry = entry->next;
    }
    return NULL;
}

void delete_hash_table(hash_table* ht, int key) {
    int index = key % ht->size;
    hash_entry* prev = NULL;
    hash_entry* curr = ht->table[index];
    while (curr != NULL) {
        if (curr->key == key) {
            if (prev != NULL) {
                prev->next = curr->next;
            } else {
                ht->table[index] = curr->next;
            }
            free(curr);
            return;
        }
        prev = curr;
        curr = curr->next;
    }
}

int main() {
    hash_table* ht = init_hash_table(16);
    // Perform insert, iterate, find and delete operations
    return 0;
}
