typedef struct {
    double value;
    char identifier;
} item_t;

// Custom hash function
unsigned int custom_hash(const char* str) {
    unsigned int hash = 0;
    while (*str != '\0') {
        hash ^= *str;
        str++;
    }
    return hash;
}

// Dynamic collection of 'item' structures
typedef struct {
    item_t* items;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} collection_t;

collection_t* collection_create(size_t initial_capacity, size_t max_size) {
    collection_t* coll = (collection_t*)malloc(sizeof(collection_t));
    if (!coll) return NULL;

    coll->capacity = initial_capacity;
    coll->size = 0;
    coll->items = (item_t*)malloc(initial_capacity * sizeof(item_t));

    if (!coll->items) {
        free(coll);
        return NULL;
    }

    pthread_mutex_init(&coll->mutex, NULL);

    return coll;
}

void collection_destroy(collection_t* coll) {
    if (!coll) return;

    for (size_t i = 0; i < coll->size; i++) {
        free(coll->items[i].identifier);
    }
    free(coll->items);
    pthread_mutex_destroy(&coll->mutex);
    free(coll);
}

int collection_add(collection_t* coll, item_t* item) {
    if (!coll || !item) return -1;

    pthread_mutex_lock(&coll->mutex);

    if (coll->size >= coll->capacity) {
        size_t new_capacity = coll->capacity * 2;
        item_t* new_items = (item_t*)realloc(coll->items, new_capacity * sizeof(item_t));
        if (!new_items) {
            pthread_mutex_unlock(&coll->mutex);
            return -1; // Memory allocation failed
        }
        coll->capacity = new_capacity;
        coll->items = new_items;
    }

    coll->items[coll->size] = *item;
    coll->size++;

    pthread_mutex_unlock(&coll->mutex);

    return 0;
}

int collection_remove(collection_t* coll, item_t* item) {
    if (!coll || !item) return -1;

    pthread_mutex_lock(&coll->mutex);

    for (size_t i = 0; i < coll->size; i++) {
        if (memcmp(&coll->items[i], item, sizeof(item_t)) == 0) {
            size_t j;
            for (j = i; j < coll->size - 1; j++) {
                coll->items[j] = coll->items[j + 1];
            }
            coll->size--;
            break;
        }
    }

    pthread_mutex_unlock(&coll->mutex);

    return 0;
}

int collection_serialize(collection_t* coll, char** serialized) {
    if (!coll || !serialized) return -1;

    size_t serialized_size = sizeof(item_t) * coll->size;
    *serialized = (char*)malloc(serialized_size);
    memcpy(*serialized, &coll->items[0], serialized_size);

    return 0;
}

int collection_deserialize(collection_t* coll, char* serialized) {
    if (!coll || !serialized) return -1;

    size_t serialized_size = strlen(serialized);
    item_t* items = (item_t*)malloc((serialized_size / sizeof(item_t)) * sizeof(item_t));
    memcpy(items, serialized, serialized_size);

    for (size_t i = 0; i < serialized_size / sizeof(item_t); i++) {
        coll->items[coll->size++] = items[i];
    }
    free(items);

    return 0;
}

int main() {
    // Example usage
    collection_t* coll = collection_create(10, 100);
    item_t item1 = {"Value 1", 'A'};
    item_t item2 = {"Value 2", 'B'};

    collection_add(coll, &item1);
    collection_add(coll, &item2);

    // Batch operation
    for (size_t i = 0; i < coll->size; i++) {
        if (coll->items[i].identifier == 'A') {
            collection_remove(coll, &coll->items[i]);
            break;
        }
    }

    char* serialized = NULL;
    int result = collection_serialize(coll, &serialized);
    // ...

    free(serialized);
    collection_destroy(coll);

    return 0;
}

