typedef struct {
    char* name;
    size_t size;
} plugin;

int load_plugins(const char* dir_path) {
    int count = 0;
    DIR* dir = opendir(dir_path);
    struct dirent* ent;
    plugin* plugins = NULL;
    size_t total_size = 0;

    if (dir == NULL)
        return -1;

    while ((ent = readdir(dir)) != NULL) {
        char path[256];
        sprintf(path, "%s/%s", dir_path, ent->d_name);

        FILE* file = fopen(path, "r");
        if (file == NULL)
            continue;

        plugin p;
        fscanf(file, "%s %zu\n", &p.name, &p.size);
        fclose(file);

        total_size += p.size;

        if (plugins == NULL) {
            plugins = malloc((count + 1) * sizeof(plugin));
            if (plugins == NULL)
                return -1;
        } else {
            plugins[count].name = realloc(plugins[count].name, (p.size + 1) * sizeof(char));
            plugins[count++].size = p.size;
        }
    }

    closedir(dir);
    return count;
}

int main() {
    int count = load_plugins("/path/to/plugins");
    // Use the plugins
    return 0;
}
