// Predefined categories for messages
#define DEBUG 0
#define TRACE 1
#define NOTICE 2
#define WARNING 3
#define ERROR 4

record* record_list = NULL;
size_t num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t* category_indices = NULL;

void init_record_list(size_t max_size) {
    // Initialize the linked list and categories array
    record_list = (record*) malloc(max_size * sizeof(record));
    category_indices = (size_t*) calloc(NUM_CATEGORIES, sizeof(size_t));

    // Initialize records with default messages based on categories
    for (int i = 0; i < NUM_CATEGORIES; i++) {
        category_indices[i] = i;
    }
}

void add_record(uint64_t id, time_t timestamp, char* message) {
    // Allocate a new record and initialize it
    record* new_record = (record*) malloc(sizeof(record));
    new_record->id = id;
    new_record->timestamp = timestamp;
    new_record->message = strdup(message);

    // Add the record to the linked list and update categories array
    pthread_mutex_lock(&lock);
    if (!record_list) {
        record_list = new_record;
    } else {
        record* current = record_list;
        while (current && current->next) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&lock);

    // Update the categories array
    int category = getCategory(message);
    size_t index = category_indices[category];
    category_indices[index]++;
}

void remove_record(uint64_t id) {
    // Find and remove the record from the linked list
    pthread_mutex_lock(&lock);
    record* current = record_list;
    while (current && current->id != id) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&lock);
        return;  // Record not found, nothing to remove
    }

    // Update the categories array
    int category = getCategory(current->message);
    size_t index = category_indices[category];
    category_indices[index]--;

    // Remove the record from the linked list and free its memory
    if (current == record_list) {
        record_list = current->next;
    } else {
        record* previous = record_list;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }
    free(current);

    pthread_mutex_unlock(&lock);
}

int getCategory(char* message) {
    // Determine the category of the message based on predefined categories
    if (strstr(message, "DEBUG")) {
        return DEBUG;
    } else if (strstr(message, "TRACE")) {
        return TRACE;
    } else if (strstr(message, "NOTICE")) {
        return NOTICE;
    } else if (strstr(message, "WARNING")) {
        return WARNING;
    } else if (strstr(message, "ERROR")) {
        return ERROR;
    }
}

void free_record_list() {
    // Free the linked list and categories array
    record* current = record_list;
    while (current) {
        record* next = current->next;
        free(current);
        current = next;
    }
    free(category_indices);
}
