#define MAX_STATS 1024
#define MAX_UE 256

typedef struct {
    uint8_t tx_ue_info_tag;
    int pci;
    L1_STATS_TAG l1_stats;
} NFAPI_L1_STATS_REPORT_PDU_T;

// Shared memory structure to store statistics
NFAPI_L1_STATS_REPORT_PDU_T stats[MAX_STATS];

// Mutex for synchronization
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for signaling updates
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to add a new statistic entry
void add_statistic(uint8_t tag, int pci, L1_STATS_TAG stats) {
    pthread_mutex_lock(&lock);
    // Find the next available slot or overwrite the oldest entry if full
    uint32_t i;
    for (i = 0; i < MAX_STATS; i++) {
        if (stats[i].tx_ue_info_tag == 0) {
            break;
        }
    }
    stats[i].tx_ue_info_tag = tag;
    stats[i].pci = pci;
    stats[i].l1_stats = stats;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

// Function to remove a statistic entry
void remove_statistic(uint8_t tag) {
    pthread_mutex_lock(&lock);
    // Find and remove the matching entry
    uint32_t i;
    for (i = 0; i < MAX_STATS; i++) {
        if (stats[i].tx_ue_info_tag == tag) {
            break;
        }
    }
    if (i < MAX_STATS)
        memset(&stats[i], 0, sizeof(NFAPI_L1_STATS_REPORT_PDU_T));
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a statistic entry
NFAPI_L1_STATS_REPORT_PDU_T* get_statistic(uint8_t tag) {
    pthread_mutex_lock(&lock);
    // Find and return the matching entry or NULL if not found
    uint32_t i;
    for (i = 0; i < MAX_STATS; i++) {
        if (stats[i].tx_ue_info_tag == tag) {
            break;
        }
    }
    if (i < MAX_STATS)
        pthread_mutex_unlock(&lock);
    else
        return NULL;
}

// Function to initialize the library
void init_library() {
    // Initialize shared memory and synchronization primitives
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond, NULL);
}

// Function to cleanup the library
void clean_up_library() {
    // Release synchronization primitives and shared memory
    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond);
}

// Example usage: add/remove/get statistics concurrently from multiple threads
#include <pthread.h>

void* thread_func(void* arg) {
    uint8_t tag = *((uint8_t*)arg);
    int i;
    for (i = 0; i < 10; i++) {
        // Add statistic entry with unique tag
        add_statistic(tag, rand() % MAX_UE, l1_stats());
        usleep(10000); // Simulate measurement interval
    }
    return NULL;
}

int main() {
    init_library();

    pthread_t threads[MAX_THREADS];
    uint8_t tags[] = {0x01, 0x02, 0x03};

    for (uint32_t i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_func, &tags[i]);
    }

    // Simulate concurrent operations
    sleep(10);

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    clean_up_library();
    return 0;
}
