    uint8_t ttl;
    uint32_t checksum;
} packet_header;

packet_header* packet_headers = NULL;
char** buffers = NULL;
uint16_t* ports = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int packets_processed = 0, max_packets = 0, memory_used = 0;

void* allocate_packet_buffer(int size) {
    void* buffer = malloc(size);
    if (!buffer) {
        LOG_ERROR("Failed to allocate packet buffer");
        return NULL;
    }
    return buffer;
}

packet_header* create_packet_header() {
    packet_header* header = (packet_header*)malloc(sizeof(packet_header));
    if (!header) {
        LOG_ERROR("Failed to allocate packet header");
        return NULL;
    }
    // Initialize fields with default values
    header->protocol = 0;
    header->ttl = 0;
    header->checksum = 0;
    return header;
}

int manage_packets() {
    if (packets_processed >= max_packets) {
        max_packets *= 2; // Double the maximum packet count
    }

    // Allocate and initialize arrays
    if (!packet_headers || !buffers || !ports) {
        packet_headers = (packet_header*)malloc(max_packets * sizeof(packet_header));
        buffers = (char**)malloc(max_packets * sizeof(char*));
        ports = (uint16_t*)malloc(max_packets * sizeof(uint16_t));

        if (!(packet_headers && buffers && ports)) {
            LOG_ERROR("Failed to allocate packet arrays");
            return -1;
        }
    }

    // Enqueue packets
    for (int i = 0; i < max_packets; i++) {
        packet_header* header = create_packet_header();

        if (!header) {
            LOG_ERROR("Failed to create packet header");
            continue;
        }

        buffers[i] = allocate_packet_buffer(1024); // Allocate buffer

        if (!buffers[i]) {
            LOG_ERROR("Failed to allocate packet buffer");
            free(header);
            continue;
        }

        ports[i] = i; // Initialize port number
    }

    return 0;
}

void process_packets() {
    for (int i = 0; i < max_packets; i++) {
        pthread_mutex_lock(&lock);

        packet_header* header = &packet_headers[i];
        char* buffer = buffers[i];

        // Process the packet
        LOG_INFO("Processing packet %d", i);

        // Release lock and process the next packet
        pthread_mutex_unlock(&lock);
    }
}

int main() {
    manage_packets();

    while (1) {
        int packets = 0;

        for (int i = 0; i < max_packets; i++) {
            if (pthread_mutex_lock(&lock)) {
                LOG_ERROR("Failed to lock");
                continue;
            }

            packet_header* header = &packet_headers[i];
            char* buffer = buffers[i];

            // Process the packet
            LOG_INFO("Processing packet %d", i);

            packets++;

            pthread_mutex_unlock(&lock);
        }

        process_packets();
    }

    return 0;
}

