#define RECORD_MAX 1000
#define KEY_RANGE 10

typedef struct {
    int key;
    int value;
} record_t;

record_t *records = NULL;
int record_count = 0;
int key_max = 0;

void* allocate_and_initialize_records(void) {
    records = (record_t*) malloc(RECORD_MAX * sizeof(record_t));
    for (int i = 0; i < RECORD_MAX; i++) {
        records[i].key = rand() % KEY_RANGE;
        records[i].value = rand();
    }
    return NULL;
}

void validate_records() {
    int key_seen[KEY_RANGE] = {0};
    for (int i = 0; i < record_count; i++) {
        if (key_seen[records[i].key]) {
            printf("Duplicate key detected: %d\n", records[i].key);
            exit(1);
        }
        key_seen[records[i].key] = 1;
    }
}

void serialize_records_to_file(char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }
    fwrite(&record_count, sizeof(int), 1, file);
    for (int i = 0; i < record_count; i++) {
        fwrite(&records[i], sizeof(record_t), 1, file);
    }
    fclose(file);
}

void deserialize_records_from_file(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return;
    }
    fread(&record_count, sizeof(int), 1, file);
    records = (record_t*) realloc(records, record_count * sizeof(record_t));
    for (int i = 0; i < record_count; i++) {
        fread(&records[i], sizeof(record_t), 1, file);
    }
    fclose(file);
}

