    int capacity, size;
} MemoryPool;

// Initialize and resize the memory pool
MemoryPool* createMemoryPool(int initialCapacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->blocks = (void**)malloc(initialCapacity * sizeof(void*));
    mp->capacity = initialCapacity;
    mp->size = 0;
    return mp;
}

// Add a new block to the memory pool
void addBlockToPool(MemoryPool* mp, void* block) {
    if(mp->size < mp->capacity) {
        mp->blocks[mp->size] = block;
        mp->size++;
    } else {
        // Resize the pool and re-add the block
        int newCapacity = mp->capacity * 2;
        mp->blocks = (void**)realloc((void*)mp, newCapacity * sizeof(void*));
        mp->capacity = newCapacity;
        addBlockToPool(mp, block);
    }
}

