import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class PacketProcessor {
    private static final int MAX_PACKET_SIZE = 8192; // 8KB
    private static final int BUFFER_UPPER_LIMIT = 1000000; // configurable limit of 1 million packets
    private static final long FLUSH_RETENTION_POLICY = 60000L; // 1 minute retention policy

    private Map<String, AtomicInteger> packetCounts;
    private Map<String, Integer> bufferSizes;
    private ThreadLocal<Buffer> buffers;

    public PacketProcessor() {
        this.packetCounts = new HashMap<>();
        this.bufferSizes = new HashMap<>();
        this.buffers = new ThreadLocal<>();
    }

    public void processPacket(String packetData) throws IOException {
        Buffer buffer = getBuffer();
        if (buffer == null || !buffer.isAvailable()) {
            // handle buffer exhaustion
            throw new IOException("Buffer exhausted");
        }
        int packetSize = packetData.length();
        if (packetSize > MAX_PACKET_SIZE) {
            // handle malformed packets
            throw new IOException("Malformed packet");
        }
        buffer.write(packetData);
    }

    private Buffer getBuffer() {
        return buffers.getOrDefault(threadId(), Buffer.create());
    }

    public void flushBuffers() throws IOException {
        for (String threadId : buffers.keySet()) {
            Buffer buffer = buffers.get(threadId);
            if (!buffer.isEmpty()) {
                // log the processed data
                System.out.println("Flushed " + buffer.getSize() + " packets from thread " + threadId);
                buffer.clear();
            }
        }
    }

    public void archiveBuffers(long retentionTime) throws IOException {
        for (String threadId : buffers.keySet()) {
            Buffer buffer = buffers.get(threadId);
            if (!buffer.isEmpty()) {
                // log the processed data
                System.out.println("Archived " + buffer.getSize() + " packets from thread " + threadId);
                buffer.clear();
            }
            try {
                Thread.sleep(retentionTime);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private String threadId() {
        return Thread.currentThread().getName();
    }

    public static class Buffer {
        private byte[] data;
        private int size;

        public Buffer(int capacity) {
            this.data = new byte[capacity];
            this.size = 0;
        }

        public boolean isAvailable() {
            return size < data.length;
        }

        public void write(String packetData) throws IOException {
            // implement buffering logic
        }

        public int getSize() {
            return size;
        }

        public void clear() {
            size = 0;
        }
    }
}
