fn initialize_data_pipeline(endpoint_url: &str, enable_logging: bool, batch_size: usize, config_overrides: Option<Hamilton::HashMap<String, String>>) -> Result<(Option<HashMap<String, String>>, Vec<usize>, Vec<f64>, Vec<DataRecord>), String> {
