    // Initialize arrays
    let mut batch_indices: Vec<usize> = (0..1024).collect();
    let mut weights: Vec<f64> = (0..512).map(|_| rng.gen_range(0.0..1.0) / 511.0).collect();
    weights.push((weights.iter().sum::<f64>() as f64).recip());
    let mut records: Vec<DataRecord> = (0..1024).map(|_| DataRecord { value: rng.gen_range(-1000..=1000) }).collect();

    // Initialize configuration
    let config = match config_overrides {
        Some(config) => config,
        None => HashMap::new(),
    };

    // Initialize logging
    let mut logger_enabled = enable_logging;

    Ok((Some(config), batch_indices, weights, records))
}
