    if (!node) {
        // Handle memory allocation failure
        return -1;
    }

    node->profile.user_id = user_id;
    strcpy(node->profile.email_address, email_address);
    node->profile.last_login_time = last_login_time;
    node->profile.status_code = status_code;
    node->next = primary_list;
    primary_list = node;

    // Update activity list
    ACTIVITY_NODE* activity_node = (ACTIVITY_NODE*)malloc(sizeof(ACTIVITY_NODE));
    if (!activity_node) {
        // Handle memory allocation failure
        return -1;
    }

    activity_node->activity_level = 0;
    activity_node->next = activity_list;
    activity_list = activity_node;

    return 0;
}

// Function to update user profile
int update_user(int user_id, char email_address[], time_t last_login_time, int status_code) {
    // Find the node with matching user id
    NODE* node = primary_list;
    while (node && node->profile.user_id != user_id) {
        node = node->next;
    }

    if (!node) {
        // User not found
        return -1;
    }

    // Update the profile fields
    strcpy(node->profile.email_address, email_address);
    node->profile.last_login_time = last_login_time;
    node->profile.status_code = status_code;

    return 0;
}

// Function to delete a user profile
int delete_user(int user_id) {
    // Find the node with matching user id
    NODE* node = primary_list;
    NODE* prev_node = NULL;
    while (node && node->profile.user_id != user_id) {
        prev_node = node;
        node = node->next;
    }

    if (!node) {
        // User not found
        return -1;
    }

    // Remove the node from the list
    if (prev_node) {
        prev_node->next = node->next;
    } else {
        primary_list = node->next;
    }

    free(node);

    // Update activity list
    ACTIVITY_NODE* activity_node = activity_list;
    while (activity_node && activity_node->activity_level > 0) {
        activity_node->activity_level--;
        if (activity_node->activity_level == 0) {
            ACTIVITY_NODE* temp = activity_node;
            activity_node = activity_node->next;
            free(temp);
        }
    }

    return 0;
}

// Function to validate integrity of linked lists
int validate_lists() {
    NODE* node = primary_list;
    while (node) {
        // Check for valid user profile fields
        if (!node->profile.email_address || !node->profile.last_login_time || node->profile.status_code < 0) {
            return -1;
        }

        node = node->next;
    }

    ACTIVITY_NODE* activity_node = activity_list;
    while (activity_node) {
        // Check for valid activity levels
        if (activity_node->activity_level < 0) {
            return -1;
        }

        activity_node = activity_node->next;
    }

    return 0;
}

// Function to periodically synchronize primary list with external user database
int sync_lists() {
    // Fetch updated user profile information from the database
    // ...

    NODE* node = primary_list;
    while (node) {
        // Update the profile fields based on the fetched data
        node->profile.email_address = ...;
        node->profile.last_login_time = ...;
        node->profile.status_code = ...;

        node = node->next;
    }

    return 0;
}

int main() {
    initialize_lists();

    add_user(1, "user1@example.com", time(NULL), 0);

    update_user(1, "new_email@example.com", time(NULL) + 3600, 1);

    delete_user(1);

    validate_lists();

    sync_lists();

    return 0;
}
