#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the possible statuses for a task
enum TaskStatus { PENDING, COMPLETED };

typedef struct {
    unsigned int taskId;
    short priority;
    time_t deadline;
    enum TaskStatus status;
} Task;

Task* createTaskArray(unsigned int initialCapacity);
void updateDeadline(Task** tasks, unsigned int newDeadline);
void markTasksAsCompleted(Task** tasks);
int serializeTasksToFile(const char* filePath, Task** tasks);
int loadTasksFromFile(const char* filePath, Task*** tasks);

// Function to dynamically allocate memory for the task array
Task* createTaskArray(unsigned int initialCapacity) {
    Task* tasks = (Task*)malloc(initialCapacity * sizeof(Task));
    if (!tasks) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    for (unsigned int i = 0; i < initialCapacity; ++i) {
        tasks[i].status = PENDING;
    }
    return tasks;
}

// Function to update the deadline of all tasks
void updateDeadline(Task** tasks, unsigned int newDeadline) {
    for (Task* task : *tasks) {
        task->deadline = newDeadline;
    }
}

// Function to mark all tasks as completed
void markTasksAsCompleted(Task** tasks) {
    for (Task* task : *tasks) {
        task->status = COMPLETED;
    }
}

// Function to serialize the list of tasks to a file
int serializeTasksToFile(const char* filePath, Task** tasks) {
    FILE* file = fopen(filePath, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return -1;
    }

    int writtenBytes = fwrite(tasks, sizeof(Task), 1, file);
    fclose(file);

    return writtenBytes;
}

// Function to load tasks from a serialized file
int loadTasksFromFile(const char* filePath, Task*** tasks) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        printf("Failed to open file for reading.\n");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    int fileSize = ftell(file);
    rewind(file);

    *tasks = (Task**)malloc((sizeof(Task*) * (fileSize / sizeof(Task))));
    if (!*tasks) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    int bytesRead = fread(*tasks, sizeof(Task), fileSize / sizeof(Task), file);
    fclose(file);

    return bytesRead;
}
