typedef struct {
    char* buffer;
    unsigned long timestamp;
} entry;

typedef struct {
    size_t length;
    size_t frequency;
} summary;

void* allocate_entry(size_t size) {
    return malloc(size);
}

void free_entry(void* ptr) {
    free(ptr);
}

entry* insert_entry(entry** entries, size_t* capacity, size_t* length, pthread_mutex_t* mutex) {
    entry* new_entry = (entry*)allocate_entry(sizeof(entry));

    if (*length >= *capacity) {
        // Double the capacity
        *capacity *= 2;
        entries = (entry**)realloc(*entries, sizeof(entry*) * *capacity);
    }

    pthread_mutex_lock(mutex);
    new_entry->buffer = (char*)malloc(strlen("default_buffer") + 1); // Initialize with default buffer
    new_entry->timestamp = time(NULL);

    (*length)++;
    for (size_t i = *length - 2; i > 0; --i) {
        entries[i] = entries[i - 1];
    }
    entries[0] = new_entry;
    pthread_mutex_unlock(mutex);

    return entries;
}

summary* update_summary(summary** summaries, entry* entry, size_t* capacity, size_t* length, pthread_mutex_t* mutex) {
    summary* new_summary = (summary*)malloc(sizeof(summary));

    if (*length >= *capacity) {
        // Double the capacity
        *capacity *= 2;
        summaries = (summary**)realloc(*summaries, sizeof(summary*) * *capacity);
    }

    pthread_mutex_lock(mutex);
    new_summary->length = strlen(entry->buffer);
    new_summary->frequency = 1; // Default frequency

    (*length)++;
    for (size_t i = *length - 2; i > 0; --i) {
        summaries[i] = summaries[i - 1];
    }
    summaries[0] = new_summary;

    pthread_mutex_unlock(mutex);

    return summaries;
}

int main() {
    entry** entries = NULL;
    size_t capacity = 4;
    size_t length = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Insert entries
    for (size_t i = 0; i < 10; ++i) {
        entries = insert_entry(entries, &capacity, &length, &mutex);
    }

    // Update summary statistics
    for (size_t i = 0; i < length; ++i) {
        entry* entry = entries[i];
        summary** summaries = (summary**)malloc(sizeof(summary*) * capacity); // Initialize with default summary
        size_t new_capacity = capacity;
        size_t new_length = 1;

        for (size_t j = 0; j < length; ++j) {
            if (entries[j]->timestamp <= entry->timestamp) {
                break;
            }
            --new_length;
        }
        for (size_t j = 0; j < new_length; ++j) {
            summaries[j] = &summaries[0][j];
        }

        // Update frequency and length statistics
        for (size_t j = 0; j < new_length; ++j) {
            summary* summary = summaries[j];
            if (summary->length > entry->timestamp) {
                --summary->frequency;
            } else if (entry->timestamp <= summary->length) {
                ++summary->frequency;
            }
        }

        // Release memory
        for (size_t j = 0; j < new_length; ++j) {
            free((void*)summaries[j]);
        }
    }

    return 0;
}
