#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

record** allocate_memory(int size) {
    record** arrays = (record**)malloc(size * sizeof(record*));
    for (int i = 0; i < size; i++) {
        arrays[i] = (record*)malloc(sizeof(record));
        arrays[i]->offset = rand() % 100;
        arrays[i]->key = rand() % 10;
    }
    return arrays;
