typedef struct {
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int N) {
    int i, j, k = 0;
    NFAPI_CRC_INDICATION_PDU_T* indications = NULL;
    int RNTI_max = (1 << 12) - 1; // Assuming 12-bit RNTI
    unsigned char CRCFLAG;

    if (N > 1024) {
        return NULL; // Error: too many indications to generate
    }

    indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        return NULL; // Allocation failed
    }

    for (i = 0; i < N; i++) {
        do {
            indications[i].RNTI = rand() % RNTI_max;
            for (j = 0; j < i; j++) {
                if (indications[j].RNTI == indications[i].RNTI) {
                    break;
                }
            }
            if (j == i) {
                break; // Found a unique RNTI
            }
        } while (1);

        CRCFLAG = 0x01;
        for (k = 1; k <= ((N / 2) + 1); k <<= 1) {
            CRCFLAG |= rand() % 2;
        }
        indications[i].CRCFLAG = CRCFLAG;

    }

    return indications;
}
