        if (*num_projects > 0) {
            // Add dependencies between projects
            project* last_project = projects[(*num_projects - 1)];
            new_project->downstream = last_project;
            last_project->downstream = new_project;
        }

        *num_projects += 1;
        projects[*num_projects - 1] = new_project;
