        } else {
            LTE_PHY_TEST_MESSAGE* current_message = messages;

            while (*current_message != NULL) {
                current_message = &(*current_message)->next;
            }

            *current_message = new_message;
        }
    }

    return allocation_success ? messages : NULL;
