['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for tasks
typedef struct {
    int priority;
    time_t deadline;
    enum { PENDING, IN_PROGRESS, COMPLETED } status;
} Task;

// Define a task list node
typedef struct TaskNode {
    Task* task;
    struct TaskNode* next;
} TaskNode;

// Define the dynamic task list
typedef struct {
    TaskNode* head;
    TaskNode* tail;
    pthread_mutex_t lock; // lock for concurrent access
    size_t capacity;
    size_t count;
} TaskList;

// Initialize the task list
TaskList* task_list_init(size_t initial_capacity) {
    TaskList* list = (TaskList*)malloc(sizeof(TaskList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initial_capacity;
    list->count = 0;
    return list;
}

// Free the task list
void task_list_free(TaskList* list) {
    TaskNode* node = list->head;
    while (node) {
        TaskNode* next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Insert a new task into the list
void task_list_insert(TaskList* list, Task* task) {
    TaskNode* node = (TaskNode*)malloc(sizeof(TaskNode));
    node->task = task;
    node->next = NULL;

    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->count++;
}

// Remove a task from the list
void task_list_remove(TaskList* list, TaskNode* node) {
    if (list->head == node) {
        list->head = node->next;
    } else {
        TaskNode* prev = list->head;
        while (prev->next != node) {
            prev = prev->next;
        }
        prev->next = node->next;
    }
    if (list->tail == node) {
        list->tail = prev;
    }
    free(node);
    list->count--;
}

// Update the status of all tasks in the list
void task_list_update_status(TaskList* list, enum { PENDING, IN_PROGRESS, COMPLETED } new_status) {
    TaskNode* node = list->head;
    while (node) {
        node->task->status = new_status;
        node = node->next;
    }
}

// Batching process and update the status of all tasks to COMPLETED
void task_list_batch_update(TaskList* list) {
    pthread_mutex_lock(&list->lock);
    task_list_update_status(list, COMPLETED);
    pthread_mutex_unlock(&list->lock);
}
