    if (!records) return NULL;

    for (int i = 0; i < size; i++) {
        records[i].offset = (long*)malloc(sizeof(long));
        records[i].key = (int*)malloc(sizeof(int));
        *records[i].offset = 0;
        *records[i].key = 0;
        int min_value = 1, max_value = 100;
        *records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

void freeRecords(Record* records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i].offset);
        free(records[i].key);
    }
    free(records);
}

int main() {
    srand(time(NULL)); // seed the random number generator

