NFAPI_CRC_INDICATION_PDU_T* create_array(int N) {
    if (N <= 0 || N > MAX_N) {
        printf("Invalid array size %d. Must be between 1 and %d.\n", N, MAX_N);
        return NULL;
    }

    int chunk = CHUNK_SIZE;
    int total_chunks = (N + chunk - 1) / chunk;

    void* p = malloc(total_chunks * sizeof(NFAPI_CRC_INDICATION_PDU_T) * chunk);

    if (!p) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < total_chunks; i++) {
        NFAPI_CRC_INDICATION_PDU_T* arr = p + i * sizeof(NFAPI_CRC_INDICATION_PDU_T) * chunk;

        for (int j = 0; j < MIN(chunk, N - i * chunk); j++) {
            arr[j].RX_UE_INFORMATION_TAG = rand() % 100;
            arr[j].RNTI = rand() % 100;
            arr[j].CRC_INDICATION_REL8_TAG = rand() % 100;
