    double *readings = (double *)malloc(num_sensors * sizeof(double));
    if (!readings) return -1;  // Handle allocation failure

    // Initialize array with zeros
    memset(readings, 0, num_sensors * sizeof(double));

    // Allocate array of char strings for sensor identifiers
