        hash_values[i] = (unsigned int)(uintptr_t)identifiers[i];  // Use the pointer as a hash value
    }

    for (int i = 0; i < num_sensors; i++) {
        for (int j = i + 1; j < num_sensors; j++) {
            if (hash_values[i] == hash_values[j]) return -1;  // Collision detected
        }
