void* crc_indication_thread(void* arg) {
    time_t last_flush = time(NULL);
    while (1) {
        // Check for expired timestamps
        pthread_mutex_lock(&log_mutex);
        rewind(log_file);
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size > LOG_FILE_SIZE_LB * 1024) {
            // Archive older logs and start fresh
            rewind(log_file);
            while (fread(&old_log_entry, sizeof(old_log_entry), 1, log_file)) {
                if (time(NULL) - old_log_entry.timestamp > 60) { // one minute old or more
                    // update timestamp for archived entry
                    fseek(log_file, ftell(log_file) - sizeof(old_log_entry), SEEK_SET);
                    fwrite(&new_timestamp, sizeof(new_timestamp), 1, log_file);
                } else {
                    break;
                }
            }
            fflush(log_file);
        }
        pthread_mutex_unlock(&log_mutex);

        // Update CRC_INDICATION_REL8_TAG timestamps
        for (int i = 0; i < list_count; i++) {
            if (list[i]->CRCFLAG) { // check for expired timestamp
                list[i]->CRC_INDICATION_REL8_TAG[15] = 
                    (unsigned char) ((time(NULL) >> 8) & 0xFF);
            }
        }

        // Sleep before the next iteration
        sleep(1); // adjust this value based on your needs
    }
}

void crc_indication_list_init(int max_size) {
    list_count = 0;
    for (int i = 0; i < max_size; i++) {
        list[i] = NULL;
    }
    sem_init(&list_lock, 1, 1);
    sem_init(&log_lock, 1, 1);
}

void crc_indication_list_add(NFAPI_CRC_INDICATION_PDU_T* entry) {
    sem_wait(&list_lock);
    if (list_count < MAX_LIST_SIZE) {
        list[list_count] = *entry;
        list_count++;
    }
    sem_post(&list_lock);
}

void crc_indication_list_remove(int rnti) {
    sem_wait(&list_lock);
    for (int i = 0; i < list_count; i++) {
        if (list[i]->RNTI == rnti) {
            list[i] = NULL;
            break;
        }
    }
    list_count--;
    sem_post(&list_lock);
}

int crc_indication_list_count() {
    int count = 0;
    sem_wait(&list_lock);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if (list[i] != NULL) {
            count++;
        } else {
            break;
        }
    }
    sem_post(&list_lock);
    return count;
}

