    int type; // 0: integer, 1: string, 2: nested object
    void* value;
} ConfigEntry;

ConfigEntry* config_entries;
int entry_count = 0;

int init_config_manager() {
    json_object* json_data = json_object_from_file(JSON_FILE);
    if (!json_data) {
        LOG_ERR("Failed to load JSON file");
        return -1;
    }

    config_entries = (ConfigEntry*)malloc(sizeof(ConfigEntry)*json_object_get_size(json_data));
    if (!config_entries) {
        LOG_ERR("Memory allocation failed");
        json_object_free(json_data);
        return -2;
    }

    entry_count = 0;

    // Populate config entries
    json_object_iter* iter;
    json_object_iter_init(json_data, NULL);
    while ((iter = json_object_iter_next(iter))) {
        ConfigEntry* entry = &config_entries[entry_count];
        entry->key = strdup(iter->key);
        if (!json_object_get_type(iter->value) == json_type_integer) {
            // Handle non-integer values
            LOG_ERR("Non-integer value encountered");
            free(entry->key);
            continue;
        }
        entry->type = 0; // integer
        entry->value = malloc(sizeof(int));
        *(int*)entry->value = (int)json_object_get_int(iter->value);
        entry_count++;
    }

    json_object_free(json_data);

    return entry_count;
}

void LOG_DBG(const char* fmt, ...) {
    va_list(ap);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
}

void LOG_ERR(const char* fmt, ...) {
    va_list(ap);
