// Define custom memory pool allocator structure
typedef struct {
    void* base;
    size_t capacity;
    size_t used;
} MemoryPool;

// Custom memory pool allocator function
MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->base = malloc(capacity);
    mp->capacity = capacity;
    mp->used = 0;
    return mp;
}

// Resize the memory pool to accommodate new data
void resize_memory_pool(MemoryPool* mp, size_t new_capacity) {
    void* new_base = realloc(mp->base, new_capacity);
    if (!new_base) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    mp->base = new_base;
    mp->capacity = new_capacity;
}

// Implement thread-safe linked list of event structures
typedef struct _event {
    time_t timestamp;
    char* message;
    int priority;
} Event;

typedef struct {
    Event* events;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
} EventList;

EventList* create_event_list(size_t capacity) {
    EventList* el = (EventList*)malloc(sizeof(EventList));
    el->events = (Event*)malloc(capacity * sizeof(Event));
    el->capacity = capacity;
    el->used = 0;
    pthread_mutex_init(&el->mutex, NULL);
    return el;
}

// Add an event to the linked list
void add_event(EventList* el, time_t timestamp, char* message, int priority) {
    pthread_mutex_lock(&el->mutex);
    if (el->used >= el->capacity) {
        resize_event_list(el, el->capacity * 2);
    }
    Event* new_event = &el->events[el->used++];
    new_event->timestamp = timestamp;
    new_event->message = message;
    new_event->priority = priority;
    pthread_mutex_unlock(&el->mutex);
}

// Implement robust error handling and resource management
