#include <time.h>

// Define the maximum allowed size of events
#define MAX_EVENTS 50000

// Define the structure for an event node in the linked list
typedef struct EventNode {
    long timestamp;
    char* message;
    struct EventNode* prev;
    struct EventNode* next;
} EventNode;

EventNode* create_event_node(long timestamp, char* message) {
    EventNode* node = (EventNode*) malloc(sizeof(EventNode));
    if (!node) return NULL;

    node->timestamp = timestamp;
    node->message = message;
    node->prev = NULL;
    node->next = NULL;

    return node;
}

// Function to dynamically allocate memory for and initialize event components
EventNode* initialize_events(int timestamps_size, int messages_size) {
    // Check for invalid input sizes
    if (timestamps_size <= 0 || messages_size <= 0 || timestamps_size + messages_size > MAX_EVENTS) return NULL;

    // Validate the total number of events does not exceed the maximum allowed size
    if (timestamps_size + messages_size > MAX_EVENTS) return NULL;

    // Dynamically allocate memory for arrays and linked list nodes
    long* timestamps = (long*) malloc(timestamps_size * sizeof(long));
    char** messages = (char**) malloc(messages_size * sizeof(char*));

    EventNode* head = NULL;
    EventNode* tail = NULL;

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < timestamps_size; i++) {
        long timestamp = rand() % (24 * 60 * 60 * 1000) + (long) time(NULL) - (24 * 60 * 60);
        timestamps[i] = timestamp;

        char buffer[64];
        sprintf(buffer, "Event at %ld", timestamp);
        messages[i] = (char*) malloc(strlen(buffer) + 1);
        strcpy(messages[i], buffer);
    }

    for (int i = 0; i < messages_size; i++) {
        head = create_event_node(timestamps[rand() % timestamps_size], messages[rand() % timestamps_size]);
        if (!head) return NULL;

        if (!tail) {
            tail = head;
        } else {
            tail->next = head;
            head->prev = tail;
            tail = head;
        }
    }

    // Ensure the linked list is properly terminated
    tail->next = NULL;

    // Initialize each element in the messages array with a formatted log message
    for (int i = 0; i < timestamps_size; i++) {
        sprintf(messages[i], "Log message at %ld", timestamps[i]);
    }

    // Free allocated memory before returning
    free(timestamps);
    for (int i = 0; i < messages_size; i++) {
        free(messages[i]);
    }

    return head;
}

void clean_up(EventNode* head) {
    EventNode* current = head;
    while (current) {
        EventNode* next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
}
