// Define structure for NODE
typedef struct {
    int node_id;
    size_t data_size;
    int access_count;
    char status;
} NODE;

// Define structure for linked list node
typedef struct {
    NODE *node;
    struct {
        struct list_node *next;
    } list_node;
} LIST_NODE;

// Function to initialize and manage a dynamic linked list of NODE structures
NODE *init_list() {
    // Create head node with NULL next pointer
    LIST_NODE *head = (LIST_NODE *)malloc(sizeof(LIST_NODE));
    head->list_node.next = NULL;
    return &head->node;
}

// Function to insert new node at end of the list
void insert_node(NODE *new_node, LIST_NODE **head) {
    LIST_NODE *new_list_node = (LIST_NODE *)malloc(sizeof(LIST_NODE));
    new_list_node->list_node.next = (*head)->list_node.next;
    (*head)->list_node.next = &new_list_node->list_node;
}

// Function to remove node from the list
void remove_node(NODE *node_to_remove, LIST_NODE **head) {
    LIST_NODE *current = *head;
    LIST_NODE *previous = NULL;

    while (current != NULL && current->list_node.next != NULL) {
        if (current->list_node.next->list_node.next == node_to_remove) {
            previous = current;
            break;
        }
        current = current->list_node.next;
    }

    if (current == NULL || current->list_node.next == NULL) {
        printf("Node not found in the list.\n");
    } else if (previous == NULL) {
        (*head)->list_node.next = current->list_node.next;
    } else {
        previous->list_node.next = current->list_node.next;
    }

    free(current);
}

// Function to sort nodes based on DATA_SIZE or ACCESS_COUNT
void sort_list(LIST_NODE **head, int sort_by) {
    LIST_NODE *current = *head;
    LIST_NODE *next = NULL;

    while (current != NULL && current->list_node.next != NULL) {
        next = current->list_node.next;
        if ((sort_by == 0 && current->node->data_size > next->node->data_size) ||
            (sort_by == 1 && current->node->access_count > next->node->access_count)) {
            NODE temp = *current->node;
            LIST_NODE temp_list = *current;
            *current = *next;
            *next = temp_list;

        }
        current = next;
    }
}

// Function to validate integrity of the list
void validate_list(LIST_NODE *head) {
    int id_count[10000] = {0};
    LIST_NODE *current = head;

    while (current != NULL) {
        if (id_count[current->node->node_id] > 1) {
            printf("Duplicate node IDs found.\n");
        }
        id_count[current->node->node_id]++;
        current = current->list_node.next;
    }
}

// Function to handle memory allocation failures
void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
    }
    return ptr;
}
