#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
} record;

void* allocate_and_init_arrays(int size, long** offset_values, int** keys, record** records) {
    *offset_values = (long*)malloc(size * sizeof(long));
    for (int i = 0; i < size; i++) {
        (*offset_values)[i] = i * sizeof(long);
    }

    *keys = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        (*keys)[i] = i;
    }

    *records = (record*)malloc(size * sizeof(record));
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % 100;
    }

    return NULL;
}

void validate_records(int* keys, record* records, int size) {
    pthread_t thread[2];
    pthread_create(&thread[0], NULL, (void*)validate_record_keys, &keys);
    pthread_create(&thread[1], NULL, (void*)validate_record_values, &records);
    for (int i = 0; i < size; i++) {
        if ((*keys)[i] == (*records)[i].value) {
            printf("Error: duplicate key-value pair found.\n");
            return;
        }
    }
}

void* validate_record_keys(void* ptr) {
    int* keys = (int*)ptr;
    for (int i = 0; i < size; i++) {
        if (hash_function(keys[i]) != NULL) {
            printf("Error: duplicate key found.\n");
            return NULL;
        }
    }
}

void* validate_record_values(void* ptr) {
    record* records = (record*)ptr;
    for (int i = 0; i < size; i++) {
        if (hash_function(&records[i]) != NULL) {
            printf("Error: duplicate value found.\n");
            return NULL;
        }
    }
}

void free_memory(long** offset_values, int** keys, record** records, int size) {
    for (int i = 0; i < size; i++) {
        free((char*)((*offset_values) + i));
        free((char*)((*keys) + i));
        free((char*)((*records) + i));
    }
    free(*offset_values);
    free(*keys);
    free(*records);
}

int main() {
    int size = 100;
    long* offset_values;
    int* keys;
    record* records;

    allocate_and_init_arrays(size, &offset_values, &keys, &records);

    validate_records(keys, records, size);

    free_memory(&offset_values, &keys, &records, size);

    return 0;
}
