#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* string;
    int identifier;
    double value;
} entry;

entry** initCollection(const char* config_file, const char* log_file) {
    FILE* config = fopen(config_file, "r");
    if (!config) return NULL;

    FILE* log = fopen(log_file, "r");
    if (!log) fclose(config), return NULL;

    int num_entries = 0;
    fscanf(config, "%d", &num_entries);

    entry** collection = (entry**)malloc((num_entries+1)*sizeof(entry*));
    for (int i = 0; i <= num_entries; i++) {
        collection[i] = (entry*)malloc(sizeof(entry));
        fscanf(config, " %s %d %lf",
               &collection[i]->string, &collection[i]->identifier, &collection[i]->value);
    }

    fclose(config);

    // merge log data
    char line[1024];
    while (fgets(line, 1024, log)) {
        int identifier;
        double value;
        fscanf(log, " %s %d %lf",
               &collection[num_entries]->string, &identifier, &value);
        if (strcmp(collection[num_entries-1]->string, line) == 0) {
            collection[num_entries]->identifier = identifier;
            collection[num_entries]->value = value;
        }
        num_entries++;
    }

    fclose(log);

    return collection;
}

entry** scaleValues(entry** collection, int num_entries, double factor) {
    entry** scaled_collection = (entry**)malloc((num_entries+1)*sizeof(entry*));
    for (int i = 0; i <= num_entries; i++) {
        if (!scaled_collection[i]) break;
        scaled_collection[i]->value *= factor;
    }

    free(collection);
    return scaled_collection;
}

void printCollection(entry** collection, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        printf("%s %d %.2f\n", collection[i]->string, collection[i]->identifier, collection[i]->value);
    }
}
