    int max = 200000; // user-provided maximum value

    long* offsets = (long*) allocate_array((max - min + 1) * sizeof(long));
    for (int i = 0; i < (max - min + 1); i++) {
        offsets[i] = (min + i);
    }

    int keys[] = {0, 1, 2}; // sample array of unique keys
    int* keys_ptr = (int*) allocate_array(sizeof(int) * sizeof(keys));
    memcpy(keys_ptr, keys, sizeof(keys));

    record* records = (record*) allocate_array((max - min + 1) * sizeof(record));
    for (int i = 0; i < (max - min + 1); i++) {
        records[i].key = offsets[i];
        records[i].value = rand() % 100; // random number within a specified range
    }

    // validate that no two records have the same key
    for (int i = 0; i < (max - min + 1); i++) {
        int found = 0;
        for (int j = 0; j < (max - min + 1); j++) {
            if (records[i].key == records[j].key) {
