typedef struct {
    int integer;
    double decimal;
    char* string;
} data_item;

// Doubly Linked List Implementation
typedef struct Node {
    data_item item;
    struct Node* prev;
    struct Node* next;
} node;

node* create_node(data_item item) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->item = item;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_node(node** head, data_item item) {
    node* new_node = create_node(item);
    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

void delete_node(node** head, data_item item) {
    node* current = *head;
    while (current != NULL && current->item.integer != item.integer
           && current->item.decimal != item.decimal
           && strcmp(current->item.string, item.string) != 0) {
        current = current->next;
    }
    if (current == NULL) return;

    node* prev = current->prev;
    node* next = current->next;
    if (prev != NULL) prev->next = next;
    else *head = next;
    if (next != NULL) next->prev = prev;
    free(current);
}

void print_list(node* head) {
    while (head != NULL) {
        printf("(%d, %f, %s)\n", head->item.integer, head->item.decimal,
               head->item.string);
        head = head->next;
    }
}

// Priority Queue Implementation
typedef struct {
    data_item item;
    int priority;
} task;

task* create_task(data_item item, int priority) {
    task* new_task = (task*)malloc(sizeof(task));
    new_task->item = item;
    new_task->priority = priority;
    return new_task;
}

void enqueue(task** head, task* new_task) {
    if (*head == NULL || new_task->priority > (*head)->priority) {
        *head = new_task;
    } else {
        task* current = *head;
        while (current->next != NULL && current->next->priority >= new_task->priority)
            current = current->next;
        new_task->next = current->next;
        current->next = new_task;
    }
}

task* dequeue(task** head) {
    if (*head == NULL) return NULL;
    task* next_task = (*head)->next;
    free(*head);
    *head = next_task;
    return *head;
}

void print_queue(task* head) {
    while (head != NULL) {
        printf("(%d, %f, %s, priority: %d)\n", head->item.integer, head->item.decimal,
               head->item.string, head->priority);
        head = head->next;
    }
}

int main() {
