int* allocate_and_initialize(int N) {
    int* offset_values = (int*)malloc((N + 1) * sizeof(int));
    int* keys = (int*)malloc((N + 1) * sizeof(int));
    struct record* records = (struct record*)malloc((N + 1) * sizeof(struct record));

    if (!offset_values || !keys || !records) {
        free(offset_values);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i <= N; i++) {
        offset_values[i] = i;
        keys[i] = i;
        records[i].val = rand() % 100 + 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(1024 * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_list) {
        free(offset_values);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i < N && i < 1024; i++) {
        crc_list[i].RNTI = i;
        crc_list[i].CRCFLAG = (i % 2 == 0) ? 1 : 0;
    }

    int* unique_rntis = (int*)malloc((N + 1) * sizeof(int));

    if (!unique_rntis) {
        free(offset_values);
        free(keys);
        free(records);
        free(crc_list);
        return NULL;
    }

    for (int i = 0; i < N && i < 1024; i++) {
        unique_rntis[i] = crc_list[i].RNTI;
    }

    int unique_count = N;

    for (int i = 1; i <= unique_count; i++) {
        for (int j = i + 1; j <= unique_count; j++) {
            if (unique_rntis[i] == unique_rntis[j]) {
                unique_count--;
                for (int k = i; k < unique_count; k++) {
                    unique_rntis[k] = unique_rntis[k + 1];
                }
                i--;
            }
        }
    }

    int* crc_list_unique = (int*)malloc((unique_count) * sizeof(int));

    if (!crc_list_unique) {
        free(offset_values);
        free(keys);
        free(records);
        free(crc_list);
        return NULL;
    }

    for (int i = 0; i < unique_count; i++) {
        crc_list_unique[i] = unique_rntis[i];
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_list_unique_ptr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_list_unique_ptr) {
        free(offset_values);
        free(keys);
        free(records);
        free(crc_list);
        free(crc_list_unique);
        return NULL;
    }

    for (int i = 0; i < unique_count; i++) {
        crc_list_unique_ptr[i].RNTI = crc_list_unique[i];
        crc_list_unique_ptr[i].CRCFLAG = (crc_list_unique[i] % 2 == 0) ? 1 : 0;
    }

    free(unique_rntis);
    free(crc_list_unique);

    return crc_list_unique_ptr;
}

