typedef struct record {
    int key;
    long offset;
    char *str;
    time_t timestamp;
} Record;

Record *manage_memory(void *buffer, int max_records) {
    void *start = buffer;
    void *end = ((char *)buffer) + BUFFER_SIZE;
    void *current = start;

    Record **records = (Record **)malloc(max_records * sizeof(Record *));
    if (!records) return NULL;

    long *offsets = (long *)malloc(max_records * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    int *keys = (int *)malloc(max_records * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        return NULL;
    }

    char **strings = (char **)malloc((max_records + 1) * sizeof(char *));
    for (int i = 0; i <= max_records; i++) {
        strings[i] = (char *)malloc(STRINGSIZE);
        if (!strings[i]) {
            free(offsets);
            free(keys);
            free(records);
            free(strings);
            return NULL;
        }
    }

    for (int i = 0; i < max_records; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            free(records);
            for (int j = 0; j <= i; j++) {
                free(strings[j]);
            }
            free(strings);
            return NULL;
        }
    }

    // Initialize records
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        keys[i] = rand() % 10000;
        offsets[i] = rand() % BUFFER_SIZE;
        time_t timestamp = time(NULL);
        char *str = strings[i];
        sprintf(str, "Record %d", i);

        records[i]->key = keys[i];
        records[i]->offset = offsets[i];
        records[i]->str = str;
        records[i]->timestamp = timestamp;
    }

    return *records;
}
