    data->d = (double)(rand() / (double)RAND_MAX);
    data->str = (char*)malloc(10); // Reserve 10 bytes for the string
    if (!data->str) {
        printf("String memory allocation failed!\n");
        free(data); // Free the ComplexData struct to prevent memory leak
        return NULL;
    }
    strcpy(data->str, "Random_string_"); // Initialize the char field with a random string
    return data;
}

// Function to dynamically manage the list of ComplexData structs
void* complex_data_manager(int* max_size) {
    int size = 0; // Current number of structures in the list
    ComplexData** list = (ComplexData**)malloc(sizeof(ComplexData*) * 10); // Initialize with a small capacity
    if (!list) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    int age_threshold = 5; // Configure the age threshold for cleaning up unused structures
    int cleanups = 0; // Track the number of cleanup operations

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Initialize a lock for concurrent access
    struct timespec last_cleanup_time = { .tv_sec = time(NULL), .tv_nsec = 0 }; // Record the timestamp of the last cleanup operation

    while (1) {
        pthread_mutex_lock(&lock);
        if (size >= *max_size) {
            printf("List exceeded maximum size!\n");
            break;
        }
        ComplexData* data = create_complex_data();
        if (!data) {
            pthread_mutex_unlock(&lock); // Release the lock to prevent deadlocks
            continue; // Try again on the next iteration
        }
        list[size++] = data;
        // Periodically clean up unused structures based on the age threshold
        if ((time(NULL) - last_cleanup_time.tv_sec) >= age_threshold) {
            for (int i = 0; i < size; i++) {
                if (!list[i]->str[0]) { // Check if the string is empty or has been deallocated
                    free(list[i]); // Free the structure and its components
                    list[i] = NULL;
                    cleanups++;
                    break;
                }
            }
            last_cleanup_time = *localtime(&time(NULL)); // Update the timestamp of the last cleanup operation
        }
        pthread_mutex_unlock(&lock); // Release the lock to allow concurrent access

        // Monitor and record memory allocation events
        char log_message[100];
        sprintf(log_message, "Memory allocated at %ld for data with f=%f, d=%lf, str='%s'\n", time(NULL), data->f, data->d, data->str);
        // Integrate the logging framework here to write the log message

        // Periodically resize the list based on its performance metrics
        if (size >= *max_size / 2) {
            int new_max_size = (*max_size + size) * 2; // Double the maximum size
            ComplexData** new_list = (ComplexData**)realloc(list, sizeof(ComplexData*) * new_max_size);
            if (!new_list) {
                printf("Memory reallocation failed!\n");
                break;
            }
            list = new_list;
        }
    }

    // Clean up and release the list
    for (int i = 0; i < size; i++) {
        free(list[i]->str); // Free the string components
        free(list[i]); // Free the structures
    }
    free(list);

    // Record termination events and performance metrics
    sprintf(log_message, "Memory deallocation completed at %ld with %d cleanups and %d active structures\n", time(NULL), cleanups, size);
    // Integrate the logging framework here to write the log message

    return NULL;
}

int main() {
    int max_size = 100; // Configure the maximum list size
    complex_data_manager(&max_size); // Start the dynamic management of ComplexData structs
    return 0;
