NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU(int n, int* total_unique_RNTIs) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    // Initialize cache
    char* rnti_cache = (char*)calloc(1 << 20, sizeof(char)); // 1MB cache size
    int cache Hits = 0;
    int cache Misses = 0;

    for (int i = 0; i < n; i++) {
        bool unique_RNTI = false;
        int rnti = 0;

        while (!unique_RNTI) {
            // Generate a random RNTI
            rnti = rand() % (1 << 20);

            // Check if the RNTI is unique in the cache or external data source
            unique_RNTI = check_unique_RNTI(rnti, &cache Hits, &cache Misses);
        }

        list[i].RX_UE_INFORMATION_TAG = i;
        list[i].RNTI = rnti;
