typedef struct {
    char* name;
    int age;
    float salary;
} entry_t;

void manage_memory(const char* dir_path) {
    DIR* dp = opendir(dir_path);
    if (dp == NULL) {
        printf("Error opening directory\n");
        return;
    }

    struct dirent* ep;
    int file_count = 0;
    while ((ep = readdir(dp)) != NULL) {
        if (strcmp(ep->d_name, ".") == 0 || strcmp(ep->d_name, "..") == 0)
            continue;

        file_count++;
    }
    closedir(dp);

    entry_t** entries = (entry_t**)malloc(file_count * sizeof(entry_t*));
    int total_entries = 0;
    for (int i = 0; i < file_count; i++) {
        char filename[256];
        sprintf(filename, "%s/%s", dir_path, ep->d_name);

        FILE* file = fopen(filename, "r");
        if (file == NULL) {
            printf("Error opening file: %s\n", filename);
            continue;
        }

        int entries_in_file = 0;
        while (1) {
            entry_t* entry = (entry_t*)malloc(sizeof(entry_t));
            char line[256];
            fgets(line, sizeof(line), file);

            if (line[0] == '#') // skip comments
                continue;

            char* token = strtok(line, ",");
            if (token == NULL || strlen(token) > 255) { // check for malformed entry
                free(entry);
                fclose(file);
                return;
            }

            entry->name = strdup(token);
            token = strtok(NULL, ",");
            entry->age = atoi(token);
            token = strtok(NULL, ",");
            entry->salary = atof(token);

            entries[i] = entry;
            total_entries++;
            entries_in_file++;

            if (ferror(file) || feof(file)) {
                break;
            }
        }

        fclose(file);
    }

    // print or process the data here
    printf("Total entries: %d\n", total_entries);

    for (int i = 0; i < file_count; i++) {
        free(entries[i]);
    }
    free(entries);
}
