#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    void* value;
    time_t expiration;
    size_t refCount;
} cacheEntry;

typedef struct {
    uint64_t hash;
    cacheEntry* entry;
    pthread_mutex_t lock;
} cacheNode;

typedef struct {
    size_t capacity;
    size_t size;
    cacheNode** table;
} cacheTable;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle memory allocation failure
        return NULL;
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int hash_function(int key, int capacity) {
    return key % capacity;
}

cacheTable create_cache_table(size_t capacity) {
    cacheTable table = (cacheTable)my_malloc(sizeof(*table));
    table->capacity = capacity;
    table->size = 0;
    table->table = (cacheNode**)my_calloc(capacity, sizeof(*table->table));
    return table;
}

void destroy_cache_table(cacheTable table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->table[i]->entry) {
            free(table->table[i]->entry.value);
        }
        my_free(table->table[i]);
    }
    my_free(table);
}

cacheNode* find_cache_node(cacheTable table, int key) {
    size_t index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->table[index]->lock);
    for (int i = 0; i < table->size; i++) {
        if (table->table[index]->entry[i].key == key) {
            pthread_mutex_unlock(&table->table[index]->lock);
            return &table->table[index]->entry[i];
        }
    }
    pthread_mutex_unlock(&table->table[index]->lock);
    return NULL;
}

cacheEntry* insert_cache_entry(cacheTable table, int key, void* value, time_t expiration) {
    size_t index = hash_function(key, table->capacity);
    cacheNode* node = &table->table[index];
    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < table->size; i++) {
        if (node->entry[i].key == key) {
            // Update existing entry
            node->entry[i].value = value;
            node->entry[i].expiration = expiration;
            return &node->entry[i];
        }
    }
    cacheEntry* new_entry = my_malloc(sizeof(*new_entry));
    new_entry->key = key;
    new_entry->value = value;
    new_entry->expiration = expiration;
    new_entry->refCount = 1;
    table->table[index]->entry[table->size++] = *new_entry;
    pthread_mutex_unlock(&node->lock);
    return new_entry;
}

void remove_cache_entry(cacheTable table, int key) {
    size_t index = hash_function(key, table->capacity);
    cacheNode* node = &table->table[index];
    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < table->size; i++) {
        if (node->entry[i].key == key) {
            // Decrement reference count
            node->entry[i].refCount--;
            if (node->entry[i].refCount == 0) {
                free(node->entry[i].value);
                my_free(node->entry[i]);
                table->size--;
                for (int j = i; j < table->size; j++) {
                    node->entry[j] = node->entry[j + 1];
                }
            } else {
                // Re-insert entry with updated reference count
                insert_cache_entry(table, key, node->entry[i].value, node->entry[i].expiration);
            }
            pthread_mutex_unlock(&node->lock);
            return;
        }
    }
    pthread_mutex_unlock(&node->lock);
}

void* get_cache_value(cacheTable table, int key) {
    size_t index = hash_function(key, table->capacity);
    cacheNode* node = &table->table[index];
    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < table->size; i++) {
        if (node->entry[i].key == key) {
            return node->entry[i].value;
        }
    }
    pthread_mutex_unlock(&node->lock);
    return NULL;
}

