#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

char* transform_filename(const char* filename) {
    // Extract the original extension
    size_t ext_len = strlen(filename) - 1;
    for (; ext_len > 0; --ext_len) if (filename[ext_len] == '.') break;

    const char* base = filename;
    while (*base && !isalpha(*base)) ++base;

    int seq_len = 0;
    while (*base && isalpha(*base)) {
        seq_len++;
        base++;
    }
    seq_len = MIN(seq_len, 10);

    // Generate the sequence of alphanumeric characters
    char* seq = (char*) malloc((seq_len + 1) * sizeof(char));
    int i = 0;
    for (; i < seq_len; ++i) {
        seq[i] = 'a' + (rand() % 26);
    }
    seq[i] = '\0';

    // Create the new filename with the modified extension
    time_t timestamp = time(NULL);
    char* checksum = (char*) malloc(10 * sizeof(char));
    sprintf(checksum, "%08x", (unsigned int) timestamp);

    char* version_id = (char*) malloc(5 * sizeof(char));
    strcpy(version_id, "V1.0");

    size_t new_len = strlen(filename) - ext_len + seq_len + strlen(checksum) + strlen(version_id) + 2;
    char* new_filename = (char*) malloc(new_len * sizeof(char));

    sprintf(new_filename, "%s-%s-%s.%s", base, seq, checksum, version_id);

    // Free temporary allocations
    free(seq);
    free(checksum);
    free(version_id);

    return new_filename;
}

int main() {
    const char* filenames[] = {"file1.txt", "file2.jpg", "file3.exe"};
    for (const char** filename : filenames) {
        printf("%s\n", transform_filename(*filename));
    }
    return 0;
}
