void* allocate_and_init_arrays(int n) {
    // Allocate memory for arrays based on user-provided size 'n'
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));

    if (!offsets || !keys) {
        return NULL;
    }

    // Initialize the arrays
    for (int i = 0; i < n; i++) {
        offsets[i] = i * 1000; // Initialize with some offset values
        keys[i] = -1;           // Initialize key values as unknown
    }

    // Allocate memory for array of 'record' structures
    struct record* records = (struct record*)malloc(n * sizeof(struct record));

    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the array of 'record' structures
    for (int i = 0; i < n; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    return records;
}

void set_random_key_values(int n, struct record* records) {
    // Set the value of each record's 'int' key field to a random value within a specified range
    srand(time(NULL)); // Initialize random seed
    int minKey = 0;     // Minimum allowed key value
    int maxKey = 1000;  // Maximum allowed key value

    for (int i = 0; i < n; i++) {
        int key;
        do {
            key = rand() % ((maxKey - minKey) + 1) + minKey;
        } while (key == records[i].key); // Ensure unique keys
        records[i].key = key;
    }
}

struct record* get_random_record(int n, struct record* records, int target_key) {
    // Retrieve a random record based on its 'int' key
    for (int i = 0; i < n; i++) {
        if (records[i].key == target_key) {
            return &records[i];
        }
    }

    return NULL;
}

void free_allocated_memory(void* ptr, int n) {
    // Free the allocated memory
    struct record* records = (struct record*)ptr;

    for (int i = 0; i < n; i++) {
        if (records[i].key != -1) {
            printf("Record with key %d: offset = %ld, key = %d\n", i + 1, records[i].offset, records[i].key);
        }
    }

    free(records);
    free((long*)records);
}

int main() {
    int n;
    // Initialize the number of records based on user input
    printf("Enter the number of records: ");
    scanf("%d", &n);

    if (n < 0) {
        return -1; // Handle error and exit
    }

    void* ptr = allocate_and_init_arrays(n);
    set_random_key_values(n, (struct record*)ptr);
    struct record* random_record = get_random_record(n, (struct record*)ptr, 500);

    if (random_record) {
        printf("Random record with key 500: offset = %ld, key = %d\n", random_record->offset, random_record->key);
    }

    free_allocated_memory(ptr, n);

    return 0;
}

