void process_list(int max_size, int **pdu_array) {
    // Initialize random number generator for CRCFLAG
    srand(time(NULL));

    int i = 0;
    int current_rnti;
    while (scanf("%d", &current_rnti) == 1 && i < max_size) {
        nfa_pi_crc_indication_pdu_t *pdu = (nfa_pi_crc_indication_pdu_t *)malloc(sizeof(nfa_pi_crc_indication_pdu_t));
        if (pdu == NULL) {
            printf("Memory allocation failed!\n");
            exit(1);
        }

        pdu->RX_UE_INFORMATION_TAG = current_rnti;
        pdu->RNTI = current_rnti;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 1000; // Randomly set CRCFLAG
        (*pdu_array)[i++] = pdu;

        for (int j = 0; j < i - 1; j++) {
            if ((*pdu_array)[j]->RNTI == current_rnti) {
                printf("Error: Duplicate RNTI detected! Terminating.\n");
                free(pdu);
                exit(1);
            }
        }
    }

    // Reset system state
    for (int k = 0; k < i; k++) {
        free((*pdu_array)[k]);
    }
}

void find_largest_rnti(int **pdu_array, int size) {
    int largest_rnti = (*pdu_array)[0]->RNTI;
    for (int i = 1; i < size; i++) {
        if ((*pdu_array)[i]->RNTI > largest_rnti)
            largest_rnti = (*pdu_array)[i]->RNTI;
    }
    printf("Largest RNTI: %d\n", largest_rnti);
}

