    int *pdu_array;

    // Read maximum list size from standard input
    if (scanf("%d", &max_size) != 1 || max_size <= 0) {
        printf("Invalid input! Exiting.\n");
        return 1;
    }

    // Dynamically allocate memory for the pdu array
    pdu_array = (int *)malloc(max_size * sizeof(int));
    if (pdu_array == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    // Process input list and validate RNTIs
    process_list(max_size, &pdu_array);

    // Find and print the largest RNTI
    int size = 0;
    for (int i = 0; i < max_size; i++) {
        if (pdu_array[i] != NULL) {
            size++;
        }
    }
    find_largest_rnti(&pdu_array, size);

    // Deallocate memory
    free(pdu_array);
    return 0;
}
