#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;
    int event_id;
    char* details;
} Event;

Event* processEvents(int num_events, long start_time, int interval) {
    Event* events = NULL;
    size_t capacity = 2;
    size_t size = 0;

    for (int i = 0; i < num_events; i++) {
        if (size >= capacity) {
            capacity *= 2;
            events = realloc(events, capacity * sizeof(Event));
        }

        Event* event = &events[size++];

        event->timestamp = start_time + (i * interval);
        event->event_id = i;

        size_t len = strlen("Event: This is a sample event details");
        event->details = malloc(len + 1);
        strcpy(event->details, "Event: This is a sample event details");
        event->details[len] = '\0';

        printf("Timestamp: %ld, Event ID: %d, Details: %s\n", event->timestamp, event->event_id, event->details);
    }

    return events;
}

int main() {
    int num_events = 5;
    long start_time = 1643723400; // Unix timestamp
    int interval = 10; // seconds

    Event* events = processEvents(num_events, start_time, interval);

    for (int i = 0; i < num_events; i++) {
        free(events[i].details);
    }

    free(events);

    return 0;
}
