#include <json/json.h>
#include "SchemaValidator.h"
#include "DynamicValueGenerator.h"

class ConfigurationManager {
public:
    ConfigurationManager() : config_{} {}

    void loadConfig(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file) {
            std::cerr << "Error loading configuration file: " << filePath << std::endl;
            return;
        }
        Json::Value root;
        try {
            Json::Reader reader;
            root = reader.parse(file);
            config_ = root;
            validateConfig();
        } catch (const Json::Exception& e) {
            std::cerr << "Error parsing configuration file: " << e.what() << std::endl;
        }
    }

    void saveConfig(const std::string& filePath) {
        std::ofstream file(filePath);
        if (!file) {
            std::cerr << "Error saving configuration file: " << filePath << std::endl;
            return;
        }
        Json::Value root = config_;
        file << root;
    }

    void validateConfig() {
        SchemaValidator validator;
        validator.validate(config_);
    }

private:
    Json::Value config_;
};
