#include <iostream>
#include <random>
#include <string>
#include <json/json.h>

class DynamicValueGenerator {
public:
    DynamicValueGenerator() : generator_(std::mt19937(std::time(0))) {}

    std::string generateValue(const std::string& type, const Json::Value& config) {
        if (type == "integer") {
            return generateInteger(config["min"], config["max"]);
        } else if (type == "double") {
            return generateDouble(config["min"], config["max"]);
        }
        // handle other types...
    }

private:
    std::mt19937 generator_;
    std::uniform_real_distribution<double> doubleDist_;
    std::uniform_int_distribution<int> intDist_;

    std::string generateInteger(int min, int max) {
        return std::to_string(intDist_(generator_));
    }

    std::string generateDouble(double min, double max) {
        return std::to_string(doubleDist_(generator_));
    }
};
