data_point** data_points = NULL;
int data_points_count = 0;

void add_data_point(int value, const char* id) {
    data_point* new_dp = (data_point*)malloc(sizeof(data_point));
    if (!new_dp) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    new_dp->value = value;
    new_dp->timestamp = time(NULL);
    new_dp->id = strdup(id);

    if (data_points_count == 0) {
        data_points = (data_point**)malloc(sizeof(data_point*) * 1);
    } else {
        data_points = (data_point**)realloc(data_points, sizeof(data_point*) * (data_points_count + 1));
    }

    data_points[data_points_count] = new_dp;
    data_points_count++;
}

void remove_data_point(const char* id) {
    for (int i = 0; i < data_points_count; i++) {
        if (!strcmp(data_points[i]->id, id)) {
            free(data_points[i]->id);
            free(data_points[i]);
            memmove(&data_points[i], &data_points[i + 1], sizeof(data_point*) * (data_points_count - i - 1));
            data_points_count--;
            return;
        }
    }
    printf("Error: Data point not found.\n");
}

void retrieve_data_point(const char* id, int* value_out, time_t* timestamp_out) {
    for (int i = 0; i < data_points_count; i++) {
        if (!strcmp(data_points[i]->id, id)) {
            *value_out = data_points[i]->value;
            *timestamp_out = data_points[i]->timestamp;
            return;
        }
    }
    printf("Error: Data point not found.\n");
}

void export_to_csv(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Error: File opening failed.\n");
        return;
    }

    for (int i = 0; i < data_points_count; i++) {
        fprintf(file, "%d,\"%s\",%ld\n", data_points[i]->value, data_points[i]->id, data_points[i]->timestamp);
    }
    fclose(file);
}

void free_data_points() {
    for (int i = 0; i < data_points_count; i++) {
        free(data_points[i]->id);
        free(data_points[i]);
    }
    free(data_points);
}
