    for (int i = 0; i < num_nodes; i++) {
        data_points[i] = (DataPoint*)malloc(sizeof(DataPoint));
        data_points[i]->value = drand48();
        sprintf(data_points[i]->str, "RandomString_%d", i);
        data_points[i]->ref_count = 1;
