typedef struct {
    double temperature;
    long timestamp;
} TempReading;

typedef struct {
    int count;
    TempReading readings[MAX_ALERTS];
} AlertList;

AlertList* create_alert_list() {
    return (AlertList*)malloc(sizeof(AlertList));
}

void add_alert(AlertList* alert_list, double temp, long timestamp) {
    if (alert_list->count < MAX_ALERTS) {
        alert_list->readings[alert_list->count].temperature = temp;
        alert_list->readings[alert_list->count].timestamp = timestamp;
        alert_list->count++;
    }
}

int check_threshold(AlertList* alert_list, double threshold) {
    for (int i = 0; i < alert_list->count; i++) {
        if (alert_list->readings[i].temperature > threshold) {
            return i;
        }
    }
    return -1;
}

void process_temperature(double temp, long timestamp, AlertList* alert_list) {
    pthread_mutex_lock(&mutex);
    add_alert(alert_list, temp, timestamp);
    pthread_mutex_unlock(&mutex);

    int idx = check_threshold(alert_list, THRESHOLD);
    if (idx != -1) {
        printf("Critical temperature reading: %f at timestamp %ld\n", alert_list->readings[idx].temperature, alert_list->readings[idx].timestamp);
    }
}

int main() {
    pthread_mutex_init(&mutex, NULL);

    AlertList* alert_list = create_alert_list();

    while (1) {
        process_temperature(23.0, 1643723900, alert_list);
        sleep(1); // simulate sensor data processing
    }

    return 0;
}

