#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define M 1000
#define X 20

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[4];
    unsigned short CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct dynamic_list {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    int size;
    int capacity;
} dynamic_list;

dynamic_list* create_dynamic_list() {
    dynamic_list* list = (dynamic_list*)malloc(sizeof(dynamic_list));
    list->entries = NULL;
    list->size = 0;
    list->capacity = M;
    return list;
}

int add_entry(dynamic_list* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->size >= list->capacity) {
        list->capacity += M;
        list->entries = realloc(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * list->capacity);
    }
    list->entries[list->size++] = entry;
    return 0;
}

int remove_entry(dynamic_list* list, int RNTI) {
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->RNTI == RNTI) {
            memmove(&list->entries[i], &list->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->size - i - 1));
            list->size--;
            return 0;
        }
    }
    return -1;
}

int get_entry_count(dynamic_list* list) {
    return list->size;
}

NFAPI_CRC_INDICATION_PDU_T* merge_lists(dynamic_list* list1, dynamic_list* list2) {
    NFAPI_CRC_INDICATION_PDU_T* merged_entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list1->size + list2->size));
    int i, j;
    for (i = 0, j = 0; i < list1->size && j < list2->size; i++, j++) {
        if (strcmp(list1->entries[i]->RX_UE_INFORMATION_TAG, list2->entries[j]->RX_UE_INFORMATION_TAG) < 0) {
            merged_entries[i] = *list1->entries[i];
            i++;
        } else {
            merged_entries[i] = *list2->entries[j];
            j++;
        }
    }
    while (i < list1->size) {
        merged_entries[i++] = *list1->entries[i];
    }
    while (j < list2->size) {
        merged_entries[i++] = *list2->entries[j++];
    }
    free(list1->entries);
    free(list2->entries);
    return merged_entries;
}

int serialize_list(dynamic_list* list, FILE* file) {
    int i;
    for (i = 0; i < list->size; i++) {
        fwrite(&list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    return 0;
}

int deserialize_list(dynamic_list* list, FILE* file) {
    int i;
    NFAPI_CRC_INDICATION_PDU_T* temp_entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * M);
    for (i = 0; !feof(file); i++) {
        fread(&temp_entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    list->size = i;
    list->entries = realloc(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * list->size);
    memcpy(list->entries, temp_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * list->size);
    free(temp_entries);
    return 0;
}

void* thread_safe_memcpy(void* dst, const void* src, size_t n) {
    __sync_lock_test_and_set(&mutex, 1);
    memcpy(dst, src, n);
    __sync_lock_release(&mutex);
}
