        return 0;
    }
}

void nfa_pi_crc_indication_pdu_list_free(void* head) {
    void* temp = head;
    while (temp != NULL) {
        void* next = ((NFAPI_CRC_INDICATION_PDU_T*)temp)->next;
        free(temp);
        temp = next;
