    new_rec->id = id;
    new_rec->str = strdup(str);
    new_rec->timestamp = time(NULL);

    // Check if the array needs to be resized
    if (record_count == 10) {
        records = (Record**)realloc(records, sizeof(Record*) * 20);
        record_count = 20;
    }

    records[record_count] = new_rec;
    record_count++;
}

