        }

        // Validate configuration settings
        if (configJson.count("IPAddresses") == 0 || configJson.count("PortNumbers") == 0 ||
            configJson.count("LoggingLevels") == 0 || configJson.count("InterComponentDependencies") == 0) {
            throw std::runtime_error("Invalid or missing configuration fields");
        }

        // Load IP addresses
        std::vector<std::string> ipAddresses;
        for (const auto& pair : configJson["IPAddresses"]) {
            ipAddresses.push_back(pair.second.get<std::string>());
        }

        // Load port numbers
        std::vector<int> portNumbers;
        for (const auto& pair : configJson["PortNumbers"]) {
            portNumbers.push_back(pair.second.get<int>());
        }

        // Load logging levels
        std::vector<std::string> loggingLevels;
        for (const auto& pair : configJson["LoggingLevels"]) {
            loggingLevels.push_back(pair.second.get<std::string>());
        }

        // Load inter-component dependencies
        std::map<std::string, std::vector<std::string>> interComponentDependencies;
        for (const auto& pair : configJson["InterComponentDependencies"]) {
            for (const auto& dependencyPair : pair.second) {
                interComponentDependencies[dependencyPair.first].push_back(dependencyPair.second);
            }
        }

        // Validate configuration settings
        for (const auto& ip : ipAddresses) {
            if (!validateIP(ip)) {
                throw std::runtime_error("Invalid IP address");
            }
        }

        for (int port : portNumbers) {
            if (port < 0 || port > 65535) {
                throw std::runtime_error("Invalid port number");
            }
        }

        for (const auto& level : loggingLevels) {
            if (!validateLoggingLevel(level)) {
                throw std::runtime_error("Invalid logging level");
            }
        }

        // Load configuration settings into the database
        try {
            pqxx::transaction tx("database_name");

            // Create tables if they do not exist
            tx.exec("CREATE TABLE IF NOT EXISTS log_config (ip_address text, port_number integer, logging_level text)");

            // Insert configuration settings into the database
            for (const auto& ip : ipAddresses) {
                tx.exec("INSERT INTO log_config VALUES ($1, $2, 'INFO')", ip, 0);
            }

            tx.commit();
        } catch (const pqxx::transaction_error& e) {
            throw std::runtime_error(e.what());
        }
    }

private:
    bool validateIP(const std::string& ip) {
        // Validate IP address format
        size_t pos = ip.find('.');
        if (pos == std::string::npos) return false;

        for (size_t i = 0; i < 4; ++i) {
            pos = ip.find('.', pos);
            if (pos == std::string::npos || pos > 15) return false;
            int num = stoi(ip.substr(i * 3, 3));
            if (num < 0 || num > 255) return false;
        }
        return true;
    }

    bool validateLoggingLevel(const std::string& level) {
        // Validate logging level
        for (const auto& validLevel : {"DEBUG", "INFO", "WARNING", "ERROR"}) {
            if (level == validLevel) return true;
        }
        return false;
    }
};

class DynamicValueGenerator {
public:
    DynamicValueGenerator(int minValue, int maxValue, bool inclusive)
        : minValue_(minValue), maxValue_(maxValue), inclusive_(inclusive) {}

    double generateRandomFloat() {
        if (!inclusive_) {
            // Generate a random float within the range [minValue + 1, maxValue]
            return static_cast<double>(rand()) / RAND_MAX * (maxValue - minvalue_) + minvalue_;
        } else {
            // Generate a random float within the range [minValue, maxValue]
            return static_cast<double>(rand()) / RAND_MAX * (maxValue_ - minValue_);
        }
    }

    int generateRandomInt() {
        if (!inclusive_) {
            // Generate a random integer within the range [minValue + 1, maxValue]
            return rand() % (maxValue_ - minvalue_) + minvalue_;
        } else {
            // Generate a random integer within the range [minValue, maxValue]
            return rand() % (maxValue_ - minValue_);
        }
    }

private:
    int minValue_;
    int maxValue_;
    bool inclusive_;
};

