use std::thread;
use std::sync::{Arc,Mutex};
use std::time::Duration;
use rand::Rng;
use xmltree::Xml;

struct NetworkConfig {
    tcp_buffer_size: Vec<usize>,
    tcp_timeout: Vec<Duration>,
    tcp_connection_limit: Vec<isize>,
    udp_buffer_size: Vec<usize>,
    udp_timeout: Vec<Duration>,
    udp_connection_limit: Vec<isize>,
}

impl NetworkConfig {
    fn new() -> Self {
        NetworkConfig {
            tcp_buffer_size: vec![1024; 5],
            tcp_timeout: vec![Duration::from_millis(100); 5],
            tcp_connection_limit: vec![10; 5],
            udp_buffer_size: vec![512; 5],
            udp_timeout: vec![Duration::from_millis(50); 5],
            udp_connection_limit: vec![20; 5],
        }
    }

    fn set_config(&mut self, protocol: &str, buffer_size: usize, timeout: Duration, connection_limit: isize) {
        match protocol {
            "tcp" => {
                self.tcp_buffer_size.push(buffer_size);
                self.tcp_timeout.push(timeout);
                self.tcp_connection_limit.push(connection_limit);
            }
            "udp" => {
                self.udp_buffer_size.push(buffer_size);
                self.udp_timeout.push(timeout);
                self.udp_connection_limit.push(connection_limit);
            }
            _ => panic!("Invalid protocol"),
        }
    }

    fn get_config(&self, protocol: &str) -> (&Vec<usize>, &Vec<Duration>, &Vec<isize>) {
        match protocol {
            "tcp" => (self.tcp_buffer_size.as_slice(), self.tcp_timeout.as_slice(), self.tcp_connection_limit.as_slice()),
            "udp" => (self.udp_buffer_size.as_slice(), self.udp_timeout.as_slice(), self.udp_connection_limit.as_slice()),
            _ => panic!("Invalid protocol"),
        }
    }
}

fn main() {
    let mut config = Arc::new(Mutex::new(NetworkConfig::new()));

    // Set network configuration
    *config.lock().unwrap() = NetworkConfig {
        tcp_buffer_size: vec![1024, 2048],
        tcp_timeout: vec![Duration::from_millis(100), Duration::from_millis(200)],
        tcp_connection_limit: vec![10, 20],
        udp_buffer_size: vec![512, 1024],
        udp_timeout: vec![Duration::from_millis(50), Duration::from_millis(100)],
        udp_connection_limit: vec![20, 30],
    };

    // Get network configuration
    let config = *config.lock().unwrap();
    println!("TCP buffer size: {:?}", config.tcp_buffer_size);
    println!("TCP timeout: {:?}", config.tcp_timeout);
    println!("TCP connection limit: {:?}", config.tcp_connection_limit);
}
