#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a record structure with an int value and a pointer to an offset
typedef struct {
    int value;
    long *offset_ptr;
} record;

// Function to manage dynamic memory allocation for the three data structures
void* manage_memory(int num_elements, int record_size) {
    // Allocate memory for the array of long offset values
    long *offset_array = (long*)malloc(num_elements * sizeof(long));

    // Check if allocation failed
    if (!offset_array) {
        free(offset_array);
        return NULL;
    }

    // Initialize the offset array with random values
    for (int i = 0; i < num_elements; i++) {
        offset_array[i] = rand();
    }

    // Allocate memory for the array of int keys
    int *key_array = (int*)malloc(num_elements * sizeof(int));

    // Check if allocation failed
    if (!key_array) {
        free(key_array);
        free(offset_array);
        return NULL;
    }

    // Initialize the key array with random values
    for (int i = 0; i < num_elements; i++) {
        key_array[i] = rand();
    }

    // Allocate memory for the array of record structures
    record *record_array = (record*)malloc(num_elements * sizeof(record));

    // Check if allocation failed
    if (!record_array) {
        free(key_array);
        free(offset_array);
        return NULL;
    }

    // Initialize the record array with random values and valid pointers from offset array
    for (int i = 0; i < num_elements; i++) {
        record_array[i].value = rand();
        record_array[i].offset_ptr = &offset_array[i];
    }

    // Periodically compact the record array to minimize memory fragmentation
    void* compact(record_array, num_elements);

    // Free allocated memory if any allocation failed
    free(key_array);
    free(offset_array);

    return record_array;
}

// Function to periodically compact the record array by reassigning elements to contiguous memory locations and updating pointers accordingly
void* compact(record *record_array, int num_elements) {
    // Reallocate memory for the record array with correct alignment
    record *new_record_array = (record*)realloc(record_array, num_elements * sizeof(record));

    if (!new_record_array) {
        return NULL;
    }

    // Update pointers in new record array to point to contiguous elements
    for (int i = 0; i < num_elements; i++) {
        new_record_array[i].offset_ptr = &record_array[i % num_elements].value;
    }

    return new_record_array;
