        auto it = std::find_if(orderList.begin(), orderList.end(),
                                [orderId](OrderItem& item) { return item.orderId == orderId; });
        if (it != orderList.end()) {
            orderList.erase(it);
            return true;
        }
        return false;
    }

    void updateProductPrice(int productId, double price) {
        std::lock_guard<std::mutex> lock(priceMutex);
        productPrices[productId] = price;
