#include <string>
#include <mutex>
#include <unordered_map>

class Item {
public:
    std::string name;
    int priorityLevel;
    double value;

    Item(std::string name, int priorityLevel, double value) : name(name), priorityLevel(priorityLevel), value(value) {}
};

class ResizableCollection {
private:
    std::vector<Item> items;
    size_t initialCapacity = 0;
    size_t maximumSize = 0;
    bool isShrinking = false;
    std::mutex resizeMutex;

public:
    ResizableCollection(size_t initialCapacity, size_t maximumSize) : initialCapacity(initialCapacity), maximumSize(maximumSize) {}

    void initialize(int itemCount) {
        items.reserve(initialCapacity);
        for (int i = 0; i < itemCount; ++i) {
            items.push_back(Item("Item" + std::to_string(i), i, static_cast<double>(i)));
        }
    }

    bool addItem(Item item) {
        if (items.size() >= maximumSize) {
            resizeMutex.lock();
            if (isShrinking) {
                isShrinking = false;
                items.shrink_to_fit();
            } else {
                items.reserve(items.capacity() * 2);
            }
            isShrinking = true;
            resizeMutex.unlock();
        }
        return true;
    }

    void iterateAndTransform(double (*transform)(double), int k) {
        std::vector<Item> result;
        for (auto& item : items) {
            double transformedValue = transform(item.value);
            if (k-- > 0) {
                result.push_back(Item(item.name, item.priorityLevel, transformedValue));
            }
        }
    }

    void registerTransformation(std::function<double(double)> transformation) {
        // Register the transformation
    }

    std::vector<Item> getTopItems(int k) {
        std::priority_queue<std::pair<int, Item>> priorityQueue;
        for (auto& item : items) {
            priorityQueue.push({item.priorityLevel, item});
        }
        std::vector<Item> result;
        while (!priorityQueue.empty() && result.size() < k) {
            result.push_back(priorityQueue.top().second);
            priorityQueue.pop();
        }
        return result;
    }

    void printCollection() {
        for (auto& item : items) {
            std::cout << "Item: " << item.name << ", Priority Level: " << item.priorityLevel << ", Value: " << item.value << std::endl;
        }
    }
};
