void crcIndicationList_init(Node** list) {
    *list = NULL;
}

int crcIndicationList_insert(Node** list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // error allocation
    new_node->data = data;
    new_node->next = *list;
    *list = new_node;
    return 0;
}

int crcIndicationList_delete(Node** list, Node* node) {
    if (*list == node) {
        *list = node->next;
        free(node);
        return 0;
    }
    Node* current = *list;
    while (current && current->next != node) current = current->next;
    if (!current) return -1; // not found
    current->next = node->next;
    free(node);
    return 0;
}

void crcIndicationList_cleanup(Node** list) {
    Node* current = *list;
    Node* next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    *list = NULL;
}

