#define RECORDS_DEFAULT_SIZE 10
#define OFFSET_RECORD_RATIO 2
#define KEY_RANGE_MIN -1000
#define KEY_RANGE_MAX 1000

typedef struct {
    int key;
} Record;

int processData(char* input, int keyRangeMin, int keyRangeMax) {
    char* error = NULL;

    // Parse the number of records from the user-provided string
    int numRecords = atoi(input);
    if (numRecords <= 0) {
        numRecords = RECORDS_DEFAULT_SIZE;
    }

    // Allocate memory for the Record array
    Record* recordArray = (Record*)malloc(numRecords * sizeof(Record));
    if (!recordArray) {
        error = "Error allocating memory for records.";
        return -1;
    }

    // Initialize the Record array with random key values within the specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        recordArray[i].key = rand() % ((keyRangeMax - keyRangeMin) + 1) + keyRangeMin;
    }

    // Calculate the size of the offset array based on the number of records
    int offsetArraySize = numRecords * OFFSET_RECORD_RATIO;

    // Allocate memory for the offset array
    long* offsetArray = (long*)malloc(offsetArraySize * sizeof(long));
    if (!offsetArray) {
        error = "Error allocating memory for offsets.";
        free(recordArray);
        return -1;
    }

    // Initialize the offset array with consecutive even numbers starting from 0
    for (int i = 0; i < numRecords; i++) {
        offsetArray[i] = i * 2;
        if (i > 0) {
            offsetArray[i] += offsetArray[i - 1];
        }
    }

    // Calculate the size of the MD5 hash buffer based on the input string length
    int md5BufferSize = strlen(input) + MD5_DIGEST_LENGTH + 1;

    // Allocate memory for the MD5 hash buffer and compute the hash
    char* md5Buffer = (char*)malloc(md5BufferSize * sizeof(char));
    if (!md5Buffer) {
        error = "Error allocating memory for MD5 hash.";
        free(recordArray);
        free(offsetArray);
        return -1;
    }

    // Compute the MD5 hash of the input string
    unsigned char* md5Data = (unsigned char*)input;
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, md5Data, strlen(input));
    unsigned char md5Digest[MD5_DIGEST_LENGTH];
    MD5_Final(md5Digest, &ctx);

    // Copy the MD5 hash to the buffer and null-terminate it
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(md5Buffer + i * 2, "%02x", md5Digest[i]);
    }
    md5Buffer[md5BufferSize - 1] = '\0';

    // Free allocated memory and return
    free(offsetArray);
    free(recordArray);

    return 0;
}
