#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

#define MAX_FILES 500
#define MAX_ENTRIES_PER_FILE 1000
#define CSV_MAX_LINE_LENGTH 1024
#define ENTRY_STRUCT_SIZE sizeof(entry)

typedef struct {
    char* name;
    int age;
    float salary;
} entry;

void manage_memory(const char* dir_path, int max_entries) {
    DIR* dp = opendir(dir_path);
    if (!dp) return; // Handle error

    int total_entries = 0;
    entry** entries = (entry**)malloc(MAX_FILES * sizeof(entry*));

    for (int i = 0; i < MAX_FILES; i++) {
        struct dirent* dent = readdir(dp);
        if (!dent || strcmp(dent->d_name, ".") == 0 || strcmp(dent->d_name, "..") == 0) continue;

        char file_path[CSV_MAX_LINE_LENGTH];
        sprintf(file_path, "%s/%s", dir_path, dent->d_name);

        FILE* file = fopen(file_path, "r");
        if (!file) {
            fprintf(stderr, "Error opening file %s\n", file_path);
            break;
        }

        entry* current_file_entries = (entry*)malloc(MAX_ENTRIES_PER_FILE * ENTRY_STRUCT_SIZE);
        int file_entries_count = 0;

        while (1) {
            char line[CSV_MAX_LINE_LENGTH];
            if (!fgets(line, CSV_MAX_LINE_LENGTH, file)) break; // End of file

            // Parse entry from CSV line
            entry* entry_ptr = current_file_entries + file_entries_count;
            sscanf(line, "%[^,],%d,%f", &entry_ptr->name, &entry_ptr->age, &entry_ptr->salary);

            if (!entry_ptr->name || entry_ptr->age < 0) {
                // Invalid or malformed entry
                fprintf(stderr, "Invalid entry in file %s: skipping\n", file_path);
                free(current_file_entries);
                fclose(file);
                break;
            }

            file_entries_count++;
            total_entries++;

            if (total_entries > max_entries) {
                // Reached maximum entries limit
                free(current_file_entries);
                fclose(file);
                for (int j = 0; j < i; j++) free(entries[j]);
                free(entries);
                return;
            }
        }

        fclose(file);
        entries[i] = current_file_entries;
    }

    closedir(dp);

    // Now process and manage the managed memory
    // ...
}
