record* generate_records(int max_limit, int min_key_range, int max_key_range) {
    // Initialize arrays for offset values and keys
    long* offsets = (long*)malloc(max_limit * sizeof(long));
    int* keys = (int*)malloc(max_limit * sizeof(int));

    srand((unsigned)time(NULL)); // Set random seed

    record* records = NULL;
    int num_records = 0;

    for (int i = 0; i < max_limit; i++) {
        long offset = (long)srand() % 100; // Randomize offset value
        int key = rand() % (max_key_range - min_key_range) + min_key_range; // Randomize key within range

        if (num_records >= max_limit) {
            break;
        }

        // Initialize record structure with random values and tags
        record* new_record = (record*)malloc(sizeof(record));
        new_record->offset = offset;
        new_record->key = key;
        // ... initialize other fields ...

        // Add to records array
        if (!records) {
            records = new_record;
        } else {
            record* prev = records;
            while (*prev != NULL && (*prev)->key < key) {
                prev = &((*prev)->offset);
            }
            *prev = new_record;
        }

        num_records++;
    }

    // Allocate memory for CRC flags
    int* crc_flags = (int*)malloc(num_records * sizeof(int));
    for (int i = 0; i < num_records; i++) {
        crc_flags[i] = (rand() % 2); // Randomize CRC flag value
    }

    // Initialize CRC indication tags
