        record* rec = &records[i];
        rec->ue_info_tag.crc_indication.rel8_tag.crcflag = crc_flags[i];
    }

    free(offsets);
    free(keys);
    free(crc_flags);

    return records;
}

void sort_records(record* records, int num_records) {
