        fprintf(output_file, "%ld %d %x\n", sorted_records[i].offset, sorted_records[i].key, sorted_records[i].ue_info_tag.crc_indication.rel8_tag.crcflag);
    }
    fclose(output_file);
}

record* quicksort(record* arr, int n) {
    if (n < 2)
        return arr;

    record pivot = arr[0];
    record* i = arr + 1;
    record* j = arr + n - 1;

    while (*j >= *i) {
        // ... perform partitioning ...
        i++;
        j--;
    }

    if (i <= &arr[n-1]) {
        // ... shift elements around pivot ...
        return NULL;
    }
}
