// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the collection structure
typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Collection;

// Function to initialize a new collection with initial size and maximum capacity
Collection* init_collection(size_t initial_size, size_t max_capacity) {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    collection->records = (Record*)calloc(initial_size, sizeof(Record));
    collection->capacity = initial_size;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

// Function to resize the collection
void resize_collection(Collection* collection, size_t new_capacity) {
    // Calculate the number of records that need to be moved
    size_t num_records_to_move = new_capacity - collection->capacity;

    // Allocate new memory for the records
    Record* new_records = (Record*)calloc(new_capacity, sizeof(Record));

    // Copy the existing records into the new array
    memcpy(new_records, collection->records, collection->count * sizeof(Record));

    // Update the capacity and count of the collection
    free(collection->records);
    collection->records = new_records;
    collection->capacity = new_capacity;

    // Check if the record count exceeds the capacity
    if (collection->count > new_capacity) {
        collection->count = new_capacity;
    }
}

// Function to add a new record to the collection
void add_record(Collection* collection, Record* record) {
    pthread_mutex_lock(&collection->mutex);

    // Check if the collection needs resizing
    if (collection->count >= collection->capacity * 0.75) {
        resize_collection(collection, collection->capacity * 2);
    }

    // Add the new record to the end of the array
    memcpy(&collection->records[collection->count], record, sizeof(Record));
    collection->count++;

    pthread_mutex_unlock(&collection->mutex);
}

// Function to transform the value of each record in the collection
void transform_values(Collection* collection, int (*transform)(int)) {
    for (size_t i = 0; i < collection->count; i++) {
        Record* record = &collection->records[i];
        record->value = transform(record->value);
    }
}

// Function to register a custom transformation operation
void register_transform(int (*operation)(int), void** operations) {
    *operations = operation;
}

// Function to apply the registered transformations to the records in the collection
void apply_transformations(Collection* collection, void** operations) {
    for (size_t i = 0; i < collection->count; i++) {
        Record* record = &collection->records[i];
        void* op = *operations;
        if (op != NULL) {
            record->value = ((int(*)(int))op)(record->value);
        }
    }
}

// Function to get the top k records with the highest usage frequencies
void get_top_k_records(Collection* collection, size_t k, Record** result) {
