#define MAX_THREADS 100
#define LOG_BUFFER_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex;
pthread_rwlock_t read_write_lock;

void* crc_indication_thread_func(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < 10; i++) { // Simulate CRC indications
        NFAPI_CRC_INDATION_PDU_T indication;
        indication.RX_UE_INFORMATION_TAG = rand();
        indication.RNTI = rand();
        indication.CRC_INDICATION_REL8_TAG = rand();
        indication.CRCFLAG = rand() % 2;

        pthread_rwlock_wrlock(&read_write_lock);
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->data = indication;
        new_node->next = head;
        head = new_node;
        pthread_rwlock_unlock(&read_write_lock);

        // Record detailed information about each CRC indication
        char log_buffer[LOG_BUFFER_SIZE];
        sprintf(log_buffer, "Thread %d: RX_UE_INFORMATION_TAG=%d RNTI=%d CRC_INDICATION_REL8_TAG=%d CRCFLAG=%d\n", thread_id, indication.RX_UE_INFORMATION_TAG, indication.RNTI, indication.CRC_INDICATION_REL8_TAG, indication.CRCFLAG);
        // Call external logging API here
    }
    return NULL;
}

void crc_indication_thread_manager(int num_threads) {
    pthread_t threads[MAX_THREADS];
    int thread_args[MAX_THREADS];

    for (int i = 0; i < num_threads; i++) {
        thread_args[i] = i;
        if (pthread_create(&threads[i], NULL, &crc_indication_thread_func, &thread_args[i]) != 0) {
            perror("Thread creation failed");
            exit(1);
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void crc_indication_cleanup() {
    Node* current = head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL; // Reset the list head
}

int main() {
    int num_threads = 5; // Number of concurrent threads

    crc_indication_thread_manager(num_threads);

    return 0;
}
