#include "lte_phy.h"
#include "gps_api.h"
#include "weather_api.h"
#include "telemetry_service.h"

void lte_phy_init_config() {
    LTEPHYMODERANGE_T modulation_modes[] = {
        // Define different modulation schemes and their corresponding configurations
        {"QPSK", 10, 1000, 200},
        {"16QAM", 20, 500, 150},
        {"64QAM", 30, 300, 100}
    };

    int num_modes = sizeof(modulation_modes) / sizeof(LTEPHYMODERANGE_T);

    for (int i = 0; i < num_modes; i++) {
        LTEPHYRXINFO_T rx_info;

        // Initialize frequency offset based on modulation scheme
        switch (modulation_modes[i].mode) {
            case "QPSK":
                rx_info.freq_offset = 100;
                break;
            case "16QAM":
                rx_info.freq_offset = 50;
                break;
            case "64QAM":
                rx_info.freq_offset = 20;
                break;
        }

        // Initialize signal strength based on modulation scheme
        switch (modulation_modes[i].mode) {
            case "QPSK":
                rx_info.signal_strength = 10;
                break;
            case "16QAM":
                rx_info.signal_strength = 5;
                break;
            case "64QAM":
                rx_info.signal_strength = 2;
                break;
        }

        // Calculate temperature compensation factor based on modulation scheme
        switch (modulation_modes[i].mode) {
            case "QPSK":
                rx_info.temp_compensation = 1.5;
                break;
            case "16QAM":
                rx_info.temp_compensation = 1.2;
                break;
            case "64QAM":
                rx_info.temp_compensation = 1.0;
                break;
        }

        // Initialize GPS time synchronization
        gps_time_t gps_time;
        gps_api_get_time(&gps_time);

        // Get weather data from API
        weather_data_t weather_data;
        weather_api_get_data(&weather_data);

        // Calculate signal prediction based on weather conditions
        double signal_pred = calculate_signal_prediction(weather_data.temperature, 
                                                            weather_data.humidity, 
                                                            modulation_modes[i].mode);

        // Initialize telemetry service with current system status and weather data
        telemetry_service_init(gps_time, weather_data);

        // Prioritize signal strength over other parameters when GPS module experiences temporary failures
        if (gps_api_get_status() == GPS_API_FAILURE) {
            rx_info.freq_offset = 0;
            rx_info.signal_strength = 100;
            temp_compensation = 1.0;
        }

        // Populate list of LTEPHYRXINFO_T structures for each modulation mode
        lte_phy_rx_info_list[i] = &rx_info;

        // Fallback mechanism to use historical weather data in case of missing live data
        if (weather_data.status == WEATHER_API_FAILURE) {
            weather_data_t historic_weather;
            get_historic_weather(&historic_weather);
            signal_pred = calculate_signal_prediction(historic_weather.temperature, 
                                                       historic_weather.humidity, 
                                                       modulation_modes[i].mode);
        }

        // Log system status and configuration
        log_system_status(gps_time, weather_data, modulation_modes[i]);
    }
}
