#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 10000
#define RECORD_LENGTH 20
#define KEY_RANGE (-32768, 32767)
#define OFFSET_RANGE (-2147483648, 2147483647)

typedef struct {
    int key;
    long offset;
    char text[RECORD_LENGTH];
} record;

record* createRecords(int keys_size, int offsets_size);
void initArrays(int* keys, long* offsets, int keys_size, int offsets_size);
char* generateRecordString(int key, long offset);
int compareRecords(const void* a, const void* b);
bool validateRecords(record* records, int size);
record* sortRecords(record* records, int size);

record* createRecords(int keys_size, int offsets_size) {
    if (keys_size + offsets_size > MAX_RECORDS) return NULL;
    record* records = malloc((keys_size + offsets_size) * sizeof(record));
    if (!records) return NULL;
    for (int i = 0; i < keys_size; i++) {
        // Initialize key and offset arrays
        records[i].key = i;
        records[i].offset = i;
        strcpy(records[i].text, generateRecordString(i, i));
    }
    for (int i = keys_size; i < keys_size + offsets_size; i++) {
        records[i] = records[i - keys_size];
    }
    return records;
}

void initArrays(int* keys, long* offsets, int keys_size, int offsets_size) {
    if (keys_size > 0 && keys_size <= MAX_RECORDS / 2) {
        for (int i = 0; i < keys_size; i++) {
            keys[i] = i;
        }
    } else {
        // Handle invalid input
    }
    if (offsets_size > 0 && offsets_size + keys_size <= MAX_RECORDS) {
        for (int i = 0; i < offsets_size; i++) {
            offsets[i] = i;
        }
    } else {
        // Handle invalid input
    }
}

char* generateRecordString(int key, long offset) {
    static char buffer[RECORD_LENGTH];
    sprintf(buffer, "%d %ld", key, offset);
    return buffer;
}

int compareRecords(const void* a, const void* b) {
    record* rec1 = (record*)a;
    record* rec2 = (record*)b;
    if (rec1->key < rec2->key) return -1;
    else if (rec1->key > rec2->key) return 1;
    else return 0;
}

bool validateRecords(record* records, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (records[i].key == records[j].key) {
                return false;
            }
        }
    }
    return true;
}

record* sortRecords(record* records, int size) {
    qsort(records, size, sizeof(record), compareRecords);
    return records;
}
