    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->list = (GTPv2_C_PATH_STATUS_INDICATION*)realloc(list->list, list->capacity * sizeof(GTPv2_C_PATH_STATUS_INDICATION));
    }
    list->list[list->size] = element;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void gtpv2_c_path_status_indication_list_validate(GTPv2_C_PATH_STATUS_INDICATION_LIST* list) {
    for (int i = 0; i < list->size; i++) {
        if (list->list[i]->rx_ue_information_tag != 0) {
            printf("Duplicate RX UE INFORMATION TAG found!\n");
            exit(1);
