    }
}

void gtpv2_c_path_status_indication_list_cleanup(GTPv2_C_PATH_STATUS_INDICATION_LIST* list, time_t threshold) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (time(NULL) - list->list[i]->creation_time > threshold) {
            free(list->list[i]);
            memmove(list->list + i, list->list + i + 1, (list->size - i - 1) * sizeof(GTPv2_C_PATH_STATUS_INDICATION));
            list->size--;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void gtpv2_c_path_status_indication_list_log_memory_events(GTPv2_C_PATH_STATUS_INDICATION_LIST* list, const char* event) {
