#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int size = 0;

void add_element(int RX_UE_INFORMATION_TAG, int RNTI) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    if (head == NULL) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    size++;
}

void print_list() {
    Node* temp = head;
    while (temp != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", temp->data.RX_UE_INFORMATION_TAG, temp->data.RNTI, temp->data.CRCFLAG);
        temp = temp->next;
    }
}

void free_list() {
    Node* temp = head;
    while (temp != NULL) {
        Node* next_node = temp->next;
        free(temp);
        temp = next_node;
    }
}
