#include <time.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000
#define MAX_DATA_LENGTH 1000
#define PRUNE_INTERVAL 10

typedef struct {
    time_t timestamp;
    size_t data_length;
    unsigned char* data;
} UDT_DATA_RECORD;

UDT_DATA_RECORD** dynamic_array = NULL;
size_t array_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int prune_count = 0;

void* allocate_data(size_t length) {
    return malloc(length);
}

void free_data(void* ptr) {
    free(ptr);
}

void* resize_array(size_t new_size) {
    UDT_DATA_RECORD** new_array = realloc(dynamic_array, sizeof(UDT_DATA_RECORD*) * new_size);
    if (!new_array) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    dynamic_array = new_array;
    array_size = new_size;
    return dynamic_array;
}

void prune_array() {
    pthread_mutex_lock(&lock);
    if (array_size <= PRUNE_INTERVAL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    size_t prune_size = array_size - PRUNE_INTERVAL;
    UDT_DATA_RECORD** new_array = realloc(dynamic_array, sizeof(UDT_DATA_RECORD*) * prune_size);
    if (!new_array) {
        printf("Memory allocation failed!\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    dynamic_array = new_array;
    array_size = prune_size;

    for (size_t i = 0; i < prune_size; i++) {
        free_data(dynamic_array[i]->data);
        free(dynamic_array[i]);
    }
    pthread_mutex_unlock(&lock);
}

void* add_record(void* ptr) {
    pthread_mutex_lock(&lock);

    if (!dynamic_array || array_size == MAX_ARRAY_SIZE) {
        size_t new_size = MAX_ARRAY_SIZE * 2;
        void* temp = resize_array(new_size);
        if (!temp) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        dynamic_array = (UDT_DATA_RECORD**)temp;
    }

    UDT_DATA_RECORD* record = malloc(sizeof(UDT_DATA_RECORD));
    if (!record) {
        printf("Memory allocation failed!\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    record->timestamp = time(NULL);
    record->data_length = rand() % (MAX_DATA_LENGTH - 100 + 1) + 100;
    void* data = allocate_data(record->data_length);
    if (!data) {
        free(record);
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    record->data = data;

    pthread_mutex_unlock(&lock);

    return record;
}

void destroy_record(void* ptr) {
    UDT_DATA_RECORD* record = (UDT_DATA_RECORD*)ptr;
    free_data(record->data);
    free(record);
}
