        transactions[i].data.id = i;
        transactions[i].data.value = (float)rand() / RAND_MAX * 100.0f;
        status_array[i] = 'P'; // Initial status: pending
    }

    // Deallocate memory when exiting the function
    free(status_array);
    free(items);
    free(transactions);
}
