typedef struct {
    double value;
    unsigned long id;
    char data[256];
} data_entry;

size_t process_dataset(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return 0;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int count = 0;

    size_t entry_size = sizeof(data_entry);
    size_t initial_allocation = 100; // adjust this based on the expected dataset size
    data_entry** entries = (data_entry**)malloc(initial_allocation * sizeof(data_entry*));

    if (!entries) {
        fclose(file);
        return 0;
    }

    pthread_mutex_lock(&lock);

    char buffer[1024];
    while (fscanf(file, "%lf %lu %s", &entries[count]->value, &entries[count]->id, buffer) == 3 && strlen(buffer) <= 255) {
        entries[count] = realloc(entries[count], entry_size);
        strcpy(entries[count]->data, buffer);
        count++;
        if (count >= initial_allocation) {
            size_t new_allocation = initial_allocation * 2;
            data_entry** new_entries = (data_entry**)malloc(new_allocation * sizeof(data_entry*));
            for (size_t i = 0; i < count; i++) {
                new_entries[i] = entries[i];
            }
            free(entries);
            entries = new_entries;
            initial_allocation = new_allocation;
        }
    }

    pthread_mutex_unlock(&lock);

    fclose(file);

    return count;
}
