struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

NFAPI_CRC_INDICATION_PDU_T* createNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) return NULL;

    srand(time(NULL)); // Ensure random numbers
    int randomFlag = rand() % 2; // Randomly set CRCFLAG

    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = randomFlag;

    return newNode;
}

void createLinkedList(int N, struct Node** headRef) {
    *headRef = NULL;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newNode = createNode(i, i, i);

        if (!newNode) return; // If memory allocation fails

        struct Node* newNodeStruct = (struct Node*)malloc(sizeof(struct Node));
        if (!newNodeStruct) return; // If memory allocation fails

        newNodeStruct->data = newNode->data;
        newNodeStruct->next = *headRef;

        *headRef = newNodeStruct;
    }
}

void validateCRCFlags(struct Node* head) {
    int prevFlag = -1;

    while (head != NULL) {
        if (head->data.CRCFLAG == prevFlag) {
            printf("Error: Consecutive nodes have the same CRCFLAG value\n");
            return; // Exit on first error
        }

        prevFlag = head->data.CRCFLAG;

        head = head->next;
    }

    printf("CRC flags validated successfully\n");
}

void destroyLinkedList(struct Node* head) {
    struct Node* temp = head;

    while (temp != NULL) {
        struct Node* nextNode = temp->next;
        free(temp);
        temp = nextNode;
    }
}
