    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

// Function to add a new node at the end of the list
void nfa_list_add_tail(NfaNode** tail, NFAPI_CRC_INDICATION_PDU_T* data) {
    NfaNode* new_node = nfa_node_create(data);
    if (*tail == NULL) {
        *tail = new_node;
