        new_node->prev = *tail;
        (*tail)->next = new_node;
        *tail = new_node;
    }
}

// Function to remove a node from the list
void nfa_list_remove(NfaNode** head, NfaNode* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        *tail = node->prev;
    }
}

