    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->mem_blocks = (void**)malloc(block_size * sizeof(void*));
    pool->block_size = block_size;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Function to allocate memory from the pool
void* mem_pool_alloc(struct MemoryPool* pool) {
    void* block = pool->mem_blocks[0];
    pool->mem_blocks[0] = NULL;
    return block;
}

// Function to deallocate memory and recycle it back into the pool
void mem_pool_free(struct MemoryPool* pool, void* block) {
    pool->mem_blocks[0] = block;
}

// Custom logger for tracking node creation, modification, and deletion
void nfa_logger_log(NfaNode* node, char* action) {
