NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int max_records, int buffer_size) {
    // Initialize the linked list and its nodes
    NFAPI_CRC_INDICATION_PDU_T* head = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T** nodes = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_records * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Create the nodes and set their values
    int crc_flags[max_records];
    for (int i = 0; i < max_records; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Set the values of the node
        node->RX_UE_INFORMATION_TAG = 1;
        node->RNTI = i;
        node->CRC_INDICATION_REL8_TAG = i;

        int crc_flag = rand() % 2; // Generate a random CRC flag that adheres to the performance constraint
        while (i > 0 && crc_flags[i - 1] == crc_flag) {
            crc_flag = (crc_flag + 1) % 2; // Ensure no two consecutive nodes have the same CRC flag value
        }
        node->CRCFLAG = crc_flag;

        // Store the node and its CRC flag in the linked list and array, respectively
        nodes[i] = node;
        crc_flags[i] = node->CRCFLAG;

        if (i > 0) {
            // Link the current node to the previous one
            node->prev = &nodes[i - 1]->next;
            nodes[i - 1]->next = &node->next;
        } else {
            head = node;
        }
    }

    // Validate the CRC flags across the linked list for correctness and efficiency
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        if (crc_flags[0] == current->CRCFLAG) {
            printf("Error: Consecutive nodes have the same CRC flag value.\n");
            free(current);
            return NULL;
        }
        current = current->next;
    }

    // Return the linked list
    return head;
}

void destroy_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}
