    TASK_COMPLETED
} task_status;

typedef struct {
    char* name;
    int priority;
    task_status status;
} task_t;

task_t** tasks = NULL;
int num_tasks = 0;

// Function to initialize the list of tasks
void init_task_list() {
    pthread_mutex_init(&tasks_lock, NULL);
}

// Function to add a new task
int add_task(task_t* task) {
    // Allocate memory for the new task and update the list
    task_t** temp_tasks = (task_t**) realloc(tasks, sizeof(task_t*) * (num_tasks + 1));
    if(temp_tasks == NULL) return -1;
    tasks = temp_tasks;
    tasks[num_tasks] = task;
    num_tasks++;
    return 0;
}

// Function to update the status of a task
int update_task_status(int index, task_status new_status) {
    // Check if the task exists and its index is within bounds
    if(index >= 0 && index < num_tasks) {
        tasks[index]->status = new_status;
        return 0;
    }
    return -1;
}

// Function to list all tasks
void list_tasks() {
    for(int i=0; i<num_tasks; i++) {
        printf("Task %s: Priority %d, Status: %s\n", tasks[i]->name, tasks[i]->priority, task_status_to_string(tasks[i]->status));
    }
}

// Helper function to convert task status to string
char* task_status_to_string(task_status status) {
    switch(status) {
        case TASK_NEW:
            return "New";
        case TASK_IN_PROGRESS:
            return "In Progress";
        case TASK_COMPLETED:
            return "Completed";
    }
}

int main() {
    init_task_list();
    // Add tasks, update their status, and list them
    task_t* task1 = (task_t*)malloc(sizeof(task_t));
    task1->name = strdup("Task 1");
    task1->priority = 3;
    task1->status = TASK_NEW;

    int result = add_task(task1);

    // Update the status of a task
    result = update_task_status(0, TASK_IN_PROGRESS);

    // List all tasks
    list_tasks();

    return 0;
}
