// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

// Function to process game session
void processGameSession(int& arraySize, vector<NFAPI_CRC_INDICATION_PDU_T>& crcArray) {
    // Initialize the attack cooldown timers
    chrono::steady_clock::time_point attackACooldownTime = chrono::steady_clock::now();
    chrono::steady_clock::time_point attackBCooldownTime = chrono::steady_clock::now();
    chrono::steady_clock::time_point attackCCooldownTime = chrono::steady_clock::now();

    // Initialize the last selected attack
    int lastAttack = -1;

    while (true) {
        // Select a random attack
        int randomAttack = rand() % 3;
        if (randomAttack == 0 && chrono::duration_cast<chrono::seconds>(chrono::steady_clock::now().time_since_epoch()).count() > (attackACooldownTime + chrono::seconds(9)).count()) {
            lastAttack = 0; // Attack A selected
            attackACooldownTime = chrono::steady_clock::now();
        } else if (randomAttack == 1 && chrono::duration_cast<chrono::seconds>(chrono::steady_clock::now().time_since_epoch()).count() > (attackBCooldownTime + chrono::seconds(15)).count()) {
            lastAttack = 1; // Attack B selected
            attackBCooldownTime = chrono::steady_clock::now();
        } else if (randomAttack == 2 && chrono::duration_cast<chrono::seconds>(chrono::steady_clock::now().time_since_epoch()).count() > (attackCCooldownTime + chrono::seconds(20)).count()) {
            lastAttack = 2; // Attack C selected
            attackCCooldownTime = chrono::steady_clock::now();
        } else {
            continue;
        }

        // Validate the CRC indications in the array
        bool crcValid = true;
        for (auto& crcIndication : crcArray) {
            if (!crcIndication.CRCFLAG) {
                crcValid = false;
                break;
            }
        }

        if (!crcValid) {
            cout << "CRC indication validation failed." << endl;
            // Handle CRC indication failure
        } else {
            cout << "Selected attack: ";
            switch (lastAttack) {
                case 0:
                    cout << "A" << endl;
                    break;
                case 1:
                    cout << "B" << endl;
                    break;
                case 2:
                    cout << "C" << endl;
                    break;
            }
        }

        // Log the selected attack and timestamp
        time_t now = time(0);
        tm* localtm = localtime(&now);
        char buffer[128];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtm);
        cout << "Timestamp: " << buffer << endl;
        if (lastAttack != -1) {
            cout << "Last attack: " << lastAttack << endl;
            lastAttack = -1; // Reset the last selected attack
        }

        // Pause or resume the game session as needed
        // ...

        // Export the logged session data to a CSV file at the end of each session
        ofstream csvfile("session_log.csv", ios::app);
        if (csvfile.is_open()) {
            csvfile << "Timestamp,Last Attack" << endl;
            for (auto& crcIndication : crcArray) {
                csvfile << chrono::duration_cast<chrono::seconds>(crcIndication.RX_UE_INFORMATION_TAG).count() << "," << lastAttack << endl;
            }
            csvfile.close();
        } else {
            cout << "Failed to open the CSV file." << endl;
        }
    }
}

int main() {
    srand(time(0)); // Seed the random number generator

    int arraySize = 10; // Initialize the dynamic array size
    vector<NFAPI_CRC_INDICATION_PDU_T> crcArray(arraySize);

    processGameSession(arraySize, crcArray);

    return 0;
}
