NFAPI_CRC_INDICATION_PDU_T* allocateStructures(int numStructures) {
    NFAPI_CRC_INDICATION_PDU_T* structures = new (nothrow) NFAPI_CRC_INDICATION_PDU_T[numStructures];

    if (!structures) {
        // Handle memory allocation failure
        logError("Memory allocation failed");
        return nullptr;
    }

    for (int i = 0; i < numStructures; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand();
        structures[i].RNTI = rand();
        structures[i].CRC_INDICATION_REL8_TAG = rand();
        structures[i].CRCFLAG = (rand() % 2 == 1);
