#include <time.h>

#define RECORD_COUNT 1000
#define OFFSET_ARRAY_SIZE 20000
#define KEY_ARRAY_SIZE 20000
#define MAX_KEY 1000000
#define MIN_KEY 1
#define RECORDS_PER_BLOCK 128

typedef struct {
    int key;
} Record;

Record* allocate_records(int count) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    return records;
}

void init_records(Record* records, int count) {
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    }
}

typedef struct {
    Record** records;
    int size;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->records = (Record**)calloc(size, sizeof(Record*));
    hash_table->size = size;
    return hash_table;
}

int hash_function(int key) {
    return key % 10; // A simple hash function for demonstration purposes
}

void insert_record(HashTable* hash_table, int key) {
    int index = hash_function(key);
    Record** records = hash_table->records + index;
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    *records++ = record;
}

int main() {
    srand(time(NULL));

    // Initialize arrays
    long* offset_values = (long*)malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    int* keys = (int*)malloc(KEY_ARRAY_SIZE * sizeof(int));

    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        offset_values[i] = rand();
    }

    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        keys[i] = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    }

    // Initialize hash table
    HashTable* hash_table = create_hash_table(100);

    Record* records = allocate_records(RECORD_COUNT);
    init_records(records, RECORD_COUNT);

    for (int i = 0; i < RECORD_COUNT; i++) {
        insert_record(hash_table, records[i].key);
    }

    // Clean up
    free(offset_values);
    free(keys);
    free(records);
    free(hash_table->records);
    free(hash_table);

    return 0;
}
