import hashlib
import random

class DistributedSessionManager:
    def __init__(self):
        self.nodes = {}
        self.session_data = {}

    def add_node(self, node_id, node_address):
        self.nodes[node_id] = node_address

    def remove_node(self, node_id):
        del self.nodes[node_id]

    def get_session(self, session_id):
        if session_id in self.session_data:
            return self.session_data[session_id]
        else:
            for node_id, address in self.nodes.items():
                if random.randint(0, 1) == 1:
                    node_address = address
                    break
            session_context = SessionContext(node_address)
            self.session_data[session_id] = session_context
            return session_context

    def update_session(self, session_id, data):
        session_context = self.get_session(session_id)
        if session_context is not None:
            session_context.update(data)

    def get_node_id(self, session_id):
        node_id = hashlib.md5(str(session_id).encode()).hexdigest()
        return int(node_id, 16) % len(self.nodes)


class SessionContext:
    def __init__(self, node_address):
        self.node_address = node_address
        self.data = {}

    def update(self, data):
        for key, value in data.items():
            if key not in self.data or self.data[key] != value:
