        if (!new_record->rx_ue_info) return NULL; // Handle memory allocation failure
        new_record->crc_rel8_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!new_record->crc_rel8_tag) return NULL; // Handle memory allocation failure
        if (new_record->value > nfa_max_rnti) nfa_max_rnti = new_record->value;
