        new_record->rx_ue_info->tag = "RX_UE_INFORMATION_TAG"; // Initialize RX_UE_INFORMATION_TAG
        new_record->crc_rel8_tag->tag = "CRC_INDICATION_REL8_TAG"; // Initialize CRC_INDICATION_REL8_TAG
        if (head == NULL) head = new_record;
        else {
            record* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_record;
        }
    }
