void* dynamic_allocator(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle memory allocation failure
        printf("Memory allocation failed: %s\n", strerror(errno));
    }
    return ptr;
}

void dynamic_deallocator(void* ptr) {
    free(ptr);
}

int insert_record(record_t* record) {
    pthread_mutex_lock(&mutex);

    records = realloc(records, (num_records + 1) * sizeof(record_t));
    if (!records) {
        // Handle memory allocation failure
        printf("Memory allocation failed: %s\n", strerror(errno));
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    records[num_records] = *record;
    num_records++;

    pthread_mutex_unlock(&mutex);
    return 0;
}

int remove_record(long offset) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset) {
            memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(record_t));
            num_records--;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int get_record(long offset, record_t* result) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset) {
            *result = records[i];
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
