int cache_size = 0;

// Initialize the cache with a specified maximum size and memory limit
void init_cache(int max_size, int max_memory_usage) {
    if (max_size > MAX_CACHE_SIZE || max_memory_usage > MAX_MEMORY_USAGE) {
        printf("Invalid parameters: max_size=%d, max_memory_usage=%d\n", max_size, max_memory_usage);
        return;
    }
    cache_size = max_size;
}

// Add a new resource to the cache with metadata
void add_resource(const char* url, int status_code) {
    // Allocate memory for the resource metadata
    resource_metadata_t* metadata = (resource_metadata_t*)malloc(sizeof(resource_metadata_t));
    if (!metadata) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        return;
    }
    metadata->url = strdup(url);
    metadata->last_accessed = time(NULL);
    metadata->status_code = status_code;

    // Find the LRU entry and evict it (if necessary)
    int i = 0;
    while (i < cache_size) {
        if (!cache[i]) break;
        if (metadata->last_accessed > cache[i]->last_accessed) {
            free(cache[i]->url);
            free(metadata);
            return;
        }
        i++;
    }

    // Insert the new resource at the end of the cache
    int j = 0;
    while (j < cache_size) {
        if (!cache[j]) break;
        j++;
    }
    cache[j] = metadata;

    // Update the recently used timestamp for all cache entries
    recently_used = time(NULL);
}

// Get the resource metadata from the cache
resource_metadata_t* get_resource(const char* url) {
    int i = 0;
    while (i < cache_size) {
        if (!cache[i]) break;
        if (strcmp(cache[i]->url, url) == 0) return cache[i];
        i++;
    }
    return NULL;
}

// Free the resource metadata from the cache
void free_resource(const char* url) {
    int i = 0;
    while (i < cache_size) {
        if (!cache[i]) break;
        if (strcmp(cache[i]->url, url) == 0) {
            free(cache[i]->url);
            free(cache[i]);
            return;
        }
        i++;
    }
}

// Update the recently used timestamp for a resource
void update_recently_used(const char* url) {
    int i = 0;
    while (i < cache_size) {
        if (!cache[i]) break;
        if (strcmp(cache[i]->url, url) == 0) {
            cache[i]->last_accessed = time(NULL);
            return;
        }
        i++;
    }
}

// Adaptive strategy to adjust behavior under heavy load conditions
void adapt_cache(int max_size, int max_memory_usage) {
    // Update the maximum size and memory usage limits
    if (max_size < cache_size) cache_size = max_size;
    if (max_memory_usage < MAX_MEMORY_USAGE - get_total_memory_usage()) {
        // Evict entries to free up memory
        int i = 0;
        while (i < cache_size) {
            if (!cache[i]) break;
            free(cache[i]->url);
            free(cache[i]);
            i++;
        }
    } else {
        // Increase the maximum size and memory usage limits
        MAX_CACHE_SIZE = max_size;
        MAX_MEMORY_USAGE = max_memory_usage;
    }
}

