#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define a list node structure
typedef struct Node {
    Record record;
    struct Node* next;
} ListNode;

// Define the linked list structure
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} List;

// Initialize the list with an empty head and a lock for concurrency control
List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Free all memory allocated by the list
void free_list(List* list) {
    ListNode* current = list->head;
    ListNode* next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new record to the end of the list
int add_record(List* list, long offset, int key) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) return -1;  // Allocation failure
    Record record;
    record.offset = offset;
    record.key = key;
    record.value = rand() % 1000;  // Random value generation
    node->record = record;
    node->next = list->head;
    pthread_mutex_lock(&list->lock);
    if (list->head) {
        ListNode* current = list->head;
        while (current->next) current = current->next;
        current->next = node;
    } else {
        list->head = node;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

// Get the record at a specific offset
Record* get_record(List* list, long offset) {
    ListNode* current = list->head;
    while (current && current->record.offset != offset) {
        current = current->next;
    }
    if (!current) return NULL;  // Record not found
    pthread_mutex_lock(&list->lock);
    return &current->record;
}

// Remove the record at a specific offset and free its memory
int remove_record(List* list, long offset) {
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current && current->record.offset != offset) {
        prev = current;
        current = current->next;
    }
    if (!current) return -1;  // Record not found
    pthread_mutex_lock(&list->lock);
    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }
    free(current);
    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

// Main function to integrate with an external data source
int main() {
    List* list = create_list();
    while (/* periodically receive records from the external data source */) {
        long offset;
        int key;
        Record record;
        // Receive and process the record
        add_record(list, offset, key);
    }
    free_list(list);
    return 0;
}
