        // Dynamically allocate memory for 'long' offset values
        if ((offsets = realloc(offsets, sizeof(long))) == NULL) {
            log_error(1, "Memory allocation failed for offsets array");
            break;
        }
    }

    for (int i = 0; i < KEYS; i++) {
        // Dynamically allocate memory for 'int' keys
        if ((keys = realloc(keys, sizeof(int))) == NULL) {
            log_error(1, "Memory allocation failed for keys array");
            break;
        }
    }

    for (int i = 0; i < RECORDS; i++) {
        // Dynamically allocate memory for 'record' structures
        if ((records = realloc(records, sizeof(Record))) == NULL) {
            log_error(1, "Memory allocation failed for records array");
            break;
        }

        Record* record = &records[i];
        // Initialize the record's int field with a random value within a given range
        record->value = rand() % 100;

        // Dynamically allocate memory for 'timestamp' values
        if ((timestamps = realloc(timestamps, sizeof(time_t))) == NULL) {
            log_error(1, "Memory allocation failed for timestamps array");
            break;
        }

        time_t* timestamp = &timestamps[i];
        // Initialize the timestamp with the current system time
        *timestamp = time(NULL);

        // Dynamically allocate memory for 'char' buffer based on a specified string length
        if ((record->buffer = malloc(BUFFER_SIZE)) == NULL) {
            log_error(1, "Memory allocation failed for record's buffer");
            break;
        }

        // Initialize the char buffer and set it to null-terminated
        sprintf(record->buffer, "%d", record->value);
        record->buffer[ BUFFER_SIZE - 1 ] = '\0';
    }

    // Validate that all allocated buffers are correctly null-terminated after initialization
    for (int i = 0; i < RECORDS; i++) {
        if (records[i].buffer == NULL || records[i].buffer[ BUFFER_SIZE - 1 ] != '\0') {
            log_error(2, "Error: record buffer is not null-terminated");
        }
    }

    // Deallocate memory in the reverse order of allocation
    for (int i = RECORDS; i > 0; i--) {
        free(records[i].buffer);
        timestamps--;
    }

    free(timestamps);
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
