#define MAX_RECORDS 1000
#define INITIAL_STRING_LENGTH 1024
#define COMPRESSION_THRESHOLD 4096
#define LOG_LEVEL 3 // Debug level (1-5)

typedef struct {
    int key;
    long offset;
    char* buffer;
} record_t;

record_t* records = NULL;
int num_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* allocate_record(int key, int string_length) {
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    if (!new_record) return NULL;

    new_record->key = key;
    new_record->offset = rand() % 1000000; // Initialize with random offset
    new_record->buffer = (char*)malloc(string_length + 1);
    if (!new_record->buffer) {
        free(new_record);
        return NULL;
    }

    return new_record;
}

void deallocate_record(record_t* record) {
    free(record->buffer);
    free(record);
}

int resize_records(int new_size) {
    record_t* new_array = (record_t*)malloc(new_size * sizeof(record_t));
    if (!new_array) return -1;

    if (records) {
        memcpy(new_array, records, num_records * sizeof(record_t));
        free(records);
    }
    records = new_array;
    return 0;
}

void* compression_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        while (!num_records || !records[num_records - 1]->buffer) {
            pthread_cond_wait(&cond, &lock);
        }

        for (int i = 0; i < num_records; i++) {
            if (strlen(records[i]->buffer) > COMPRESSION_THRESHOLD) {
                // Compress buffer and update record
                char* compressed_buffer = compress(records[i]->buffer);
                free(records[i]->buffer);
                records[i]->buffer = compressed_buffer;
            }
        }

        pthread_mutex_unlock(&lock);
    }
}

int main() {
    pthread_t compression_thread_id;

    pthread_create(&compression_thread_id, NULL, compression_thread, NULL);

    // Example usage
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % 10000;
        int string_length = rand() % INITIAL_STRING_LENGTH + 1;
        record_t* new_record = allocate_record(key, string_length);
        if (!new_record) break;

        // Initialize buffer with random data
        char* buffer_data = (char*)malloc(string_length);
        for (int j = 0; j < string_length; j++) {
            buffer_data[j] = 'A' + rand() % 26;
        }
        strcpy(new_record->buffer, buffer_data);
        free(buffer_data);

        // Add record to array and increment count
        if (!records) {
            records = (record_t*)malloc(sizeof(record_t));
            num_records = 1;
        } else if (num_records < MAX_RECORDS) {
            if (resize_records(num_records * 2) == -1) break;

            // Move existing records to the new array
            memcpy(&records[num_records], &records, sizeof(record_t) * (num_records - 1));
            num_records *= 2;
        }

        pthread_mutex_lock(&lock);
        records[num_records - 1] = new_record;
        num_records++;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }

    // Clean up
    for (int i = 0; i < num_records; i++) {
        deallocate_record(records[i]);
    }
    free(records);

    return 0;
}
