typedef struct {
    int key;
    int value;
} record;

record** records;
int* record_count;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_records(int max_records) {
    int i;
    if (max_records > 0) {
        records = (record**)malloc(max_records * sizeof(record*));
        record_count = (int*)malloc(max_records * sizeof(int));

        for (i = 0; i < max_records; i++) {
            records[i] = (record*)malloc(sizeof(record));
            records[i]->key = i;
            records[i]->value = rand() % 100;
        }
    }
}

void deallocate_records() {
    int i;
    if (records != NULL) {
        for (i = 0; i < *record_count; i++) {
            free(records[i]);
        }
        free(records);
        free(record_count);
    }
}

int main() {
    pthread_t threads[5];

    // Initialize the random number generator
    srand(time(NULL));

    // Allocate a maximum of 10 records
    allocate_records(10);

    // Create 5 threads to access and modify the records concurrently
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, &thread_function, NULL);
    }

    // Wait for the threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate all allocated records
    deallocate_records();

    return 0;
}

void* thread_function(void* arg) {
    int i, key;
    record* rec;

    // Get a random record to modify
    key = rand() % *record_count;
    rec = records[key];

    // Simulate concurrent read and write operations
    for (i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        rec->value += i;
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}
