    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_list() {
    head = NULL;
}

void add_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data = new_data;
    new_node->next = (*head_ref);
    *head_ref = new_node;
}

NFAPI_CRC_INDICATION_PDU_T get_largest_rnti() {
    NFAPI_CRC_INDICATION_PDU_T largest = {0};
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI > largest.RNTI) {
            largest = current->data;
        }
        current = current->next;
    }
    return largest;
}

void serialize_list_to_file(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file for writing.\n");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_list_from_file(Node** head_ref, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file for reading.\n");
        return;
    }

    Node* new_head = NULL;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T data;
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        add_node(&new_head, data);
        if (ferror(file)) {
            break;
        }
    }
    fclose(file);

    *head_ref = new_head;
}

void* random_data() {
    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = rand();
    data.RNTI = rand();
    strcpy(data.CRC_INDICATION_REL8_TAG, "random_string");
    bool flag = (rand() % 2 == 0);
    data.CRCFLAG = flag;
    return &data;
}

void* thread_func(void* arg) {
    Node* current = head;
    while (current != NULL) {
        pthread_mutex_lock(&mutex);
        // Perform operations on the linked list
        pthread_mutex_unlock(&mutex);
        current = current->next;
    }
    return NULL;
}

int main() {
    int N = 10000; // Number of elements in the linked list

    initialize_list();
    for (int i = 0; i < N; i++) {
        add_node(&head, *random_data());
    }

    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Largest RNTI: %d\n", get_largest_rnti().RNTI);

    serialize_list_to_file(head, "output.bin");

    Node* new_head;
    deserialize_list_from_file(&new_head, "output.bin");

    return 0;
}
