#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define PRIORITIES 3

typedef struct task {
    char* command;
    time_t timestamp;
    int id;
    int priority;
} task;

task tasks[MAX_TASKS];
int num_tasks = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void add_task(task t) {
    pthread_mutex_lock(&mutex);
    if (num_tasks >= MAX_TASKS) {
        fprintf(stderr, "Error: Task list is full.\n");
        return;
    }
    tasks[num_tasks] = t;
    num_tasks++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

void execute_task(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].id == id) {
            // execute task logic here
            printf("Executing task %d\n", id);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void pause_task(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].id == id) {
            // pause task logic here
            printf("Pausing task %d\n", id);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void resume_task(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].id == id) {
            // resume task logic here
            printf("Resuming task %d\n", id);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* thread_function(void* arg) {
    int* tid = (int*)arg;
    while (1) {
