        if (t.priority == PRIORITIES - 1) {
            pause_task(t.id);
            sleep(2); // simulate some work being done
            resume_task(t.id);
        }
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_TASKS];

    for (int i = 0; i < MAX_TASKS; i++) {
