#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CHUNK_SIZE 1024 * 1024 // 10MB chunks

typedef struct {
    int id;
    char* data;
} DataChunk;

// Optimized quicksort algorithm for stable sorting
void qsort(int arr[], int left, int right) {
    if (left >= right)
        return;

    int i = left, j = right;
    int pivot = arr[(i + j) / 2];

    do {
        while (arr[i] < pivot)
            i++;

        while (arr[j] > pivot)
            j--;

        if (i <= j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    } while (i <= j);

    qsort(arr, left, j);
    qsort(arr, i, right);
}

// Dynamic resizing of hash buckets
void resize_hash_buckets(int* hash_buckets[], int size) {
    int new_size = size * 2;
    int* new_hash_buckets = (int*)malloc(new_size * sizeof(int));

    for (int i = 0; i < size; ++i)
        new_hash_buckets[i] = hash_buckets[i];

    free(hash_buckets);
    hash_buckets = new_hash_buckets;
}

// Sorting, filtering, and deduplication
void process_data(DataChunk* data_chunks[], int num_chunks) {
    // Sort chunks by ID
    qsort((int*)data_chunks[0].id, 0, num_chunks - 1);

    // Filter out duplicates
    for (int i = 0; i < num_chunks; ++i) {
        if (data_chunks[i]->data == NULL || strlen(data_chunks[i]->data) == 0)
            continue;

        bool duplicate = false;
        for (int j = i - 1; j >= 0 && !duplicate; --j) {
            if (strcmp(data_chunks[j]->data, data_chunks[i]->data) == 0) {
                duplicate = true;
                break;
            }
        }

        if (!duplicate)
            printf("Chunk %d: %s\n", i, data_chunks[i]->data);
    }
}

int main() {
    int num_chunks = 10000; // number of chunks
    DataChunk* data_chunks = (DataChunk*)malloc(num_chunks * sizeof(DataChunk));

    // Initialize data chunks with sample data
    for (int i = 0; i < num_chunks; ++i) {
        data_chunks[i].id = i;
        char buffer[CHUNK_SIZE];
        sprintf(buffer, "Chunk %d: Sample Data", i);
        data_chunks[i].data = (char*)malloc(strlen(buffer) + 1);
        strcpy(data_chunks[i].data, buffer);
    }

    process_data(data_chunks, num_chunks);

    // Free allocated memory
    for (int i = 0; i < num_chunks; ++i)
        free(data_chunks[i].data);

    free(data_chunks);
    return 0;
}
