NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU(int n) {
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        structures[i].RX_UE_INFORMATION_TAG = 1;
        structures[i].RNTI = i;

        // Set CRCFLAG randomly
        srand(time(NULL) + i);
        unsigned char crcflag[2] = {(unsigned char)(rand() % 256), (unsigned char)(rand() % 256)};
        for (int j = 0; j < 2; j++) {
            structures[i].CRCFLAG[j] = crcflag[j];
        }
    }

    return structures;
}

