void insert_entry(struct NFAPI_CRC_INDICATION_PDU_T *array, int num_entries, unsigned int rnti) {
    // Find the position to insert the new entry
    for (int i = 0; i < num_entries; i++) {
        if (array[i].RNTI > rnti) {
            break;
        }
    }

    // Insert the new entry at the correct position
    for (int j = num_entries; j > i; j--) {
        array[j] = array[j - 1];
    }

    array[i].RX_UE_INFORMATION_TAG = malloc(strlen("RX_UE_INFORMATION_TAG") + 1);
    strcpy(array[i].RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
    array[i].RNTI = custom_hash_function(rnti);
