void delete_entry(struct NFAPI_CRC_INDICATION_PDU_T *array, int num_entries, unsigned int rnti) {
    // Find the position to delete the entry
    for (int i = 0; i < num_entries; i++) {
        if (array[i].RNTI == rnti) {
            break;
        }
    }

    // Shift all entries after the deleted one down by one position
    for (int j = i; j < num_entries - 1; j++) {
        array[j] = array[j + 1];
    }

    // Free memory of the deleted entry
    free(array[i].RX_UE_INFORMATION_TAG);
    free(array[i].CRC_INDICATION_REL8_TAG);

    // Reduce the number of entries
    num_entries--;
