        ue_ctxs[i].ue_id = ue_id;
        ue_ctxs[i].cell_id = i + 1; // Cell ID starts from 1
        ue_ctxs[i].downlink_grants = rand() % 10 + 1; // Generate a random number of downlink grants between 1-10
    }

    return (int*)ue_ctxs;
}

// Function to add uplink PRBs with configurable bandwidth settings
void add_uplink_prb(int* ue_ctxs, int num_ues, int ue_id, int prbs, int bandwidth) {
    lte_ue_context* current_ue = NULL;

    for (int i = 0; i < num_ues; i++) {
        if (ue_ctxs[i].ue_id == ue_id) {
            current_ue = &ue_ctxs[i];
            break;
        }
    }

    // Add uplink PRBs to the corresponding UE context record
    current_ue->downlink_grants += prbs;
    current_ue->bandwidth = bandwidth; // Update the bandwidth setting for the added PRBs
}

