// Function to dynamically construct and manage a linked list
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu(int num_entries) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entry) {
            // Handle memory allocation error
            printf("Memory allocation failed for entry %d.\n", i);
            return NULL;
        }
        new_entry->RX_UE_INFORMATION_TAG = (rand() % 100); // Randomly set RX_UE_INFORMATION_TAG
        new_entry->RNTI = rand() % 100; // Randomly set RNTI
        sprintf(new_entry->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG_%d", i);
        new_entry->CRCFLAG = (rand() % 2); // Randomly set CRCFLAG
        if (!head) {
            head = new_entry;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_entry;
        }
    }
    return head;
}

// Function to filter entries based on RNTI range
NFAPI_CRC_INDICATION_PDU_T* filter_entries(NFAPI_CRC_INDICATION_PDU_T* head, int start_RNTI, int end_RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* filtered_head = NULL;
    for (NFAPI_CRC_INDICATION_PDU_T* current = head; current; ) {
        if (current->RNTI >= start_RNTI && current->RNTI <= end_RNTI) {
            if (!filtered_head) {
                filtered_head = current;
            } else {
                NFAPI_CRC_INDICATION_PDU_T* prev = filtered_head;
                while (prev->next) {
                    prev = prev->next;
                }
                prev->next = current;
            }
        } else {
            NFAPI_CRC_INDICATION_PDU_T* next = current->next;
            free(current);
            current = next;
        }
    }
    return filtered_head;
}

// Function to validate the linked list
int validate_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    int count = 0;
    for (NFAPI_CRC_INDICATION_PDU_T* current = head; current; ) {
        count++;
        current = current->next;
    }
    return count;
}

// Function to free memory
void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator
    int num_entries = 100; // Number of entries in the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = create_nfa_pi_crc_indication_pdu(num_entries);
    if (!head) {
        printf("Failed to create linked list.\n");
        return -1;
    }

    int start_RNTI = 10; // Start of the RNTI range
    int end_RNTI = 50; // End of the RNTI range

    NFAPI_CRC_INDICATION_PDU_T* filtered_head = filter_entries(head, start_RNTI, end_RNTI);

    if (!filtered_head) {
        printf("Failed to filter entries.\n");
        return -1;
    }

    int count = validate_linked_list(filtered_head);
    printf("Linked list validated: %d entries\n", count);

    free_linked_list(filtered_head);

    return 0;
}
