#include "crc_utils.h"
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_pdu_list(int n, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    // Initialize list of PDUs
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize RNTI set and CRC sequence generator
    RNTI rnti_set[n];
    unsigned int crc_sequence[256];
    for (int i = 0; i < n; i++) {
        rnti_set[i] = i;
    }
    srand(time(NULL));
    for (int i = 0; i < 256; i++) {
        crc_sequence[i] = rand();
    }

    // Generate PDUs
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_info.tag = i;
        pdu.rnti = rnti_set[i];
        pdu.crc_ind_rel8_tag = crc_sequence[i % 256] >> 8;
        if (i > 0 && pdu.crc_ind_rel8_tag == (*pdu_list)[i - 1].crc_ind_rel8_tag) {
            i--;
        }
    }

    free(*pdu_list);
}

void serialize_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int n, FILE *file) {
    fwrite(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
}
