void* system_of_records(int num_records) {
    // Set maximum record size limit
    const int MAX_RECORD_SIZE = sizeof(Record);

    // Initialize total memory usage tracker
    static long total_memory_usage = 0;

    // Calculate required memory for records
    size_t required_memory = num_records * MAX_RECORD_SIZE;

    // Check if total memory usage exceeds the maximum allowed (e.g., 1 GB)
    const int MAX_MEMORY_USAGE = 1024 * 1024 * 1024; // 1 GB
    if (total_memory_usage + required_memory > MAX_MEMORY_USAGE) {
        return NULL; // Exceeded maximum allowed memory usage
    }

    // Allocate memory for records and initialize tracker
    void* records = malloc(required_memory);
    total_memory_usage += required_memory;

    // Initialize the system of records with num_records number of records
    Record* record_ptr = (Record*) records;
    for (int i = 0; i < num_records; i++) {
        record_ptr[i].offset = -1; // Offset initialized to -1 for simplicity
        record_ptr[i].key = -1;     // Key initialized to -1 for simplicity
        strcpy(record_ptr[i].identifier, ""); // Initialize identifier with empty string
    }

    return records;
}

void free_system_of_records(void* system) {
    if (system != NULL) {
        free(system);
    }
}
