            srand(time(NULL) + i); // ensure unique timestamps

            // populate char buffer with a combination of ASCII letters and digits
            for (int j = 0; j < 20; j++) {
                int c = rand() % ('Z' - 'A' + 1) + 'A';
                if (rand() % 2) c += ('9' - '0' + 1);
                entries[i].buffer[j] = (char)c;
            }

            // assign unique timestamp starting from a configurable initial value
            entries[i].timestamp = i + 10; // adjust this as needed

            offsets[i] = i * sizeof(entry); // store offset for data retrieval
            keys[i] = i; // use array index as key for indexing or lookup
        }
    } catch (...) {
        if (entries) free(entries);
        if (offsets) free(offsets);
        if (keys) free(keys);
        return NULL;
    }

