typedef struct {
    int RNTI;
    int CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int flag;
} CRC_INDICATION_REL8_TAG;

RX_UE_INFORMATION_TAG** processCommandAndGeneratePDUList(char* command, int N, int seed) {
    pid_t pid = fork();
    if (pid == 0) { // child process
        system(command);
        exit(0);
    } else { // parent process
        wait(NULL);

        RX_UE_INFORMATION_TAG** pduList = (RX_UE_INFORMATION_TAG**)malloc(N * sizeof(RX_UE_INFORMATION_TAG*));
        for (int i = 0; i < N; i++) {
            pduList[i] = (RX_UE_INFORMATION_TAG*)malloc(sizeof(RX_UE_INFORMATION_TAG));

            // populate structure with data from external data source
            pduList[i]->RNTI = rand_r(&seed) % 100;
            pduList[i]->CRCFLAG = (rand_r(&seed) % 2) ? 1 : 0;
        }

        // dynamically allocate memory for CRC_INDICATION_REL8_TAG structures
        CRC_INDICATION_REL8_TAG** crcList = (CRC_INDICATION_REL8_TAG**)malloc(N * sizeof(CRC_INDICATION_REL8_TAG*));
        for (int i = 0; i < N; i++) {
            crcList[i] = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
            crcList[i]->flag = rand_r(&seed) % 2;
        }

        // release allocated memory
        for (int i = 0; i < N; i++) {
            free(pduList[i]);
            free(crcList[i]);
        }
        free(pduList);
        free(crcList);

        return pduList;
    }
}
