        size_t new_size = min(max_size - total_size, sizeof(Record));
        if (!records) {
            records = malloc(new_size);
        } else {
            Record* temp = records;
            records = realloc(temp, allocated_size + new_size);
            free(temp);
        }
        allocated_size += new_size;

        // Your processing function f
        // ...
    }

    return records;
}

void processRecords(Record* records) {
    for (int i = 0; i < 100; i++) {
        printf("%ld %d %s\n", records[i].offset, records[i].key, records[i].string);
    }
}

void freeRecords(Record* records) {
    while (records) {
        Record* temp = records;
        records = records->next;
        free(temp);
    }
}

int main() {
    size_t max_size = 1024 * 1024; // 1 MB
    Record* records = dynamicRecordManager(max_size);

    if (!records) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    processRecords(records);

    freeRecords(records);
    return 0;
}
