// Linked list node structure
typedef struct Node {
    Measurement data;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int window_size = 100; // default time window size in seconds
int max_list_size = 1000; // default maximum list size
float threshold = 25.0f; // default alert threshold

// Thread-safe function to add a new measurement to the linked list
void add_measurement(Measurement m) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed!\n");
        return;
    }
    newNode->data = m;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
}

// Thread-safe function to check for duplicate measurements within the time window
int has_duplicate(int timestamp, Measurement m) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.timestamp == timestamp && current->data.temperature == m.temperature) {
            return 1; // duplicate found
        }
        current = current->next;
    }
    return 0; // no duplicates found
}

// Function to compute and return the most critical temperature reading and its timestamp
void get_critical_reading(int* timestamp, float* temp) {
    Node* current = head;
    float max_temp = -INFINITY;
    int max_timestamp = -1;

    while (current != NULL) {
        if (current->data.temperature > max_temp) {
            max_temp = current->data.temperature;
            max_timestamp = current->data.timestamp;
        }
        current = current->next;
    }

    *timestamp = max_timestamp;
    *temp = max_temp;
}

// Function to compute and return the total number of alerts exceeding the threshold within the window
int get_alert_count() {
    int count = 0;

    Node* current = head;
    while (current != NULL) {
        if (current->data.temperature > threshold) {
            count++;
        }
        current = current->next;
    }

    return count;
}

// Thread-safe function to handle memory allocation failures and resource cleanup
void* thread_safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed!\n");
        free(ptr);
        return NULL;
    }
    return ptr;
}

