} NFAPI_CRC_INDICATION_PDU_T;

// Custom allocator function with memory pooling
void* custom_allocator(size_t size) {
    static void* pool[10000]; // Memory pool for 10,000 elements
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    void* ptr = NULL;

    // Lock the memory pool to avoid concurrent access
    pthread_mutex_lock(&lock);

    for (int i = 0; i < sizeof(pool) / sizeof(*pool); i++) {
        if (!pool[i]) {
            ptr = realloc(pool[i], size);
            break;
        }
    }

    // If no available memory block is found, allocate a new one
    if (!ptr) {
        ptr = malloc(size);
        printf("Memory allocation failure. Using fallback allocator.\n");
    }

    pthread_mutex_unlock(&lock);

    return ptr;
}

// Doubly linked list node structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Initialize a new list with a given initial capacity
Node* init_list(int capacity) {
    Node* head = NULL;

    for (int i = 0; i < capacity; i++) {
        // Allocate memory dynamically using the custom allocator
        Node* node = (Node*)custom_allocator(sizeof(Node));

        // Initialize node data
        node->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        node->data->RX_UE_INFORMATION_TAG = rand();
        node->data->RNTI = rand();
        node->data->CRC_INDICATION_REL8_TAG = rand();
        node->data->CRCFLAG = rand();

        // Link the new node to the list
        if (!head) {
            head = node;
        } else {
            head->prev = node;
            node->next = head;
            head = node;
        }
    }

    return head;
}

// Remove an element from the list by deallocating its memory and updating links
void remove_element(Node* node) {
    if (!node)
        return;

    // Deallocate the removed node's data
    free(node->data);

    // Update links for the adjacent nodes
    if (node->prev)
        node->prev->next = node->next;
    else
        node->next->prev = NULL;

    if (node->next)
        node->next->prev = node->prev;
    else
        node->prev->next = NULL;
}

// Compact the list by re-linking existing elements and deallocating unused memory blocks
void compact_list(Node* head) {
    Node* current = head;
    Node* prev = NULL;

    while (current) {
        // Move to the next element
        Node* next = current->next;

        // Reallocate the current node's data to reduce fragmentation
        current->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Update links for adjacent nodes
        if (prev)
            prev->next = next;
        else
            head = next;

        if (next)
            next->prev = current;
        else
            current->next = NULL;

        // Move to the next element
        prev = current;
        current = next;
    }
}

// Logging function for tracking allocations, deallocations, and list statistics
void log_list(Node* head) {
    int allocation_count = 0;
    int deallocation_count = 0;

    Node* current = head;

    while (current) {
        // Count the number of elements in the list
        allocation_count++;

        // Move to the next element
        current = current->next;
    }

    printf("Allocation count: %d, Deallocation count: %d, List size: %d\n", allocation_count, deallocation_count, allocation_count);
}

// Main function to demonstrate the module's functionality
int main() {
    // Initialize the list with an initial capacity of 10,000 elements
    Node* head = init_list(10000);

    // Perform operations on the list (e.g., insertion, removal, iteration)
    // ...

    // Periodically compact the list to optimize memory usage and reduce fragmentation
    while (1) {
        compact_list(head);
        log_list(head);

        // Simulate system-wide memory limits and constraints
        if (get_memory_usage() > 0.5 * get_total_memory()) {
            printf("Memory limit exceeded! Reducing functionality.\n");

            // Handle memory allocation failures gracefully
            void* ptr = custom_allocator(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!ptr) {
                printf("Memory allocation failure. Operation reduced.\n");
            }

            break;
        }

        sleep(1);  // Periodic compaction and logging
    }

    return 0;
}

