NFAPI_CRC_INDICATION_PDU_TP manage_crc_indication(int N, uint32_t seed, int max_traffic) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_TP head = NULL;
    NFAPI_CRC_INDICATION_PDU_TP current = NULL;
    struct node* list_head = NULL;
    struct node* list_current = NULL;

    for (int i = 0; i < N; i++) {
        struct node* new_node = malloc(sizeof(struct node));
        if (new_node == NULL) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            return NULL;
        }

        new_node->data = (NFAPI_CRC_INDICATION_PDU_TP)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (new_node->data == NULL) {
            free(new_node);
            fprintf(stderr, "Error: Memory allocation failed\n");
            return NULL;
        }

        new_node->data->RX_UE_INFORMATION_TAG = rand();
        new_node->data->RNTI = rand() % 65536;
        while (find_rnti(list_head, list_current, &new_node->data->RNTI) != NULL) {
            new_node->data->RNTI = rand() % 65536;
        }
        new_node->data->CRC_INDICATION_REL8_TAG = rand();
        new_node->data->CRCFLAG = rand();

        if (head == NULL) {
            head = new_node->data;
            list_head = new_node;
        } else {
            current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node->data;
            new_node->prev = current;
            list_current = new_node;
        }

        free(new_node);
    }

    return head;
}

NFAPI_CRC_INDICATION_PDU_TP find_rnti(struct node* head, struct node* current, uint16_t rnti) {
    while (current != NULL) {
        if (current->data->RNTI == rnti) {
            return current->data;
        }
        current = current->next;
    }
    return NULL;
}
